def test_full_verification(run, x):
    # Only run full verification on small inputs to stay fast.
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n * m > 1000:
        return  # skip large inputs
    grid = lines[1:1 + n]
    heights = []
