def test_bruteforce_small(run, x):
    lines = x.strip().split('\n')
    n_m = lines[0].split()
    if len(n_m) != 2:
        return
    n, m = map(int, n_m)
    if n * m > 6:
        return  # too large for brute force
    grid = lines[1:1+n]
    # Enumerate all possible sequences of operations
    from itertools import combinations, product
    all_rows = list(range(n))
    all_cols = list(range(m))
    # Generate all non-empty subsets of rows and columns for each operation,
    # but rows and columns across operations must be disjoint.
    # Since n*m <=6, brute force over all sequences up to n+m operations.
    max_ops = n + m  # upper bound
    best_found = False
    # Iterate over number of operations k
    for k in range(0, max_ops+1):
        # We'll generate sequences of k pairs (R_i, C_i) with R_i non-empty subset of rows,
        # C_i non-empty subset of cols, and all R_i disjoint, all C_i disjoint.
        # Represent as list of (R_set, C_set).
        # Generate all ways to partition rows into k groups (some empty) and similarly columns.
        # For each partition, assign each non‑empty row group to an operation, likewise columns.
        # This is messy; instead we can brute-force over all assignments of each row to an operation index or -1 (unused),
        # similarly columns, ensuring each operation gets at least one row and one column.
        # Since n,m <=6, total possibilities are (k+1)^{n+m} which is small.
        for row_assign in product(range(-1, k), repeat=n):
            for col_assign in product(range(-1, k), repeat=m):
                # Check each operation has at least one row and one column
                ok = True
                for op in range(k):
                    if (op not in row_assign) or (op not in col_assign):
                        ok = False
                        break
                if not ok:
                    continue
                # Simulate painting
                painted = [[False]*m for _ in range(n)]
                for r in range(n):
                    op_r = row_assign[r]
                    if op_r == -1:
                        continue
                    for c in range(m):
                        op_c = col_assign[c]
                        if op_c == -1:
                            continue
                        if op_r == op_c:
                            painted[r][c] = True
                # Compare with grid
                match = True
                for r in range(n):
                    for c in range(m):
                        if (grid[r][c] == '#') != painted[r][c]:
                            match = False
                            break
                    if not match:
                        break
                if match:
                    best_found = True
                    break
            if best_found:
                break
        if best_found:
            break
    expected = 'yes' if best_found else 'no'
    out = run(x).strip().lower()
    assert out == expected, f'bruteforce says {expected}, got {out}'

