            if grid[r][c] == '#':
                col_to_rows[c].append(r)
    for c in range(m):
        rows = col_to_rows[c]
        if not rows:
            continue
        first_set = {c2 for c2 in range(m) if grid[rows[0]][c2] == '#'}
        for r in rows[1:]:
            cur_set = {c2 for c2 in range(m) if grid[r][c2] == '#'}
            if cur_set != first_set:
                col_ok = False
                break
        if not col_ok:
            break
    # Group rows by column sets and check disjointness
    row_groups = {}
    for r in range(n):
        col_set = frozenset(c for c in range(m) if grid[r][c] == '#')
        if col_set:
            row_groups.setdefault(col_set, []).append(r)
    disjoint_ok = True
    sets_list = list(row_groups.keys())
    for i in range(len(sets_list)):
        for j in range(i+1, len(sets_list)):
            if sets_list[i] & sets_list[j]:
                disjoint_ok = False
                break
        if not disjoint_ok:
            break
    # Row‑column consistency
    rc_ok = True
    for col_set, rows in row_groups.items():
