    },
    {
      "name": "test_non_star_not_zero",
      "source": "def test_non_star_not_zero(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    deg = [0] * (n + 1)
    for edge in lines[1:]:
        if edge:
            u, v = map(int, edge.split())
            deg[u] += 1
            deg[v] += 1
    is_star = any(d == n - 1 for d in deg) and all(d == 1 or d == n - 1 for d in deg[1:])
    if not is_star:
