    },
    {
      "name": "test_small_brute_force",
      "source": "def test_small_brute_force(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 8:
        return  # too big for brute‑force
    # parse edges
    edges = []
    for line in lines[1:]:
        if line:
            u, v = map(int, line.split())
            edges.append((u-1, v-1))
    # adjacency matrix for BFS
    from collections import deque
    from copy import deepcopy
    start_state = tuple(sorted(edges))
    def is_star(state):
        deg = [0]*n
        for u, v in state:
            deg[u] += 1
            deg[v] += 1
        return any(d == n-1 for d in deg) and all(d==1 or d==n-1 for d in deg)
    # pre‑compute all reachable states by BFS
    q = deque([start_state])
    dist = {start_state: 0}
    while q:
        cur = q.popleft()
        if is_star(cur):
            expected = dist[cur]
            out = run(x)
            val = int(out.strip())
            assert val == expected, f"For n={n} brute‑force gives {expected}, got {val}"
            return
        # generate all possible operations
        # Build adjacency list
        adj = [[] for _ in range(n)]
        for u, v in cur:
            adj[u].append(v)
            adj[v].append(u)
        # iterate over all choices of a,b,c with b adjacent to a and c, a adjacent to b
        for a in range(n):
            for b in adj[a]:
                for c in adj[b]:
                    if c == a:
                        continue
                    # perform operation: move all neighbors of a (except b) to c
                    new_edges = []
                    # copy all edges not incident to a (except the edge a-b)
                    for u, v in cur:
                        if (u==a and v==b) or (u==b and v==a):
                            continue  # edge a-b will be removed
                        if u != a and v != a:
                            new_edges.append((u, v))
                    # add new edges from a to c
                    new_edges.append((a, c))
                    # for each neighbor d of a except b, add edge d-c
                    for d in adj[a]:
                        if d == b:
                            continue
                        new_edges.append((d, c))
                    # sort each edge and the whole list for canonical representation
                    new_edges = tuple(sorted((min(u,v), max(u,v)) for u, v in new_edges))
                    if new_edges not in dist:
                        dist[new_edges] = dist[cur] + 1
                        q.append(new_edges)
    # If no star reachable (should not happen), skip assertion
    # But specification guarantees it is always possible.
    # We computed the distance, so we must have found a star.
    # If we reach here, something went wrong in BFS.
    raise RuntimeError("Brute‑force BFS did not find a star for n ≤ 8")"
