      "source": "def test_10_brute_force_small(run, x):
    parts = x.strip().split()
    n = int(parts[0])
    colors = list(map(int, parts[1:1+n]))
    if n > 8:
        return  # too big for brute force
    # compress to components
    comp = []
    for c in colors:
        if not comp or c != comp[-1]:
            comp.append(c)
    m = len(comp)
    # BFS over states: state = tuple of component colors
    start = tuple(comp)
    from collections import deque
    q = deque()
    dist = {start: 0}
    q.append(start)
    while q:
        cur = q.popleft()
        if len(set(cur)) == 1:
            computed = dist[cur]
            ans = int(run(x).strip())
            assert ans == computed, f'answer {ans} != computed {computed}'
            return
        # expand: pick a starting component index i (0‑based)
        for i in range(len(cur)):
            # try changing component i to any color not equal to its current
            cur_col = cur[i]
            for new_col in set(cur):
                if new_col == cur_col:
                    continue
                # merge adjacent same colors after change
                new_list = list(cur)
                new_list[i] = new_col
                # merge left
                if i > 0 and new_list[i-1] == new_col:
                    new_list.pop(i)
                    i -= 1
                # merge right
                while i+1 < len(new_list) and new_list[i] == new_list[i+1]:
                    new_list.pop(i+1)
                nxt = tuple(new_list)
                if nxt not in dist:
                    dist[nxt] = dist[cur] + 1
                    q.append(nxt)
    # should never reach here for valid n ≤ 8
    raise AssertionError('BFS did not find solution')
