    {
      "name": "test_prefix_sum",
      "source": "def test_prefix_sum(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n > 500:  # too large for brute recomputation
        return
    s = sum(a) // n
    c = 0
    total = 0
    for i in range(n):
        c += a[i] - s
        total += abs(c)
    out = run(x)
    try:
        ans = int(out.strip())
    except ValueError:
        assert False, 'output not an integer'
    assert ans == total, f'prefix sum method gives {total}, got {ans}'"
    },
    {
      "name": "test_greedy_left",
      "source": "def test_greedy_left(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n > 500:
        return
    b = a[:]
    s = sum(b) // n
    moves = 0
    for i in range(n - 1):
        if b[i] < s:
            d = s - b[i]
            moves += d
            b[i + 1] -= d
        else:
            d = b[i] - s
            moves += d
            b[i + 1] += d
    moves += abs(b[-1] - s)
    out = run(x)
    try:
        ans = int(out.strip())
    except ValueError:
        assert False, 'output not an integer'
    assert ans == moves, f'greedy left gives {moves}, got {ans}'"
    },
    {
      "name": "test_greedy_right",
      "source": "def test_greedy_right(run, x):
