    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n > 500:
        return
    b = a[:]
    s = sum(b) // n
    moves = 0
    for i in range(n - 1, 0, -1):
        if b[i] < s:
            d = s - b[i]
            moves += d
            b[i - 1] -= d
        else:
            d = b[i] - s
            moves += d
            b[i - 1] += d
    moves += abs(b[0] - s)
    out = run(x)
    try:
