    for name in pokemon:
        if len(name) == n:
            ok = True
            for i, ch in enumerate(pattern):
                if ch != '.' and name[i] != ch:
                    ok = False
                    break
            if ok:
                matching.append(name)
    assert len(matching) == 1, f"expected exactly one matching name, got {matching}"
    out = run(x)
    stripped = out.strip()
    assert stripped == matching[0], f"output '{stripped}' does not equal unique match '{matching[0]}'"

def test_no_extra_whitespace(run, x):
    out = run(x)
    stripped = out.strip()
    assert out == stripped or out == stripped + '\n', "output contains extra whitespace"
    for ch in stripped:
        assert not ch.isspace(), f"stripped output contains whitespace character '{ch}'"

