tests_src:
def test_exact(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    if n > 10:
        return
    a = list(map(int, lines[1].split()))
    # verify strictly increasing as per spec
    for i in range(n-1):
        if a[i] >= a[i+1]:
            return  # skip non‑increasing – spec guarantees increasing
    best = float('inf')
    for remove in range(1, n-1):
        diff = []
        for i in range(n-1):
            if i == remove:
                # gap that replaces a[remove] - a[remove-1] and a[remove+1] - a[remove]
                diff.append(a[remove+1] - a[remove-1])
            elif i+1 != remove:
                # original gap not involving removed element
                diff.append(a[i+1] - a[i])
        best = min(best, max(diff))
    expected = str(best) + '\n'
    assert run(x) == expected

def test_integer(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False, f'output "{out}" is not an integer'

def test_positive(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    n = len(a)
    for i in range(n-1):
        if a[i] >= a[i+1]:
            return  # skip non‑increasing inputs
    out = run(x).strip()
    val = int(out)
    assert val >= 1

def test_lower_bound_avg(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    n = len(a)
    for i in range(n-1):
        if a[i] >= a[i+1]:
            return  # skip non‑increasing
    if n <= 2:
        return  # not in spec range
    total = a[-1] - a[0]
    lower = (total + (n-2) - 1) // (n-2)  # ceil(total/(n-2))
    out = run(x).strip()
    val = int(out)
    assert val >= lower

def test_lower_bound_min_combined(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    n = len(a)
    for i in range(n-1):
        if a[i] >= a[i+1]:
            return  # skip non‑increasing
    if n < 3:
        return
    min_combined = min(a[i+1] - a[i-1] for i in range(1, n-1))
    out = run(x).strip()
    val = int(out)
    assert val >= min_combined

def test_upper_bound_max_combined(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    n = len(a)
    for i in range(n-1):
        if a[i] >= a[i+1]:
            return  # skip non‑increasing
    if n < 3:
        return
    max_combined = max(a[i+2] - a[i] for i in range(n-2))
    out = run(x).strip()
    val = int(out)
    assert val <= max_combined

def test_in_set_S(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    n = len(a)
    for i in range(n-1):
        if a[i] >= a[i+1]:
            return  # skip non‑increasing
    S = set()
    for i in range(n-1):
        S.add(a[i+1] - a[i])
    for i in range(n-2):
        S.add(a[i+2] - a[i])
    out = run(x).strip()
    val = int(out)
    assert val in S

def test_n3_case(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    n = len(a)
    if n != 3:
        return
    for i in range(n-1):
        if a[i] >= a[i+1]:
            return  # skip non‑increasing
    expected = a[2] - a[0]
    out = run(x).strip()
    val = int(out)
    assert val == expected

def test_arithmetic_progression(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    n = len(a)
    for i in range(n-1):
        if a[i] >= a[i+1]:
            return  # skip non‑increasing
    d = a[1] - a[0]
    if all(a[i+1] - a[i] == d for i in range(n-1)):
        expected = 2 * d
        out = run(x).strip()
        val = int(out)
        assert val == expected

def test_ge_min_original_gap(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    a = list(map(int, lines[1].split()))
    n = len(a)
    for i in range(n-1):
        if a[i] >= a[i+1]:
            return  # skip non‑increasing
    min_gap = min(a[i+1] - a[i] for i in range(n-1))
    out = run(x).strip()
    val = int(out)
    assert val >= min_gap

