def test_exact_brute(run, x):
    # brute-force as in intent 1, but only for small grids
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n * m > 10000:   # safety limit
        return
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    ans = int(run(x).strip())
    computed = 0
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 0:
                # left
                cc = c - 1
                while cc >= 0:
                    if grid[r][cc] == 1:
                        computed += 1
                        break
                    cc -= 1
                # right
                cc = c + 1
                while cc < m:
                    if grid[r][cc] == 1:
                        computed += 1
                        break
                    cc += 1
                # up
                rr = r - 1
                while rr >= 0:
                    if grid[rr][c] == 1:
                        computed += 1
                        break
                    rr -= 1
                # down
                rr = r + 1
                while rr < n:
                    if grid[rr][c] == 1:
                        computed += 1
                        break
                    rr += 1
    assert ans == computed

def test_prefix_sum(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n * m > 10000:
        return
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    ans = int(run(x).strip())
    # row prefix
    row_pref = [[0]*(m+1) for _ in range(n)]
    for r in range(n):
        for c in range(m):
            row_pref[r][c+1] = row_pref[r][c] + grid[r][c]
    # column prefix
    col_pref = [[0]*(n+1) for _ in range(m)]
    for c in range(m):
        for r in range(n):
            col_pref[c][r+1] = col_pref[c][r] + grid[r][c]
    computed = 0
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 0:
                if c > 0 and row_pref[r][c] > 0:
                    computed += 1
                if row_pref[r][m] - row_pref[r][c+1] > 0:
                    computed += 1
                if r > 0 and col_pref[c][r] > 0:
                    computed += 1
                if col_pref[c][n] - col_pref[c][r+1] > 0:
                    computed += 1
    assert ans == computed

def test_per_direction(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n * m > 10000:
        return
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    ans = int(run(x).strip())
    computed = 0
    # right
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 0:
                ok = False
                cc = c + 1
                while cc < m and not ok:
                    if grid[r][cc] == 1:
                        ok = True
                    cc += 1
                if ok:
                    computed += 1
    # left
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 0:
                ok = False
                cc = c - 1
                while cc >= 0 and not ok:
                    if grid[r][cc] == 1:
                        ok = True
                    cc -= 1
                if ok:
                    computed += 1
    # down
    for c in range(m):
        for r in range(n):
            if grid[r][c] == 0:
                ok = False
                rr = r + 1
                while rr < n and not ok:
                    if grid[rr][c] == 1:
                        ok = True
                    rr += 1
                if ok:
                    computed += 1
    # up
    for c in range(m):
        for r in range(n):
            if grid[r][c] == 0:
                ok = False
                rr = r - 1
                while rr >= 0 and not ok:
                    if grid[rr][c] == 1:
                        ok = True
                    rr -= 1
                if ok:
                    computed += 1
    assert ans == computed

def test_output_format(run, x):
    out = run(x).strip()
    # must be an integer
    num = int(out)
    # non‑negative because count of positions
    assert num >= 0

def test_upper_bound_zeros(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    zeros = sum(row.count(0) for row in grid)
    bound = 4 * zeros
    ans = int(run(x).strip())
    assert ans <= bound

def test_upper_bound_rowcol(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    bound = 0
    # rows with at least one actor
    for r in range(n):
        if any(grid[r][c] == 1 for c in range(m)):
            zeros = sum(1 for c in range(m) if grid[r][c] == 0)
            bound += 2 * zeros
    # columns with at least one actor
    for c in range(m):
        if any(grid[r][c] == 1 for r in range(n)):
            zeros = sum(1 for r in range(n) if grid[r][c] == 0)
            bound += 2 * zeros
    ans = int(run(x).strip())
    assert ans <= bound

def test_lower_bound_non_isolated(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n * m > 10000:
        return
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    ans = int(run(x).strip())
    lower = 0
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 0:
                # check any direction has an actor
                left = any(grid[r][cc] == 1 for cc in range(c))
                right = any(grid[r][cc] == 1 for cc in range(c+1, m))
                up = any(grid[rr][c] == 1 for rr in range(r))
                down = any(grid[rr][c] == 1 for rr in range(r+1, n))
                if left or right or up or down:
                    lower += 1
    assert ans >= lower

def test_consistency_rows_columns(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n * m > 10000:
        return
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    ans = int(run(x).strip())
    # horizontal
    horiz = 0
    for r in range(n):
        row = grid[r]
        for c in range(m):
            if row[c] == 0:
                # left
                if any(row[cc] == 1 for cc in range(c)):
                    horiz += 1
                # right
                if any(row[cc] == 1 for cc in range(c+1, m)):
                    horiz += 1
    # vertical
    vert = 0
    for c in range(m):
        for r in range(n):
            if grid[r][c] == 0:
                # up
                if any(grid[rr][c] == 1 for rr in range(r)):
                    vert += 1
                # down
                if any(grid[rr][c] == 1 for rr in range(r+1, n)):
                    vert += 1
    assert ans == horiz + vert

def test_suffix_sum(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n * m > 10000:
        return
    grid = [list(map(int, lines[i+1].split())) for i in range(n)]
    ans = int(run(x).strip())
    # row prefix and suffix
    row_pref = [[0]*(m+1) for _ in range(n)]
    row_suff = [[0]*(m+2) for _ in range(n)]
    for r in range(n):
        for c in range(m):
            row_pref[r][c+1] = row_pref[r][c] + grid[r][c]
        for c in range(m, 0, -1):
            row_suff[r][c] = row_suff[r][c+1] + grid[r][c-1]
    # column prefix and suffix
    col_pref = [[0]*(n+1) for _ in range(m)]
    col_suff = [[0]*(n+2) for _ in range(m)]
    for c in range(m):
        for r in range(n):
            col_pref[c][r+1] = col_pref[c][r] + grid[r][c]
        for r in range(n, 0, -1):
            col_suff[c][r] = col_suff[c][r+1] + grid[r-1][c]
    computed = 0
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 0:
                if row_pref[r][c] > 0:
                    computed += 1
                if row_suff[r][c+2] > 0:
                    computed += 1
                if col_pref[c][r] > 0:
                    computed += 1
                if col_suff[c][r+2] > 0:
                    computed += 1
    assert ans == computed

def test_direction_first(run, x):
