tests_src:
def test_small_n_bruteforce(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 4:
        return
    p = lines[1].strip()
    if m == 0:
        y = []
    else:
        y = list(map(int, lines[2].split()))
    MOD = 10**9 + 7
    from itertools import product
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    count = 0
    for chars in product(alphabet, repeat=n):
        s = ''.join(chars)
        ok = True
        for pos in y:
            if s[pos-1:pos-1+len(p)] != p:
                ok = False
                break
        if ok:
            count += 1
    ans = int(run(x).strip())
    assert ans == count % MOD

def test_power_of_26(run, x):
    MOD = 10**9 + 7
    ans_str = run(x).strip()
    try:
        ans = int(ans_str)
    except ValueError:
        raise AssertionError('Output not an integer')
    if ans == 0:
        return
    for k in range(0, 1000001):
        if pow(26, k, MOD) == ans:
            return
    raise AssertionError('Answer is not 0 nor a power of 26 modulo MOD')

def test_no_constraints(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if m != 0:
        return
    MOD = 10**9 + 7
    expected = pow(26, n, MOD)
    ans = int(run(x).strip())
    assert ans == expected

def test_non_overlapping(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    p = lines[1].strip()
    if m == 0:
        return
    y = list(map(int, lines[2].split()))
    lp = len(p)
    overlap = False
    for i in range(m-1):
        if y[i+1] < y[i] + lp:
            overlap = True
            break
    if overlap:
        return
    MOD = 10**9 + 7
    expected = pow(26, n - m * lp, MOD)
    ans = int(run(x).strip())
    assert ans == expected

def test_inconsistent_overlap(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    p = lines[1].strip()
    if m < 2:
        return
    y = list(map(int, lines[2].split()))
    lp = len(p)
    for i in range(m):
        for j in range(i+1, m):
            d = y[j] - y[i]
            if d < lp:
                if p[:lp-d] != p[d:]:
                    ans = int(run(x).strip())
                    assert ans == 0
                    return
    return

def test_small_m_direct(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if m > 10:
        return
    p = lines[1].strip()
    if m == 0:
        y = []
    else:
        y = list(map(int, lines[2].split()))
    lp = len(p)
    for i in range(m):
        for j in range(i+1, m):
            d = y[j] - y[i]
            if d < lp and p[:lp-d] != p[d:]:
                ans = int(run(x).strip())
                assert ans == 0
                return
    intervals = [(y[i]-1, y[i]-1+lp) for i in range(m)]
    union = []
    for begin, end in sorted(intervals):
        if not union or union[-1][1] < begin:
            union.append([begin, end])
        else:
            union[-1][1] = max(union[-1][1], end)
    free = n
    for begin, end in union:
        free -= (end - begin)
    MOD = 10**9 + 7
    expected = pow(26, free, MOD)
    ans = int(run(x).strip())
    assert ans == expected

def test_output_format(run, x):
