def test_arithmetic_periodic(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if m < 2:
        return
    p = lines[1].strip()
    y = list(map(int, lines[2].split()))
    lp = len(p)
    d = y[1] - y[0]
    if d >= lp:
        return
    ok = True
    for i in range(m-1):
        if y[i+1] - y[i] != d:
            ok = False
            break
    if not ok:
        return
    if p[:lp-d] != p[d:]:
        return
    union_size = lp + (m-1) * d
    MOD = 10**9 + 7
    expected = pow(26, n - union_size, MOD)
    ans = int(run(x).strip())
    assert ans == expected

def test_single_char_p(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    p = lines[1].strip()
    if len(p) != 1:
        return
    MOD = 10**9 + 7
    expected = pow(26, n - m, MOD)
    ans = int(run(x).strip())
    assert ans == expected

def test_constant_p(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    p = lines[1].strip()
    if m == 0:
        return
    if len(set(p)) != 1:
        return
    y = list(map(int, lines[2].split()))
    lp = len(p)
    intervals = [(y[i]-1, y[i]-1+lp) for i in range(m)]
    union = []
    for begin, end in sorted(intervals):
        if not union or union[-1][1] < begin:
            union.append([begin, end])
        else:
            union[-1][1] = max(union[-1][1], end)
    free = n
    for begin, end in union:
        free -= (end - begin)
    MOD = 10**9 + 7
    expected = pow(26, free, MOD)
    ans = int(run(x).strip())
    assert ans == expected

