    out_lines = output.strip().splitlines()
    assert len(out_lines) == n, f'Expected {n} lines, got {len(out_lines)}'

def test_valid_strings(run, x):
    output = run(x)
    out_lines = output.strip().splitlines()
    allowed = {"Freda's", "Rainbow's", "OMG>.< I don't know!"}
    for line in out_lines:
        assert line in allowed, f'Invalid output line: {line}'

def test_freda_condition(run, x):
    lines = x.strip().splitlines()[1:]
    output = run(x)
    out_lines = output.strip().splitlines()
    for sent, out in zip(lines, out_lines):
        if sent.endswith('lala.') and not sent.startswith('miao.'):
            assert out == "Freda's", f'Freda condition failed: {sent}'

def test_rainbow_condition(run, x):
    lines = x.strip().splitlines()[1:]
    output = run(x)
    out_lines = output.strip().splitlines()
    for sent, out in zip(lines, out_lines):
        if sent.startswith('miao.') and not sent.endswith('lala.'):
            assert out == "Rainbow's", f'Rainbow condition failed: {sent}'

def test_both_condition(run, x):
    lines = x.strip().splitlines()[1:]
    output = run(x)
    out_lines = output.strip().splitlines()
    for sent, out in zip(lines, out_lines):
        if sent.startswith('miao.') and sent.endswith('lala.'):
            assert out == "OMG>.< I don't know!", f'Both condition failed: {sent}'

def test_neither_condition(run, x):
    lines = x.strip().splitlines()[1:]
    output = run(x)
    out_lines = output.strip().splitlines()
    for sent, out in zip(lines, out_lines):
        if not sent.startswith('miao.') and not sent.endswith('lala.'):
            assert out == "OMG>.< I don't know!", f'Neither condition failed: {sent}'

def test_no_rainbow_if_lala(run, x):
    lines = x.strip().splitlines()[1:]
    output = run(x)
    out_lines = output.strip().splitlines()
    for sent, out in zip(lines, out_lines):
        if sent.endswith('lala.'):
            assert out != "Rainbow's", f'Rainbow output not allowed for lala. sentence: {sent}'

def test_no_freda_if_miao(run, x):
    lines = x.strip().splitlines()[1:]
    output = run(x)
    out_lines = output.strip().splitlines()
    for sent, out in zip(lines, out_lines):
        if sent.startswith('miao.'):
            assert out != "Freda's", f'Freda output not allowed for miao. sentence: {sent}'

def test_consistent_for_identical_sentences(run, x):
    lines = x.strip().splitlines()[1:]
    output = run(x)
    out_lines = output.strip().splitlines()
    groups = {}
    for idx, sent in enumerate(lines):
        groups.setdefault(sent, []).append(idx)
    for sent, indices in groups.items():
        outputs = [out_lines[i] for i in indices]
        assert all(o == outputs[0] for o in outputs), f'Inconsistent outputs for identical sentence: {sent}'

def test_full_bruteforce(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0])
    if n > 10:  # spec says n <= 10, but guard anyway
        return
    sentences = lines[1:]
