def test_reference(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    sentences = lines[1:1+n]
    expected = []
    for s in sentences:
        starts = s.startswith('miao.')
        ends = s.endswith('lala.')
        if ends and not starts:
            expected.append("Freda's")
        elif starts and not ends:
            expected.append("Rainbow's")
        else:
            expected.append("OMG>.< I don't know!")
    expected_str = '\n'.join(expected) + ('\n' if n > 0 else '')
    assert run(x) == expected_str

def test_output_structure(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    output = run(x)
    out_lines = output.rstrip('\n').split('\n')
    if output.endswith('\n'):
        out_lines = output[:-1].split('\n')
    assert len(out_lines) == n
    allowed = {"Freda's", "Rainbow's", "OMG>.< I don't know!"}
    for line in out_lines:
        assert line in allowed

def test_freda_condition(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    sentences = lines[1:1+n]
    output = run(x)
    out_lines = output.rstrip('\n').split('\n')
    if output.endswith('\n'):
        out_lines = output[:-1].split('\n')
    for s, out in zip(sentences, out_lines):
        if s.endswith('lala.') and not s.startswith('miao.'):
            assert out == "Freda's"

def test_rainbow_condition(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    sentences = lines[1:1+n]
    output = run(x)
    out_lines = output.rstrip('\n').split('\n')
    if output.endswith('\n'):
        out_lines = output[:-1].split('\n')
    for s, out in zip(sentences, out_lines):
        if s.startswith('miao.') and not s.endswith('lala.'):
            assert out == "Rainbow's"

def test_both_condition(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    sentences = lines[1:1+n]
    output = run(x)
    out_lines = output.rstrip('\n').split('\n')
    if output.endswith('\n'):
        out_lines = output[:-1].split('\n')
    for s, out in zip(sentences, out_lines):
        if s.startswith('miao.') and s.endswith('lala.'):
            assert out == "OMG>.< I don't know!"

def test_neither_condition(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    sentences = lines[1:1+n]
    output = run(x)
    out_lines = output.rstrip('\n').split('\n')
