def test_freda_converse(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    sentences = lines[1:1+n]
    output = run(x)
    out_lines = output.rstrip('\n').split('\n')
    if output.endswith('\n'):
        out_lines = output[:-1].split('\n')
    for s, out in zip(sentences, out_lines):
        if out == "Freda's":
            assert s.endswith('lala.') and not s.startswith('miao.')

def test_rainbow_converse(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    sentences = lines[1:1+n]
    output = run(x)
    out_lines = output.rstrip('\n').split('\n')
    if output.endswith('\n'):
        out_lines = output[:-1].split('\n')
    for s, out in zip(sentences, out_lines):
        if out == "Rainbow's":
            assert s.startswith('miao.') and not s.endswith('lala.')

def test_omg_converse(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    sentences = lines[1:1+n]
    output = run(x)
    out_lines = output.rstrip('\n').split('\n')
    if output.endswith('\n'):
        out_lines = output[:-1].split('\n')
    for s, out in zip(sentences, out_lines):
        if out == "OMG>.< I don't know!":
            assert (s.startswith('miao.') and s.endswith('lala.')) or (not s.startswith('miao.') and not s.endswith('lala.'))

def test_line_count(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    output = run(x)
    out_lines = output.rstrip('\n').split('\n')
    if output.endswith('\n'):
        out_lines = output[:-1].split('\n')
    assert len(out_lines) == n

