def test_format(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if not lines:
        assert False, 'empty output'
    first = lines[0].strip()
    assert first in ('Yes', 'No'), "first line must be 'Yes' or 'No'"
    if first == 'Yes':
        assert len(lines) >= 3, "Yes must have two more lines"
        n, m = map(int, x.strip().split('\n')[0].split())
        second = lines[1].strip().split()
        third = lines[2].strip().split()
        assert len(second) == n, f"second line must have {n} numbers"
        assert len(third) == m, f"third line must have {m} numbers"
        try:
            [int(v) for v in second]
            [int(v) for v in third]
        except ValueError:
            assert False, "numbers must be integers"
    else:
        assert len(lines) == 1, "No must have no further lines"

def test_positive(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if lines[0].strip() == 'Yes':
        n, m = map(int, x.strip().split('\n')[0].split())
        vals1 = list(map(int, lines[1].strip().split()))
        vals2 = list(map(int, lines[2].strip().split()))
        assert all(v >= 1 for v in vals1 + vals2), "all numbers must be positive integers"

def test_direct_constraints(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if lines[0].strip() != 'Yes':
        return
    n, m = map(int, x.strip().split('\n')[0].split())
    table = [list(line.strip()) for line in x.strip().split('\n')[1:]]
    vals1 = list(map(int, lines[1].strip().split()))
    vals2 = list(map(int, lines[2].strip().split()))
    for i in range(n):
        for j in range(m):
            if table[i][j] == '<':
                assert vals1[i] < vals2[j], f"{vals1[i]} < {vals2[j]} violated at ({i},{j})"
            elif table[i][j] == '>':
                assert vals1[i] > vals2[j], f"{vals1[i]} > {vals2[j]} violated at ({i},{j})"
            else:
                assert vals1[i] == vals2[j], f"{vals1[i]} == {vals2[j]} violated at ({i},{j})"

def test_equality_classes(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if lines[0].strip() != 'Yes':
        return
    n, m = map(int, x.strip().split('\n')[0].split())
    table = [list(line.strip()) for line in x.strip().split('\n')[1:]]
    vals1 = list(map(int, lines[1].strip().split()))
    vals2 = list(map(int, lines[2].strip().split()))
    # Build graph of dishes 0..n-1 (first set) and n..n+m-1 (second set)
    from collections import defaultdict
    adj = defaultdict(set)
    for i in range(n):
        for j in range(m):
            if table[i][j] == '=':
                adj[i].add(n + j)
                adj[n + j].add(i)
    # BFS to find connected components
    visited = [False] * (n + m)
    comp_id = [-1] * (n + m)
    comp_val = []
    from collections import deque
    for v in range(n + m):
        if not visited[v]:
            q = deque([v])
            visited[v] = True
            comp_vals = []
            while q:
                u = q.popleft()
                comp_id[u] = len(comp_val)
                if u < n:
                    comp_vals.append(vals1[u])
                else:
                    comp_vals.append(vals2[u - n])
                for w in adj[u]:
                    if not visited[w]:
                        visited[w] = True
                        q.append(w)
            comp_val.append(comp_vals)
    # All values in a component must be equal
    for comp in comp_val:
        if len(set(comp)) != 1:
            assert False, "dishes in same equality class must have same number"

def test_upper_bound(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if lines[0].strip() != 'Yes':
        return
    n, m = map(int, x.strip().split('\n')[0].split())
    vals1 = list(map(int, lines[1].strip().split()))
    vals2 = list(map(int, lines[2].strip().split()))
    assert max(vals1 + vals2) <= n + m, f"max number {max(vals1 + vals2)} exceeds n+m={n+m}"

def test_all_equal(run, x):
    n, m = map(int, x.strip().split('\n')[0].split())
    table = [list(line.strip()) for line in x.strip().split('\n')[1:]]
    all_eq = all(c == '=' for row in table for c in row)
    if not all_eq:
        return
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    assert lines[0].strip() == 'Yes', "all '=' must be feasible"
    vals1 = list(map(int, lines[1].strip().split()))
    vals2 = list(map(int, lines[2].strip().split()))
    assert all(v == 1 for v in vals1 + vals2), "all numbers must be 1 when all '='"

