    n, m = map(int, x.strip().split('\n')[0].split())
    table = [list(line.strip()) for line in x.strip().split('\n')[1:]]
    all_gt = all(c == '>' for row in table for c in row)
    all_lt = all(c == '<' for row in table for c in row)
    if not (all_gt or all_lt):
        return
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    assert lines[0].strip() == 'Yes', f"all '{'>' if all_gt else '<'}' must be feasible"
    vals1 = list(map(int, lines[1].strip().split()))
    vals2 = list(map(int, lines[2].strip().split()))
    if all_gt:
        assert len(set(vals1)) == 1, "first-set numbers must all be equal"
        assert len(set(vals2)) == 1, "second-set numbers must all be equal"
        assert vals1[0] == vals2[0] + 1, f"first-set {vals1[0]} must be one greater than second-set {vals2[0]}"
    if all_lt:
        assert len(set(vals1)) == 1, "first-set numbers must all be equal"
        assert len(set(vals2)) == 1, "second-set numbers must all be equal"
        assert vals2[0] == vals1[0] + 1, f"second-set {vals2[0]} must be one greater than first-set {vals1[0]}"

