def test_bruteforce(run, x):
    # Efficient simulation using last timestamps per row/col.
    lines = x.strip().split('\n')
    if not lines:
        return
    n, m, k = map(int, lines[0].split())
    # last_color and last_time for rows and columns
    row_color = [0] * (n+1)  # 1-indexed
    row_time = [-1] * (n+1)
    col_color = [0] * (m+1)
    col_time = [-1] * (m+1)
    for idx, line in enumerate(lines[1:1+k]):
        parts = line.split()
        if parts[0] == '1':
            r = int(parts[1])
            a = int(parts[2])
            row_color[r] = a
            row_time[r] = idx
        else:
            c = int(parts[1])
            a = int(parts[2])
            col_color[c] = a
            col_time[c] = idx
    out = run(x)
    out_lines = out.strip('\n').split('\n')
    if len(out_lines) != n:
        return  # will be caught by dimensions test
    for i in range(n):
        vals = out_lines[i].split()
        if len(vals) != m:
            return
        for j in range(m):
            val = int(vals[j])
            r, c = i+1, j+1
            if row_time[r] > col_time[c]:
                expected = row_color[r]
            else:
                expected = col_color[c]
            if val != expected:
                assert False, f'Cell ({i+1},{j+1}) expected {expected}, got {val}'

def test_dimensions(run, x):
    lines = x.strip().split('\n')
    n, m, _ = map(int, lines[0].split())
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    assert len(out_lines) == n, f'Expected {n} lines, got {len(out_lines)}'
    for i, line in enumerate(out_lines):
        parts = line.split()
        assert len(parts) == m, f'Line {i+1}: expected {m} numbers, got {len(parts)}'

def test_color_range(run, x):
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    for line in out_lines:
        for part in line.split():
            val = int(part)
            assert 0 <= val <= 10**9, f'Color {val} out of range'

def test_row_uniformity(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    row_time = [-1] * (n+1)
    row_color = [0] * (n+1)
    col_max_time = -1
    for idx, line in enumerate(lines[1:1+k]):
        parts = line.split()
        if parts[0] == '1':
            r = int(parts[1])
            a = int(parts[2])
            row_time[r] = idx
            row_color[r] = a
        else:
            c = int(parts[1])
            a = int(parts[2])
            col_max_time = max(col_max_time, idx)
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    for i in range(n):
        r = i+1
        if row_time[r] > col_max_time:
            expected = row_color[r]
            vals = out_lines[i].split()
            for j in range(m):
                val = int(vals[j])
                assert val == expected, f'Row {r} should be uniform {expected}, got {val} at column {j+1}'

def test_column_uniformity(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    col_time = [-1] * (m+1)
    col_color = [0] * (m+1)
    row_max_time = -1
    for idx, line in enumerate(lines[1:1+k]):
        parts = line.split()
        if parts[0] == '1':
            r = int(parts[1])
            a = int(parts[2])
            row_max_time = max(row_max_time, idx)
        else:
            c = int(parts[1])
            a = int(parts[2])
            col_time[c] = idx
            col_color[c] = a
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    # build column lists
    cols = [[] for _ in range(m)]
    for i in range(n):
        vals = out_lines[i].split()
        for j in range(m):
            cols[j].append(int(vals[j]))
    for j in range(m):
        c = j+1
        if col_time[c] > row_max_time:
            expected = col_color[c]
            for i in range(n):
                val = cols[j][i]
                assert val == expected, f'Column {c} should be uniform {expected}, got {val} at row {i+1}'

def test_timestamp_uniqueness(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    row_time = [-1] * (n+1)
    col_time = [-1] * (m+1)
    for idx, line in enumerate(lines[1:1+k]):
        parts = line.split()
        if parts[0] == '1':
            r = int(parts[1])
            row_time[r] = idx
        else:
            c = int(parts[1])
            col_time[c] = idx
    # For any row and column that have been painted, timestamps must be distinct
    for r in range(1, n+1):
        if row_time[r] >= 0:
            for c in range(1, m+1):
                if col_time[c] >= 0:
                    assert row_time[r] != col_time[c], f'Row {r} and column {c} have same last timestamp {row_time[r]}'
    # This property holds for correct solutions, but we don't need output.
    # Just run to get output (to ensure we call run once).
    run(x)

def test_last_operation_consistency(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    row_time = [-1] * (n+1)
    row_color = [0] * (n+1)
    col_time = [-1] * (m+1)
    col_color = [0] * (m+1)
    for idx, line in enumerate(lines[1:1+k]):
        parts = line.split()
        if parts[0] == '1':
            r = int(parts[1])
            a = int(parts[2])
            row_time[r] = idx
            row_color[r] = a
        else:
            c = int(parts[1])
            a = int(parts[2])
            col_time[c] = idx
            col_color[c] = a
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    for i in range(n):
        vals = out_lines[i].split()
        for j in range(m):
            val = int(vals[j])
            r, c = i+1, j+1
            if row_time[r] > col_time[c]:
                expected = row_color[r]
                assert val == expected, f'Cell ({r},{c}) expected row color {expected}, got {val}'
            elif col_time[c] > row_time[r]:
                expected = col_color[c]
                assert val == expected, f'Cell ({r},{c}) expected column color {expected}, got {val}'

def test_no_extra_colors(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    allowed = {0}
    for line in lines[1:1+k]:
        parts = line.split()
        a = int(parts[2])
        allowed.add(a)
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    for line in out_lines:
        for part in line.split():
            val = int(part)
            assert val in allowed, f'Color {val} not in allowed set'

def test_last_operation_overall(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if k == 0:
        return
    last_op = lines[k].split()  # because lines[0] is n m k, lines[1]..lines[k] are ops
    typ = last_op[0]
    pos = int(last_op[1])
    a = int(last_op[2])
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    if typ == '1':
        # row operation
        row_vals = out_lines[pos-1].split()
        for j in range(m):
            val = int(row_vals[j])
            assert val == a, f'Row {pos} column {j+1} should be {a}, got {val}'
    else:
        # column operation
        col_idx = pos-1
        for i in range(n):
            vals = out_lines[i].split()
            val = int(vals[col_idx])
            assert val == a, f'Column {pos} row {i+1} should be {a}, got {val}'

def test_single_operation(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if k != 1:
        return
    op = lines[1].split()
    typ = op[0]
    pos = int(op[1])
    a = int(op[2])
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    if typ == '1':
        # row pos should be all a, others all 0
        for i in range(n):
            vals = out_lines[i].split()
            for j in range(m):
                val = int(vals[j])
                if i+1 == pos:
                    assert val == a, f'Row {pos} should be all {a}, got {val} at column {j+1}'
                else:
                    assert val == 0, f'Row {i+1} should be all 0, got {val}'
    else:
        # column pos should be all a, others all 0
        for i in range(n):
            vals = out_lines[i].split()
            for j in range(m):
                val = int(vals[j])
                if j+1 == pos:
                    assert val == a, f'Column {pos} should be all {a}, got {val} at row {i+1}'
                else:
                    assert val == 0, f'Column {j+1} should be 0, got {val}'

