def test_cycle_consistency(run, x):
    lines_in = x.strip().split('\n')
    n, m = map(int, lines_in[0].split())
    table = lines_in[1:1+n]
    # Build equivalence classes
    parent = list(range(n + m))
    rank = [0]*(n + m)
    def find(v):
        while parent[v] != v:
            parent[v] = parent[parent[v]]
            v = parent[v]
        return v
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
    for i in range(n):
        for j in range(m):
            if table[i][j] == '=':
                union(i, n + j)
    # Build graph of classes
    comp_id = {}
    ids = []
    for v in range(n + m):
        r = find(v)
        if r not in comp_id:
            comp_id[r] = len(ids)
            ids.append(r)
    k = len(ids)
    comp = [comp_id[find(v)] for v in range(n + m)]
    adj = [[] for _ in range(k)]
    indeg = [0]*k
    for i in range(n):
        ci = comp[i]
        for j in range(m):
            cj = comp[n + j]
            if table[i][j] == '<':
                if ci != cj:
                    adj[ci].append(cj)
            elif table[i][j] == '>':
                if ci != cj:
                    adj[cj].append(ci)
    for u in range(k):
        adj[u] = list(set(adj[u]))
        for v in adj[u]:
            indeg[v] += 1
    # Detect cycle with Kahn's
    from collections import deque
    q = deque([u for u in range(k) if indeg[u] == 0])
    topo = []
    indeg2 = indeg[:]
    while q:
        u = q.popleft()
        topo.append(u)
        for v in adj[u]:
            indeg2[v] -= 1
            if indeg2[v] == 0:
                q.append(v)
    has_cycle = (len(topo) != k)
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    first = out_lines[0].strip()
    if has_cycle:
        assert first == 'No', f'Cycle exists but output is {first}'
    else:
        assert first == 'Yes', f'No cycle but output is {first}'


