def test_transitive_inequalities(run, x):
    lines_in = x.strip().split('\n')
    n, m = map(int, lines_in[0].split())
    table = lines_in[1:1+n]
    # Build equivalence classes
    parent = list(range(n + m))
    rank = [0]*(n + m)
    def find(v):
        while parent[v] != v:
            parent[v] = parent[parent[v]]
            v = parent[v]
        return v
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
    for i in range(n):
        for j in range(m):
            if table[i][j] == '=':
                union(i, n + j)
    # Build graph of classes
    comp_id = {}
    ids = []
    for v in range(n + m):
        r = find(v)
        if r not in comp_id:
            comp_id[r] = len(ids)
            ids.append(r)
    k = len(ids)
    comp = [comp_id[find(v)] for v in range(n + m)]
    adj = [[] for _ in range(k)]
    for i in range(n):
        ci = comp[i]
        for j in range(m):
            cj = comp[n + j]
            if table[i][j] == '<':
                if ci != cj:
                    adj[ci].append(cj)
            elif table[i][j] == '>':
                if ci != cj:
                    adj[cj].append(ci)
    for u in range(k):
        adj[u] = list(set(adj[u]))
    # Compute reachability (Floyd-Warshall) because k ≤ n+m ≤ 2000, but worst-case k=2000 -> O(k^3) too big.
    # Instead, we only check direct edges and rely on the DAG property (already verified in cycle test).
    # For transitive inequalities, we can compute longest paths if k is small enough (≤ 100).
    if k > 100:
        # Too large; skip transitive check
        return
    # Compute topological order (should be acyclic if output is Yes)
    indeg = [0]*k
    for u in range(k):
        for v in adj[u]:
            indeg[v] += 1
    from collections import deque
    q = deque([u for u in range(k) if indeg[u] == 0])
    topo = []
    indeg2 = indeg[:]
    while q:
        u = q.popleft()
        topo.append(u)
        for v in adj[u]:
            indeg2[v] -= 1
            if indeg2[v] == 0:
                q.append(v)
    # If there is a cycle, we already caught it in cycle_consistency test.
    # Now compute longest path distances
    dist = [0]*k
    for u in topo:
        for v in adj[u]:
            if dist[v] < dist[u] + 1:
                dist[v] = dist[u] + 1
    # Now for every edge (u,v) we already have dist[u] < dist[v]; transitive inequalities are satisfied.
    # But we want to check the output numbers respect these distances.
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    if out_lines[0].strip() != 'Yes':
        return
    vals1 = list(map(int, out_lines[1].split()))
    vals2 = list(map(int, out_lines[2].split()))
    all_vals = vals1 + vals2
    # For each pair of components, if there is a path from comp a to comp b, then value(a) < value(b).
    # Since we have distances, we can check: if dist[a] < dist[b] then value(a) must be <= value(b)? Not necessarily.
    # Actually, the minimal assignment is dist+1, but other assignments could have larger gaps.
    # The only guarantee from specification is that if there is a directed path, then for every dish in a and b, value(a) < value(b).
    # So we compute reachability via BFS from each node (k is ≤ 100 here).
    reach = [[False]*k for _ in range(k)]
    for u in range(k):
        reach[u][u] = True
        for v in adj[u]:
            reach[u][v] = True
    # Floyd-Warshall for transitive closure
    for w in range(k):
        for i in range(k):
            if reach[i][w]:
                row_i = reach[i]
                row_w = reach[w]
                for j in range(k):
                    if row_w[j]:
                        row_i[j] = True
    # Now check all pairs
    for a in range(k):
        for b in range(k):
            if a != b and reach[a][b]:
                # any dish in a must have value < any dish in b
                # pick first dish in each component
                dish_a = next(v for v in range(n+m) if comp[v] == a)
                dish_b = next(v for v in range(n+m) if comp[v] == b)
                assert all_vals[dish_a] < all_vals[dish_b], f'Transitive inequality violated: component {a} -> {b}'


def test_no_self_inequality(run, x):
    lines_in = x.strip().split('\n')
    n, m = map(int, lines_in[0].split())
    table = lines_in[1:1+n]
    # Check if there exists a dish pair (i from first, j from second) such that they are connected by '=' (directly or indirectly)
    # but have a '<' or '>' relation in the table.
    # Build equivalence classes
    parent = list(range(n + m))
    rank = [0]*(n + m)
    def find(v):
        while parent[v] != v:
            parent[v] = parent[parent[v]]
            v = parent[v]
        return v
    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            parent[ra] = rb
        elif rank[ra] > rank[rb]:
            parent[rb] = ra
        else:
            parent[rb] = ra
            rank[ra] += 1
    for i in range(n):
        for j in range(m):
            if table[i][j] == '=':
                union(i, n + j)
    # Now check each cell for contradiction
    contradiction_found = False
    for i in range(n):
        for j in range(m):
            if table[i][j] != '=' and find(i) == find(n + j):
                contradiction_found = True
                break
        if contradiction_found:
            break
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    first = out_lines[0].strip()
    if contradiction_found:
        assert first == 'No', f'Direct equality-incompatible relation but output is {first}'
    # If no contradiction, we cannot assert Yes because there might be a cycle.

