def test_integer(run, x):
    out = run(x)
    # Parse as integer; if parsing fails, the answer is wrong.
    try:
        int(out.strip())
    except ValueError:
        assert False, "Output must be a valid integer"

def test_nonnegative(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 0, "Output must be nonnegative"

def test_upper_bound(run, x):
    n = int(x.strip())
    out = run(x)
    val = int(out.strip())
    # Each M_i < P_i, sum of all P_i = n*(n+1)//2, so total < n*(n+1)//2.
    assert val < n * (n + 1) // 2, "Output must be strictly less than n*(n+1)//2"

def test_lower_bound(run, x):
    n = int(x.strip())
    out = run(x)
    val = int(out.strip())
    # The permutation P_i = i+1 for i < N, P_N = 1 achieves sum n*(n-1)//2.
    assert val >= n * (n - 1) // 2, "Output must be at least n*(n-1)//2"

def test_small_exact(run, x):
    n = int(x.strip())
    if n > 10:
        return  # Pass without checking for larger N.
    # Enumerate all permutations, compute max sum.
    import itertools
    best = -1
    for perm in itertools.permutations(range(1, n + 1)):
        total = 0
        for i in range(1, n + 1):
            total += i % perm[i - 1]
        if total > best:
            best = total
    out = run(x)
    val = int(out.strip())
    assert val == best, f"For N={n}, expected {best}, got {val}"

def test_no_leading_zeros(run, x):
    out = run(x)
    s = out.rstrip('\n')
    if s != '0':
        assert not s.startswith('0'), "Output must not have leading zeros unless it is '0'"

def test_newline(run, x):
    out = run(x)
    assert out.endswith('\n'), "Output must end with a newline"

def test_sample1(run, x):
    n = int(x.strip())
    if n == 1:
        out = run(x)
        val = int(out.strip())
        assert val == 0, "For N=1, output must be 0"

def test_sample2(run, x):
    n = int(x.strip())
    if n == 2:
        out = run(x)
        val = int(out.strip())
        assert val == 1, "For N=2, output must be 1"

def test_n3(run, x):
    n = int(x.strip())
    if n == 3:
        out = run(x)
        val = int(out.strip())
        assert val == 3, "For N=3, output must be 3"

