    while i < n:
        if a[i] == a[i-1] + a[i-2]:
            start = i
            while i < n and a[i] == a[i-1] + a[i-2]:
                i += 1
            run_len = i - start
            cand = run_len + 2  # default case when start > 2
            if start == 2:
                if run_len >= 2:
                    cand = run_len + 1
                else:
                    cand = 2
            if cand > max_run:
                max_run = cand
        else:
            i += 1
    # also consider length 2 always possible
    lower_bound = max(2, max_run)
    ans = int(run(x).strip())
    assert ans >= lower_bound, f'answer {ans} < lower bound {lower_bound} from recurrence runs'

def test_upper_bound_n(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    ans = int(run(x).strip())
    assert ans <= n, f'answer {ans} > n={n}'

def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 20:
        return
    a = list(map(int, lines[1].split()))
    best = 1
    for l in range(n):
        for r in range(l, n):
            ok = True
            for i in range(l+2, r+1):
                if a[i] != a[i-1] + a[i-2]:
                    ok = False
                    break
            if ok:
                best = max(best, r - l + 1)
    ans = int(run(x).strip())
    assert ans == best, f'brute force says answer is {best}, got {ans}'

def test_at_least_three_if_any_triple(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n < 3:
        return
    a = list(map(int, lines[1].split()))
    has_triple = any(a[i] == a[i-1] + a[i-2] for i in range(2, n))
    if has_triple:
        ans = int(run(x).strip())
        assert ans >= 3, f'found i with a[i]=a[i-1]+a[i-2], answer must be >=3, got {ans}'

def test_consistent_with_run_length(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    # compute max consecutive run length of indices i (2 <= i < n) satisfying recurrence
    M = 0
    i = 2
    while i < n:
        if a[i] == a[i-1] + a[i-2]:
            start = i
            while i < n and a[i] == a[i-1] + a[i-2]:
                i += 1
            M = max(M, i - start)
        else:
            i += 1
    ans = int(run(x).strip())
    if ans > 2:
        assert M >= ans - 2, f'answer {ans} > 2 requires run length at least {ans-2}, but max run is {M}'

def test_upper_bound_run_plus_two(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    # compute max consecutive run length of indices i (2 <= i < n) satisfying recurrence
    M = 0
    i = 2
    while i < n:
        if a[i] == a[i-1] + a[i-2]:
            start = i
            while i < n and a[i] == a[i-1] + a[i-2]:
                i += 1
            M = max(M, i - start)
        else:
            i += 1
    ans = int(run(x).strip())
    assert ans <= M + 2, f'answer {ans} exceeds max run length {M} + 2 = {M+2}'

def test_base_cases(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    ans = int(run(x).strip())
    if n == 1:
        assert ans == 1, f'n=1 -> answer must be 1, got {ans}'
    elif n == 2:
        assert ans == 2, f'n=2 -> answer must be 2, got {ans}'

