    },
    {
      "name": "test_at_least_one",
      "source": "def test_at_least_one(run, x):
    out = run(x)
    v = int(out.strip())
    assert v >= 1, 'Length must be at least 1'"
    },
    {
      "name": "test_single_element_case",
      "source": "def test_single_element_case(run, x):
    parts = list(map(int, x.strip().split()))
    X, Y = parts[0], parts[1]
    if X == Y:
        v = int(run(x).strip())
        assert v == 1, 'When X == Y, maximum length must be 1'"
    },
    {
      "name": "test_doubling_lower_bound",
      "source": "def test_doubling_lower_bound(run, x):
    parts = list(map(int, x.strip().split()))
    X, Y = parts[0], parts[1]
    # Minimal growth factor is 2, so length L: start at X, repeatedly multiply by 2 while ≤ Y
    cur = X
    L = 0
    while cur <= Y:
        L += 1
        if cur > Y // 2:  # avoid overflow
            break
        cur *= 2
    v = int(run(x).strip())
    assert v >= L, f'Output {v} < lower bound {L} from doubling sequence'"
    },
    {
      "name": "test_upper_bound_inequality",
      "source": "def test_upper_bound_inequality(run, x):
    parts = list(map(int, x.strip().split()))
    X, Y = parts[0], parts[1]
    v = int(run(x).strip())
    if v == 1:
        return  # inequality trivially holds (X ≤ Y)
    # Need X * 2^{v-1} ≤ Y
    # Compute by repeated doubling with overflow check
    prod = X
    for _ in range(v-1):
        if prod > Y // 2:
            prod = Y + 1  # will exceed Y
            break
        prod *= 2
    assert prod <= Y, f'Output {v} implies last element {prod} > Y'"
    },
    {
      "name": "test_small_Y_brute_force",
      "source": "def test_small_Y_brute_force(run, x):
    parts = list(map(int, x.strip().split()))
    X, Y = parts[0], parts[1]
    if Y > 100:
        return  # skip, too large for brute force
    # Brute‑force search over all possible sequences
    best = 0
    from functools import lru_cache
    @lru_cache(None)
    def dfs(start):
        max_len = 1
        # next element must be a multiple of start, > start, ≤ Y
        mult = 2
        while start * mult <= Y:
            cand = start * mult
            max_len = max(max_len, 1 + dfs(cand))
            mult += 1
        return max_len
    for a1 in range(X, Y+1):
        best = max(best, dfs(a1))
    v = int(run(x).strip())
    assert v == best, f'For Y ≤ 100, output {v} ≠ computed maximum {best}'"
    },
    {
      "name": "test_if_double_possible_then_at_least_two",
      "source": "def test_if_double_possible_then_at_least_two(run, x):
    parts = list(map(int, x.strip().split()))
    X, Y = parts[0], parts[1]
    if 2 * X <= Y:
        v = int(run(x).strip())
        assert v >= 2, f'2*X ≤ Y implies length ≥ 2, got {v}'"
    },
    {
      "name": "test_if_no_double_then_one",
      "source": "def test_if_no_double_then_one(run, x):
    parts = list(map(int, x.strip().split()))
    X, Y = parts[0], parts[1]
    if Y < 2 * X:
        v = int(run(x).strip())
        assert v == 1, f'Y < 2*X implies length = 1, got {v}'"
    },
    {
      "name": "test_output_bounded_by_60",
      "source": "def test_output_bounded_by_60(run, x):
    v = int(run(x).strip())
    assert v <= 60, f'Maximum possible length cannot exceed 60, got {v}'"
    },
    {
      "name": "test_exact_power_of_two_case",
      "source": "def test_exact_power_of_two_case(run, x):
    parts = list(map(int, x.strip().split()))
    X, Y = parts[0], parts[1]
    if Y % X == 0:
        q = Y // X
        # check if q is a power of two
        if q & (q - 1) == 0 and q >= 1:
            k = q.bit_length() - 1
            expected = k + 1
            v = int(run(x).strip())
            assert v == expected, f'Y/X = {q} power of two implies length {expected}, got {v}'"
    }
  ]
}

