def test_output_format(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        raise AssertionError("Output must be a valid integer.")

def test_lower_bound_single(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    max_h = 0
    for i in range(1, n+1):
        _, _, h = map(int, lines[i].split())
        max_h = max(max_h, h)
    ans = int(run(x).strip())
    assert ans >= max_h, f"Answer {ans} is less than maximum single height {max_h}"

def test_upper_bound_total(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    total_h = 0
    for i in range(1, n+1):
        _, _, h = map(int, lines[i].split())
        total_h += h
    ans = int(run(x).strip())
    assert ans <= total_h, f"Answer {ans} exceeds total height {total_h}"

def test_pairwise_lower_bound(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    rings = []
    for i in range(1, n+1):
        a, b, h = map(int, lines[i].split())
        rings.append((a, b, h))
    best = 0
    for i in range(n):
        ai, bi, hi = rings[i]
        best = max(best, hi)
        for j in range(i+1, n):
            aj, bj, hj = rings[j]
            if bj <= bi and bj > ai:
                best = max(best, hi + hj)
            if bi <= bj and bi > aj:
                best = max(best, hi + hj)
    ans = int(run(x).strip())
    assert ans >= best, f"Answer {ans} is less than best pair/single lower bound {best}"

def test_all_same_outer(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 0:
        return
    first_b = None
    total_h = 0
    for i in range(1, n+1):
        a, b, h = map(int, lines[i].split())
        total_h += h
        if first_b is None:
            first_b = b
        elif b != first_b:
            return  # not all same outer radius, test passes
    ans = int(run(x).strip())
    assert ans == total_h, f"All outer radii equal, answer {ans} should equal total height {total_h}"

def test_no_pair_compatible(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    rings = []
    max_h = 0
    for i in range(1, n+1):
        a, b, h = map(int, lines[i].split())
        rings.append((a, b, h))
        max_h = max(max_h, h)
    incompatible = True
    for i in range(n):
        ai, bi, hi = rings[i]
        for j in range(i+1, n):
            aj, bj, hj = rings[j]
            if (bj <= bi and bj > ai) or (bi <= bj and bi > aj):
                incompatible = False
                break
        if not incompatible:
            break
    if incompatible:
        ans = int(run(x).strip())
        assert ans == max_h, f"No pair compatible, answer {ans} must equal max single height {max_h}"

def test_small_exact_dp(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return  # too large, skip
    rings = []
    for i in range(1, n+1):
        a, b, h = map(int, lines[i].split())
        rings.append((a, b, h))
    rings.sort(key=lambda r: (-r[1], -r[0]))  # sort by b descending, then a descending
    dp = [0]*n
    best = 0
    for i in range(n):
        ai, bi, hi = rings[i]
        dp[i] = hi
        for j in range(i):
            _, bj, hj = rings[j]
            if bi > rings[j][0]:  # b_i > a_j
                dp[i] = max(dp[i], hi + dp[j])
        best = max(best, dp[i])
    ans = int(run(x).strip())
    assert ans == best, f"For n <= 10, answer {ans} should equal exact DP result {best}"

def test_example1(run, x):
    example = '3\n1 5 1\n2 6 2\n3 7 3\n'
    if x == example:
        ans = int(run(x).strip())
        assert ans == 6, f"For example 1, answer must be 6, got {ans}"

def test_example2(run, x):
    example = '4\n1 2 1\n1 3 3\n4 6 2\n5 7 1\n'
    if x == example:
        ans = int(run(x).strip())
        assert ans == 4, f"For example 2, answer must be 4, got {ans}"

def test_positive_height(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n >= 1:
        ans = int(run(x).strip())
        assert ans >= 1, f"Answer {ans} must be at least 1 for n >= 1"

