        count = 0
        n = len(s)
        for i in range(n-1):
            if s[i]=='v' and s[i+1]=='v':
                for j in range(i+2, n):
                    if s[j]=='o':
                        for k in range(j+1, n-1):
                            if s[k]=='v' and s[k+1]=='v':
