def test_consistent_with_vv_counts(run, x):
    s = x.strip()
    n = len(s)
    # prefix of vv pairs ending before or at position i
    pref = [0]* (n+1)
    for i in range(1, n):
        pref[i+1] = pref[i] + (1 if s[i-1]=='v' and s[i]=='v' else 0)
    total = 0
    for j in range(n):
        if s[j] == 'o':
            L = pref[j]   # vv pairs strictly before j
            # vv pairs starting strictly after j
            R = pref[n] - pref[j+2]  # because a vv pair at (k,k+1) ends at k+1, we need k > j
            total += L * R
    out = run(x)
    val = int(out.strip())
    assert val == total

