    assert s.isdigit()

def test_lower_bound_single_o(run, x):
    s = x.strip()
    if s.count('o') == 1:
        j = s.index('o')
        L = sum(1 for i in range(j-1) if s[i]=='v' and s[i+1]=='v')
        R = sum(1 for i in range(j+1, len(s)-1) if s[i]=='v' and s[i+1]=='v')
        expected = L * R
        out = run(x)
        val = int(out.strip())
        assert val == expected

