def test_valid_integer(run, x):
    output = run(x)
    val = int(output.strip())
    assert val >= 0, "output must be nonnegative integer"

def test_upper_bound(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    n = int(lines[0])
    from collections import Counter
    cnt = Counter()
    for i in range(1, n+1):
        name = lines[i]
        if name:
            cnt[name[0]] += 1
    total_pairs = sum(v*(v-1)//2 for v in cnt.values())
    output = run(x)
    val = int(output.strip())
    assert val <= total_pairs, f"output {val} exceeds total pairs {total_pairs}"

def test_lower_bound(run, x):
    output = run(x)
    val = int(output.strip())
    assert val >= 0, "output must be nonnegative"

def test_brute_force(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    n = int(lines[0])
    if n > 12:
        return
    names = lines[1:1+n]
    first_letters = [name[0] if name else '' for name in names]
    best = float('inf')
    for mask in range(1 << n):
        cnt0 = {}
        cnt1 = {}
        pairs = 0
        for i in range(n):
            ch = first_letters[i]
            if not ch:
                continue
            if (mask >> i) & 1:
                d = cnt1
            else:
                d = cnt0
            d[ch] = d.get(ch, 0) + 1
            # increment pairs for this classroom only after counting?
            # instead compute after counting all
        # compute pairs from counts
        for d in (cnt0, cnt1):
            for v in d.values():
                pairs += v*(v-1)//2
        if pairs < best:
            best = pairs
    output = run(x)
    val = int(output.strip())
    assert val == best, f"brute force says {best}, got {val}"

def test_example1(run, x):
    example = "4\njorge\njose\noscar\njerry\n"
    if x == example:
        output = run(x)
        assert output == "1\n", f"expected '1\\n', got {repr(output)}"

def test_example2(run, x):
    example = "7\nkambei\ngorobei\nshichiroji\nkyuzo\nheihachi\nkatsushiro\nkikuchiyo\n"
    if x == example:
        output = run(x)
        assert output == "2\n", f"expected '2\\n', got {repr(output)}"

def test_example3(run, x):
    example = "5\nmike\nmike\nmike\nmike\nmike\n"
    if x == example:
        output = run(x)
        assert output == "4\n", f"expected '4\\n', got {repr(output)}"

def test_all_distinct(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    n = int(lines[0])
    names = lines[1:1+n]
    firsts = [name[0] for name in names if name]
    if len(set(firsts)) == len(firsts):
        output = run(x)
        val = int(output.strip())
        assert val == 0, f"all first letters distinct => answer must be 0, got {val}"

def test_single_student(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    n = int(lines[0])
    if n == 1:
        output = run(x)
        val = int(output.strip())
        assert val == 0, f"single student => answer must be 0, got {val}"

def test_same_letter(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    n = int(lines[0])
    names = lines[1:1+n]
    firsts = [name[0] for name in names if name]
    if not firsts:
        return
    if len(set(firsts)) == 1:
        k = len(firsts)
        t = k // 2
        u = k - t
        min_pairs = t*(t-1)//2 + u*(u-1)//2
        output = run(x)
        val = int(output.strip())
        assert val == min_pairs, f"all same first letter => answer must be {min_pairs}, got {val}"

