    a = list(map(int, lines[1].split()))
    ans = int(run(x).strip())
    if n <= 1000:  # keep scan O(n^2) manageable
        found = False
        for i in range(n - ans + 1):
            if sum(a[i:i+ans]) <= t:
                found = True
                break
        assert found, f'No contiguous segment of length {ans} has sum ≤ t'"
    }
  ]
}

