def test_direct(run, x):
    # Compute expected output via specification for small inputs
    lines = x.rstrip('\n').split('\n')
    if len(lines) != 3:
        return  # malformed input; skip
    layout1 = lines[0]
    layout2 = lines[1]
    s = lines[2]
    if len(s) > 1000 or len(layout1) != 26 or len(layout2) != 26:
        return  # ignore invalid inputs according to spec
    # Build mapping from lowercase letters
    mapping = {}
    for c1, c2 in zip(layout1, layout2):
        mapping[c1] = c2
    expected = []
    for ch in s:
        if ch.isalpha():
            lower = ch.lower()
            mapped = mapping.get(lower)
            if mapped is None:
                continue  # should not happen as layout1 contains all letters
            if ch.isupper():
                expected.append(mapped.upper())
            else:
                expected.append(mapped)
        else:
            expected.append(ch)
    expected_str = ''.join(expected)
    output = run(x).rstrip('\n')
    assert output == expected_str, f'Direct computation mismatch: expected {expected_str!r}, got {output!r}'

def test_length(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) != 3:
        return
    s = lines[2]
    output = run(x).rstrip('\n')
    assert len(output) == len(s), f'Length mismatch: input length {len(s)}, output length {len(output)}'

def test_non_letters(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) != 3:
        return
    s = lines[2]
    output = run(x).rstrip('\n')
    for i, ch in enumerate(s):
        if not ch.isalpha():
            assert output[i] == ch, f'Non‑letter at position {i} changed: {ch!r} -> {output[i]!r}'

def test_case_preservation(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) != 3:
        return
    s = lines[2]
    output = run(x).rstrip('\n')
    for i, ch in enumerate(s):
        if ch.isalpha():
            assert output[i].isalpha(), f'Letter became non‑letter at position {i}'
            assert (ch.isupper() and output[i].isupper()) or (ch.islower() and output[i].islower()), \
                f'Case changed at position {i}: {ch!r} -> {output[i]!r}'

def test_consistent_mapping(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) != 3:
        return
    s = lines[2]
    output = run(x).rstrip('\n')
    mapping = {}
    for i, ch in enumerate(s):
        if ch.isalpha():
            key = ch.lower()
            val = output[i].lower()
            if key in mapping:
                assert mapping[key] == val, f'Inconsistent mapping for {key!r}: {mapping[key]!r} vs {val!r}'
            else:
                mapping[key] = val

def test_valid_chars(run, x):
    output = run(x).rstrip('\n')
    for ch in output:
        assert ch.isalnum(), f'Invalid character {ch!r} in output'

def test_digits_unchanged(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) != 3:
        return
    s = lines[2]
    output = run(x).rstrip('\n')
    for i, ch in enumerate(s):
        if ch.isdigit():
            assert output[i] == ch, f'Digit at position {i} changed: {ch!r} -> {output[i]!r}'

def test_inverse(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) != 3:
        return
    layout1 = lines[0]
    layout2 = lines[1]
    s = lines[2]
    output = run(x).rstrip('\n')
    # Build reverse mapping using layout2 as first, layout1 as second
    rev = {c2: c1 for c1, c2 in zip(layout2, layout1)}
    reconstructed = []
    for ch in output:
        if ch.isalpha():
            lower = ch.lower()
            mapped = rev.get(lower)
            if mapped is None:
                continue  # should not happen as layouts are permutations
            if ch.isupper():
                reconstructed.append(mapped.upper())
            else:
                reconstructed.append(mapped)
        else:
            reconstructed.append(ch)
    reconstructed_str = ''.join(reconstructed)
    assert reconstructed_str == s, f'Inverse mapping fails: reconstructed {reconstructed_str!r}, original {s!r}'

def test_output_letters_in_s2(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) != 3:
        return
    layout2 = lines[1]
    output = run(x).rstrip('\n')
    for ch in output:
        if ch.isalpha():
            assert ch.lower() in layout2, f'Letter {ch!r} not in second layout'

def test_mapping_correct(run, x):
    lines = x.rstrip('\n').split('\n')
    if len(lines) != 3:
        return
    layout1 = lines[0]
    layout2 = lines[1]
    s = lines[2]
    output = run(x).rstrip('\n')
    for i, ch in enumerate(s):
        if ch.isalpha():
            idx = layout1.find(ch.lower())
            assert idx != -1, f'Letter {ch!r} not in first layout'
            expected_lower = layout2[idx]
            if ch.isupper():
                expected = expected_lower.upper()
            else:
                expected = expected_lower
            assert output[i] == expected, f'Mapping mismatch at position {i}: expected {expected!r}, got {output[i]!r}'

