tests_src:
def test_length(run, x):
    lines = x.split('\n')
    s = lines[2]
    out = run(x)
    assert len(out) == len(s), f'Length mismatch: {len(out)} vs {len(s)}'

def test_digits(run, x):
    lines = x.split('\n')
    s = lines[2]
    out = run(x)
    for i, ch in enumerate(s):
        if ch.isdigit():
            assert out[i] == ch, f'Digit altered at position {i}: {ch} -> {out[i]}'

def test_non_english_unchanged(run, x):
    lines = x.split('\n')
    s = lines[2]
    out = run(x)
    for i, ch in enumerate(s):
        if not ('A' <= ch <= 'Z' or 'a' <= ch <= 'z' or '0' <= ch <= '9'):
            assert out[i] == ch, f'Non-letter/non-digit altered at {i}: {ch} -> {out[i]}'

def test_case_preservation(run, x):
    lines = x.split('\n')
    s = lines[2]
    out = run(x)
    for i, ch in enumerate(s):
        if 'A' <= ch <= 'Z':
            assert out[i].isupper(), f'Unexpected lowercase at {i} for input uppercase {ch}'
        elif 'a' <= ch <= 'z':
            assert out[i].islower(), f'Unexpected uppercase at {i} for input lowercase {ch}'

def test_output_in_layout2(run, x):
    lines = x.split('\n')
    L2 = lines[1]
    out = run(x)
    for ch in out:
        if ch.isalpha():
            assert ch.lower() in L2, f'Output letter {ch} not in second layout'

def test_inverse_consistency(run, x):
    lines = x.split('\n')
    L1 = lines[0]
    L2 = lines[1]
    s = lines[2]
    out = run(x)
    for i, ch in enumerate(s):
        if 'A' <= ch <= 'Z' or 'a' <= ch <= 'z':
            out_lower = out[i].lower()
            idx = L2.find(out_lower)
            assert idx != -1, f'Output letter {out[i]} not in L2'
            expected_lower = L1[idx]
            assert expected_lower == ch.lower(), f'Inverse mapping mismatch at {i}: {ch} -> {out[i]}'
        else:
            assert out[i] == ch, f'Non-letter mismatch at {i}: {ch} -> {out[i]}'

def test_injectivity(run, x):
    lines = x.split('\n')
    s = lines[2]
    out = run(x)
    # Only need to check positions with English letters; length ≤1000 is safe.
    pos_letters = {}
    for i, ch in enumerate(s):
        if 'A' <= ch <= 'Z' or 'a' <= ch <= 'z':
            key = ch.lower()
            val = out[i].lower()
            if key in pos_letters:
                assert pos_letters[key] == val, f'Input letter {key} maps inconsistently'
            else:
                pos_letters[key] = val
    # Ensure distinct input letters map to distinct output letters
    seen_out = set()
    for inp, out_val in pos_letters.items():
        if out_val in seen_out:
            assert False, f'Two input letters map to same output letter {out_val}'
        seen_out.add(out_val)

def test_direct_mapping_small(run, x):
    lines = x.split('\n')
    L1 = lines[0]
    L2 = lines[1]
    s = lines[2]
    if len(s) <= 100:
        out = run(x)
        expected = []
        for ch in s:
            if 'a' <= ch <= 'z':
                idx = L1.find(ch)
                expected.append(L2[idx])
            elif 'A' <= ch <= 'Z':
                idx = L1.find(ch.lower())
                expected.append(L2[idx].upper())
            else:
                expected.append(ch)
        expected_str = ''.join(expected)
        assert out == expected_str, f'Direct mapping mismatch: got {out}, expected {expected_str}'

def test_case_count(run, x):
    lines = x.split('\n')
    s = lines[2]
    out = run(x)
    s_upper = sum(1 for ch in s if 'A' <= ch <= 'Z')
    s_lower = sum(1 for ch in s if 'a' <= ch <= 'z')
    out_upper = sum(1 for ch in out if 'A' <= ch <= 'Z')
    out_lower = sum(1 for ch in out if 'a' <= ch <= 'z')
    assert s_upper == out_upper, f'Uppercase count mismatch: {s_upper} vs {out_upper}'
    assert s_lower == out_lower, f'Lowercase count mismatch: {s_lower} vs {out_lower}'

def test_consistent_mapping(run, x):
    lines = x.split('\n')
    s = lines[2]
    out = run(x)
    mapping = {}
    for i, ch in enumerate(s):
        if ch in mapping:
            assert out[i] == mapping[ch], f'Inconsistent output for identical input character {ch} at position {i}'
        else:
            mapping[ch] = out[i]

