        assert out == examples[x], f"Example mismatch, expected {examples[x]!r}"

def test_small_inversion(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n <= 1000:
        s = lines[1]
        rev = s[::-1]
        # Build permutation: for each char in s, match to same char in rev left‑to‑right
        pos_s = {}
        for i, ch in enumerate(s):
            pos_s.setdefault(ch, []).append(i)
        pos_rev = {ch: iter(pos_s.get(ch, [])) for ch in rev}
        perm = []
        for ch in rev:
            perm.append(next(pos_rev[ch]))
        # Count inversions in perm
        inv = 0
        for i in range(n):
            for j in range(i+1, n):
                if perm[i] > perm[j]:
                    inv += 1
        out = run(x)
        assert int(out) == inv, f"Inversion count gives {inv}"

def test_no_extra_whitespace(run, x):
    out = run(x)
    assert out.strip() == out, "Output contains leading/trailing whitespace"
    # Ensure it's only digits (and possibly a minus, but non‑negative already checked)
    stripped = out.strip()
    assert stripped.isdigit() or (stripped[0] == '-' and stripped[1:].isdigit()), "Output contains non‑digit characters"

