def test_small_bruteforce(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    nk = list(map(int, lines[0].split()))
    if len(nk) != 2:
        return
    n, k = nk
    if not (2 <= k <= n <= 10**5):
        return
    a = list(map(int, lines[1].split()))
    if len(a) != n:
        return
    if set(a) != set(range(1, k+1)):
        return
    if n > 10:
        return
    best_stress = None
    best_genre = None
    for excl in range(1, k+1):
        seq = [v for v in a if v != excl]
        if not seq:
            stress = 0
        else:
            compressed = [seq[0]]
            for v in seq[1:]:
                if v != compressed[-1]:
                    compressed.append(v)
            stress = len(compressed) - 1
        if best_stress is None or stress < best_stress or (stress == best_stress and excl < best_genre):
            best_stress = stress
            best_genre = excl
    out = run(x).strip()
    try:
        out_val = int(out)
    except ValueError:
        raise AssertionError(f'Output must be integer, got {out!r}')
    assert out_val == best_genre, f'Expected {best_genre}, got {out_val}'

