    },
    {
      "name": "test_order",
      "intent": "After parsing the two numbers as floats, the first number must be strictly greater than the second."
    },
    {
      "name": "test_distinct",
      "intent": "The two roots must be distinct: the absolute difference between them must be at least 1e-12."
    },
    {
      "name": "test_polynomial",
      "intent": "For each parsed root r, compute f = a*r*r + b*r + c. The absolute value of f must be at most (|2*a*r + b|) * 1e-6 + 1e-9."
    },
    {
      "name": "test_vieta_sum",
      "intent": "The sum of the two parsed roots must approximate -b/a within absolute or relative error of 1e-6."
    },
    {
      "name": "test_vieta_product",
      "intent": "The product of the two parsed roots must approximate c/a within absolute or relative error of 1e-6."
    },
    {
      "name": "test_direct_computation",
      "intent": "Compute the expected roots using high-precision arithmetic (e.g., decimal.Decimal with 30 digits) via the quadratic formula. Sort them. Compare each output root to the corresponding expected root: the error must be within 1e-6 absolute or relative."
    },
    {
      "name": "test_bounds",
      "intent": "Each root's absolute value must be at most (|b| + math.sqrt(b*b + 4*abs(a*c))) / (2*abs(a)) + 1e-6, a theoretical upper bound for real roots."
    },
    {
      "name": "test_finite",
      "intent": "Both parsed roots must be finite (not math.isnan and not math.isinf)."
    },
    {
      "name": "test_discriminant_consistency",
      "intent": "Compute D = b*b - 4*a*c. Then |a * (first_root - second_root)| must approximate math.sqrt(D) within absolute or relative error of 1e-6."
    }
  ]
}

