  ]
}

{
  "rationale": "The tests combine brute-force verification for small n (strongest) with necessary conditions: non-negativity, upper bound from total span, special cases where the answer is known exactly (k=n, k=1, all equal, k=n-1, k=2), output format, and a heuristic upper bound from a concrete partition. These are safe because they follow directly from the problem statement or simple mathematical reasoning. The brute-force test is limited to n≤10 to stay fast. If a test were dropped, the heuristic upper bound is least necessary as it is a loose bound, but it can catch answers that are too high.",
  "plan": [
    {
      "name": "test_non_negative",
