    {
      "name": "test_output_format",
      "intent": "The output must be a single integer followed by a newline, with no extra characters. Strip trailing whitespace, ensure the string consists only of digits, parse it as an integer, and verify that re‑converting to string matches the stripped output (to catch leading zeros or signs)."
    },
    {
      "name": "test_brute_force_small_n",
      "intent": "For n ≤ 10, the exact minimum can be computed by enumerating all ways to split into k non‑empty consecutive subarrays. Parse input, if n ≤ 10 compute the minimum cost by brute force, parse the output as integer ans, and assert ans equals that minimum."
    },
    {
      "name": "test_heuristic_upper_bound",
      "intent": "The minimum cost is at most the cost of any specific partition. Construct the partition where subarray lengths are as equal as possible (first n%k subarrays of size n//k+1, rest of size n//k), compute its cost, parse the output as integer ans, and assert ans ≤ that cost."
    },
    {
      "name": "test_k_equals_n_minus_1",
