    if m > 300:
        return
    queries = []
    for i in range(m):
        l_str, r_str, k_str = lines[2 + i].split()
        l, r, k = int(l_str), int(r_str), int(k_str)
        queries.append((l, r, k))
    out = run(x).strip('\n')
    s = out
    for l, r, k in reversed(queries):
        length = r - l + 1
        shift = k % length
        left_shift = (length - shift) % length
        if left_shift == 0:
