tests_src:
def test_exact(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    if n < 3:
        # No interior indices, so exact count is 0.
        expected = 0
    else:
        a = list(map(int, lines[1].strip().split()))
        expected = 0
        for i in range(1, n - 1):
            if (a[i] > a[i-1] and a[i] > a[i+1]) or (a[i] < a[i-1] and a[i] < a[i+1]):
                expected += 1
    output = run(x).strip()
    assert output.isdigit()
    assert int(output) == expected


def test_diff_sign(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    if n < 3:
        expected = 0
    else:
        a = list(map(int, lines[1].strip().split()))
        diffs = [a[i+1] - a[i] for i in range(n-1)]
        expected = 0
        for i in range(1, n-1):
            if diffs[i-1] * diffs[i] < 0:
                expected += 1
    output = run(x).strip()
    assert output.isdigit()
    assert int(output) == expected


def test_format(run, x):
    output = run(x)
    s = output.strip()
    assert s.isdigit()
    # No leading zeros unless the integer is exactly 0.
    if s != '0':
        assert s[0] != '0'
    # The string representation of the parsed integer must equal the stripped string.
    assert str(int(s)) == s


def test_non_negative(run, x):
    output = run(x).strip()
    assert output.isdigit()
    assert int(output) >= 0


def test_upper_bound_n(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    output = run(x).strip()
    assert output.isdigit()
    k = int(output)
    assert k <= max(0, n - 2)


def test_small_n(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    if n <= 2:
        output = run(x).strip()
        assert output.isdigit()
        assert int(output) == 0


def test_all_equal(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    if n > 0:
        a = list(map(int, lines[1].strip().split()))
        if all(x == a[0] for x in a):
            output = run(x).strip()
            assert output.isdigit()
            assert int(output) == 0


def test_strictly_increasing(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    if n > 0:
        a = list(map(int, lines[1].strip().split()))
        if all(a[i] < a[i+1] for i in range(n-1)):
            output = run(x).strip()
            assert output.isdigit()
            assert int(output) == 0


def test_strictly_decreasing(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    if n > 0:
        a = list(map(int, lines[1].strip().split()))
        if all(a[i] > a[i+1] for i in range(n-1)):
            output = run(x).strip()
            assert output.isdigit()
            assert int(output) == 0


def test_upper_bound_distinct(run, x):
    lines = x.strip().splitlines()
    n = int(lines[0].strip())
    if n < 3:
        upper = 0
    else:
        a = list(map(int, lines[1].strip().split()))
        upper = 0
        for i in range(1, n - 1):
            if a[i] != a[i-1] and a[i] != a[i+1]:
                upper += 1
    output = run(x).strip()
    assert output.isdigit()
    assert int(output) <= upper

