def test_range(run, x):
    out = run(x).strip()
    try:
        ans = int(out)
    except ValueError:
        raise AssertionError('output not an integer')
    lines = x.strip().split('\n')
    if lines:
        n, m = map(int, lines[0].split())
        assert 0 <= ans <= n + m, 'answer out of bounds'
    else:
        assert 0 <= ans <= 0, 'answer out of bounds for empty input'

