def test_exact_bruteforce(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1].strip()
    if n > 12:
        return  # skip, too large for brute force
    from itertools import product
    best = [0] * n
    for bits in product([0, 1], repeat=s.count('?')):
        t = list(s)
        idx = 0
        for i,ch in enumerate(t):
            if ch == '?':
                t[i] = str(bits[idx])
                idx += 1
        # compute for each x
        for xval in range(1, n+1):
            cnt = 0
            streak = 0
            last = None
            for ch in t:
                if ch == last:
                    streak += 1
                else:
                    streak = 1
                    last = ch
                if streak == xval:
                    cnt += 1
                    streak = 0
                    last = None
            if cnt > best[xval-1]:
                best[xval-1] = cnt
    out = run(x).strip().split()
    assert len(out) == n, f'Expected {n} integers, got {len(out)}'
    for i in range(n):
        assert int(out[i]) == best[i], f'For x={i+1} expected {best[i]} got {out[i]}'


def test_output_length(run, x):
    n = int(x.strip().split('\n')[0])
    out = run(x).strip().split()
    assert len(out) == n, f'Expected {n} integers, got {len(out)}'


def test_first_value(run, x):
    n = int(x.strip().split('\n')[0])
    out = run(x).strip().split()
    assert len(out) > 0, 'No output'
    first = int(out[0])
    assert first == n, f'For x=1 expected {n} got {first}'


def test_non_increasing(run, x):
    out = list(map(int, run(x).strip().split()))
    for i in range(1, len(out)):
        assert out[i] <= out[i-1], f'At x={i+1} value {out[i]} > previous {out[i-1]}'


def test_bounds_per_x(run, x):
    n = int(x.strip().split('\n')[0])
    out = list(map(int, run(x).strip().split()))
    for i, val in enumerate(out):
        xval = i+1
        upper = n // xval
        assert 0 <= val <= upper, f'For x={xval} value {val} not in [0, {upper}]'


def test_last_value(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1].strip()
    out = run(x).strip().split()
    last = int(out[-1]) if out else 0
    has0 = '0' in s
    has1 = '1' in s
    if not has0 and not has1:
        # all '?' -> can be all 0 or all 1
        expected = 1
    else:
        expected = 0
    assert last == expected, f'For x={n} expected {expected} got {last}'


def test_integer_parsing(run, x):
    out = run(x).strip().split()
    for token in out:
        int(token)  # raises ValueError if not integer


def test_non_negative(run, x):
    out = list(map(int, run(x).strip().split()))
    for val in out:
        assert val >= 0, f'Negative value {val}'


def test_at_most_one_for_large_x(run, x):
    n = int(x.strip().split('\n')[0])
    out = list(map(int, run(x).strip().split()))
    for i, val in enumerate(out):
        xval = i+1
        if xval > n/2:
            assert val <= 1, f'For x={xval} > n/2, value {val} > 1'


def test_consistency_fixed_completion(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    s = lines[1].strip()
    # replace all '?' with '0'
    t = ''.join(ch if ch != '?' else '0' for ch in s)
    # compute finished sets for each x
    computed = [0]*n
    for xval in range(1, n+1):
        cnt = 0
        streak = 0
        last = None
        for ch in t:
            if ch == last:
                streak += 1
            else:
                streak = 1
                last = ch
            if streak == xval:
                cnt += 1
                streak = 0
                last = None
        computed[xval-1] = cnt
    out = list(map(int, run(x).strip().split()))
    for i in range(n):
        assert out[i] >= computed[i], f'For x={i+1} output {out[i]} < fixed completion value {computed[i]}'

