def test_int(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False, 'output must be an integer'

def test_nonneg(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0, 'output must be non‑negative'

def test_upper_bound(run, x):
    out = run(x).strip()
    val = int(out)
    # count spells from input
    lines = x.strip().split('\n')
    if not lines:
        total = 0
    else:
        n_m = list(map(int, lines[0].split()))
        if len(n_m) >= 2:
            n, m = n_m[0], n_m[1]
            total = n + m
        else:
            total = 0
    assert val <= total, f'output {val} exceeds total spells {total}'

def test_brute_force(run, x):
    # only run when total spells ≤ 8
    lines = x.strip().split('\n')
    if not lines:
        return
    n_m = list(map(int, lines[0].split()))
    if len(n_m) < 2:
        return
    n, m = n_m[0], n_m[1]
    if n + m > 8:
        return
    # parse spells
    vertical = []
    idx = 1
    for i in range(n):
        vertical.append(int(lines[idx]))
        idx += 1
    horizontal = []
    for i in range(m):
        x1, x2, y = map(int, lines[idx].split())
        horizontal.append((x1, x2, y))
        idx += 1
    # brute‑force over subsets
    answer = n + m  # worst case
    total_spells = n + m
    from itertools import combinations
    for r in range(total_spells + 1):
        for combo in combinations(range(total_spells), r):
            removed = set(combo)
            # check if path exists with these spells removed
            # build vertical barriers not removed
            vbar = set()
            for i, v in enumerate(vertical):
                if i not in removed:
                    vbar.add(v)
            # build horizontal barriers not removed
            hbar = []
            for i, (x1, x2, y) in enumerate(horizontal):
                if i + n not in removed:
                    hbar.append((x1, x2, y))
            # simulate movement on a discrete grid of coordinates
            # we only need columns at vertical barriers, horizontal ends, and 1, 10^9
            cols = {1, 10**9}
            for v in vbar:
                cols.add(v)
                cols.add(v + 1)
            for x1, x2, y in hbar:
                cols.add(x1)
                cols.add(x2)
                if x1 > 1:
                    cols.add(x1 - 1)
                if x2 < 10**9:
                    cols.add(x2 + 1)
            cols = sorted(cols)
            col_to_idx = {c: i for i, c in enumerate(cols)}
            # rows: y‑coordinates of horizontal spells, 1, 10^9
            rows = {1, 10**9}
            for _, _, y in hbar:
                rows.add(y)
                rows.add(y + 1)  # block is on top side of row y
            rows = sorted(rows)
            row_to_idx = {r: i for i, r in enumerate(rows)}
            # create grid: 0 = free, 1 = blocked
            R = len(rows)
            C = len(cols)
            grid = [[0] * C for _ in range(R)]
            # vertical barriers between columns
            for v in vbar:
                # find column index where cols[i] == v
                if v in col_to_idx:
                    cidx = col_to_idx[v]
                    # barrier between column v and v+1
                    # we mark the edge between cidx and cidx+1 if v+1 exists
                    if v + 1 in col_to_idx:
                        cnext = col_to_idx[v + 1]
                        # we store barrier as forbidden horizontal move across this edge
                        # easier: treat grid as cells; moving right from column v to v+1 blocked
                        # we'll handle during BFS
                        pass
            # horizontal barriers on top side of row y
            for x1, x2, y in hbar:
                # barrier blocks moving up from row y to y+1 within columns [x1, x2]
                # find row index of y
                if y in row_to_idx:
                    ridx = row_to_idx[y]
                    # columns from x1 to x2 inclusive
                    for c in range(C):
                        if x1 <= cols[c] <= x2:
                            # mark that moving up from (ridx, c) is blocked
                            # we'll handle during BFS
                            pass
            # BFS from (row=1, col=1) to any cell with row = 10^9
            from collections import deque
            start_r = row_to_idx[1]
            start_c = col_to_idx[1]
            q = deque()
            q.append((start_r, start_c))
            visited = [[False] * C for _ in range(R)]
            visited[start_r][start_c] = True
            target_rows = set()
            for rval in rows:
                if rval == 10**9:
                    target_rows.add(row_to_idx[rval])
            reached_top = False
            while q:
                r, c = q.popleft()
                if r in target_rows:
                    reached_top = True
                    break
                # move up
                if r + 1 < R:
                    # check horizontal barrier blocking upward from (r, c)
                    blocked = False
                    for x1, x2, y in hbar:
                        if y == rows[r] and x1 <= cols[c] <= x2:
                            blocked = True
                            break
                    if not blocked and not visited[r + 1][c]:
                        visited[r + 1][c] = True
                        q.append((r + 1, c))
                # move down
                if r > 0:
                    # barrier on top of row rows[r-1] could block moving down from (r, c)
                    # actually moving down from r to r-1 is blocked if there is a horizontal barrier on top of row rows[r-1] covering cols[c]
                    blocked = False
                    for x1, x2, y in hbar:
                        if y == rows[r - 1] and x1 <= cols[c] <= x2:
                            blocked = True
                            break
                    if not blocked and not visited[r - 1][c]:
                        visited[r - 1][c] = True
                        q.append((r - 1, c))
                # move left
                if c > 0:
                    # vertical barrier between cols[c-1] and cols[c] if cols[c-1] + 1 == cols[c] and cols[c-1] in vbar
                    blocked = False
                    if cols[c - 1] in vbar and cols[c] == cols[c - 1] + 1:
                        blocked = True
                    if not blocked and not visited[r][c - 1]:
                        visited[r][c - 1] = True
                        q.append((r, c - 1))
                # move right
                if c + 1 < C:
                    blocked = False
                    if cols[c] in vbar and cols[c + 1] == cols[c] + 1:
                        blocked = True
                    if not blocked and not visited[r][c + 1]:
                        visited[r][c + 1] = True
                        q.append((r, c + 1))
            if reached_top:
                answer = min(answer, r)
                break
        if answer == r:
            break
    # compare with submission's output
    out = int(run(x).strip())
    assert out == answer, f'brute‑force answer is {answer}, got {out}'

