def test_brute_force(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    n = int(lines[0])
    strings = lines[1:1 + n]
    total_len = sum(len(s) for s in strings)
    if n > 7 or total_len > 20:
        return  # too big to brute force; skip test
    from itertools import permutations
    def noise_of_string(t):
        cnt_s = 0
        noise = 0
        for ch in t:
            if ch == 's':
                cnt_s += 1
            elif ch == 'h':
                noise += cnt_s
        return noise
    max_noise = -1
    for perm in permutations(strings):
        concat = ''.join(perm)
        noise = noise_of_string(concat)
        if noise > max_noise:
            max_noise = noise
    out = run(x).strip()
    try:
        ans = int(out)
    except ValueError:
        raise AssertionError('Output not an integer')
    assert ans == max_noise, f'Brute-force max noise is {max_noise}, got {ans}'

def test_output_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    assert len(lines) == 1, 'Output must be exactly one line'
    try:
        int(lines[0].strip())
    except ValueError:
        raise AssertionError('Output not an integer')

def test_nonnegative(run, x):
    out = run(x).strip()
    ans = int(out)
    assert ans >= 0, 'Noise must be non‑negative'

def test_upper_bound_total(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    n = int(lines[0])
    strings = lines[1:1 + n]
    S = sum(s.count('s') for s in strings)
    H = sum(s.count('h') for s in strings)
    out = run(x).strip()
    ans = int(out)
    assert ans <= S * H, f'Noise cannot exceed total s * h = {S * H}'

def test_lower_bound_internal(run, x):
    lines = x.strip().split('\n')
    if not lines:
        return
    n = int(lines[0])
    strings = lines[1:1 + n]
    def internal_noise(t):
        cnt_s = 0
        noise = 0
        for ch in t:
            if ch == 's':
                cnt_s += 1
            elif ch == 'h':
                noise += cnt_s
        return noise
    lower = sum(internal_noise(s) for s in strings)
    out = run(x).strip()
    ans = int(out)
    assert ans >= lower, f'Noise must be at least sum of internal noises = {lower}'

def test_lower_bound_original_order(run, x):
    lines = x.strip().split('\n')
    if not lines:
