def test_valid_integer(run, x):
    out = run(x)
    s = out.strip()
    # Must parse as integer
    try:
        val = int(s)
    except ValueError:
        raise AssertionError('Output is not an integer')
    # Must be between 0 and 10**9+6 inclusive
    if not (0 <= val <= 10**9+6):
        raise AssertionError('Output integer out of range')


def test_no_leading_zeros(run, x):
    out = run(x)
    s = out.strip()
    if len(s) > 1 and s[0] == '0':
        raise AssertionError('Output has leading zeros')


def test_example_n2(run, x):
    if x.strip() == '2':
        out = run(x).strip()
        if out != '1':
            raise AssertionError('For n=2, output must be 1')


def test_example_n3(run, x):
    if x.strip() == '3':
        out = run(x).strip()
        if out != '4':
            raise AssertionError('For n=3, output must be 4')


def test_example_n6(run, x):
    if x.strip() == '6':
        out = run(x).strip()
        if out != '120':
            raise AssertionError('For n=6, output must be 120')


def test_bruteforce_small(run, x):
    n = int(x.strip())
    if n > 10:
        return  # too large for brute-force
    import itertools, math
    best = 0
    count = 0
    for perm in itertools.permutations(range(1, n+1)):
        seen = set()
        g = 0
        for v in perm:
            g = math.gcd(g, v)
            seen.add(g)
        f_val = len(seen)
        if f_val > best:
            best = f_val
            count = 1
        elif f_val == best:
            count += 1
    expected = count % (10**9+7)
    out = run(x).strip()
    if int(out) != expected:
        raise AssertionError(f'Brute-force mismatch for n={n}')


def test_positive_count(run, x):
    n = int(x.strip())
    if n > 10:
        return  # brute-force only for small n
    import itertools, math
    best = 0
    count = 0
    for perm in itertools.permutations(range(1, n+1)):
        seen = set()
        g = 0
        for v in perm:
            g = math.gcd(g, v)
            seen.add(g)
        f_val = len(seen)
        if f_val > best:
            best = f_val
            count = 1
        elif f_val == best:
            count += 1
    if count == 0:
        raise AssertionError(f'Brute-force count zero for n={n}')


def test_fmax_formula_small(run, x):
    n = int(x.strip())
    if n > 10:
        return
    import itertools, math
    best = 0
    for perm in itertools.permutations(range(1, n+1)):
        seen = set()
        g = 0
        for v in perm:
            g = math.gcd(g, v)
            seen.add(g)
        f_val = len(seen)
        if f_val > best:
            best = f_val
    expected = math.floor(math.log2(n)) + 1
    if best != expected:
        raise AssertionError(f'f_max({n}) = {best} != floor(log2(n))+1 = {expected}')


def test_output_no_whitespace(run, x):
    out = run(x)
    # Must not have leading/trailing whitespace
    if out != out.strip():
        raise AssertionError('Output has extra whitespace')
    # Must be exactly one line
    if '\n' in out.rstrip('\n'):
        raise AssertionError('Output contains multiple lines')


def test_modulo_range(run, x):
    out = run(x)
    s = out.strip()
    val = int(s)
    MOD = 10**9 + 7
    if val % MOD != val:
        raise AssertionError('Output not reduced modulo 10^9+7')

