def test_brute_force(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    idx = 1
    for _ in range(t):
        n = int(lines[idx]); idx += 1
        s = lines[idx].strip(); idx += 1
        if n <= 11:
            # enumerate all subsets
            best = n + 1
            for mask in range(1 << n):
                flips = bin(mask).count('1')
                if flips >= best:
                    continue
                # apply flips
                t = list(s)
                for i in range(n):
                    if mask & (1 << i):
                        t[i] = 'L' if t[i] == 'R' else 'R'
                # check logical condition
                ok = True
                for i in range(n):
                    left = (i - 1) % n
                    right = (i + 1) % n
                    attacked_by = 0
                    if t[left] == 'R':
                        attacked_by += 1
                    if t[right] == 'L':
                        attacked_by += 1
                    if attacked_by == 1:
                        # must attack the attacker
                        attacker = left if t[left] == 'R' else right
                        if t[i] != ('R' if attacker == (i - 1) % n else 'L'):
                            ok = False
                            break
                if ok:
                    best = flips
            # get output for this test case
            out_lines = run(x).strip().split()
            out_vals = list(map(int, out_lines))
            assert len(out_vals) == t
            ans = out_vals[_]
            assert ans == best, f"Brute-force minimum is {best}, got {ans}"
        else:
            # skip brute-force for large n
            pass


def test_output_integer(run, x):
