        n = int(lines[idx]); idx += 1
        s = lines[idx].strip(); idx += 1
        # check if s is already logical
        logical = True
        for i in range(n):
            left = (i - 1) % n
            right = (i + 1) % n
            attacked_by = 0
            if s[left] == 'R':
                attacked_by += 1
            if s[right] == 'L':
                attacked_by += 1
            if attacked_by == 1:
