                    break
            if alt:
                assert out_vals[case] == 0, f"Even alternating string must give 0, got {out_vals[case]}"


def test_symmetry_reverse_complement(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    idx = 1
    out_vals = list(map(int, run(x).strip().split()))
    for case in range(t):
        n = int(lines[idx]); idx += 1
        s = lines[idx].strip(); idx += 1
        if n <= 11:
            # compute s' = reverse and swap L/R
            s_prime = ''.join('L' if c == 'R' else 'R' for c in reversed(s))
            # brute-force minimum for s_prime
            best_prime = n + 1
            for mask in range(1 << n):
                flips = bin(mask).count('1')
                if flips >= best_prime:
                    continue
                tlist = list(s_prime)
                for i in range(n):
                    if mask & (1 << i):
                        tlist[i] = 'L' if tlist[i] == 'R' else 'R'
                ok = True
                for i in range(n):
                    left = (i - 1) % n
                    right = (i + 1) % n
                    attacked_by = 0
                    if tlist[left] == 'R':
                        attacked_by += 1
                    if tlist[right] == 'L':
                        attacked_by += 1
                    if attacked_by == 1:
                        attacker = left if tlist[left] == 'R' else right
                        if tlist[i] != ('R' if attacker == (i - 1) % n else 'L'):
                            ok = False
                            break
                if ok:
                    best_prime = flips
            assert out_vals[case] == best_prime, f"Symmetry broken: expected {best_prime}, got {out_vals[case]}"
        else:
            # skip for large n
            pass


def test_feasibility(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    idx = 1
    out_vals = list(map(int, run(x).strip().split()))
    for case in range(t):
        n = int(lines[idx]); idx += 1
        s = lines[idx].strip(); idx += 1
        k = out_vals[case]
        # specification guarantees it's always possible, but we can check for small n and small k
        if n <= 11 and k <= n:
            feasible = False
            # enumerate subsets of size exactly k
            from itertools import combinations
            for subset in combinations(range(n), k):
                tlist = list(s)
                for i in subset:
                    tlist[i] = 'L' if tlist[i] == 'R' else 'R'
                ok = True
                for i in range(n):
                    left = (i - 1) % n
                    right = (i + 1) % n
                    attacked_by = 0
                    if tlist[left] == 'R':
                        attacked_by += 1
                    if tlist[right] == 'L':
                        attacked_by += 1
                    if attacked_by == 1:
                        attacker = left if tlist[left] == 'R' else right
                        if tlist[i] != ('R' if attacker == (i - 1) % n else 'L'):
                            ok = False
                            break
                if ok:
                    feasible = True
                    break
            assert feasible, f"No subset of size {k} makes the configuration logical"
        else:
            # trust the specification's guarantee
            pass


def test_greedy_upper_bound(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    idx = 1
    out_vals = list(map(int, run(x).strip().split()))
    for case in range(t):
        n = int(lines[idx]); idx += 1
        s = lines[idx].strip(); idx += 1
        # greedy algorithm: repeatedly find a player attacked by exactly one neighbor but not attacking that neighbor, flip that player
        arr = list(s)
        flips = 0
        changed = True
        # limit iterations to avoid infinite loops
        for _ in range(n + 5):
            changed = False
            for i in range(n):
                left = (i - 1) % n
                right = (i + 1) % n
                attacked_by = 0
                if arr[left] == 'R':
                    attacked_by += 1
                if arr[right] == 'L':
                    attacked_by += 1
                if attacked_by == 1:
                    attacker = left if arr[left] == 'R' else right
                    expected = 'R' if attacker == (i - 1) % n else 'L'
                    if arr[i] != expected:
                        arr[i] = expected
                        flips += 1
                        changed = True
            if not changed:
                break
        # after greedy, check if logical (should be, but we just need bound)
        # compute greedy upper bound: flips performed
        greedy_bound = flips
        assert out_vals[case] <= greedy_bound, f"Output {out_vals[case]} exceeds greedy upper bound {greedy_bound}"

