def test_length_match(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    strings = lines[1:1 + n]
    total_len = sum(len(s) for s in strings)
    output = run(x)
    if output.endswith('\n'):
        output = output[:-1]
    assert len(output) == total_len

def test_character_multiset(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    strings = lines[1:1 + n]
    all_chars = ''.join(strings)
    output = run(x)
    if output.endswith('\n'):
        output = output[:-1]
    assert sorted(output) == sorted(all_chars)

def test_bruteforce_small(run, x):
    import itertools
    lines = x.strip().split('\n')
    n = int(lines[0])
    strings = lines[1:1 + n]
    if n > 5:
        return
    best = min(''.join(p) for p in itertools.permutations(strings))
    output = run(x)
    if output.endswith('\n'):
        output = output[:-1]
    assert output == best

def test_two_strings(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n != 2:
        return
    a, b = lines[1], lines[2]
    expected = min(a + b, b + a)
    output = run(x)
    if output.endswith('\n'):
        output = output[:-1]
    assert output == expected

def test_single_string(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n != 1:
        return
    s = lines[1]
    output = run(x)
    if output.endswith('\n'):
        output = output[:-1]
    assert output == s

def test_all_equal(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    strings = lines[1:1 + n]
    if len(set(strings)) != 1:
        return
    expected = strings[0] * n
    output = run(x)
    if output.endswith('\n'):
        output = output[:-1]
    assert output == expected

def test_valid_partition_small(run, x):
    def can_partition(s, words):
        if not words:
            return s == ''
        for w in words:
            if s.startswith(w):
                new_words = words.copy()
                new_words.remove(w)
                if can_partition(s[len(w):], new_words):
                    return True
        return False
    lines = x.strip().split('\n')
    n = int(lines[0])
    strings = lines[1:1 + n]
    if n > 8 or sum(len(s) for s in strings) > 100:
        return
    output = run(x)
    if output.endswith('\n'):
        output = output[:-1]
    assert can_partition(output, strings)

def test_lowercase_only(run, x):
    output = run(x)
    if output.endswith('\n'):
        output = output[:-1]
    assert all('a' <= c <= 'z' for c in output)

def test_no_extra_whitespace(run, x):
    output = run(x)
    assert output.rstrip() == output.rstrip('\n')
    assert output.endswith('\n')

def test_adjacent_condition_when_unique(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    strings = lines[1:1 + n]
    # check no string is a prefix of another
    for i in range(n):
        for j in range(n):
            if i != j and strings[i].startswith(strings[j]):
                return
    output = run(x)
    if output.endswith('\n'):
        output = output[:-1]
    # try to recover order by greedy longest match
    order = []
    pos = 0
    while pos < len(output):
        matched = False
        for s in strings:
            if output.startswith(s, pos):
                order.append(s)
                pos += len(s)
                matched = True
                break
        if not matched:
            return  # ambiguous or not partitionable, skip
    if len(order) != n:
        return
    # verify pairwise condition for consecutive strings
    for i in range(len(order) - 1):
        a = order[i]
        b = order[i + 1]
        if a + b > b + a:
            assert False

