tests_src:
def test_brute_force_small(run, x):
    received, t = x.strip().split('\n')
    if len(received) > 12:
        return
    from itertools import permutations
    n_len_candidates = []
    for L in range(1, len(received) + 1):
        len_str = str(L)
        if len(received) != L + len(len_str):
            continue
        for perm in permutations(received, L):
            if perm[0] == '0' and L > 1:
                continue
            n_candidate = ''.join(perm)
            if t not in n_candidate:
                continue
            if (sorted(list(n_candidate) + list(len_str)) == sorted(received)):
                n_len_candidates.append(n_candidate)
    if n_len_candidates:
        expected = min(n_len_candidates, key=lambda s: (len(s), s))
        assert run(x).strip() == expected


def test_contains_substring(run, x):
    received, t = x.strip().split('\n')
    output = run(x).strip()
    assert t in output


def test_no_leading_zero(run, x):
    output = run(x).strip()
    assert output == '0' or not output.startswith('0')


def test_digits_only(run, x):
    output = run(x).strip()
    assert output.isdigit()


def test_length_condition(run, x):
    received, t = x.strip().split('\n')
    output = run(x).strip()
    L = len(output)
    len_str = str(L)
    assert len(received) == L + len(len_str)


def test_multiset_condition(run, x):
    received, t = x.strip().split('\n')
    output = run(x).strip()
    L = len(output)
    len_str = str(L)
    assert sorted(list(output) + list(len_str)) == sorted(received)


def test_t_starts_with_zero(run, x):
    received, t = x.strip().split('\n')
    if t.startswith('0'):
        output = run(x).strip()
        assert output == '0' or not output.startswith(t)


def test_output_length_ge_t(run, x):
    received, t = x.strip().split('\n')
    output = run(x).strip()
    assert len(output) >= len(t)


def test_output_non_empty(run, x):
    output = run(x).strip()
    assert output != ''


def test_subset_multiset(run, x):
    received, t = x.strip().split('\n')
    output = run(x).strip()
    from collections import Counter
    cnt_recv = Counter(received)
    cnt_out = Counter(output)
    for d in cnt_out:
        assert cnt_out[d] <= cnt_recv.get(d, 0)

