def test_bruteforce_full(run, x):
    import sys
    sys.setrecursionlimit(2000000)
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return
    costs = list(map(int, lines[1].split()))
    m = int(lines[2])
    edges = []
    for i in range(m):
        u, v = map(int, lines[3+i].split())
        edges.append((u-1, v-1))
    # Build adjacency list for reachability
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
    # Find SCCs using Kosaraju
    visited = [False]*n
    order = []
    def dfs(v):
        visited[v] = True
        for to in adj[v]:
            if not visited[to]:
                dfs(to)
        order.append(v)
    for v in range(n):
        if not visited[v]:
            dfs(v)
    radj = [[] for _ in range(n)]
    for u, v in edges:
        radj[v].append(u)
    comp = [-1]*n
    def rdfs(v, c):
        comp[v] = c
        for to in radj[v]:
            if comp[to] == -1:
                rdfs(to, c)
    cid = 0
    for v in reversed(order):
        if comp[v] == -1:
            rdfs(v, cid)
            cid += 1
    # A subset protects all junctions if every SCC has at least one checkpost in it.
    best_cost = float('inf')
    best_subsets = []
    for mask in range(1 << n):
        total_cost = 0
        for i in range(n):
            if (mask >> i) & 1:
                total_cost += costs[i]
        # Check protection
        scc_protected = [False]*cid
        for i in range(n):
            if (mask >> i) & 1:
                scc_protected[comp[i]] = True
        if all(scc_protected):
            if total_cost < best_cost:
                best_cost = total_cost
                best_subsets = [(mask, total_cost, bin(mask).count('1'))]
            elif total_cost == best_cost:
                best_subsets.append((mask, total_cost, bin(mask).count('1')))
    if best_cost == float('inf'):
        # No subset protects? According to spec, at least one exists (take all junctions).
        best_cost = sum(costs)
        best_subsets = [( (1<<n)-1, best_cost, n )]
    min_checkposts = min(s[2] for s in best_subsets)
    ways = sum(1 for s in best_subsets if s[2] == min_checkposts)
    out = run(x)
    out_vals = out.strip().split()
    assert len(out_vals) == 2
    ans_cost = int(out_vals[0])
    ans_ways = int(out_vals[1])
    assert ans_cost == best_cost, f"cost mismatch: expected {best_cost}, got {ans_cost}"
    assert ans_ways == ways, f"ways mismatch: expected {ways}, got {ans_ways}"


