def test_checkposts_minimal(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return
    costs = list(map(int, lines[1].split()))
    m = int(lines[2])
    edges = []
    for i in range(m):
        u, v = map(int, lines[3+i].split())
        edges.append((u-1, v-1))
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
    radj = [[] for _ in range(n)]
    for u, v in edges:
        radj[v].append(u)
    visited = [False]*n
    order = []
    def dfs(v):
        visited[v] = True
        for to in adj[v]:
            if not visited[to]:
                dfs(to)
        order.append(v)
    for v in range(n):
        if not visited[v]:
            dfs(v)
    comp = [-1]*n
    def rdfs(v, c):
        comp[v] = c
        for to in radj[v]:
            if comp[to] == -1:
                rdfs(to, c)
    cid = 0
    for v in reversed(order):
        if comp[v] == -1:
            rdfs(v, cid)
            cid += 1
    out = run(x)
    ans_cost, ans_ways = map(int, out.strip().split())
    # Enumerate all protecting subsets with cost = ans_cost
    subsets = []
    for mask in range(1 << n):
        total_cost = 0
        for i in range(n):
            if (mask >> i) & 1:
                total_cost += costs[i]
        if total_cost != ans_cost:
            continue
        scc_protected = [False]*cid
        for i in range(n):
            if (mask >> i) & 1:
                scc_protected[comp[i]] = True
        if all(scc_protected):
            cnt = bin(mask).count('1')
            subsets.append((mask, cnt))
    min_checkposts = min(cnt for _, cnt in subsets) if subsets else n
    ways = sum(1 for _, cnt in subsets if cnt == min_checkposts)
    assert ans_ways == ways, f"Ways mismatch: expected {ways}, got {ans_ways}"


def test_modulo(run, x):
    import sys
    sys.setrecursionlimit(2000000)
    lines = x.strip().split('\n')
    n = int(lines[0])
    costs = list(map(int, lines[1].split()))
    m = int(lines[2])
    edges = []
    for i in range(m):
        u, v = map(int, lines[3+i].split())
        edges.append((u-1, v-1))
    # Build graph
    adj = [[] for _ in range(n)]
    radj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        radj[v].append(u)
    visited = [False]*n
    order = []
    def dfs(v):
        visited[v] = True
        for to in adj[v]:
            if not visited[to]:
                dfs(to)
        order.append(v)
    for v in range(n):
        if not visited[v]:
            dfs(v)
    comp = [-1]*n
    def rdfs(v, c):
        comp[v] = c
        for to in radj[v]:
            if comp[to] == -1:
                rdfs(to, c)
    cid = 0
    for v in reversed(order):
        if comp[v] == -1:
            rdfs(v, cid)
            cid += 1
    # For each component, find min cost and count
    comp_min = [10**18]*cid
    comp_cnt = [0]*cid
    for v in range(n):
        c = comp[v]
        if costs[v] < comp_min[c]:
            comp_min[c] = costs[v]
            comp_cnt[c] = 1
        elif costs[v] == comp_min[c]:
            comp_cnt[c] += 1
    MOD = 1000000007
    prod = 1
    for c in range(cid):
        prod = (prod * comp_cnt[c]) % MOD
    out = run(x)
    _, ans_ways = map(int, out.strip().split())
    assert ans_ways == prod, f"Ways modulo mismatch: expected {prod}, got {ans_ways}"

