tests_src:
def test_valid_range(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    out = run(x).strip()
    a = int(out)
    assert 1 <= a <= n

def test_not_m(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    m = int(lines[1])
    if n > 1:
        a = int(run(x).strip())
        assert a != m

def test_adjacent(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    m = int(lines[1])
    if n == 1:
        return
    a = int(run(x).strip())
    if m == 1:
        assert a == 2
    elif m == n:
        assert a == n - 1
    else:
        assert a == m - 1 or a == m + 1

def test_optimality_condition(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    m = int(lines[1])
    a = int(run(x).strip())
    if a == m - 1 and m - 1 >= 1:
        assert m - 1 >= n - m
    if a == m + 1 and m + 1 <= n:
        assert n - m > m - 1

def test_brute_force_small(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    m = int(lines[1])
    if n > 10000:
        return
    best_a = None
    best_win = -1
    for a in range(1, n + 1):
        win = 0
        for c in range(1, n + 1):
            if abs(c - a) < abs(c - m):
                win += 1
        if win > best_win or (win == best_win and (best_a is None or a < best_a)):
            best_win = win
            best_a = a
    assert int(run(x).strip()) == best_a

def test_smallest_on_tie(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    m = int(lines[1])
    if m - 1 == n - m:
        a = int(run(x).strip())
        assert a == m - 1

def test_positive_probability(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    m = int(lines[1])
    if n == 1:
        return
    a = int(run(x).strip())
    if a < m:
        win = (a + m - 1) // 2
    else:
        win = n - (a + m) // 2
    assert win > 0

def test_local_optimum(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    m = int(lines[1])
    a = int(run(x).strip())
    def wins(a_val):
        if a_val < m:
            return (a_val + m - 1) // 2
        else:
            return n - (a_val + m) // 2
    w_a = wins(a)
    if a - 1 >= 1:
        assert w_a >= wins(a - 1)
    if a + 1 <= n:
        assert w_a >= wins(a + 1)

def test_n1(run, x):
    lines = x.strip().split()
    n = int(lines[0])
    if n == 1:
        assert int(run(x).strip()) == 1

def test_output_format(run, x):
    out = run(x)
    assert out.strip() == out.rstrip()
    int(out.strip())

