def test_integer(run, x):
    output = run(x)
    try:
        int(output.strip())
    except ValueError:
        assert False, "Output must be an integer"

def test_range(run, x):
    output = run(x)
    n = int(output.strip())
    assert 1 <= n <= 10, f"Output {n} not in 1..10"

def test_payment(run, x):
    k_str, r_str = x.strip().split()
    k = int(k_str)
    r = int(r_str)
    output = run(x)
    n = int(output.strip())
    total = k * n
    assert total % 10 == 0 or total % 10 == r, f"Total {total} mod 10 not 0 or {r}"

def test_minimal(run, x):
    k_str, r_str = x.strip().split()
    k = int(k_str)
    r = int(r_str)
    output = run(x)
    n = int(output.strip())
    for y in range(1, n):
        if (k * y) % 10 == 0 or (k * y) % 10 == r:
            assert False, f"Smaller y={y} also works"

def test_example1(run, x):
    if x == "117 3\n":
        assert run(x) == "9\n", "Example 1 must output 9"

def test_example2(run, x):
    if x == "237 7\n":
        assert run(x) == "1\n", "Example 2 must output 1"

def test_example3(run, x):
    if x == "15 2\n":
        assert run(x) == "2\n", "Example 3 must output 2"

def test_boundary_multiple_of_10(run, x):
    k_str, r_str = x.strip().split()
    k = int(k_str)
    r = int(r_str)
    if k % 10 == 0:
        output = run(x)
        n = int(output.strip())
        assert n == 1, f"When k divisible by 10, answer must be 1, got {n}"

def test_boundary_last_digit_r(run, x):
    k_str, r_str = x.strip().split()
    k = int(k_str)
    r = int(r_str)
    if k % 10 == r:
        output = run(x)
        n = int(output.strip())
        assert n == 1, f"When last digit of k equals r, answer must be 1, got {n}"

def test_immediate_predecessor(run, x):
    k_str, r_str = x.strip().split()
    k = int(k_str)
    r = int(r_str)
    output = run(x)
    n = int(output.strip())
    if n > 1:
        prev_total = k * (n - 1)
        assert not (prev_total % 10 == 0 or prev_total % 10 == r), f"n-1={n-1} also works, so not minimal"

