def test_range(run, x):
    n_str, _ = x.strip().split()
    n = int(n_str)
    out = run(x).strip()
    a = int(out)
    assert 1 <= a <= n

def test_not_m(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n == 1:
        return  # a may equal m for n=1
    a = int(run(x).strip())
    assert a != m

def test_neighbor(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n == 1:
        return
    a = int(run(x).strip())
    if m == 1:
        assert a == 2
    elif m == n:
        assert a == n - 1
    else:
        assert a == m - 1 or a == m + 1

def test_positive_count(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n == 1:
        return
    a = int(run(x).strip())
    win = sum(1 for c in range(1, n + 1) if abs(c - a) < abs(c - m))
    assert win > 0

def test_local_optimal(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n <= 1 or m == 1 or m == n or n > 10000:
        return  # skip large n to keep test fast
    a = int(run(x).strip())
    if a == m - 1:
        other = m + 1
    else:
        other = m - 1
    cnt_a = sum(1 for c in range(1, n + 1) if abs(c - a) < abs(c - m))
    cnt_other = sum(1 for c in range(1, n + 1) if abs(c - other) < abs(c - m))
    if cnt_a > cnt_other:
        return
    # counts equal → must pick smaller neighbor
    assert cnt_a == cnt_other and a == m - 1

def test_small_brute(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n > 1000:
        return  # brute force only for small n
    best_a = None
    best_cnt = -1
    for a_cand in range(1, n + 1):
        cnt = sum(1 for c in range(1, n + 1) if abs(c - a_cand) < abs(c - m))
        if cnt > best_cnt or (cnt == best_cnt and a_cand < best_a):
            best_cnt = cnt
            best_a = a_cand
    assert int(run(x).strip()) == best_a

def test_middle_tie(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n % 2 == 1 and m == (n + 1) // 2 and n > 1:
        assert int(run(x).strip()) == m - 1

def test_edge_cases(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if m == 1 and n > 1:
        assert int(run(x).strip()) == 2
    if m == n and n > 1:
        assert int(run(x).strip()) == n - 1

def test_examples(run, x):
    if x.strip() == '3 1':
        assert run(x).strip() == '2'
    if x.strip() == '4 3':
        assert run(x).strip() == '2'

def test_format(run, x):
    out = run(x)
    s = out.strip()
    # must be a single integer
    int(s)
    # no extra whitespace besides optional trailing newline
    assert out == s + '\n' or out == s

