tests_src:
def test_brute_small(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 6:
        return
    from collections import deque
    perm = list(map(int, lines[1].split()))
    target = tuple(sorted(perm))
    start = tuple(perm)
    if start == target:
        expected = 0
    else:
        visited = {start: 0}
        q = deque([start])
        while q:
            cur = q.popleft()
            d = visited[cur]
            if cur == target:
                expected = d
                break
            lst = list(cur)
            for i in range(n):
                # move car at position i to front
                nxt = (lst[i],) + tuple(lst[:i] + lst[i+1:])
                if nxt not in visited:
                    visited[nxt] = d + 1
                    q.append(nxt)
                # move car at position i to back
                nxt = tuple(lst[:i] + lst[i+1:]) + (lst[i],)
                if nxt not in visited:
                    visited[nxt] = d + 1
                    q.append(nxt)
        else:
            expected = n  # fallback, never used because BFS always finds
    out = run(x).strip()
    assert out.isdigit() and int(out) == expected

def test_output_integer(run, x):
    out = run(x).strip()
    assert out.isdigit() or (out.startswith('-') and out[1:].isdigit())

def test_output_range(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = run(x).strip()
    val = int(out)
    assert 0 <= val <= n

def test_sorted_zero(run, x):
    lines = x.strip().split('\n')
    perm = list(map(int, lines[1].split()))
    if perm == sorted(perm):
        out = run(x).strip()
        assert out == '0'

def test_unsorted_positive(run, x):
    lines = x.strip().split('\n')
    perm = list(map(int, lines[1].split()))
    if perm != sorted(perm):
        out = run(x).strip()
        val = int(out)
        assert val >= 1

def test_n1(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        out = run(x).strip()
        assert out == '0'

def test_n2(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 2:
        perm = list(map(int, lines[1].split()))
        out = run(x).strip()
        if perm == [1, 2]:
            assert out == '0'
        else:
            assert out == '1'

def test_lower_bound_consecutive(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    perm = list(map(int, lines[1].split()))
    pos = {v: i for i, v in enumerate(perm)}
    best = 1
    cur = 1
    for v in range(2, n+1):
        if pos[v] == pos[v-1] + 1:
            cur += 1
            if cur > best:
                best = cur
        else:
            cur = 1
    L = best
    out = run(x).strip()
    val = int(out)
    assert val >= n - L

def test_example1(run, x):
    if x == '5\n4 1 2 5 3\n':
        out = run(x).strip()
        assert out == '2'

def test_example2(run, x):
    if x == '4\n4 1 3 2\n':
        out = run(x).strip()
        assert out == '2'

