def test_format(run, x):
    out = run(x)
    # Must be a single integer followed by a newline
    lines = out.split('\n')
    # Allow trailing newlines, but no extra lines with content
    nonempty = [line for line in lines if line.strip() != '']
    assert len(nonempty) == 1, 'Output must have exactly one non-empty line'
    s_line = nonempty[0]
    # Must be an integer
    try:
        s = int(s_line)
    except ValueError:
        raise AssertionError('Output must be a single integer')
    # No extra characters after the integer on that line
    assert s_line.strip() == str(s), 'Extra characters on output line'

def test_bounds(run, x):
    lines = x.strip().split('\n')
