    out = run(x).strip()
    s = int(out) if out != '' else 0
    assert 0 <= s <= n * m, f'Output {s} out of range [0, {n*m}]'

def test_feasible(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    out = run(x).strip()
    s = int(out) if out != '' else 0
    if s == 0:
        return
    # There must exist h <= n, w <= m such that h*w == s
    possible = False
    for h in range(1, n + 1):
        if s % h == 0:
            w = s // h
            if w <= m:
                possible = True
                break
    assert possible, f'Area {s} cannot be formed as height*width with height≤{n}, width≤{m}'

def test_existence(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    x_val = int(lines[3])
    out = run(x).strip()
    s = int(out) if out != '' else 0
    if s == 0:
        # No subrectangle with sum <= x may exist; we could check but enumeration may be heavy.
        # We only check if n*m is small enough to brute-force.
        if n * m <= 10**6:
            found = False
            for x1 in range(n):
                for x2 in range(x1, n):
                    sa = sum(a[x1:x2+1])
                    for y1 in range(m):
                        for y2 in range(y1, m):
                            sb = sum(b[y1:y2+1])
                            if sa * sb <= x_val:
                                found = True
                                break
                        if found:
                            break
                    if found:
                        break
                if found:
                    break
            # If a subrectangle exists, s must not be 0
            if found:
                assert False, 'Output is 0 but a subrectangle with sum ≤ x exists'
        return
    # s > 0, we must find at least one subrectangle of area s with sum ≤ x
    # Enumerate all subrectangles if small enough
    if n * m <= 10**6:
        found = False
        for x1 in range(n):
            for x2 in range(x1, n):
                h = x2 - x1 + 1
                sa = sum(a[x1:x2+1])
                for y1 in range(m):
                    for y2 in range(y1, m):
                        w = y2 - y1 + 1
                        if h * w != s:
                            continue
                        sb = sum(b[y1:y2+1])
                        if sa * sb <= x_val:
                            found = True
                            break
                    if found:
                        break
                if found:
                    break
            if found:
                break
        assert found, f'No subrectangle of area {s} has sum ≤ x'

