    limit = min(max_area, s + 1000)
    for area in range(s + 1, limit + 1):
        ok = False
        for h in range(1, n + 1):
            if area % h != 0:
                continue
            w = area // h
            if w > m:
                continue
            if min_row_sum[h] * min_col_sum[w] <= x_val:
                ok = True
                break
        if ok:
            # Found an area larger than s that can achieve sum ≤ x -> output not maximal
            assert False, f'Area {area} > {s} can achieve sum ≤ x, so output is not maximal'

