def test_integer(run, x):
    output = run(x)
    try:
        int(output.strip())
    except ValueError:
        assert False, "Output must be an integer"


def test_ge_n(run, x):
    output = run(x)
    n, _ = map(int, x.split())
    val = int(output.strip())
    assert val >= n, f"Output {val} must be >= n={n}"


def test_upper_bound(run, x):
    output = run(x)
    n, _ = map(int, x.split())
    L = n.bit_length()
    upper = (1 << L) - 1
    val = int(output.strip())
    assert val <= upper, f"Output {val} exceeds maximum possible {upper}"


def test_k1_equals_n(run, x):
    n, k = map(int, x.split())
    if k == 1:
        val = int(run(x).strip())
        assert val == n, f"When k=1, output must equal n={n}, got {val}"


def test_small_n_bruteforce_1(run, x):
    n, k = map(int, x.split())
    if n <= 10:
        # brute-force over all non-empty subsets of size at most k
        best = 0
        from itertools import combinations
        for size in range(1, min(k, n) + 1):
            for comb in combinations(range(1, n+1), size):
                xor = 0
                for v in comb:
                    xor ^= v
                if xor > best:
                    best = xor
        val = int(run(x).strip())
        assert val == best, f"For n={n}, k={k}, expected {best}, got {val}"


def test_small_n_bruteforce_2(run, x):
    n, k = map(int, x.split())
    if 10 < n <= 20:
        best = 0
        from itertools import combinations
        for size in range(1, min(k, n) + 1):
            for comb in combinations(range(1, n+1), size):
                xor = 0
                for v in comb:
                    xor ^= v
                if xor > best:
                    best = xor
        val = int(run(x).strip())
        assert val == best, f"For n={n}, k={k}, expected {best}, got {val}"


def test_formula_kge2(run, x):
    n, k = map(int, x.split())
    if k >= 2:
        # We cannot assume the exact formula (1 << n.bit_length()) - 1,
        # but we can bound it by the XOR of all numbers 1..n when k=n.
        # For k >= 2, the true answer is at most that.
        # Also, it cannot exceed (1 << n.bit_length()) - 1, already tested in test_upper_bound.
        # However, we can also compute the XOR of all 1..n (which is known pattern)
        # and ensure the output is at least that when k=n? Not required by spec.
        # Instead, we just check it's achievable: for k=n, output must be XOR of all 1..n.
        if k == n:
            full_xor = 0
            for i in range(1, n+1):
                full_xor ^= i
            val = int(run(x).strip())
            assert val == full_xor, f"When k=n, output must equal xor of 1..n={full_xor}, got {val}"


def test_positive(run, x):
    output = run(x)
    val = int(output.strip())
    assert val >= 1, f"Output must be at least 1, got {val}"


def test_max_bits(run, x):
    output = run(x)
    val = int(output.strip())
    max_val = (1 << 60) - 1
    assert val <= max_val, f"Output exceeds 2^60 - 1"


def test_bit_length(run, x):
    output = run(x)
    val = int(output.strip())
    assert val.bit_length() <= 60, f"Output bit-length exceeds 60"

