def test_output_format(run, x):
    out = run(x).strip()
    # Must be a single integer possibly -1
    try:
        val = int(out)
    except ValueError:
        raise AssertionError('Output not an integer')
    # If not -1, must be at least 1
    if val != -1:
        assert val >= 1, 'Positive answer must be at least 1'
    # No extra characters after newline is guaranteed by strip
    # but we ensure no extra lines
    lines = run(x).strip().split('\n')
    assert len(lines) == 1, 'Extra lines in output'

def test_n_in_a(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if n in a:
        out = run(x).strip()
        try:
            val = int(out)
        except ValueError:
            raise AssertionError('Output not integer')
        assert val == 1, 'n is in a, answer must be 1'

def test_all_above_or_below(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if n in a:
        return  # handled by another test
    if all(v > n for v in a) or all(v < n for v in a):
        out = run(x).strip()
        try:
            val = int(out)
        except ValueError:
            raise AssertionError('Output not integer')
        assert val == -1, 'All a_i strictly above or below n, must be impossible'

def test_small_distinct_bruteforce(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    distinct = set(a)
    if len(distinct) > 5:
