def test_gcd_condition(run, x):
    import math
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    distinct_nonzero = [v for v in set(a) if v != 0]
    if distinct_nonzero:
        G = distinct_nonzero[0]
        for v in distinct_nonzero[1:]:
            G = math.gcd(G, v)
    else:
        G = 0
    out = run(x).strip()
    try:
        val = int(out)
    except ValueError:
        raise AssertionError('Output not integer')
    if val != -1:
        if G > 0:
            # G divides each a_i, so for any mixture, sum a_i = G * something
            # total carbon = sum a_i * liters_i, total volume = sum liters_i * 1000
            # requirement: (sum a_i) / (total liters * 1000) = n / 1000
            # => sum a_i = n * total liters
            # Let total liters = val, then sum a_i = n * val
            # Since each a_i divisible by G, sum a_i divisible by G, so G divides n * val
            assert (n * val) % G == 0, f'GCD condition violated: G={G}, n={n}, L={val}'
