def test_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    assert len(lines) == 1 and out.endswith('\n'), 'output must be a single integer followed by newline'
    val = int(lines[0])
    MOD = 10**9 + 7
    assert 0 <= val < MOD, f'output must be in [0, {MOD})'


