def test_n1_small(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n == 1 and m <= 10:
        total = 0
        for mask in range(1 << m):
            ok = True
            for i in range(m - 2):
                bits = ((mask >> i) & 1, (mask >> (i + 1)) & 1, (mask >> (i + 2)) & 1)
                if bits[0] == bits[1] == bits[2]:
                    ok = False
                    break
            if ok:
                total += 1
        MOD = 10**9 + 7
        expected = total % MOD
        out = run(x)
        got = int(out.strip())
        assert got == expected, f'n=1, m={m}: expected {expected}, got {got}'


