    if n == 1:
        MOD = 10**9 + 7
        if m == 1:
            expected = 2
        elif m == 2:
            expected = 4
        else:
            f = [0] * (m + 1)
            f[1] = 2
            f[2] = 4
            for i in range(3, m + 1):
                f[i] = (f[i - 1] + f[i - 2]) % MOD
            expected = f[m]
        out = run(x)
        got = int(out.strip())
        assert got == expected, f'n=1, m={m}: expected {expected}, got {got}'


def test_n2_dp(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n == 2:
        MOD = 10**9 + 7
        # states: 0=00, 1=01, 2=10, 3=11 (bits: top, bottom)
        # precompute valid transitions
        ok_trans = [[] for _ in range(4)]
        for prev in range(4):
            for cur in range(4):
                # check cells of prev column given left neighbor cur and right neighbor cur (since columns are prev and cur, we check prev's right neighbor is cur)
                # For top cell of prev:
                same = 0
                if ((prev >> 1) & 1) == ((cur >> 1) & 1):   # right neighbor
                    same += 1
                if ((prev >> 1) & 1) == ((prev >> 0) & 1):  # bottom neighbor (vertical within column)
                    same += 1
                # left neighbor not considered because we only have two columns
                if same > 1:
                    continue
                # For bottom cell of prev:
                same = 0
                if ((prev >> 0) & 1) == ((cur >> 0) & 1):   # right neighbor
                    same += 1
                if ((prev >> 0) & 1) == ((prev >> 1) & 1):  # top neighbor
                    same += 1
                if same > 1:
                    continue
                ok_trans[prev].append(cur)
        dp = [1] * 4  # first column any pattern is allowed
        for _ in range(1, m):
            ndp = [0] * 4
            for prev in range(4):
                for cur in ok_trans[prev]:
                    ndp[cur] = (ndp[cur] + dp[prev]) % MOD
            dp = ndp
        expected = sum(dp) % MOD
        out = run(x)
        got = int(out.strip())
        assert got == expected, f'n=2, m={m}: expected {expected}, got {got}'


def test_n3_dp(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n == 3 and m <= 10000:
        MOD = 10**9 + 7
        # states: 0..7, bits: top, middle, bottom
        # precompute valid transitions between prev and cur columns
        ok_trans = [[] for _ in range(8)]
        for prev in range(8):
            p_top = (prev >> 2) & 1
            p_mid = (prev >> 1) & 1
            p_bot = (prev >> 0) & 1
            for cur in range(8):
                c_top = (cur >> 2) & 1
                c_mid = (cur >> 1) & 1
                c_bot = (cur >> 0) & 1
                # check each cell of prev column
                # top cell
                same = 0
                if p_top == c_top:          # right neighbor
                    same += 1
                if p_top == p_mid:          # bottom neighbor
                    same += 1
                if same > 1:
                    continue
                # middle cell
                same = 0
                if p_mid == c_mid:          # right neighbor
                    same += 1
                if p_mid == p_top:          # top neighbor
                    same += 1
                if p_mid == p_bot:          # bottom neighbor
                    same += 1
                if same > 1:
                    continue
                # bottom cell
                same = 0
                if p_bot == c_bot:          # right neighbor
                    same += 1
                if p_bot == p_mid:          # top neighbor
                    same += 1
                if same > 1:
                    continue
                ok_trans[prev].append(cur)
        dp = [1] * 8  # first column
        for _ in range(1, m):
            ndp = [0] * 8
            for prev in range(8):
                for cur in ok_trans[prev]:
                    ndp[cur] = (ndp[cur] + dp[prev]) % MOD
            dp = ndp
        expected = sum(dp) % MOD
        out = run(x)
        got = int(out.strip())
        assert got == expected, f'n=3, m={m}: expected {expected}, got {got}'


def test_n4_small(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n == 4 and m <= 4:
        total = 0
        for mask in range(1 << (4 * m)):
            ok = True
            for r in range(4):
                for c in range(m):
                    idx = r * m + c
                    same = 0
                    if c > 0 and ((mask >> (idx - 1)) & 1) == ((mask >> idx) & 1):
                        same += 1
                    if c < m - 1 and ((mask >> (idx + 1)) & 1) == ((mask >> idx) & 1):
                        same += 1
                    if r > 0 and ((mask >> (idx - m)) & 1) == ((mask >> idx) & 1):
                        same += 1
                    if r < 3 and ((mask >> (idx + m)) & 1) == ((mask >> idx) & 1):
                        same += 1
                    if same > 1:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                total += 1
        MOD = 10**9 + 7
        expected = total % MOD
        out = run(x)
        got = int(out.strip())
        assert got == expected, f'n=4, m={m}: expected {expected}, got {got}'

