def test_small_brute(run, x):
    import sys
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n * m > 29:
        return  # too large for brute-force
    total = 0
    cells = [(i, j) for i in range(n) for j in range(m)]
    for mask in range(1 << (n * m)):
        ok = True
        # build grid
        grid = [[0]*m for _ in range(n)]
        for idx, (i, j) in enumerate(cells):
            grid[i][j] = (mask >> idx) & 1
        for i in range(n):
            for j in range(m):
                same = 0
                color = grid[i][j]
                if i > 0 and grid[i-1][j] == color:
                    same += 1
                if i + 1 < n and grid[i+1][j] == color:
                    same += 1
                if j > 0 and grid[i][j-1] == color:
                    same += 1
                if j + 1 < m and grid[i][j+1] == color:
                    same += 1
                if same > 1:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            total += 1
    out = run(x)
    val = int(out.strip())
    assert val == total, f'brute-force count {total} != output {val}'

def test_n1(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n != 1:
        return
    MOD = 10**9 + 7
    if m == 1:
        expected = 2
    elif m == 2:
        expected = 4
    else:
        a, b = 2, 4  # lengths 1 and 2
        for i in range(3, m + 1):
            a, b = b, (a + b) % MOD
        expected = b
    out = run(x)
    val = int(out.strip())
    assert val == expected, f'for n=1, m={m}, expected {expected}, got {val}'

def test_m1(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if m != 1:
        return
    MOD = 10**9 + 7
    if n == 1:
        expected = 2
    elif n == 2:
        expected = 4
    else:
        a, b = 2, 4  # lengths 1 and 2
        for i in range(3, n + 1):
            a, b = b, (a + b) % MOD
        expected = b
    out = run(x)
    val = int(out.strip())
    assert val == expected, f'for m=1, n={n}, expected {expected}, got {val}'

def test_format(run, x):
    out = run(x)
    assert out.endswith('\n'), 'output must end with newline'
    line = out.rstrip('\n')
    assert line.isdigit() or (line == '0'), 'output must be an integer'
    # Ensure no extra characters besides newline
    assert out == line + '\n', 'extra characters after newline or multiple lines'

def test_range(run, x):
    out = run(x)
    val = int(out.strip())
    MOD = 10**9 + 7
    assert 0 <= val < MOD, f'output {val} not in modulo range [0, {MOD})'

def test_example(run, x):
    if x == '2 3\n':
        out = run(x)
        assert out == '8\n', f'example input 2 3 must output 8\n, got {repr(out)}'

def test_even_small(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n * m > 29:
        return  # only when brute-force feasible
    out = run(x)
    val = int(out.strip())
    # The count of random pictures must be even because flipping all colors
    # gives a bijection between pictures, and the chessboard pattern is not fixed.
    # Actually, both chessboard patterns are fixed under flip? Wait: flipping colors swaps the two chessboard patterns, so they are not fixed points.
    # Therefore the involution pairs all pictures, so count is even.
    assert val % 2 == 0, f'for small n*m={n*m}, count should be even, got {val}'

def test_upper_bound_small(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n * m > 29:
        return
    total_all = 1 << (n * m)
    out = run(x)
    val = int(out.strip())
    assert val <= total_all, f'random pictures are subset of all pictures, {val} > {total_all}'

def test_lower_bound_small(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n * m > 29:
        return
    out = run(x)
    val = int(out.strip())
    # At least two pictures: chessboard pattern starting black/white.
    assert val >= 2, f'at least two random pictures exist, got {val}'

def test_no_leading_zeros(run, x):
    out = run(x)
    line = out.rstrip('\n')
    if line == '0':
        assert out == '0\n', 'zero must be exactly 0 followed by newline'
    else:
        assert not line.startswith('0'), 'non‑zero output must not have leading zeros'

