    n = int(lines[0])
    if n > 30:
        return  # pass for larger inputs
    t = list(map(int, lines[1].split()))
    if len(t) != n:
        return  # malformed input, pass
    # Determine if it's an arithmetic progression
    if n >= 2:
        diff = t[1] - t[0]
        is_ap = all(t[i] - t[i-1] == diff for i in range(1, n))
    else:
        is_ap = False  # shouldn't happen per constraints
    if is_ap:
        expected = t[-1] + diff
    else:
        expected = t[-1]
    out = run(x).strip()
    try:
        ans = int(out)
    except ValueError:
        raise AssertionError(f'Output not an integer: {out!r}')
    assert ans == expected, f'Expected {expected}, got {ans}'

def test_n2(run, x):
    lines = x.strip().split('\n')
