def test_bruteforce_small(run, x):
    import collections
    # parse input
    parts = x.strip().split()
    if len(parts) != 2:
        return  # not a valid input per spec, but we ignore
    xx, yy = map(int, parts)
    if xx > 20 or yy > 20:
        return  # only brute force small inputs
    # BFS from (orig=1, copies=0)
    start = (1, 0)  # (originals, copies)
    q = collections.deque([start])
    visited = {start}
    while q:
        o, c = q.popleft()
        if (c, o) == (xx, yy):
            correct = True
            break
        # apply to original
        n1 = (o + 1, c + 1)
        if n1 not in visited:
            visited.add(n1)
            q.append(n1)
        # apply to copy, only if at least one copy
        if c > 0:
            n2 = (o, c + 2)
            if n2 not in visited:
                visited.add(n2)
                q.append(n2)
    else:
        correct = False
    # get program output
    out = run(x).strip().lower()
    if out not in ('yes', 'no'):
        assert False, f'Output "{out}" is not Yes/No'
    prog_yes = (out == 'yes')
    assert prog_yes == correct, f'For ({xx},{yy}) expected {correct} but got {out}'


