tests_src:
def test_example1(run, x):
    if x == '8-7+6-5+4-3+2-1-0\n':
        out = run(x)
        assert out == '4\n', f"Expected '4\\n', got {repr(out)}"


def test_example2(run, x):
    if x == '2+2\n':
        out = run(x)
        assert out == '-46\n', f"Expected '-46\\n', got {repr(out)}"


def test_example3(run, x):
    if x == '112-37\n':
        out = run(x)
        assert out == '375\n', f"Expected '375\\n', got {repr(out)}"


def test_output_ends_with_newline(run, x):
    out = run(x)
    assert out.endswith('\n'), f"Output must end with newline, got {repr(out)}"


def test_output_parses_as_int(run, x):
    out = run(x)
    s = out.rstrip('\n')
    try:
        int(s)
    except ValueError:
        assert False, f"Output must be integer, got {repr(s)}"


def test_no_extra_whitespace(run, x):
    out = run(x)
    s = out.rstrip('\n')
    assert s.strip() == s, f"Output contains extra whitespace, got {repr(out)}"


def test_output_length_reasonable(run, x):
    out = run(x)
    assert len(out) <= 20, f"Output too long: length {len(out)} > 20"


def test_output_within_bounds(run, x):
    out = run(x)
    s = out.rstrip('\n')
    v = int(s)
    assert -1_000_000 <= v <= 1_000_000, f"Output value {v} out of plausible range"


def test_output_not_empty(run, x):
    out = run(x)
    assert out != '', f"Output cannot be empty"


def test_output_consistent_with_input_structure(run, x):
    out = run(x)
    s = out.rstrip('\n')
    import re
    assert re.fullmatch(r'-?\d+', s), f"Output must be integer, got {repr(s)}"

