tests_src:
def test_newline(run, x):
    out = run(x)
    assert out.endswith('\n'), 'output must end with newline'

def test_integer(run, x):
    out = run(x)
    s = out.rstrip('\n')
    try:
        int(s)
    except ValueError:
        assert False, 'output must be an integer'

def test_no_leading_zeros(run, x):
    out = run(x)
    s = out.rstrip('\n')
    if s == '0':
        return
    assert not s.startswith('0'), 'non‑zero integer must not have leading zeros'

def test_example_2plus2(run, x):
    if x == '2+2\n':
        out = run(x)
        assert out == '-46\n', 'output must be -46 for input 2+2'

def test_example_112minus37(run, x):
    if x == '112-37\n':
        out = run(x)
        assert out == '375\n', 'output must be 375 for input 112-37'

def test_example_long(run, x):
    if x == '8-7+6-5+4-3+2-1-0\n':
        out = run(x)
        assert out == '4\n', 'output must be 4 for the long example'

def test_chars(run, x):
    out = run(x)
    s = out.rstrip('\n')
    if s == '':
        assert False, 'output must not be empty'  # caught by test_non_empty, but safe
    if s[0] == '-':
        s = s[1:]
    assert s.isdigit(), 'output must contain only digits and optional leading minus'

def test_non_empty(run, x):
    out = run(x)
    s = out.rstrip('\n')
    assert s != '', 'output must contain at least one digit'

def test_sign_consistency(run, x):
    out = run(x)
    s = out.rstrip('\n')
    if s == '':
        assert False, 'output empty'  # covered by test_non_empty
    value = int(s)  # already validated by test_integer
    if value >= 0:
        assert not s.startswith('-'), 'non‑negative output must not start with -'
    else:
        assert s.startswith('-'), 'negative output must start with -'

def test_no_plus_sign(run, x):
    out = run(x)
    assert '+' not in out, 'output must not contain +'

