def test_running_intersection(run, x):
    lines = x.strip().split('\n')
    N, M = map(int, lines[0].split())
    # We cannot simulate reading gates one by one in the submission,
    # but we can compute the intersection after each gate from the full input.
    # The plan says: assert that the output does not exceed the size of the current intersection.
    # Since we only have the final output, we can check that the output does not exceed the size of any prefix intersection.
    # That is a necessary condition: for each k from 1 to M, output <= size(intersection of first k gates).
    # So we compute prefix intersections.
    cur_L = 1
    cur_R = N
    out = run(x).strip()
    if out.startswith('-'):
        if out != '-0':
            assert False
        out_val = 0
    else:
        if out == '0':
            out_val = 0
        else:
            assert out.isdigit()
            assert out[0] != '0'
            out_val = int(out)
    for i in range(1, M+1):
        L, R = map(int, lines[i].split())
        # update intersection
        if L > cur_L:
            cur_L = L
        if R < cur_R:
            cur_R = R
        if cur_L > cur_R:
            prefix_len = 0
        else:
            prefix_len = cur_R - cur_L + 1
        assert out_val <= prefix_len, f'output {out_val} > prefix intersection size after gate {i}'

