tests_src:
def test_direct(run, x):
    A, B, C = map(int, x.strip().split())
    d = A - B
    correct = 0 if C <= d else C - d
    output = run(x)
    assert int(output.strip()) == correct

def test_format(run, x):
    import re
    output = run(x)
    assert re.fullmatch(r'\d+\n', output), f'Output "{output}" does not match ^\\d+\\n$'

def test_bounds(run, x):
    A, B, C = map(int, x.strip().split())
    out_val = int(run(x).strip())
    assert 0 <= out_val <= C

def test_sufficient_space(run, x):
    A, B, C = map(int, x.strip().split())
    if A - B >= C:
        out_val = int(run(x).strip())
        assert out_val == 0

def test_insufficient_space(run, x):
    A, B, C = map(int, x.strip().split())
    if A - B < C:
        out_val = int(run(x).strip())
        assert out_val == C - (A - B)

def test_transfer_limit(run, x):
    A, B, C = map(int, x.strip().split())
    out_val = int(run(x).strip())
    transferred = C - out_val
    assert transferred <= A - B

def test_full_bottle(run, x):
    A, B, C = map(int, x.strip().split())
    if A == B:
        out_val = int(run(x).strip())
        assert out_val == C

def test_single_space(run, x):
    A, B, C = map(int, x.strip().split())
    if A - B == 1:
        out_val = int(run(x).strip())
        correct = 0 if C <= 1 else C - 1
        assert out_val == correct

def test_consistency(run, x):
    A, B, C = map(int, x.strip().split())
    out_val = int(run(x).strip())
    d = A - B
    if out_val == 0:
        assert C <= d
    else:
        assert out_val == C - d

def test_sample(run, x):
    if x == '6 4 3\n':
        output = run(x)
        assert output == '1\n'

