def test_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False, f'Output {repr(out)} is not a valid integer.'

def test_non_negative(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0, f'Output {val} is negative.'

def test_upper_bound_odd(run, x):
    N = int(x.strip())
    max_odd = (N + 1) // 2
    val = int(run(x).strip())
    assert val <= max_odd, f'Output {val} exceeds possible odd numbers ≤ {N} (max {max_odd}).'

def test_small_N_zero(run, x):
    N = int(x.strip())
    if N < 105:
        val = int(run(x).strip())
        assert val == 0, f'N={N}<105 should output 0, got {val}.'

def test_at_least_105(run, x):
    N = int(x.strip())
    if N >= 105:
        val = int(run(x).strip())
        assert val >= 1, f'N={N}≥105 should output at least 1, got {val}.'

def test_at_least_135(run, x):
    N = int(x.strip())
    if N >= 135:
        val = int(run(x).strip())
        assert val >= 2, f'N={N}≥135 should output at least 2, got {val}.'

def test_at_least_165(run, x):
    N = int(x.strip())
    if N >= 165:
        val = int(run(x).strip())
        assert val >= 3, f'N={N}≥165 should output at least 3, got {val}.'

def test_at_least_189(run, x):
    N = int(x.strip())
    if N >= 189:
        val = int(run(x).strip())
        assert val >= 4, f'N={N}≥189 should output at least 4, got {val}.'

def test_at_least_195(run, x):
    N = int(x.strip())
    if N >= 195:
        val = int(run(x).strip())
        assert val >= 5, f'N={N}≥195 should output at least 5, got {val}.'

def test_brute_force(run, x):
    N = int(x.strip())
    # brute‑force computation per specification
    count = 0
    for k in range(1, N + 1, 2):  # odd numbers only
        divisors = 0
        for d in range(1, int(k**0.5) + 1):
            if k % d == 0:
                divisors += 1
                if d != k // d:
                    divisors += 1
        if divisors == 8:
            count += 1
    val = int(run(x).strip())
    assert val == count, f'Expected {count}, got {val}.'

