tests_src:
def test_exact_output(run, x):
    out = run(x)
    assert out in ('Yes\n', 'No\n'), 'Output must be exactly "Yes\\n" or "No\\n"'

def test_length(run, x):
    out = run(x)
    assert len(out) in (4, 3), 'Output length must be 4 for "Yes\\n" or 3 for "No\\n"'
    if out.startswith('Y'):
        assert len(out) == 4
    elif out.startswith('N'):
        assert len(out) == 3

def test_newline(run, x):
    out = run(x)
    assert out.endswith('\n'), 'Output must end with newline'

def test_yes_format(run, x):
    out = run(x)
    if out.startswith('Y'):
        assert out == 'Yes\n', 'If output starts with Y, it must be exactly "Yes\\n"'

def test_no_format(run, x):
    out = run(x)
    if out.startswith('N'):
        assert out == 'No\n', 'If output starts with N, it must be exactly "No\\n"'

def test_stripped(run, x):
    out = run(x)
    stripped = out.rstrip('\n')
    assert stripped in ('Yes', 'No'), 'Stripped output must be "Yes" or "No"'

def test_allowed_chars(run, x):
    out = run(x)
    allowed = set('Yes\nNo')
    assert all(c in allowed for c in out), 'Output contains disallowed character'
    assert out in ('Yes\n', 'No\n'), 'Output must be exactly "Yes\\n" or "No\\n"'

def test_non_empty(run, x):
    out = run(x)
    assert len(out) > 0, 'Output must not be empty'

def test_single_line(run, x):
    out = run(x)
    lines = out.split('\n')
    assert len(lines) == 2, 'Output must be exactly one line followed by newline'
    assert lines[1] == '', 'Extra characters after newline'

def test_correctness(run, x):
    lines = x.strip('\n').split('\n')
    if len(lines) != 2:
        return  # malformed input, but our given inputs are well-formed
    S, T = lines[0], lines[1]
    expected = 'Yes\n' if (len(T) == len(S) + 1 and T[:-1] == S) else 'No\n'
    out = run(x)
    assert out == expected, f'Expected {expected!r} for S={S}, T={T}'

