def test_length(run, x):
    output = run(x)
    assert len(output) == 19, "output must be 19 characters long"

def test_two_spaces(run, x):
    output = run(x)
    assert output.count(' ') == 2, "output must contain exactly two spaces"

def test_no_commas(run, x):
    output = run(x)
    assert ',' not in output, "output must not contain commas"

def test_characters_match(run, x):
    output = run(x)
    for i, ch in enumerate(output):
        if i in (5, 13):
            continue  # spaces expected
        assert ch == x[i], f"character mismatch at index {i}: expected {x[i]}, got {ch}"

def test_space_positions(run, x):
    output = run(x)
    assert output[5] == ' ' and output[13] == ' ', "positions 5 and 13 must be spaces"

def test_split_three(run, x):
    output = run(x)
    parts = output.split(' ')
    assert len(parts) == 3, "output must split into exactly three parts"

def test_parts_lowercase(run, x):
    output = run(x)
    parts = output.split(' ')
    for part in parts:
        assert part.isalpha() and part.islower(), f"part {part!r} must be lowercase letters"

def test_part_lengths(run, x):
    output = run(x)
    parts = output.split(' ')
    assert (len(parts[0]), len(parts[1]), len(parts[2])) == (5, 7, 5), "part lengths must be 5, 7, 5"

def test_reversible(run, x):
    output = run(x)
    reconstructed = output.replace(' ', ',')
    assert reconstructed == x, "replacing spaces with commas must yield the original input"

def test_no_extra_spaces(run, x):
    output = run(x)
    assert output.strip() == output, "output must have no leading or trailing spaces"

