      "name": "test_exact_match",
      "intent": "Parse the input as an integer N. If N <= 999, the output without newline must be 'ABC'; otherwise it must be 'ABD'. Violation: output does not match the expected label."
    },
    {
      "name": "test_output_length",
      "intent": "The output must be exactly four characters ending with a newline, and after stripping the newline, exactly three characters remain. Violation: length mismatch or missing newline."
