tests_src:
def test_output_is_abc_or_abd(run, x):
    output = run(x).strip()
    assert output in ('ABC', 'ABD'), f"Output must be ABC or ABD, got {output}"

def test_starts_with_A(run, x):
    output = run(x).strip()
    assert output.startswith('A'), f"Output must start with A, got {output}"

def test_second_is_B(run, x):
    output = run(x).strip()
    assert len(output) >= 2 and output[1] == 'B', f"Second character must be B, got {output}"

def test_third_is_C_or_D(run, x):
    output = run(x).strip()
    assert len(output) >= 3 and output[2] in ('C', 'D'), f"Third character must be C or D, got {output}"

def test_length_three(run, x):
    output = run(x).strip()
    assert len(output) == 3, f"Stripped output must be exactly 3 characters, got length {len(output)}"

def test_no_extra_chars(run, x):
    raw = run(x)
    stripped = raw.rstrip('\n')
    assert stripped.isalpha() and stripped.isupper() and len(stripped) == 3, f"Output must be exactly three uppercase letters (optionally followed by newline), got {repr(raw)}"

def test_consistency_abc(run, x):
    n = int(x.strip())
    output = run(x).strip()
    if output == 'ABC':
        assert n <= 999, f"Output ABC requires N ≤ 999, got N={n}"

def test_consistency_abd(run, x):
    n = int(x.strip())
    output = run(x).strip()
    if output == 'ABD':
        assert n >= 1000, f"Output ABD requires N ≥ 1000, got N={n}"

def test_no_digits(run, x):
    output = run(x)
    assert not any(c.isdigit() for c in output), f"Output must not contain digits, got {repr(output)}"

def test_no_lowercase(run, x):
    output = run(x)
    assert output.strip().isupper(), f"Output must be uppercase letters, got {repr(output)}"

