    },
    {
      "name": "test_output_non_negative",
      "intent": "Check that the parsed integer is non-negative. Since the answer is an absolute difference, it cannot be negative. A violation is a negative integer."
    },
    {
      "name": "test_output_upper_bound",
      "intent": "Check that the parsed integer is at most 642. The maximum possible difference between any three-digit number (111-999) and 753 is 642. A violation is an integer greater than 642."
    },
    {
      "name": "test_output_not_sentinel",
      "intent": "Check that the parsed integer is not equal to 1145141919810. This constant is far outside the valid range and is suspicious. A violation is that exact value."
    },
    {
      "name": "test_output_in_difference_set",
      "intent": "Check that the output equals |753 - int(S[i:i+3])| for some i where S[i:i+3] is a consecutive three-digit substring. Compute all such differences and verify the output is among them. A violation is an output not in this set."
    },
    {
      "name": "test_output_minimum",
      "intent": "Check that the output is the minimum of all |753 - int(S[i:i+3])| over valid i. Compute the minimum directly and assert equality. A violation is any discrepancy."
    },
    {
      "name": "test_zero_iff_753_substring",
      "intent": "Check that the output is 0 if and only if the string S contains '753' as a substring. Compute whether '753' is in S and compare with (output == 0). A violation is a mismatch."
