tests_src:
def test_format(run, x):
    out = run(x)
    assert out in {'YES\n', 'NO\n'}, f'Output must be YES or NO, got {repr(out)}'

def test_c_zero(run, x):
    import math
    A, B, C = map(int, x.split())
    if C == 0:
        out = run(x)
        assert out == 'YES\n', f'When C=0 the answer must be YES, got {repr(out)}'

def test_gcd_one(run, x):
    import math
    A, B, C = map(int, x.split())
    if math.gcd(A, B) == 1:
        out = run(x)
        assert out == 'YES\n', f'When gcd(A,B)=1 the answer must be YES, got {repr(out)}'

def test_a_multiple_b(run, x):
    A, B, C = map(int, x.split())
    if A % B == 0:
        out = run(x)
        expected = 'YES\n' if C == 0 else 'NO\n'
        assert out == expected, f'When A is a multiple of B, answer must be {expected.strip()}, got {repr(out)}'

def test_b_one(run, x):
    A, B, C = map(int, x.split())
    if B == 1:
        out = run(x)
        assert out == 'YES\n', f'When B=1 the answer must be YES, got {repr(out)}'

def test_a_one(run, x):
    A, B, C = map(int, x.split())
    if A == 1:
        out = run(x)
        assert out == 'YES\n', f'When A=1 the answer must be YES, got {repr(out)}'

def test_necessary(run, x):
    import math
    A, B, C = map(int, x.split())
    out = run(x)
    if out == 'YES\n':
        g = math.gcd(A, B)
        assert C % g == 0, f'Output YES but gcd(A,B)={g} does not divide C={C}'

def test_sufficient(run, x):
    import math
    A, B, C = map(int, x.split())
    out = run(x)
    if math.gcd(A, B) % C == 0:
        assert out == 'YES\n', f'gcd(A,B) divides C, so answer must be YES, got {repr(out)}'

def test_brute_force(run, x):
    A, B, C = map(int, x.split())
    # brute force up to B: specification allows any number of copies, so checking K from 1 to B suffices
    possible = False
    for K in range(1, B+1):
        if (A * K) % B == C:
            possible = True
            break
    expected = 'YES\n' if possible else 'NO\n'
    out = run(x)
    assert out == expected, f'Brute force says {expected.strip()}, got {repr(out)}'

def test_mod_invariance(run, x):
    A, B, C = map(int, x.split())
    A_mod = A % B
    if A_mod == 0:
        A_mod = B
    possible = False
    for K in range(1, B+1):
        if (A_mod * K) % B == C:
            possible = True
            break
    expected = 'YES\n' if possible else 'NO\n'
    out = run(x)
    assert out == expected, f'Using A modulo B gives {expected.strip()}, got {repr(out)}'

