def test_format(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n'), f'Output must be exactly YES\\n or NO\\n, got {repr(out)}'

def test_c_zero(run, x):
    A, B, C = map(int, x.split())
    if C == 0:
        out = run(x)
        assert out == 'YES\n', f'When C=0 output must be YES\\n, got {repr(out)}'

def test_b_one(run, x):
    A, B, C = map(int, x.split())
    if B == 1:
        out = run(x)
        assert out == 'YES\n', f'When B=1 output must be YES\\n, got {repr(out)}'

def test_a_one(run, x):
    A, B, C = map(int, x.split())
    if A == 1:
        out = run(x)
        assert out == 'YES\n', f'When A=1 output must be YES\\n, got {repr(out)}'

def test_gcd_one(run, x):
    import math
    A, B, C = map(int, x.split())
    if math.gcd(A, B) == 1:
        out = run(x)
        assert out == 'YES\n', f'When gcd(A,B)=1 output must be YES\\n, got {repr(out)}'

def test_a_multiple_b(run, x):
    A, B, C = map(int, x.split())
    if A % B == 0:
        out = run(x)
        expected = 'YES\n' if C == 0 else 'NO\n'
        assert out == expected, f'When A multiple of B, expected {repr(expected)} got {repr(out)}'

def test_brute_force(run, x):
    A, B, C = map(int, x.split())
    possible = any((A * S) % B == C for S in range(1, B + 1))
    expected = 'YES\n' if possible else 'NO\n'
    out = run(x)
    assert out == expected, f'Brute‑force says {possible}, output {repr(out)}'

def test_no_extra_chars(run, x):
    out = run(x)
    assert out.startswith('Y') or out.startswith('N'), f'Output must start with Y or N, got {repr(out)}'
    assert all(c in 'YESNO\n' for c in out), f'Output contains invalid characters: {repr(out)}'

def test_case(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n'), f'Output must be uppercase YES\\n or NO\\n, got {repr(out)}'

def test_newline(run, x):
    out = run(x)
    assert out.endswith('\n'), f'Output must end with newline, got {repr(out)}'

