tests_src:
def test_format(run, x):
    out = run(x).strip()
    if out == 'inf':
        return
    # decimal integer, no leading zeros except '0'
    assert out.isdigit() and (out == '0' or out[0] != '0')
    val = int(out)
    mod = 10**9 + 7
    assert 0 <= val <= mod - 1


def test_no_inf_for_t_gt_1(run, x):
    t, _, _ = map(int, x.strip().split())
    out = run(x).strip()
    if t > 1:
        assert out != 'inf'


def test_inf_only_for_1_1_1(run, x):
    t, a, b = map(int, x.strip().split())
    out = run(x).strip()
    if t == 1 and a == 1 and b == 1:
        assert out == 'inf'
    # specification: only this case yields infinite count


def test_monotonicity_violation_zero(run, x):
    t, a, b = map(int, x.strip().split())
    out = run(x).strip()
    # Because P(t) and P(P(t)) for a polynomial with non‑negative integer coefficients is monotone increasing in t and a.
    # If a > t and b < a, impossible (since P(P(t)) >= P(t)).
    # If a < t and b > a, impossible similarly.
    # If a == t and b != a, impossible because constant polynomial would give b = a.
    if (a > t and b < a) or (a < t and b > a) or (a == t and b != a):
        assert out == '0'


def test_constant_polynomial_exists(run, x):
    t, a, b = map(int, x.strip().split())
    out = run(x).strip()
    if b == a and out != 'inf':
        # constant polynomial P(x)=a always works (degree 0)
        assert out != '0'


def test_small_brute_force(run, x):
    t, a, b = map(int, x.strip().split())
    if t <= 1 or a > 10:
        return
    # Enumerate polynomials with non‑negative integer coefficients up to degree D where t^D ≤ a
    D = 0
    while t**D <= a:
        D += 1
    from itertools import product
    mod = 10**9 + 7
    count = 0
    # Try degrees 0..D
    for deg in range(D + 1):
        # coefficients c0..cdeg each up to a
        for coeffs in product(range(a + 1), repeat=deg + 1):
            # evaluate P(t)
            pt = 0
            for i, c in enumerate(coeffs):
                pt += c * (t ** i)
            if pt != a:
                continue
            # evaluate P(P(t))
            ppt = 0
            for i, c in enumerate(coeffs):
                ppt += c * (pt ** i)
            if ppt == b:
                count += 1
    expected = str(count % mod)
    out = run(x).strip()
    assert out == expected


def test_inf_implies_t1(run, x):
    t, _, _ = map(int, x.strip().split())
    out = run(x).strip()
    if out == 'inf':
        assert t == 1


def test_inf_implies_a1_b1(run, x):
    t, a, b = map(int, x.strip().split())
    out = run(x).strip()
    if out == 'inf':
        assert a == 1 and b == 1


def test_at_least_two_when_a_eq_t_and_b_eq_a_and_a_gt_1(run, x):
    t, a, b = map(int, x.strip().split())
    out = run(x).strip()
    if a == t and b == a and a > 1:
        # Must not be inf (t>1 already, but safe)
        assert out != 'inf'
        # Must not be zero because constant polynomial works and identity polynomial P(x)=x also works (since P(t)=t=a, P(P(t))=P(a)=a=b)
        # But we cannot assert count >= 2 without solving; we can assert it's not zero because constant polynomial exists.
        assert out != '0'


def test_examples_from_statement(run, x):
    if x == '2 2 2\n':
        out = run(x)
        assert out.strip() == '2'
    if x == '2 3 3\n':
        out = run(x)
        assert out.strip() == '1'

