import math
def test_terminating_not_minus_one_for_zero(run, x):
    a_str, b_str, c_str = x.strip().split()
    a, b, c = int(a_str), int(b_str), int(c_str)
    if c == 0:
        g = math.gcd(a, b)
        den = b // g
        while den % 2 == 0:
            den //= 2
        while den % 5 == 0:
            den //= 5
        if den == 1:  # terminating fraction
            out = run(x).strip()
            assert out != "-1", "Terminating fraction with c=0 cannot output -1"


import math
def test_terminating_exact(run, x):
    a_str, b_str, c_str = x.strip().split()
    a, b, c = int(a_str), int(b_str), int(c_str)
    g = math.gcd(a, b)
    num = a // g
    den = b // g
    temp = den
    while temp % 2 == 0:
        temp //= 2
    while temp % 5 == 0:
        temp //= 5
    if temp != 1:
        return  # not terminating, skip
    # simulate long division until remainder 0
    pos = 1
    rem = num % den
    found = False
    answer = None
    while rem != 0 and pos <= 2 * b:  # safe limit
        digit = (rem * 10) // den
        if digit == c and not found:
            answer = pos
            found = True
        rem = (rem * 10) % den
        pos += 1
    if not found:
        if c == 0:
            answer = pos  # position after last finite digit
        else:
            answer = -1
    out = run(x).strip()
    assert int(out) == answer, "Wrong answer for terminating fraction"


