def test_brute_force_small_n(run, x):
    # Only compute brute‑force for n ≤ 1000 (all given inputs satisfy this)
    lines = x.strip().split('\n')
    n, x_val = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if n <= 1000:
        expected = 0
        for i in range(n):
            for j in range(i+1, n):
                if a[i] ^ a[j] == x_val:
                    expected += 1
        assert int(run(x).strip()) == expected

def test_bounds(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    total_pairs = n * (n-1) // 2
    out = run(x).strip()
    val = int(out)
    assert 0 <= val <= total_pairs

def test_x_zero(run, x):
    lines = x.strip().split('\n')
    n, x_val = map(int, lines[0].split())
    if x_val == 0:
        a = list(map(int, lines[1].split()))
        from collections import Counter
        freq = Counter(a)
        expected = sum(c * (c-1) // 2 for c in freq.values())
        assert int(run(x).strip()) == expected

def test_output_parsable(run, x):
    out = run(x)
    # Must be parseable as int
    int(out.strip())

def test_output_format(run, x):
    out = run(x)
    stripped = out.rstrip('\n')
    assert stripped.isdigit() or stripped == '0'
    assert out.endswith('\n')

def test_example1(run, x):
    if x == "2 3\n1 2\n":
        assert run(x) == "1\n"

def test_example2(run, x):
    if x == "6 1\n5 1 2 3 4 1\n":
        assert run(x) == "2\n"

def test_n1(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    if n == 1:
        assert run(x).strip() == "0"

def test_n2(run, x):
    lines = x.strip().split('\n')
    n, x_val = map(int, lines[0].split())
    if n == 2:
        a = list(map(int, lines[1].split()))
        expected = 1 if (a[0] ^ a[1]) == x_val else 0
        assert int(run(x).strip()) == expected

def test_no_extra_whitespace(run, x):
    out = run(x)
    stripped = out.rstrip('\n')
    # No whitespace inside the number
    assert stripped.strip() == stripped

