    import heapq
    limit = 2 * n
    dist = [float('inf')] * (limit + 1)
    dist[0] = 0
    heap = [(0, 0)]
    while heap:
        d, v = heapq.heappop(heap)
        if d != dist[v]:
            continue
        if v + 1 <= limit and dist[v + 1] > d + x:
            dist[v + 1] = d + x
