def test_non_decreasing(run, x):
    out = run(x).strip()
    if out == '':
        parsed = []
    else:
        parsed = list(map(int, out.split()))
    for i in range(len(parsed)-1):
        assert parsed[i] <= parsed[i+1], f"Sequence not non-decreasing at index {i}"

def test_last_first(run, x):
    lines = x.strip().split('\n')
    b1 = int(lines[1].split()[0])
    out = run(x).strip()
    if out == '':
        parsed = []
    else:
        parsed = list(map(int, out.split()))
    if parsed:  # n >= 1 guaranteed
        assert parsed[-1] == b1, f"Last light should be turned off by first button {b1}, got {parsed[-1]}"

def test_first_one(run, x):
    lines = x.strip().split('\n')
