        out = run(x).strip()
        if out == '':
            parsed = []
        else:
            parsed = list(map(int, out.split()))
        if parsed:  # n >= 1
            assert parsed[0] == 1, f"Button 1 is pressed, so first light should be turned off by 1, got {parsed[0]}"

def test_prefix_minima_set(run, x):
    lines = x.strip().split('\n')
    buttons = list(map(int, lines[1].split()))
    prefix_minima = []
    curr_min = float('inf')
    for b in buttons:
        if b < curr_min:
            curr_min = b
            prefix_minima.append(b)
    out = run(x).strip()
    if out == '':
        parsed = []
    else:
        parsed = list(map(int, out.split()))
    # Every output value must be a prefix minimum
    for a in parsed:
        assert a in prefix_minima, f"Output value {a} is not a prefix minimum of button sequence"
    # The set of distinct output values must equal the set of prefix minima
    assert set(parsed) == set(prefix_minima), f"Output values {set(parsed)} do not match prefix minima {set(prefix_minima)}"

def test_contiguous(run, x):
    out = run(x).strip()
    if out == '':
        parsed = []
    else:
        parsed = list(map(int, out.split()))
    # For each distinct value, check contiguous block
    seen = {}
    for idx, val in enumerate(parsed):
        if val not in seen:
            seen[val] = (idx, idx)
        else:
            start, end = seen[val]
            # If idx > end+1, there is a gap
            if idx > end + 1:
                assert False, f"Value {val} appears in non‑contiguous positions"
            seen[val] = (start, idx)

def test_le_i(run, x):
    out = run(x).strip()
    if out == '':
        parsed = []
    else:
        parsed = list(map(int, out.split()))
    for i, a in enumerate(parsed, start=1):
        assert a <= i, f"Light {i} turned off by button {a} > {i}"

def test_simulation(run, x):
    lines = x.strip().split('\n')
    n, _ = map(int, lines[0].split())
    if n > 20:  # Avoid simulation on large n (spec allows up to 100)
        return
    buttons = list(map(int, lines[1].split()))
    # Simulate
    turned_off_by = [0] * (n + 1)  # 1‑based
    on = [True] * (n + 1)
    for b in buttons:
        for i in range(b, n + 1):
            if on[i]:
                on[i] = False
                turned_off_by[i] = b
    expected = turned_off_by[1:]
    out = run(x).strip()
    if out == '':
        parsed = []
    else:
        parsed = list(map(int, out.split()))
    assert parsed == expected, f"Simulation expects {expected}, got {parsed}"

