        out = run(x).strip()
        if b == a:
            assert out == '1', f"t > a and b == a must output 1, got {out}"
        else:
            assert out == '0', f"t > a and b != a must output 0, got {out}"

def test_t_equal_a(run, x):
    t_str, a_str, b_str = x.strip().split()
    t, a, b = int(t_str), int(a_str), int(b_str)
    if t == a:
