        count = 0
        # For each possible degree d (0..max_deg), iterate over coefficients
        for d in range(max_deg + 1):
            # Upper bound for coefficient i: a // (t**i)
            bounds = [a // (t**i) + 1 for i in range(d + 1)]
            for coeffs in product(*[range(b) for b in bounds]):
                # Compute P(t)
                pt = sum(c * (t**i) for i, c in enumerate(coeffs))
                if pt == a:
                    # Compute P(a)
                    pa = sum(c * (a**i) for i, c in enumerate(coeffs))
                    if pa == b:
                        count += 1
        # Reduce modulo 10**9+7
        expected = count % (10**9 + 7)
        out = run(x).strip()
        assert out != 'inf', f"Small parameters (t={t}, a={a}) cannot yield infinite polynomials"
        assert int(out) == expected, f"For t={t}, a={a}, b={b} expected {expected} got {out}"

def test_inf_implies_t1_a1_b1(run, x):
    out = run(x).strip()
    if out == 'inf':
        t_str, a_str, b_str = x.strip().split()
        t, a, b = int(t_str), int(a_str), int(b_str)
        assert (t, a, b) == (1, 1, 1), f"Output 'inf' only allowed for t=a=b=1, got t={t},a={a},b={b}"

def test_t_gt1_a1(run, x):
    t_str, a_str, b_str = x.strip().split()
    t, a, b = int(t_str), int(a_str), int(b_str)
    if t > 1 and a == 1:
