            assert out == '1', f"t>1, a=1, b=1 must output 1, got {out}"
        else:
            assert out == '0', f"t>1, a=1, b !=1 must output 0, got {out}"

def test_example_2_2_2(run, x):
    if x.strip() == '2 2 2':
        out = run(x).strip()
        assert out == '2', f"Input '2 2 2' must output 2, got {out}"

