def test_shift_period(run, x):
    s = x.strip()
    out = run(x).strip()
    try:
        d = int(out)
    except ValueError:
        assert False, "Output must be an integer"
    t = s
    for _ in range(d):
        t = t[-1] + t[:-1]
    assert t == s, f"Shifting {d} times did not return to original"

def test_minimal_divisor(run, x):
    s = x.strip()
    out = run(x).strip()
    try:
        d = int(out)
    except ValueError:
        assert False, "Output must be an integer"
    n = len(s)
    for k in range(1, d):
        if n % k == 0:
            t = s
            for _ in range(k):
                t = t[-1] + t[:-1]
            if t == s:
                assert False, f"Shifting {k} times returns to original, but output is {d}"

