    assert val >= 1, "Output must be at least 1"

def test_n1(run, x):
    if x.strip() == '1':
        output = run(x)
        assert output.strip() == '1', "For n=1 the answer must be 1"

def test_n2(run, x):
    if x.strip() == '2':
        output = run(x)
        assert output.strip() == '3', "For n=2 the answer must be 3"

def test_n3(run, x):
    if x.strip() == '3':
        output = run(x)
        assert output.strip() == '7', "For n=3 the answer must be 7"

def test_small_bruteforce(run, x):
    n = int(x.strip())
    if n > 8:
        return
    # exact minimax search
    from itertools import permutations
    all_seqs = list(permutations(range(1, n+1)))
    # state: tuple of pressed buttons in order, or empty if reset
    from functools import lru_cache
    @lru_cache(None)
    def worst_pushes(state):
        if len(state) == n:
            return 0
        # adversary chooses the worst sequence consistent with state
        max_cost = -1
        for seq in all_seqs:
            # check consistency: seq must start with state
            if list(seq[:len(state)]) != list(state):
                continue
            # player chooses next button 1..n
            best = float('inf')
            for b in range(1, n+1):
                if b == seq[len(state)]:
                    new_state = state + (b,)
                else:
                    new_state = ()
                cost = 1 + worst_pushes(new_state)
                if cost < best:
                    best = cost
            if best > max_cost:
                max_cost = best
        return max_cost
    expected = worst_pushes(())
    output = run(x)
    assert int(output.strip()) == expected, f"For n={n} the answer must be {expected}"

def test_lower_bound_n(run, x):
    n = int(x.strip())
    output = run(x)
    val = int(output.strip())
    assert val >= n, f"Output {val} must be at least n={n} (each button pressed once)"

def test_strict_lower_bound(run, x):
    n = int(x.strip())
    if n >= 2:
        output = run(x)
        val = int(output.strip())
        assert val > n, f"For n={n} worst‑case pushes must be greater than n"

