      "name": "test_exact",
      "intent": "Compute the correct minimum capacity by simulating the process: maintain a set of visitors currently inside and a count. For each '+', add visitor and increment count, updating the maximum. For each '-', if visitor is in the set, remove and decrement count; otherwise, update maximum with count+1 (visitor was initially inside). The output must equal this computed maximum."
    },
    {
      "name": "test_integer",
      "intent": "The output string must parse as a single integer (no extra whitespace or characters)."
    },
    {
      "name": "test_at_least_one",
      "intent": "The output integer must be at least 1, because the log always implies at least one visitor present at some time."
    },
    {
      "name": "test_lower_bound_initial",
      "intent": "Find all visitors whose first event in the log is '-'. These visitors must have been initially inside simultaneously, so the output must be at least the number of such distinct visitors."
    },
    {
      "name": "test_upper_bound_distinct",
      "intent": "Count the distinct registration numbers appearing in the log. Since no two visitors share a registration number and each can be inside at most once at a time, the output cannot exceed this count."
    },
    {
      "name": "test_feasibility",
      "intent": "Using the output as capacity C, simulate the log: maintain a set of visitors currently inside. For each '+', if the visitor is not already inside and the current number inside equals C, the capacity is exceeded; otherwise, add them. For each '-', if the visitor is inside, remove them; otherwise, they must have been initially inside—ensure that just before this event the number inside (including them) did not exceed C. If any step fails, the output is invalid."
    },
    {
      "name": "test_per_residue_lower_bound",
      "intent": "For each residue r modulo 997, consider only events for visitors whose registration number modulo 997 equals r. Compute the minimum capacity for this sub‑log using the method from test_exact. The overall output must be at least the maximum of these per‑residue capacities."
    },
    {
      "name": "test_upper_bound_total_entrants",
      "intent": "Count the number of '+' events and the number of visitors whose first event is '-'. At any time, the number inside cannot exceed the total number of people that have ever entered (initial visitors plus those who entered later), so the output must be at most the sum of these two counts."
    },
    {
      "name": "test_lower_bound_net_flow",
      "intent": "Compute the maximum over all prefixes of the log of (number of '+' events so far minus number of '-' events so far). This net flow is a lower bound on the number inside at any time, so the output must be at least this maximum."
    },
    {
      "name": "test_all_exit_events",
      "intent": "If every event in the log is '-', then each distinct visitor must have been initially inside and all were present simultaneously at the start. Therefore, the output must equal the number of distinct registration numbers in the log."
    }
  ]
