tests_src:
def test_valid_output(run, x):
    out = run(x)
    assert out == 'YES\n' or out == 'NO\n', 'Output must be exactly YES or NO with newline'

def test_example1(run, x):
    if x == '2 3\n':
        out = run(x)
        assert out == 'YES\n', 'For input 2 3, output must be YES'

def test_example2(run, x):
    if x == '3 1\n':
        out = run(x)
        assert out == 'NO\n', 'For input 3 1, output must be NO'

def test_zero_zero(run, x):
    if x == '0 0\n':
        out = run(x)
        assert out == 'NO\n', 'For input 0 0, output must be NO because interval must be non-empty'

def test_small_bruteforce(run, x):
    a_str, b_str = x.strip().split()
    a = int(a_str); b = int(b_str)
    if a + b > 20:
        return  # skip large inputs
    # brute-force check if any interval [l, r] yields exactly a evens, b odds
    found = False
    max_r = 2000  # safe bound given a, b ≤ 100
    for l in range(1, max_r + 1):
        for r in range(l, max_r + 1):
            length = r - l + 1
            ev = length // 2
            od = length - ev
            if l % 2 == 0:
                ev, od = od, ev
            if ev == a and od == b:
                found = True
                break
        if found:
            break
    out = run(x)
    expected = 'YES\n' if found else 'NO\n'
    assert out == expected, f'For small input {a} {b}, expected {expected.strip()}'

def test_yes_implies_positive(run, x):
    out = run(x)
    a_str, b_str = x.strip().split()
    a = int(a_str); b = int(b_str)
    if out == 'YES\n':
        assert a + b > 0, 'If output is YES, interval must be non-empty so a+b > 0'

def test_yes_implies_diff_le1(run, x):
    out = run(x)
    a_str, b_str = x.strip().split()
    a = int(a_str); b = int(b_str)
    if out == 'YES\n':
        assert abs(a - b) <= 1, 'In any consecutive interval, even and odd counts differ by at most 1'

def test_specific_4_4(run, x):
    if x == '4 4\n':
        out = run(x)
        assert out == 'YES\n', 'For input 4 4, output must be YES (e.g., interval 1..8)'

def test_sum_one(run, x):
    a_str, b_str = x.strip().split()
    a = int(a_str); b = int(b_str)
    if a + b == 1:
        out = run(x)
        assert out == 'YES\n', 'When a+b == 1, a one-step interval always exists'

def test_no_extra_spaces(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n'), 'Output must be exactly YES or NO with newline, no extra spaces'

