        assert out == 'NO\n', f'Output for (0,2) is {repr(out)}, expected NO'

def test_brute_force(run, x):
    a, b = map(int, x.strip().split())
    if a + b > 200:  # keep brute-force fast; all given inputs have a+b ≤ 200
        return
    if a + b == 0:
        assert run(x) == 'NO\n', f'For (0,0) expected NO'
        return
    # try intervals [1, n] and [2, n+1] where n = a+b
    n = a + b
    # interval [1, n]
    evens1 = n // 2
    odds1 = n - evens1
    # interval [2, n+1]
    total = n  # length is n
    # odds from 2..n+1 are same as odds in 1..n if n is even? simpler: compute directly
    evens2 = (n + 1) // 2  # number of evens in 2..n+1 (since first is 2)
    odds2 = total - evens2
    correct = (evens1 == a and odds1 == b) or (evens2 == a and odds2 == b)
    out = run(x)
    if correct:
        assert out == 'YES\n', f'Input ({a},{b}) should be YES but got {repr(out)}'
    else:
        assert out == 'NO\n', f'Input ({a},{b}) should be NO but got {repr(out)}'

