        typ = parts[0]
        idd = int(parts[1])
        events.append((typ, idd))
        if idd not in ids:
            ids.append(idd)
    # try all subsets of distinct visitors as initial set
    from itertools import chain, combinations
    m = len(ids)
    best = n+1  # upper bound
    for mask in range(1 << m):
        inside = set()
        for j in range(m):
            if (mask >> j) & 1:
                inside.add(ids[j])
        ok = True
        mx = len(inside)
        for typ, idd in events:
            if typ == '+':
                if idd in inside:
