def test_small_brute_force(run, x):
    # parse input
    lines = x.strip().split('\n')
    t = int(lines[0])
    out_lines = run(x).strip('\n').split('\n')
    # process each test case
    idx = 1
    for case in range(t):
        s = lines[idx]
        idx += 1
        if len(s) > 8:
            continue  # too large for brute‑force
        # enumerate all assignments for characters present
        chars = set(s)
        n = len(chars)
        possible_working = []
        from itertools import product
        for assignment in product([False, True], repeat=n):
            # False = malfunctioning, True = working
            works = {c: assignment[i] for i, c in enumerate(sorted(chars))}
            # simulate: build string from presses, checking consistency
            # we need to see if there exists a sequence of presses that yields s
            # We'll use a DP on positions of s.
            # dp[i] = set of possible lengths of the typed string after processing s[:i]
            dp = [set() for _ in range(len(s)+1)]
            dp[0].add(0)
            for i in range(len(s)):
                c = s[i]
                for prev_len in dp[i]:
                    # press c once (if working) or twice (if malfunctioning)
                    if works[c]:
                        # working: one char added
                        if prev_len + 1 <= len(s) and s[prev_len:prev_len+1] == c:
                            dp[i+1].add(prev_len + 1)
                    else:
                        # malfunctioning: two chars added
                        if prev_len + 2 <= len(s) and s[prev_len:prev_len+2] == c*2:
                            dp[i+1].add(prev_len + 2)
            if any(l == len(s) for l in dp[len(s)]):
                # this assignment is consistent
                working_set = {c for c in chars if works[c]}
                possible_working.append(working_set)
        # intersect all consistent assignments to get sure‑working characters
        if possible_working:
            sure_working = set.intersection(*map(set, possible_working))
        else:
            sure_working = set()  # no consistent assignment → empty
        expected = ''.join(sorted(sure_working))
        if out_lines[case] != expected:
            assert False, f'Case {case}: expected "{expected}", got "{out_lines[case]}"'


def test_output_chars_in_input(run, x):
