def test_sorted_no_duplicates(run, x):
    out_lines = run(x).strip('\n').split('\n')
    for out in out_lines:
        if out == '':
            continue
        # check sorted and no duplicates
        for i in range(len(out)-1):
            if out[i] >= out[i+1]:
                assert False, f'Output "{out}" not strictly increasing'


def test_singleton_in_output(run, x):
    lines = x.strip().split('\n')
