        from collections import Counter
        cnt = Counter(s)
        for ch, freq in cnt.items():
            if freq == 1:
                if ch not in out:
                    assert False, f'Character {ch} appears once in input but missing from output'


def test_even_run_exclusion(run, x):
    lines = x.strip().split('\n')
    t = int(lines[0])
    out_lines = run(x).strip('\n').split('\n')
    for case in range(t):
        s = lines[case+1]
