        assert output == 'YES', f'All 25s but output is {output}'"
    },
    {
      "name": "test_change_amount_feasible",
      "source": "def test_change_amount_feasible(run, x):
    output = run(x).strip()
    if output == 'YES':
        lines = x.strip().split('\n')
        n = int(lines[0])
        bills = list(map(int, lines[1].split()))
