def test_small_bruteforce(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n <= 4 and m <= 4:
        MOD = 10**9 + 7
        total = 0
        # each kind chooses a non‑empty subset of m boxes
        # total ways = (2^m - 1)^n
        total = pow(pow(2, m, MOD) - 1, n, MOD)
        out = run(x).strip()
        assert out.isdigit() and int(out) == total

def test_m1(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if m == 1:
        out = run(x).strip()
        assert out == '1'

def test_n1(run, x):
    n_str, m_str = x.strip().split()
    n, m = int(n_str), int(m_str)
    if n == 1:
        MOD = 10**9 + 7
        expected = (pow(2, m, MOD) - 1) % MOD
        out = run(x).strip()
        assert out.isdigit() and int(out) == expected

def test_output_format(run, x):
    out = run(x).strip()
    # must be an integer, no leading zeros unless it's '0'
    assert out.isdigit() or (out[0] == '-' and out[1:].isdigit())
    if out != '0':
        assert out[0] != '0'
    val = int(out)
    MOD = 10**9 + 7
    assert 0 <= val < MOD

def test_odd(run, x):
    out = run(x).strip()
    val = int(out)
    assert val % 2 == 1

def test_example_2_2(run, x):
    if x.strip() == '2 2':
        out = run(x).strip()
        assert out == '9'

def test_example_1_1(run, x):
    if x.strip() == '1 1':
        out = run(x).strip()
        assert out == '1'

def test_example_2_3(run, x):
    if x.strip() == '2 3':
        # compute by brute‑force logic: (2^3-1)^2 = 7^2 = 49
        out = run(x).strip()
        assert out == '49'

def test_example_3_2(run, x):
    if x.strip() == '3 2':
        # (2^2-1)^3 = 3^3 = 27
        out = run(x).strip()
        assert out == '27'

def test_no_zero(run, x):
    out = run(x).strip()
    assert out != '0'

