  "plan": [
    {
      "name": "test_basic",
      "intent": "Check that output length equals k, all characters are from the set of letters of s, and output is lexicographically greater than s. Violation of any indicates wrong answer."
    },
    {
      "name": "test_brute_small",
      "intent": "If the number of possible strings of length k using letters from the set of s is at most 10000, enumerate all such strings, filter those lexicographically greater than s, and verify output is the smallest among them. If not, answer is wrong."
    },
    {
      "name": "test_k_greater_n",
      "intent": "If k > n, output must be exactly s followed by the smallest letter in s repeated (k-n) times. Any deviation is wrong."
    },
    {
      "name": "test_minimality_decrease",
      "intent": "For each position i in output, if character is not the smallest in set, construct string by replacing it with previous letter in sorted set and filling remainder with smallest letter. This string must be lexicographically not greater than s. If any such string is greater than s, answer is wrong."
    },
    {
      "name": "test_lex_condition",
      "intent": "Either s is a prefix of output (when k > n) or there exists index i < min(n,k) such that output[i] > s[i] and for all j < i, output[j] == s[j]. If neither holds, answer is wrong."
    },
    {
      "name": "test_not_prefix",
      "intent": "If k <= n, output must not equal the first k characters of s. If it does, answer is wrong."
    },
    {
      "name": "test_charset",
      "intent": "Every character in output must belong to the set of letters of s. If any extra character appears, answer is wrong."
    },
    {
      "name": "test_length",
      "intent": "Output string must have length exactly k. If length differs, answer is wrong."
    },
    {
      "name": "test_lex_gt",
      "intent": "Output must be lexicographically greater than s. If output <= s, answer is wrong."
    },
    {
      "name": "test_suffix_smallest",
      "intent": "If k <= n, let i be first position where output differs from s (must exist). Then for every j > i, output[j] must be the smallest letter in set of s. If any such character is not the smallest, answer is wrong."
    }
  ]
}

