tests_src:
def test_small_inputs(run, x):
    if len(x) > 1000:
        return
    out = run(x)
    lines = [line.rstrip('\n') for line in out.split('\n') if line]
    # Parse input manually
    lexemes = []
    i = 0
    in_quote = False
    current = []
    while i < len(x):
        if x[i] == '"':
            in_quote = not in_quote
            i += 1
        elif not in_quote and x[i] == ' ':
            if current:
                lexemes.append(''.join(current))
                current = []
            i += 1
        else:
            current.append(x[i])
            i += 1
    if current:
        lexemes.append(''.join(current))
    # Compare to output lines
    for line, expected in zip(lines, lexemes):
        if not (line.startswith('<') and line.endswith('>')):
            assert False, 'bad format'
        got = line[1:-1]
        assert got == expected, 'lexeme mismatch'
    assert len(lines) == len(lexemes), 'wrong number of lexemes'

def test_output_format(run, x):
    out = run(x)
    lines = out.split('\n')
    # Remove trailing empty line if present
    if lines and lines[-1] == '':
        lines = lines[:-1]
    for line in lines:
        assert line.startswith('<') and line.endswith('>'), 'missing delimiters'
        assert line.count('<') == 1 and line.count('>') == 1, 'extra delimiters'
        content = line[1:-1]
        assert '<' not in content and '>' not in content, 'extra angle brackets in content'

def test_no_quotes_in_lexemes(run, x):
    out = run(x)
    lines = out.split('\n')
    for line in lines:
        if line == '':
            continue
        content = line[1:-1]
        assert '"' not in content, 'quote character inside lexeme'

def test_lexeme_count(run, x):
    out = run(x)
    lines = [line for line in out.split('\n') if line]
    # Count lexemes by spec rules
    count = 0
    in_quote = False
    i = 0
    while i < len(x):
        if x[i] == '"':
            in_quote = not in_quote
            if not in_quote:
                count += 1  # quoted block just ended
            i += 1
        elif not in_quote and x[i] != ' ':
            # start of a non‑quoted lexeme
            count += 1
            while i < len(x) and x[i] != ' ' and x[i] != '"':
                i += 1
        else:
            i += 1
    assert len(lines) == count, 'wrong number of lexemes'

def test_empty_lexemes(run, x):
    out = run(x)
    lines = [line for line in out.split('\n') if line]
    empty_output = sum(1 for line in lines if line == '<>')
    empty_input = x.count('""')
    assert empty_output == empty_input, 'empty lexeme count mismatch'

def test_non_space_order(run, x):
    out = run(x)
    lines = [line for line in out.split('\n') if line]
    # Remove quotes and spaces from input
    s_noq = []
    for ch in x:
        if ch != '"' and ch != ' ':
            s_noq.append(ch)
    S = ''.join(s_noq)
    # Remove spaces from concatenated lexemes
    L = ''.join(line[1:-1] for line in lines).replace(' ', '')
    assert S == L, 'character sequence mismatch after removing quotes and spaces'

def test_total_length(run, x):
    out = run(x)
    lines = [line for line in out.split('\n') if line]
    total_out = sum(len(line) - 2 for line in lines)  # subtract <>
    # Compute expected total length
    total_exp = 0
    in_quote = False
    for ch in x:
        if ch == '"':
            in_quote = not in_quote
        elif in_quote or (not in_quote and ch != ' '):
            total_exp += 1
    assert total_out == total_exp, 'total lexeme length mismatch'

def test_spaces_require_quotes(run, x):
    out = run(x)
    lines = [line for line in out.split('\n') if line]
    for line in lines:
        lex = line[1:-1]
        if ' ' in lex:
            quoted = '"' + lex + '"'
            assert quoted in x, f'space-containing lexeme {lex} not quoted in input'

def test_space_containing_blocks(run, x):
    out = run(x)
    lines = [line for line in out.split('\n') if line]
    space_lexemes = sum(1 for line in lines if ' ' in line[1:-1])
    # Count quoted blocks with at least one space
    in_quote = False
    block_has_space = False
    quoted_blocks_with_space = 0
    i = 0
    while i < len(x):
        if x[i] == '"':
            if in_quote and block_has_space:
                quoted_blocks_with_space += 1
            in_quote = not in_quote
            block_has_space = False
            i += 1
        elif in_quote:
            if x[i] == ' ':
                block_has_space = True
            i += 1
        else:
            i += 1
    # Last block closed at end of string is guaranteed by correctness
    if in_quote and block_has_space:
        quoted_blocks_with_space += 1
    assert space_lexemes == quoted_blocks_with_space, 'space-containing lexeme count mismatch'

def test_lexeme_characters(run, x):
    import string
    allowed = set(string.ascii_letters + string.digits + '.,?! ')
    out = run(x)
    lines = [line for line in out.split('\n') if line]
    for line in lines:
        lex = line[1:-1]
        for ch in lex:
            assert ch in allowed, f'invalid character {ch} in lexeme'

