tests_src:
def test_example1(run, x):
    if x == "3\n1 2 -1\n":
        out = run(x)
        assert out.strip() == "3"

def test_example2(run, x):
    if x == "5\n28 35 7 14 21\n":
        out = run(x)
        assert out.strip() == "4"

def test_bruteforce(run, x):
    # Only run brute force for n ≤ 30 because O(n^3) is okay and inputs given are small.
    import sys
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    n = int(lines[0])
    if n > 30:
        return
    from collections import Counter
    a = list(map(int, lines[1].split()))
    cnt = Counter(a)
    best = 2
    # Try all ordered pairs (x,y) with available multiplicities.
    items = list(cnt.items())
    for val1, c1 in items:
        for val2, c2 in items:
            if val1 == val2 and c1 < 2:
                continue
            used = Counter()
            used[val1] += 1
            used[val2] += 1
            if used[val1] > cnt[val1] or used[val2] > cnt[val2]:
                continue
            length = 2
            prev1, prev2 = val1, val2
            while True:
                nxt = prev1 + prev2
                if used[nxt] + 1 <= cnt[nxt]:
                    used[nxt] += 1
                    length += 1
                    prev1, prev2 = prev2, nxt
                else:
                    break
            if length > best:
                best = length
    out = run(x).strip()
    assert out.isdigit() and int(out) == best

def test_min_length(run, x):
    out = run(x).strip()
    assert out.isdigit() and int(out) >= 2

def test_max_length(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = run(x).strip()
    assert out.isdigit() and int(out) <= n

def test_all_zero(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    if all(v == 0 for v in a):
        out = run(x).strip()
        assert out.isdigit() and int(out) == len(a)

def test_all_equal_nonzero(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    if len(set(a)) == 1 and a[0] != 0:
        out = run(x).strip()
        assert out.isdigit() and int(out) == 2

def test_exists_triple(run, x):
    # We cannot assert output ≥ 3 just because a triple exists, because that requires solving.
    # Instead we check contrapositive: if output < 3 then there must not exist a triple.
    out = run(x).strip()
    if not out.isdigit():
        return
    ans = int(out)
    if ans < 3:
        # verify no triple exists
        lines = x.strip().split('\n')
        a = list(map(int, lines[1].split()))
        from collections import Counter
        cnt = Counter(a)
        triple_exists = False
        for x_val, cx in cnt.items():
            for y_val, cy in cnt.items():
                if x_val == y_val and cx < 2:
                    continue
                s = x_val + y_val
                if cnt.get(s, 0) >= (1 if s != x_val and s != y_val else (2 if s == x_val == y_val else 1)):
                    # careful with multiplicities: we only need one occurrence of s beyond those used.
                    # We have at least one x and one y available (if x==y then two).
                    # For s, we need at least one if s is different, or at least two if s equals x and y.
                    if s == x_val == y_val:
                        if cx >= 3:
                            triple_exists = True
                    elif s == x_val or s == y_val:
                        if cnt[s] >= 2:
                            triple_exists = True
                    else:
                        if cnt[s] >= 1:
                            triple_exists = True
                if triple_exists:
                    break
            if triple_exists:
                break
        assert not triple_exists, f"Output is {ans} but a Fibonacci-ish triple exists"

def test_no_triple(run, x):
    # If output is exactly 2, then there must be no triple.
    out = run(x).strip()
    if not out.isdigit():
        return
    ans = int(out)
    if ans == 2:
        lines = x.strip().split('\n')
        a = list(map(int, lines[1].split()))
        from collections import Counter
        cnt = Counter(a)
        triple_exists = False
        for x_val, cx in cnt.items():
            for y_val, cy in cnt.items():
                if x_val == y_val and cx < 2:
                    continue
                s = x_val + y_val
                if cnt.get(s, 0) >= (1 if s != x_val and s != y_val else (2 if s == x_val == y_val else 1)):
                    if s == x_val == y_val:
                        if cx >= 3:
                            triple_exists = True
                    elif s == x_val or s == y_val:
                        if cnt[s] >= 2:
                            triple_exists = True
                    else:
                        if cnt[s] >= 1:
                            triple_exists = True
                if triple_exists:
                    break
            if triple_exists:
                break
        assert not triple_exists, f"Output is 2 but a Fibonacci-ish triple exists"

def test_output_integer(run, x):
    out = run(x).strip()
    # Must be a valid integer
    try:
        int(out)
    except ValueError:
        assert False, "Output is not a valid integer"

