def test_small_brute(run, x):
    lines = x.strip().split('\n')
    n_k = list(map(int, lines[0].split()))
    if len(n_k) == 1:
        n_k = list(map(int, lines[1].split()))
    n, k = n_k
    a = list(map(int, lines[2].split()))
    # Only brute when small
    if n <= 4 and max(a) <= 4:
        from itertools import product
        # generate all non-decreasing sequences of length n with values in 0..max(a)
        # for each m from 1 to max(a) (since m <= a_n) try to split
        found = None
        for m in range(1, max(a)+1):
            # each b_i is non-decreasing, at most k distinct values
            # we can brute over all possible tuples of m sequences
            # but that's huge; instead we can think of each column independently?
            # Since n is tiny, we can brute over all possible b_i as sequences
            # with values in 0..max(a) and non-decreasing.
            # Generate all such sequences for one array
            seqs = []
            for vals in product(range(max(a)+1), repeat=n):
                if all(vals[i] <= vals[i+1] for i in range(n-1)):
                    if len(set(vals)) <= k:
                        seqs.append(vals)
            # now check if there exist m sequences from seqs that sum to a
            # brute force over m-tuples
            # This is still large but for n<=4, max(a)<=4, |seqs| is manageable.
            # We'll do a DFS.
            # But for simplicity, we'll use a naive search.
            # Since m <= max(a) <=4, we can iterate over m-tuples with repetition.
            # We'll implement a recursive search.
            def dfs(idx, chosen):
                if idx == m:
                    # check sum
                    total = [0]*n
                    for seq in chosen:
                        for i in range(n):
                            total[i] += seq[i]
                    if total == a:
                        return True
                    return False
                for seq in seqs:
                    chosen.append(seq)
                    if dfs(idx+1, chosen):
                        return True
                    chosen.pop()
                return False
            if dfs(0, []):
                found = m
                break
        out = run(x).strip()
        try:
            ans = int(out)
        except ValueError:
            assert False
        if found is None:
            assert ans == -1, f"No solution exists, expected -1, got {ans}"
        else:
            assert ans == found, f"Brute force says minimum m = {found}, got {ans}"

