def test_format(run, x):
    output = run(x).rstrip('\n')
    lines = output.split('\n')
    if lines[0] == 'NO':
        assert len(lines) == 1, "NO output must be a single line"
        return
    assert lines[0] == 'YES', "First line must be YES or NO"
    n = int(x.split('\n')[0])
    expected_lines = 2 * n - 1
    assert len(lines) == expected_lines + 1, f"Expected {expected_lines+1} lines total (YES + board), got {len(lines)}"
    for i in range(1, len(lines)):
        assert len(lines[i]) == 2 * n - 1, f"Line {i} length mismatch: expected {2*n-1}, got {len(lines[i])}"
        for ch in lines[i]:
            assert ch in 'xo.', f"Invalid character '{ch}' in board"


def test_center_o(run, x):
