def test_brute_force_small(run, x):
    n = int(x.split('\n')[0])
    if n > 6:
        return  # too large for brute force
    input_lines = x.strip().split('\n')[1:1+n]
    pieces = [(r, c) for r in range(n) for c in range(n) if input_lines[r][c] == 'o']
    # enumerate all subsets of possible move vectors (dx,dy) with |dx|,|dy| < n
    all_moves = [(dr, dc) for dr in range(-(n-1), n) for dc in range(-(n-1), n) if not (dr == 0 and dc == 0)]
    from itertools import chain, combinations
    possible = False
    for mask in range(1 << len(all_moves)):
        moves = [all_moves[i] for i in range(len(all_moves)) if (mask >> i) & 1]
        ok = True
        # check condition: no move lands on a '.' from any piece
        for (dr, dc) in moves:
            for (r, c) in pieces:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < n and input_lines[nr][nc] == '.':
                    ok = False
                    break
            if not ok:
                break
        if not ok:
            continue
        # check that every 'x' is attacked
        for r in range(n):
            for c in range(n):
                if input_lines[r][c] == 'x':
                    attacked = False
                    for (pr, pc) in pieces:
                        dr, dc = r - pr, c - pc
                        if (dr, dc) in moves:
                            attacked = True
                            break
                    if not attacked:
                        ok = False
                        break
            if not ok:
                break
        if ok:
            possible = True
            break
    output = run(x).rstrip('\n')
    lines = output.split('\n')
    if possible:
        assert lines[0] == 'YES', f"Solution exists but output is not YES"
        # verify that the provided board is valid (already covered by other tests, but we can double‑check)
        # we rely on test_no_attack_on_dot and test_every_x_covered for that
    else:
        assert lines[0] == 'NO', f"No solution exists but output is not NO"


def test_illegal_chars(run, x):
    output = run(x)
    allowed = set('YESNO\nxo.')
    for ch in output:
        assert ch in allowed, f"Illegal character '{ch}' in output"


