def test_brute_force(run, x):
    lines = x.strip().splitlines()
    N = int(lines[0])
    grid = [list(line.strip()) for line in lines[1:]]
    # only brute-force for small N
    if N <= 6:
        rectangles = []
        for x1 in range(N):
            for x2 in range(x1+1, N+1):
                for y1 in range(N):
                    for y2 in range(y1+1, N+1):
                        # compute expected grid
                        expected = [[0]*N for _ in range(N)]
                        for r in range(N):
                            # row index r corresponds to y = N - r
                            y_cell = N - r
                            for c in range(N):
                                x_cell = c + 1
                                cnt = 0
                                if x1 <= x_cell-1 < x2 and y1 <= y_cell-1 < y2:
                                    cnt += 1
                                if x1 <= x_cell   < x2 and y1 <= y_cell-1 < y2:
                                    cnt += 1
                                if x1 <= x_cell-1 < x2 and y1 <= y_cell   < y2:
                                    cnt += 1
                                if x1 <= x_cell   < x2 and y1 <= y_cell   < y2:
                                    cnt += 1
                                expected[r][c] = str(cnt)
                        if all(expected[r][c] == grid[r][c] for r in range(N) for c in range(N)):
                            rectangles.append((x1, x2, y1, y2))
        correct = 'Yes' if rectangles else 'No'
        output = run(x).strip()
        assert output == correct, f'Brute force says {correct} but output is {output}'
    else:
        # For larger N we cannot brute-force; just ensure output is Yes/No
        output = run(x).strip()
        assert output in ('Yes', 'No'), 'Output must be Yes or No'


def test_output_format(run, x):
    output = run(x)
    stripped = output.strip()
    assert stripped == 'Yes' or stripped == 'No', 'Output must be exactly Yes or No (optional newline)'
    # Ensure no extra characters before or after
    if output != stripped:
        # allow exactly one newline at end
        assert output == stripped + '\n', 'Extra whitespace not allowed'


