def test_full_consistency(run, x):
    lines = x.strip().splitlines()
    N = int(lines[0])
    grid = [list(line.strip()) for line in lines[1:]]
    output = run(x).strip()
    if output == 'Yes' and N <= 6:  # only recompute for small N
        # infer rectangle from 4-block
        four_positions = [(r, c) for r in range(N) for c in range(N) if grid[r][c] == '4']
        if not four_positions:
            return
        rows = [r for r, c in four_positions]
        cols = [c for r, c in four_positions]
        min_row, max_row = min(rows), max(rows)
        min_col, max_col = min(cols), max(cols)
        # convert to rectangle coordinates (x1, x2, y1, y2) as in spec: grid cells are 1..N
        x1 = min_col          # because column index c corresponds to x = c+1, so min x = min_col+1? Wait: careful.
        # Actually: cell (r,c) has corners at (c, N-r) and (c+1, N-r) and (c, N-r-1) and (c+1, N-r-1).
        # The rectangle corners are integer lattice points (x1, y1) etc with 0 ≤ x1 < x2 ≤ N, 0 ≤ y1 < y2 ≤ N.
        # The block of 4's corresponds to cells completely inside the rectangle.
        # A cell is fully inside if its four corners are inside/on rectangle.
        # That means cell's x range [c, c+1] is inside [x1, x2] and y range [N-r-1, N-r] inside [y1, y2].
        # So for the 4-block we have x1 ≤ c, c+1 ≤ x2 and y1 ≤ N-r-1, N-r ≤ y2.
        # Therefore x1 = min_col, x2 = max_col+1, y1 = N-1-max_row, y2 = N-min_row.
        x1 = min_col
        x2 = max_col + 1
        y1 = N - 1 - max_row
        y2 = N - min_row
        # compute expected grid
        expected = [[0]*N for _ in range(N)]
        for r in range(N):
            y_cell_top = N - r        # y coordinate of top edge of cell
            y_cell_bottom = N - r - 1 # y coordinate of bottom edge
            for c in range(N):
                x_cell_left = c
                x_cell_right = c + 1
                cnt = 0
                if x1 <= x_cell_left <= x2 and y1 <= y_cell_bottom <= y2:
                    cnt += 1
                if x1 <= x_cell_right <= x2 and y1 <= y_cell_bottom <= y2:
                    cnt += 1
                if x1 <= x_cell_left <= x2 and y1 <= y_cell_top <= y2:
                    cnt += 1
                if x1 <= x_cell_right <= x2 and y1 <= y_cell_top <= y2:
                    cnt += 1
                expected[r][c] = str(cnt)
        for r in range(N):
            for c in range(N):
                assert grid[r][c] == expected[r][c], f'Inconsistency at ({r},{c}): expected {expected[r][c]}, got {grid[r][c]}'


