def test_exact_brute_force(run, x):
    a, b = x.strip().split('\n')
    if len(a) > 8 or len(b) > 8:
        # Too large for brute force; just check output is nonempty or '-'
        out = run(x).rstrip('\n')
        assert out == '-' or (out.isalpha() and out.islower())
        return
    best_len = -1
    best_strings = set()
    n = len(b)
    # enumerate all consecutive removals
    for start in range(n+1):
        for end in range(start, n+1):
            candidate = b[:start] + b[end:]
            # check if candidate is subsequence of a
            i = 0
            for ch in candidate:
                i = a.find(ch, i)
                if i == -1:
                    break
                i += 1
            else:
                if len(candidate) > best_len:
                    best_len = len(candidate)
                    best_strings = {candidate}
                elif len(candidate) == best_len:
                    best_strings.add(candidate)
    if best_len == 0:
        best_strings.add('-')
    out = run(x).rstrip('\n')
    assert out in best_strings

def test_is_subsequence(run, x):
    a, b = x.strip().split('\n')
    out = run(x).rstrip('\n')
    if out == '-':
        return
    i = 0
    for ch in out:
        i = a.find(ch, i)
        if i == -1:
            assert False, f"character {ch} not found in order"
        i += 1

def test_one_consecutive_removal(run, x):
    a, b = x.strip().split('\n')
    out = run(x).rstrip('\n')
    if out == '-':
        return
    # check if out can be obtained from b by removing one consecutive block
    found = False
    n = len(b)
    m = len(out)
    for start in range(n+1):
        for end in range(start, n+1):
            if b[:start] + b[end:] == out:
                found = True
                break
        if found:
            break
    assert found, f"output cannot be obtained by one consecutive removal from b"

def test_characters_in_a(run, x):
    a, b = x.strip().split('\n')
    out = run(x).rstrip('\n')
    if out == '-':
        return
    set_a = set(a)
    for ch in out:
        assert ch in set_a, f"output contains character {ch} not in a"

def test_length_bound_prefix_suffix(run, x):
    a, b = x.strip().split('\n')
    out = run(x).rstrip('\n')
    # longest prefix of b that is subsequence of a
    i = 0
    prefix_len = 0
    for ch in b:
        i = a.find(ch, i)
        if i == -1:
            break
        i += 1
        prefix_len += 1
    # longest suffix of b that is subsequence of a
    i = len(a) - 1
    suffix_len = 0
    for ch in reversed(b):
        j = a.rfind(ch, 0, i+1) if i >=0 else -1
        if j == -1:
            break
        i = j - 1
        suffix_len += 1
    bound = max(prefix_len, suffix_len)
    if out == '-':
        assert bound == 0, f"empty output but bound is {bound}"
    else:
        assert len(out) >= bound, f"output length {len(out)} < bound {bound}"

def test_nonempty_if_edge_in_a(run, x):
    a, b = x.strip().split('\n')
    out = run(x).rstrip('\n')
    if out == '-':
        if b and (b[0] in a or b[-1] in a):
            assert False, f"output empty but edge character present in a"

def test_empty_implies_edge_not_in_a(run, x):
    a, b = x.strip().split('\n')
    out = run(x).rstrip('\n')
    if out == '-':
        if b:
            assert b[0] not in a, f"empty output but first character in a"
            assert b[-1] not in a, f"empty output but last character in a"

def test_length_not_exceed_b(run, x):
    a, b = x.strip().split('\n')
    out = run(x).rstrip('\n')
    if out != '-':
        assert len(out) <= len(b), f"output length {len(out)} > length of b {len(b)}"

def test_examples(run, x):
    if x == "hi\nbob\n":
        assert run(x) == "-\n", "example 1 mismatch"
    elif x == "abca\naccepted\n":
        assert run(x) == "ac\n", "example 2 mismatch"
    elif x == "abacaba\nabcdcba\n":
        assert run(x) == "abcba\n", "example 3 mismatch"
    # otherwise pass

def test_output_format(run, x):
    out = run(x)
    assert out.endswith('\n'), "output must end with newline"
    line = out.rstrip('\n')
    if line == '-':
        return
    assert line.isalpha() and line.islower(), f"output must be lowercase letters or '-', got {repr(line)}"
    assert line, "output must not be empty (unless '-') "

