      "name": "test_output_non_negative",
      "intent": "Since all damages are positive and we can choose zero hits, the output must be ≥ 0."
    },
    {
      "name": "test_output_not_exceed_total_sum",
      "intent": "The output cannot exceed the sum of all given damage values, because that sum is the total damage if every hit were taken (even if that selection is invalid)."
    },
    {
      "name": "test_output_at_least_max_damage",
      "intent": "We can always select exactly one hit (the one with the largest damage), so the output must be at least the maximum of the damage array."
    },
    {
      "name": "test_output_upper_bound_per_block",
      "intent": "For each maximal contiguous block of identical letters, at most k hits can be chosen from that block. Therefore the sum over blocks of the k largest damages in each block is an upper bound on the answer."
    },
    {
      "name": "test_output_lower_bound_greedy",
      "intent": "A simple greedy algorithm that takes a hit whenever pressing it would not make the current button's consecutive count exceed k produces a feasible solution. Its total damage is a lower bound on the optimum."
    },
    {
      "name": "test_all_distinct_letters",
      "intent": "If all characters in the string are distinct, no two consecutive chosen hits can be the same, so the constraint is always satisfied and the optimum is to take all hits. Thus the output must equal the sum of all damages."
    },
    {
      "name": "test_k_ge_n",
      "intent": "If k ≥ n, even if all hits use the same button we can take all of them without breaking it. Hence the optimum is the sum of all damages."
    },
    {
      "name": "test_k_eq_1_all_same",
      "intent": "If k = 1 and all characters are identical, we can take at most one hit, so the optimum is the maximum damage among the hits."
    }
  ]
}

