def test_example1(run, x):
    if x == '4 3 2\n1\n2\n3\n4\n':
        out = run(x)
        assert out == 'Vanya\nVova\nVanya\nBoth\n', f'Expected exact example output, got {repr(out)}'

def test_example2(run, x):
    if x == '2 1 1\n1\n2\n':
        out = run(x)
        assert out == 'Both\nBoth\n', f'Expected exact example output, got {repr(out)}'

def test_x_equal_y(run, x):
    first = x.split('\n')[0]
    n_str, x_str, y_str = first.split()
    x_val = int(x_str)
    y_val = int(y_str)
    if x_val == y_val:
        out = run(x)
        lines = out.rstrip('\n').split('\n')
        for line in lines:
            assert line == 'Both', f'When x == y, every line must be "Both", got {repr(line)}'

def test_first_hit(run, x):
    lines = x.rstrip('\n').split('\n')
    first_line = lines[0].split()
    if len(first_line) != 3:
        return
    x_val = int(first_line[1])
    y_val = int(first_line[2])
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    for i, a_line in enumerate(lines[1:]):
        a = int(a_line)
        if a == 1:
            expected = 'Vanya' if x_val > y_val else ('Vova' if x_val < y_val else 'Both')
            assert out_lines[i] == expected, f'For a_i=1, expected {expected}, got {repr(out_lines[i])}'

def test_small_simulation(run, x):
    lines = x.rstrip('\n').split('\n')
    first = lines[0].split()
    n = int(first[0])
    x_val = int(first[1])
    y_val = int(first[2])
    if x_val > 100 or y_val > 100:
        return
    a_vals = [int(lines[i+1]) for i in range(n)]
    if any(a > 10000 for a in a_vals):
        return
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    for idx, a in enumerate(a_vals):
        hits = 0
        i = 1
        j = 1
        last_hitters = set()
        while hits < a:
            t_vanya = i / x_val
            t_vova = j / y_val
            if abs(t_vanya - t_vova) < 1e-12:
                hits += 2
                i += 1
                j += 1
                last_hitters = {'Both'}
            elif t_vanya < t_vova:
                hits += 1
                i += 1
                last_hitters = {'Vanya'}
            else:
                hits += 1
                j += 1
                last_hitters = {'Vova'}
        expected = 'Both' if 'Both' in last_hitters else (list(last_hitters)[0])
        assert out_lines[idx] == expected, f'Simulation mismatch for monster {idx}: expected {expected}, got {repr(out_lines[idx])}'

def test_duplicate_a(run, x):
    lines = x.rstrip('\n').split('\n')
    first = lines[0].split()
    n = int(first[0])
    a_vals = [int(lines[i+1]) for i in range(n)]
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    seen = {}
    for i, a in enumerate(a_vals):
        if a in seen:
            assert out_lines[i] == seen[a], f'Duplicate a_i={a} must have same output, got {repr(out_lines[i])} vs {repr(seen[a])}'
        else:
            seen[a] = out_lines[i]

def test_line_count(run, x):
    first = x.split('\n')[0].split()
    n = int(first[0])
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if out.endswith('\n'):
        lines = out[:-1].split('\n')
    else:
        lines = out.split('\n')
    assert len(lines) == n, f'Expected {n} output lines, got {len(lines)}'

def test_line_format(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    import re
    pattern = re.compile(r'^(Vanya|Vova|Both)$')
    for line in lines:
        assert pattern.match(line), f'Line {repr(line)} does not match allowed words'

def test_no_extra_whitespace(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    for line in lines:
        assert line == line.strip(), f'Line has extra whitespace: {repr(line)}'

def test_capitalization(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    allowed = {'Vanya', 'Vova', 'Both'}
    for line in lines:
        assert line in allowed, f'Line {repr(line)} not exactly one of the allowed capitalized words'

