tests_src:
def test_output_parses(run, x):
    out = run(x)
    try:
        n = int(out.strip())
        assert n >= 0
    except Exception:
        assert False, 'Output must be a nonnegative integer'

def test_upper_bound(run, x):
    parts = list(map(int, x.strip().split()))
    k, a, b = parts
    length = b - a + 1
    out = int(run(x).strip())
    assert out <= length, 'Output cannot exceed number of integers in [a,b]'

def test_k_eq_1(run, x):
    parts = list(map(int, x.strip().split()))
    k, a, b = parts
    if k == 1:
        expected = b - a + 1
        out = int(run(x).strip())
        assert out == expected, 'When k=1 every integer in range is divisible'

def test_single_point(run, x):
    parts = list(map(int, x.strip().split()))
    k, a, b = parts
    if a == b:
        out = int(run(x).strip())
        if a % k == 0:
            assert out == 1, 'Single integer divisible => output must be 1'
        else:
            assert out == 0, 'Single integer not divisible => output must be 0'

def test_brute_small_range(run, x):
    parts = list(map(int, x.strip().split()))
    k, a, b = parts
    if b - a + 1 <= 100000:
        count = 0
        for x_val in range(a, b + 1):
            if x_val % k == 0:
                count += 1
        out = int(run(x).strip())
        assert out == count, 'Brute force count mismatch for small range'

def test_existence_consistency(run, x):
    parts = list(map(int, x.strip().split()))
    k, a, b = parts
    # ceil(a/k)
    if a >= 0:
        ceil_ak = (a + k - 1) // k
    else:
        ceil_ak = -((-a) // k)  # floor division towards -∞
    floor_bk = b // k
    out = int(run(x).strip())
    if ceil_ak <= floor_bk:
        assert out >= 1, 'At least one multiple exists => output >=1'
    else:
        assert out == 0, 'No multiple exists => output must be 0'

def test_large_k(run, x):
    parts = list(map(int, x.strip().split()))
    k, a, b = parts
    length = b - a + 1
    if k > length:
        out = int(run(x).strip())
        assert out in (0, 1), 'When k > length, at most one multiple possible'

def test_divisible_endpoints(run, x):
    parts = list(map(int, x.strip().split()))
    k, a, b = parts
    out = int(run(x).strip())
    if a % k == 0:
        assert out >= 1, 'a divisible => output >=1'
    if b % k == 0:
        assert out >= 1, 'b divisible => output >=1'

def test_output_format(run, x):
    out = run(x)
    stripped = out.strip()
    import re
    assert re.fullmatch(r'\d+', stripped), 'Output must consist only of digits (optional newline)'

def test_both_endpoints_divisible(run, x):
    parts = list(map(int, x.strip().split()))
    k, a, b = parts
    if a % k == 0 and b % k == 0:
        expected = (b - a) // k + 1
        out = int(run(x).strip())
        assert out == expected, 'Both endpoints divisible => multiples form arithmetic progression'

