def test_output_format(run, x):
    output = run(x)
    # Must be a string that can be parsed as an integer, possibly with surrounding whitespace
    try:
        int(output.strip())
    except ValueError:
        assert False, 'Output must be a valid integer'

def test_nonnegative(run, x):
    output = run(x)
    val = int(output.strip())
    assert val >= 0, 'Answer must be nonnegative'

def test_lower_bound(run, x):
    # Compute positions of fragment 1 and fragment n (1-indexed positions in the list)
    lines = x.strip().split('\n')
    n = int(lines[0])
    f = list(map(int, lines[1].split()))
    # Build mapping from fragment number to index (0‑based)
    pos = {}
    for idx, frag in enumerate(f):
        pos[frag] = idx
    # fragments are 1..n
    pos1 = pos[1]
    posn = pos[n]
    D = abs(posn - pos1)
    answer = int(run(x).strip())
    assert answer >= D, f'Answer {answer} < lower bound {D}'

def test_parity(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    f = list(map(int, lines[1].split()))
    pos = {}
    for idx, frag in enumerate(f):
        pos[frag] = idx
    pos1 = pos[1]
    posn = pos[n]
    expected_parity = (posn - pos1) % 2
    answer = int(run(x).strip())
    assert answer % 2 == expected_parity, f'Parity mismatch: answer mod 2 = {answer % 2}, expected {expected_parity}'

def test_n1(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        answer = int(run(x).strip())
        assert answer == 0, 'For n=1 answer must be 0'

def test_identity(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    f = list(map(int, lines[1].split()))
    if all(f[i] == i+1 for i in range(n)):
        answer = int(run(x).strip())
        assert answer == n-1, f'For identity permutation answer must be {n-1}'

def test_reverse(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    f = list(map(int, lines[1].split()))
    if all(f[i] == n - i for i in range(n)):
        answer = int(run(x).strip())
        assert answer == n-1, f'For reverse permutation answer must be {n-1}'

def test_example1(run, x):
    if x == '3\n3 1 2\n':
        output = run(x)
        assert output == '3\n', f'For example 1 expected "3\n", got {repr(output)}'

def test_example2(run, x):
    if x == '5\n1 3 5 4 2\n':
        output = run(x)
        assert output == '10\n', f'For example 2 expected "10\n", got {repr(output)}'

def test_correct_sum(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    # Only compute the sum if n is small enough; we guard at n <= 1000 to keep the test fast.
    if n > 1000:
        return  # skip large inputs
    f = list(map(int, lines[1].split()))
    # Build mapping fragment -> position (0‑based)
    pos = {}
    for idx, frag in enumerate(f):
        pos[frag] = idx
    total = 0
    for i in range(1, n):
        total += abs(pos[i] - pos[i+1])
    answer = int(run(x).strip())
    assert answer == total, f'Answer {answer} does not match computed sum {total}'

