tests_src:
def test_integer(run, x):
    out = run(x).strip()
    try:
        int(out)
    except ValueError:
        assert False, "output must be an integer"

def test_range(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    out = run(x).strip()
    k = int(out)
    assert 1 <= k <= n, f"output {k} not in [1, {n}]"

def test_n1(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    if n == 1:
        out = run(x).strip()
        assert out == '1', f"for n=1 output must be 1, got {out}"

def test_all_gaps_le_c(run, x):
    lines = x.strip().split('\n')
    n, c = map(int, lines[0].split())
    if n <= 1:
        return
    times = list(map(int, lines[1].split()))
    all_le = all(times[i] - times[i-1] <= c for i in range(1, n))
    if all_le:
        out = run(x).strip()
        k = int(out)
        assert k == n, f"all gaps <= c => output must be {n}, got {k}"

def test_all_gaps_gt_c(run, x):
    lines = x.strip().split('\n')
    n, c = map(int, lines[0].split())
    if n <= 1:
        return
    times = list(map(int, lines[1].split()))
    all_gt = all(times[i] - times[i-1] > c for i in range(1, n))
    if all_gt:
        out = run(x).strip()
        k = int(out)
        assert k == 1, f"all gaps > c => output must be 1, got {k}"

def test_last_gap_gt_c(run, x):
    lines = x.strip().split('\n')
    n, c = map(int, lines[0].split())
    if n <= 1:
        return
    times = list(map(int, lines[1].split()))
    if times[-1] - times[-2] > c:
        out = run(x).strip()
        k = int(out)
        assert k == 1, f"last gap > c => output must be 1, got {k}"

def test_suffix_condition(run, x):
    lines = x.strip().split('\n')
    n, c = map(int, lines[0].split())
    times = list(map(int, lines[1].split()))
    out = run(x).strip()
    k = int(out)
    # check that the suffix of length k satisfies consecutive gaps <= c
    for i in range(n - k, n - 1):
        if times[i+1] - times[i] > c:
            assert False, f"gap at index {i} > c in claimed suffix"
    # check that the gap before the suffix (if exists) is > c
    if n - k - 1 >= 0:
        if times[n - k] - times[n - k - 1] <= c:
            assert False, f"gap before suffix not > c"

def test_example1(run, x):
    if x == "6 5\n1 3 8 14 19 20\n":
        out = run(x).strip()
        assert out == '3', f"example1 must output 3, got {out}"

def test_example2(run, x):
    if x == "6 1\n1 3 5 7 9 10\n":
        out = run(x).strip()
        assert out == '2', f"example2 must output 2, got {out}"

def test_simulation_small(run, x):
    lines = x.strip().split('\n')
    n, c = map(int, lines[0].split())
    if n > 10:
        return
    times = list(map(int, lines[1].split()))
    count = 1
    for i in range(1, n):
        if times[i] - times[i-1] <= c:
            count += 1
        else:
            count = 1
    out = run(x).strip()
    k = int(out)
    assert k == count, f"simulation gives {count}, output is {k}"

