def test_output_format(run, x):
    output = run(x)
    value = int(output.strip())  # raises ValueError if not an integer
    # Check no extra characters after the integer
    # strip trailing whitespace, but ensure no non-whitespace remains after parsing
    # We'll reconstruct the expected output string
    expected = str(value)
    # Allow trailing newline(s) and spaces/tabs, but nothing else.
    # So after stripping whitespace, it should equal expected.
    if output.rstrip(' \t\n') != expected:
        raise AssertionError('Output contains extra non-whitespace characters')

def test_range(run, x):
    n = int(x.strip())
    ans = int(run(x).strip())
    # The count of numbers from 1..n not divisible by 2..10 must be between 0 and n inclusive.
    assert 0 <= ans <= n, f'Answer {ans} out of range [0, {n}]'

def test_small_brute_force_1e3(run, x):
    n = int(x.strip())
    if n > 1000:
        return  # skip, as per plan
    # brute force correct answer
    cnt = 0
    for i in range(1, n + 1):
        ok = True
        for d in range(2, 11):
            if i % d == 0:
                ok = False
                break
        if ok:
            cnt += 1
    ans = int(run(x).strip())
    assert ans == cnt, f'For n={n}, expected {cnt}, got {ans}'

def test_small_brute_force_1e4(run, x):
    n = int(x.strip())
    if n > 10000:
        return
    cnt = 0
    for i in range(1, n + 1):
        ok = True
        for d in range(2, 11):
            if i % d == 0:
                ok = False
                break
        if ok:
            cnt += 1
    ans = int(run(x).strip())
    assert ans == cnt

def test_small_brute_force_1e5(run, x):
    n = int(x.strip())
    if n > 100000:
        return
    cnt = 0
    for i in range(1, n + 1):
        ok = True
        for d in range(2, 11):
            if i % d == 0:
                ok = False
                break
        if ok:
            cnt += 1
    ans = int(run(x).strip())
    assert ans == cnt

def test_small_brute_force_1e6(run, x):
    n = int(x.strip())
    if n > 1000000:
        return
    cnt = 0
    for i in range(1, n + 1):
        ok = True
        for d in range(2, 11):
            if i % d == 0:
                ok = False
                break
        if ok:
            cnt += 1
    ans = int(run(x).strip())
    assert ans == cnt

def test_parity(run, x):
    n = int(x.strip())
    # Inclusion-exclusion on primes {2,3,5,7}
    primes = [2,3,5,7]
    total_mod2 = 0
    from itertools import combinations
    for k in range(1, len(primes)+1):
        for comb in combinations(primes, k):
            lcm = 1
            for p in comb:
                lcm = lcm * p // math.gcd(lcm, p)
            cnt = n // lcm
            if k % 2 == 1:
                total_mod2 = (total_mod2 + cnt) % 2
            else:
                total_mod2 = (total_mod2 - cnt) % 2
    # Also include the term for empty set? Actually inclusion-exclusion for union
    # count = n - sum floor(n/p_i) + sum floor(n/lcm(p_i,p_j)) - ...
    # So we start with n and subtract for odd-sized subsets, add for even-sized.
    # Let's compute properly:
    count_mod2 = n % 2  # start with n
    for k in range(1, len(primes)+1):
        for comb in combinations(primes, k):
            lcm = 1
            for p in comb:
                lcm = lcm * p // math.gcd(lcm, p)
            cnt = n // lcm
            if k % 2 == 1:
                count_mod2 = (count_mod2 - cnt) % 2
            else:
                count_mod2 = (count_mod2 + cnt) % 2
    ans = int(run(x).strip())
    assert ans % 2 == count_mod2, f'Parity mismatch: ans%2={ans%2}, expected%2={count_mod2}'

def test_mod3(run, x):
    n = int(x.strip())
    primes = [2,3,5,7]
    count_mod3 = n % 3
    from itertools import combinations
    for k in range(1, len(primes)+1):
        for comb in combinations(primes, k):
            lcm = 1
            for p in comb:
                lcm = lcm * p // math.gcd(lcm, p)
            cnt = n // lcm
            if k % 2 == 1:
                count_mod3 = (count_mod3 - cnt) % 3
            else:
                count_mod3 = (count_mod3 + cnt) % 3
    ans = int(run(x).strip())
    assert ans % 3 == count_mod3

def test_mod5(run, x):
    n = int(x.strip())
    primes = [2,3,5,7]
    count_mod5 = n % 5
    from itertools import combinations
    for k in range(1, len(primes)+1):
        for comb in combinations(primes, k):
            lcm = 1
            for p in comb:
                lcm = lcm * p // math.gcd(lcm, p)
            cnt = n // lcm
            if k % 2 == 1:
                count_mod5 = (count_mod5 - cnt) % 5
            else:
                count_mod5 = (count_mod5 + cnt) % 5
    ans = int(run(x).strip())
    assert ans % 5 == count_mod5

def test_multiples_of_210(run, x):
    n = int(x.strip())
    if n % 210 == 0:
        # The count of numbers not divisible by any of 2..10 repeats every 210.
        # In each full block of 210 numbers, there are 48 such numbers.
        expected = (n // 210) * 48
        ans = int(run(x).strip())
        assert ans == expected, f'For n={n} (multiple of 210), expected {expected}, got {ans}'

