tests_src:
def test_bruteforce_small(run, x):
    import itertools
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    if m ** n > 1_000_000:
        return
    best = None
    for choices in itertools.product(range(m), repeat=n):
        or_val = 0
        for i, j in enumerate(choices):
            or_val |= a[i] & b[j]
        if best is None or or_val < best:
            best = or_val
    out = int(run(x).strip())
    assert out == best

def test_output_range(run, x):
    out = int(run(x).strip())
    assert 0 <= out <= 511

def test_upper_bound_or_a(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    or_a = 0
    for v in a:
        or_a |= v
    out = int(run(x).strip())
    assert out <= or_a

def test_upper_bound_or_b(run, x):
    lines = x.strip().split('\n')
    b = list(map(int, lines[2].split()))
    or_b = 0
    for v in b:
        or_b |= v
    out = int(run(x).strip())
    assert out <= or_b

def test_upper_bound_or_all_and(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    or_all = 0
    for ai in a:
        for bj in b:
            or_all |= ai & bj
    out = int(run(x).strip())
    assert out <= or_all

def test_per_i_subset(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    out = int(run(x).strip())
    for i in range(n):
        ok = False
        for j in range(m):
            if (a[i] & b[j]) | out == out:
                ok = True
                break
        assert ok

def test_per_bit_coverage(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    out = int(run(x).strip())
    for bit in range(9):
        if (out >> bit) & 1:
            found = False
            for i in range(n):
                for j in range(m):
                    val = a[i] & b[j]
                    if (val >> bit) & 1 and (val | out) == out:
                        found = True
                        break
                if found:
                    break
            assert found

def test_minimality(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    out = int(run(x).strip())
    for bit in range(9):
        if (out >> bit) & 1:
            candidate = out & ~(1 << bit)
            # If candidate is achievable, then out is not minimal.
            # Candidate is achievable if for every i there exists j with (a[i] & b[j]) | candidate == candidate.
            achievable = True
            for i in range(n):
                ok = False
                for j in range(m):
                    if (a[i] & b[j]) | candidate == candidate:
                        ok = True
                        break
                if not ok:
                    achievable = False
                    break
            if achievable:
                assert False, f'Candidate {candidate} is achievable, so {out} is not minimal'

def test_upper_bound_fixed_j(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    out = int(run(x).strip())
    min_or = None
    for j in range(m):
        or_val = 0
        for i in range(n):
            or_val |= a[i] & b[j]
        if min_or is None or or_val < min_or:
            min_or = or_val
    assert out <= min_or

def test_upper_bound_per_i_min(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    b = list(map(int, lines[2].split()))
    out = int(run(x).strip())
    per_i_min_or = 0
    for i in range(n):
        min_val = None
        for j in range(m):
            val = a[i] & b[j]
            if min_val is None or val < min_val:
                min_val = val
        per_i_min_or |= min_val
    assert out <= per_i_min_or

