def test_format(run, x):
    out = run(x)
    assert out in ("Happy Alex\n", "Poor Alex\n"), f"Output must be exactly 'Happy Alex\\n' or 'Poor Alex\\n', got {repr(out)}"

def test_n1(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        out = run(x)
        assert out == "Poor Alex\n", f"For n=1 output must be 'Poor Alex\\n', got {repr(out)}"

def test_exists_inversion(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 1000:
        return  # test passes for larger n as per plan
    laptops = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        laptops.append((a, b))
    has_inversion = False
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            if laptops[i][0] < laptops[j][0] and laptops[i][1] > laptops[j][1]:
                has_inversion = True
                break
        if has_inversion:
            break
    out = run(x)
    if has_inversion:
        assert out == "Happy Alex\n", f"Inversion exists, output must be 'Happy Alex\\n', got {repr(out)}"

def test_no_inversion(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 1000:
        return  # test passes for larger n as per plan
    laptops = []
    for i in range(1, n+1):
        a, b = map(int, lines[i].split())
        laptops.append((a, b))
    has_inversion = False
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            if laptops[i][0] < laptops[j][0] and laptops[i][1] > laptops[j][1]:
                has_inversion = True
                break
        if has_inversion:
            break
    out = run(x)
