def test_small_4(run, x):
    n = int(x.strip())
    if n != 4:
        return  # only for n==4 per plan
    # Brute-force minimax for n=4
    from itertools import product
    size = 4
    cells = [(r, c) for r in range(size) for c in range(size)]
    from functools import lru_cache
    @lru_cache(None)
    def win(mask):
        if mask == (1 << (size*size)) - 1:
            return False  # all painted, current player loses (no move)
        # generate all empty cells with no adjacent painted neighbor
        for idx, (r, c) in enumerate(cells):
            if not (mask >> idx) & 1:
                # check four orthogonal directions
                ok = True
                for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < size and 0 <= nc < size:
                        nidx = nr * size + nc
                        if (mask >> nidx) & 1:
                            ok = False
                            break
                if ok:
                    if not win(mask | (1 << idx)):
                        return True
        return False
    winner = 1 if win(0) else 2
    output = run(x)
    got = int(output.strip())
    assert got == winner, f'For n=4 expected {winner}, got {got}'

