        l, t, m = map(int, data[i+1].split())
        out = lines[i].strip()
        if out != '-1':
            r = int(out)
            # Check r+1, but only if it exists (no upper bound needed).
            s_next = A + r * B  # because s_{r+1} = A + ((r+1)-1)*B = A + r*B
            # per-element condition for r+1
            if s_next <= t:
                # sum condition for [l, r+1]
                def S(i):
                    if i == 0:
                        return 0
                    return i * A + B * i * (i - 1) // 2
                total_next = S(r + 1) - S(l - 1)
                if total_next <= m * t:
                    # Both conditions hold for r+1, so r is not maximal.
                    assert False, f'Query {i+1}: r={r} not maximal because r+1 also satisfies conditions'


def test_upper_bound_i_max(run, x):
    lines = run(x).strip().split('\n')
    data = x.strip().split('\n')
    A, B, n = map(int, data[0].split())
    for i in range(n):
        _, t, _ = map(int, data[i+1].split())
        out = lines[i].strip()
        if out != '-1':
            r = int(out)
            # largest i such that s_i <= t
            if B == 0:
                if A <= t:
                    i_max = float('inf')
                else:
                    i_max = 0
            else:
                # A + (i-1)*B <= t  =>  i-1 <= (t-A)/B
                if t < A:
                    i_max = 0
                else:
                    i_max = (t - A) // B + 1
            # If i_max is finite, r must not exceed it.
            if i_max != float('inf'):
                assert r <= i_max, f'Query {i+1}: r={r} > i_max={i_max} (largest index with s_i ≤ t)'


def test_positive_answer_when_possible(run, x):
    lines = run(x).strip().split('\n')
    data = x.strip().split('\n')
    A, B, n = map(int, data[0].split())
    for i in range(n):
        l, t, m = map(int, data[i+1].split())
        s_l = A + (l - 1) * B
        out = lines[i].strip()
        if s_l <= t and s_l <= m * t:
            # at least r=l is valid, so output cannot be -1
            if out == '-1':
                assert False, f'Query {i+1}: -1 output but r=l is valid (s_l={s_l} ≤ t={t} and ≤ m*t={m*t})'


def test_brute_force_small(run, x):
    lines = run(x).strip().split('\n')
    data = x.strip().split('\n')
    A, B, n = map(int, data[0].split())
    for i in range(n):
        l, t, m = map(int, data[i+1].split())
        if l <= 1000:
            # compute i_max (largest index with s_i <= t) only if it's not huge.
            if B == 0:
                if A <= t:
                    i_max = float('inf')
                else:
                    i_max = 0
            else:
                if t < A:
                    i_max = 0
                else:
                    i_max = (t - A) // B + 1
            # if i_max is finite and not too far from l
            if i_max != float('inf') and i_max - l <= 10000:
                # brute force: find largest r in [l, i_max] satisfying sum condition
                def S(i):
                    if i == 0:
                        return 0
                    return i * A + B * i * (i - 1) // 2
                best = -1
                for r_cand in range(l, i_max + 1):
                    total = S(r_cand) - S(l - 1)
                    if total <= m * t:
                        best = r_cand
                    else:
                        break  # heights increase, so sum only grows, further r will only be larger sum
                # Now compare with output
                out = lines[i].strip()
                if out == '-1':
                    assert best == -1, f'Query {i+1}: output -1 but brute force found r={best}'
                else:
                    r_out = int(out)
                    assert r_out == best, f'Query {i+1}: output r={r_out} but brute force says r={best}'


def test_trivial_upper_bound(run, x):
    lines = run(x).strip().split('\n')
    data = x.strip().split('\n')
    A, B, n = map(int, data[0].split())
    for i in range(n):
        l, t, m = map(int, data[i+1].split())
        out = lines[i].strip()
        if out != '-1':
            r = int(out)
            # r cannot exceed l + m*t - 1 because each Karafs requires at least one decrement
            assert r <= l + m * t - 1, f'Query {i+1}: r={r} > l + m*t - 1 = {l + m*t - 1}'

