def test_dag_dp_consistency(run, x):
    # Only run on small acyclic graphs
    lines = x.strip().split('\n')
    first = lines[0].split()
    n, m = map(int, first)
    if n > 30 or m > 100:
        return
    # Build adjacency list and check for cycles
    adj = [[] for _ in range(n+1)]
    edges_start = 2
    for i in range(edges_start, edges_start + m):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) < 2:
            continue
        u, v = map(int, parts)
        adj[u].append(v)
    # Detect cycle
    visited = [0] * (n+1)
    has_cycle = False
    def dfs_cycle(u):
        nonlocal has_cycle
        if has_cycle:
            return
        visited[u] = 1
        for v in adj[u]:
            if visited[v] == 0:
                dfs_cycle(v)
            elif visited[v] == 1:
                has_cycle = True
                return
        visited[u] = 2
    for i in range(1, n+1):
        if visited[i] == 0:
            dfs_cycle(i)
            if has_cycle:
                return  # not a DAG, skip test
    # Compute DP for DAG
    from collections import deque
    indeg = [0] * (n+1)
    for u in range(1, n+1):
        for v in adj[u]:
            indeg[v] += 1
    q = deque([i for i in range(1, n+1) if indeg[i]==0])
    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v]==0:
                q.append(v)
    if len(topo) != n:
        # still cycle? should not happen
        return
    s = lines[1].strip()
    # dp[u][c] = max frequency of letter c on a path ending at u
    # map letter to index 0..25
    dp = [[0]*26 for _ in range(n+1)]
    ans = 0
    for u in topo:
        c_idx = ord(s[u-1]) - ord('a')
        dp[u][c_idx] = max(dp[u][c_idx], 1)
        for v in adj[u]:
            for c in range(26):
                new_val = dp[u][c] + (1 if c == c_idx else 0)
                if new_val > dp[v][c]:
                    dp[v][c] = new_val
        ans = max(ans, max(dp[u]))
    # Compare with output
    out = run(x).strip()
    if out == '-1':
        # DAG cannot have -1
        assert False, "DAG cannot output -1"
    else:
        assert int(out) == ans, f"DP computed {ans}, output {out}"


def test_simple_path_enumeration(run, x):
    # Only on tiny graphs (n <= 8) because enumerating all simple paths is factorial
    lines = x.strip().split('\n')
    first = lines[0].split()
    n, m = map(int, first)
    if n > 8 or m > 15:
        return
    # Build adjacency list
    adj = [[] for _ in range(n+1)]
    edges_start = 2
    for i in range(edges_start, edges_start + m):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) < 2:
            continue
        u, v = map(int, parts)
        adj[u].append(v)
    # Enumerate all simple paths (vertices distinct)
    s = lines[1].strip()
    best = 0
    # DFS from each start
    from collections import Counter
    def dfs(u, visited, cnt):
        nonlocal best
        # update cnt
        c = s[u-1]
        cnt[c] = cnt.get(c,0)+1
        best = max(best, max(cnt.values()))
        for v in adj[u]:
            if v not in visited:
                visited.add(v)
                dfs(v, visited, cnt)
                visited.remove(v)
        # backtrack cnt
        cnt[c] -= 1
        if cnt[c]==0:
            del cnt[c]
    for start in range(1, n+1):
        dfs(start, {start}, {})
    out = run(x).strip()
    if out == '-1':
        # Only possible if there's a cycle that can be repeated infinitely
        # For simple paths enumeration we cannot detect that, so skip assertion
        pass
    else:
        assert int(out) == best, f"Brute force max {best}, output {out}"


def test_achievable(run, x):
    # Only for small DAGs
    lines = x.strip().split('\n')
    first = lines[0].split()
    n, m = map(int, first)
    if n > 30 or m > 100:
        return
    # Build adjacency list and check for cycles
    adj = [[] for _ in range(n+1)]
    edges_start = 2
    for i in range(edges_start, edges_start + m):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) < 2:
            continue
        u, v = map(int, parts)
        adj[u].append(v)
    visited = [0] * (n+1)
    has_cycle = False
    def dfs_cycle(u):
        nonlocal has_cycle
        if has_cycle:
            return
        visited[u] = 1
        for v in adj[u]:
            if visited[v] == 0:
                dfs_cycle(v)
            elif visited[v] == 1:
                has_cycle = True
                return
        visited[u] = 2
    for i in range(1, n+1):
        if visited[i] == 0:
            dfs_cycle(i)
            if has_cycle:
                return  # not a DAG
    out = run(x).strip()
    if out == '-1':
        return
    target = int(out)
    # For each letter, try to find a path with frequency target
    s = lines[1].strip()
    # DP for max frequency per letter per node
    dp_max = [[0]*26 for _ in range(n+1)]
    # Also need to know if a particular frequency is achievable (boolean)
    # We'll use DP: dp_achieve[u][c][f]? Too large.
    # Instead, for each letter, we can DFS to see if we can get target occurrences.
    # Since graph is DAG, we can do DP with bitset of achievable frequencies up to n.
    from collections import deque
    indeg = [0]*(n+1)
    for u in range(1, n+1):
        for v in adj[u]:
            indeg[v] += 1
    q = deque([i for i in range(1,n+1) if indeg[i]==0])
    topo = []
    while q:
        u = q.popleft()
        topo.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v]==0:
                q.append(v)
    # For each letter
    possible = False
    for letter in range(26):
        # bitset for each node: achievable counts
        # We'll keep a set of achievable counts for each node
        achievable = [set() for _ in range(n+1)]
        for u in topo:
            c = ord(s[u-1]) - ord('a')
            base = 1 if c == letter else 0
            if base == 1:
                achievable[u].add(1)
            else:
                achievable[u].add(0)
            for v in adj[u]:
                for cnt in achievable[u]:
                    new_cnt = cnt + (1 if c == letter else 0)
                    achievable[v].add(new_cnt)
        # check any node has target
        for u in range(1, n+1):
            if target in achievable[u]:
                possible = True
                break
        if possible:
            break
    assert possible, f"No path with frequency {target} found"

