def test_exact_brute_force(run, x):
    lines = x.strip().split('\n')
    n_k = list(map(int, lines[0].split()))
    n, k = n_k[0], n_k[1]
    if n > 8:
        return
    perms = [list(map(int, lines[i+1].split())) for i in range(k)]
    from itertools import combinations
    best = 0
    for mask in range(1 << n):
        indices = [i for i in range(n) if (mask >> i) & 1]
        candidate = [perms[0][i] for i in indices]
        ok = True
        for p in perms[1:]:
            pos = 0
            for val in candidate:
                while pos < n and p[pos] != val:
                    pos += 1
                if pos == n:
                    ok = False
                    break
                pos += 1
            if not ok:
                break
        if ok:
            best = max(best, len(candidate))
    ans = int(run(x).strip())
    assert ans == best


def test_exact_dp(run, x):
    lines = x.strip().split('\n')
    n_k = list(map(int, lines[0].split()))
    n, k = n_k[0], n_k[1]
    if n > 8 or k > 5:
        return
    perms = [list(map(int, lines[i+1].split())) for i in range(k)]
    # dp over positions
    from itertools import product
    dp = {}
    for idxs in product(range(n+1), repeat=k):
        dp[idxs] = 0
    for idxs in product(range(1, n+1), repeat=k):
        vals = [perms[i][idxs[i]-1] for i in range(k)]
        if all(v == vals[0] for v in vals):
            prev = tuple(idxs[i]-1 for i in range(k))
            dp[idxs] = dp[prev] + 1
        else:
            candidates = []
            for d in range(k):
                prev = list(idxs)
                prev[d] -= 1
                candidates.append(dp[tuple(prev)])
            dp[idxs] = max(candidates)
    ans = int(run(x).strip())
    assert ans == dp[tuple([n]*k)]


def test_exact_partial_order(run, x):
    lines = x.strip().split('\n')
    n_k = list(map(int, lines[0].split()))
    n, k = n_k[0], n_k[1]
    perms = [list(map(int, lines[i+1].split())) for i in range(k)]
    # build adjacency: pos[a] is position of a in each permutation
    pos = [[0]*(n+1) for _ in range(k)]
    for i in range(k):
        for idx, val in enumerate(perms[i]):
            pos[i][val] = idx
    # edge a->b if a appears before b in all permutations
    from collections import defaultdict
    adj = defaultdict(list)
    for a in range(1, n+1):
        for b in range(1, n+1):
            if a == b:
                continue
            if all(pos[i][a] < pos[i][b] for i in range(k)):
                adj[a].append(b)
    # longest path in DAG
    memo = {}
    def dfs(u):
        if u in memo:
            return memo[u]
        best = 0
        for v in adj[u]:
            best = max(best, dfs(v))
        memo[u] = best + 1
        return memo[u]
    longest = 0
    for node in range(1, n+1):
        longest = max(longest, dfs(node))
    ans = int(run(x).strip())
    assert ans == longest


