    perms = [list(map(int, line.split())) for line in data[1:1+k]]
    # compute LCS for each pair via reduction to LIS
    def pair_lcs(a, b):
        pos_in_b = {val: idx for idx, val in enumerate(b)}
        seq = [pos_in_b[val] for val in a if val in pos_in_b]
        # LIS on seq
        from bisect import bisect_left
        lis = []
        for x in seq:
            i = bisect_left(lis, x)
            if i == len(lis):
                lis.append(x)
            else:
                lis[i] = x
        return len(lis)
    min_pair = n
    for i in range(k):
        for j in range(i+1, k):
            cur = pair_lcs(perms[i], perms[j])
            if cur < min_pair:
                min_pair = cur
    out = run(x).strip()
    assert out.isdigit(), f'output not an integer: {out}'
    out_val = int(out)
