    {
      "name": "test_partial_order_longest_chain",
      "source": "def test_partial_order_longest_chain(run, x):
    data = x.strip().splitlines()
    if not data:
        return
    nk = list(map(int, data[0].split()))
    n, k = nk[0], nk[1]
    perms = [list(map(int, line.split())) for line in data[1:1+k]]
    # positions[perm_idx][value] = index in that permutation
    pos = [[0]*(n+1) for _ in range(k)]
    for pid, p in enumerate(perms):
        for idx, val in enumerate(p):
            pos[pid][val] = idx
    # partial order: i precedes j iff pos[pid][i] < pos[pid][j] for all pid
    precede = [[True]*(n+1) for _ in range(n+1)]
    for i in range(1, n+1):
        for j in range(1, n+1):
            if i == j:
                precede[i][j] = False
                continue
            ok = all(pos[pid][i] < pos[pid][j] for pid in range(k))
            precede[i][j] = ok
    # longest chain via DP on DAG
    from functools import lru_cache
    @lru_cache(None)
    def dp(v):
        best = 1
        for u in range(1, n+1):
            if precede[v][u]:
                cand = dp(u) + 1
                if cand > best:
                    best = cand
        return best
    longest = max(dp(v) for v in range(1, n+1))
    out = run(x).strip()
    assert out.isdigit(), f'output not an integer: {out}'
    out_val = int(out)
    assert out_val == longest, f'LCS (longest chain) expected {longest}, got {out_val}'"
