def test_component_size_bound(run, x):
    lines = x.strip('\n').split('\n')
    n, m, k = map(int, lines[0].split())
    grid = [list(line.rstrip('\n')) for line in lines[1:1+n]]
    queries = []
    for line in lines[1+n:1+n+k]:
        xq, yq = map(int, line.split())
        queries.append((xq-1, yq-1))
    from collections import deque
    comp_id = [[-1]*m for _ in range(n)]
    comp_size = []
    current = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and comp_id[i][j] == -1:
                q = deque([(i,j)])
                comp_id[i][j] = current
                sz = 0
                while q:
                    ci, cj = q.popleft()
                    sz += 1
                    for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ni, nj = ci+di, cj+dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.' and comp_id[ni][nj] == -1:
                            comp_id[ni][nj] = current
                            q.append((ni,nj))
                comp_size.append(sz)
                current += 1
    output = run(x).strip()
