def test_exact_small(run, x):
    lines = x.strip('\n').split('\n')
    n, m, k = map(int, lines[0].split())
    if n * m > 2000:
        return  # too large for brute‑force
    grid = [list(line.rstrip('\n')) for line in lines[1:1+n]]
    queries = []
    for line in lines[1+n:1+n+k]:
        xq, yq = map(int, line.split())
        queries.append((xq-1, yq-1))
    from collections import deque
    comp_walls = {}
    comp_id = [[-1]*m for _ in range(n)]
    current = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.' and comp_id[i][j] == -1:
                q = deque([(i,j)])
                comp_id[i][j] = current
                walls = 0
                visited = []
                while q:
                    ci, cj = q.popleft()
                    visited.append((ci,cj))
                    for di, dj in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ni, nj = ci+di, cj+dj
                        if 0 <= ni < n and 0 <= nj < m:
                            if grid[ni][nj] == '*':
                                walls += 1
                            elif grid[ni][nj] == '.' and comp_id[ni][nj] == -1:
                                comp_id[ni][nj] = current
                                q.append((ni,nj))
                # Every wall is counted twice (once from each side), but the problem says
                # each wall contains one picture, so the total pictures visible from the whole component is walls
                # (because Igor can see a picture from any adjacent empty cell, and walls are between empty and impassable).
                # Actually, each empty–impassable adjacency contributes one picture.
                # When we sum over all empty cells in the component, each such adjacency is counted exactly once.
                # So the answer for any cell in the component is exactly `walls`.
                comp_walls[current] = walls
                current += 1
    expected = [comp_walls[comp_id[i][j]] for (i,j) in queries]
    output = run(x).strip()
    if output == '':
        out_vals = []
    else:
        out_vals = list(map(int, output.split('\n')))
    assert out_vals == expected, f'Expected {expected}, got {out_vals}'

