def test_exact_match(run, x):
    # Simulate only for small n to avoid timeout
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return  # skip simulation for large inputs
    seq = list(map(int, lines[1].split()))
    expected_lines = []
    have = set()
    next_needed = n
    for day in range(n):
        have.add(seq[day])
        placed_today = []
        while next_needed in have:
            placed_today.append(next_needed)
            have.remove(next_needed)
            next_needed -= 1
        if placed_today:
            expected_lines.append(' '.join(map(str, reversed(placed_today))))
        else:
            expected_lines.append('')
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    # pad to n lines
    out_lines = out_lines[:n] + [''] * max(0, n - len(out_lines))
    for i in range(n):
        if out_lines[i].strip() != expected_lines[i].strip():
            raise AssertionError(f'Line {i+1} mismatch')


def test_line_count(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    # Allow trailing newline, but must have exactly n lines of output
    if len(out_lines) != n:
        raise AssertionError(f'Expected {n} lines, got {len(out_lines)}')


def test_flattened_sequence(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = run(x)
    # Extract all integers from output
    flattened = []
    for line in out.rstrip('\n').split('\n'):
        if line.strip():
            flattened.extend(map(int, line.strip().split()))
    # Must be exactly n integers
    if len(flattened) != n:
        raise AssertionError(f'Expected {n} integers total, got {len(flattened)}')
    # Must be strictly decreasing by 1 each step
    for i in range(n-1):
        if flattened[i] != flattened[i+1] + 1:
            raise AssertionError('Flattened sequence not consecutive decreasing')
    # Must start at n
    if flattened[0] != n:
        raise AssertionError('Flattened sequence does not start at n')


def test_consecutive_per_line(run, x):
    out = run(x)
    for line in out.rstrip('\n').split('\n'):
        if line.strip():
            nums = list(map(int, line.strip().split()))
            for i in range(len(nums)-1):
                if nums[i] != nums[i+1] + 1:
                    raise AssertionError('Line numbers not consecutive decreasing')


def test_set_completeness(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = run(x)
    seen = set()
    for line in out.rstrip('\n').split('\n'):
        if line.strip():
            for num in map(int, line.strip().split()):
                seen.add(num)
    expected = set(range(1, n+1))
    if seen != expected:
        raise AssertionError('Set of output integers does not match {1,...,n}')


def test_bounds(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = run(x)
    for line in out.rstrip('\n').split('\n'):
        if line.strip():
            for num in map(int, line.strip().split()):
                if not (1 <= num <= n):
                    raise AssertionError(f'Integer {num} out of bounds')


def test_feasibility(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    seq = list(map(int, lines[1].split()))
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    # flattened order of placed snacks
    placed_order = []
    for line in out_lines:
        if line.strip():
            placed_order.extend(map(int, line.strip().split()))
    # check each day
    fallen_so_far = set()
    placed_idx = 0
    for day in range(n):
        fallen_so_far.add(seq[day])
        # snacks placed on this day
        day_placed = []
        if day < len(out_lines) and out_lines[day].strip():
            day_placed = list(map(int, out_lines[day].strip().split()))
        # each must be in fallen_so_far
        for snack in day_placed:
            if snack not in fallen_so_far:
                raise AssertionError(f'Snack {snack} placed day {day+1} but not yet fallen')
        # all larger snacks must already be placed earlier
        for snack in day_placed:
            larger = snack + 1
            while larger <= n:
                # if larger has been placed, must be before this snack in placed_order
                if larger in placed_order:
                    if placed_order.index(larger) >= placed_idx:
                        raise AssertionError(f'Larger snack {larger} not placed before {snack}')
                larger += 1
        placed_idx += len(day_placed)


def test_format(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    for line in lines:
        stripped = line.strip()
        if stripped:
            # must be integers separated by single spaces
            parts = stripped.split()
            if not all(p.isdigit() for p in parts):
                raise AssertionError('Non-digit characters in output line')
            if '  ' in stripped:
                raise AssertionError('Multiple consecutive spaces')
            if stripped != ' '.join(parts):
                raise AssertionError('Extra whitespace')
    # must end with newline
    if not out.endswith('\n'):
        raise AssertionError('Output does not end with newline')


def test_no_duplicates(run, x):
    out = run(x)
    seen = set()
    for line in out.rstrip('\n').split('\n'):
        if line.strip():
            for num in map(int, line.strip().split()):
                if num in seen:
                    raise AssertionError(f'Duplicate snack {num}')
                seen.add(num)


def test_day_consistency(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    out = run(x)
    out_lines = out.rstrip('\n').split('\n')
    # flattened order
    placed_order = []
    for line in out_lines:
        if line.strip():
            placed_order.extend(map(int, line.strip().split()))
    # placed_order must be n, n-1, ..., 1 (already checked by test_flattened_sequence)
    # now ensure each day's placed block is a consecutive suffix of this sequence
    idx = 0
    for day in range(n):
        day_placed = []
        if day < len(out_lines) and out_lines[day].strip():
            day_placed = list(map(int, out_lines[day].strip().split()))
        if day_placed:
            # must match next segment of placed_order
            expected_block = placed_order[idx:idx+len(day_placed)]
            if day_placed != expected_block:
                raise AssertionError(f'Day {day+1} block mismatch')
            # within block, numbers must be consecutive decreasing
            for i in range(len(day_placed)-1):
                if day_placed[i] != day_placed[i+1] + 1:
                    raise AssertionError('Block not consecutive decreasing')
            idx += len(day_placed)

