def test_exact_line_count(run, x):
    n = int(x.strip().split('\n')[0])
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    assert len(lines) == n, f'Expected {n} lines, got {len(lines)}'

def test_line_decreasing_consecutive(run, x):
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    for line in lines:
        if line.strip() == '':
            continue
        nums = list(map(int, line.split()))
        for i in range(len(nums)-1):
            assert nums[i] - 1 == nums[i+1], f'Line not consecutive decreasing: {line}'

def test_full_sequence(run, x):
    n = int(x.strip().split('\n')[0])
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    flat = []
    for line in lines:
        if line.strip() == '':
            continue
        flat.extend(map(int, line.split()))
    expected = list(range(n, 0, -1))
    assert flat == expected, f'Flattened sequence mismatch: expected {expected}, got {flat}'

def test_all_snacks_once(run, x):
    n = int(x.strip().split('\n')[0])
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    seen = []
    for line in lines:
        if line.strip() == '':
            continue
        seen.extend(map(int, line.split()))
    assert set(seen) == set(range(1, n+1)), f'Missing or extra snacks: {set(seen)} vs 1..{n}'
    assert len(seen) == n, f'Duplicate or missing snacks: length {len(seen)}'

def test_placement_after_fall(run, x):
    lines_input = x.strip().split('\n')
    n = int(lines_input[0])
    fall = list(map(int, lines_input[1].split()))
    fall_day = {size: day+1 for day, size in enumerate(fall)}  # 1-indexed day
    output = run(x)
    out_lines = output.rstrip('\n').split('\n')
    for day_idx, line in enumerate(out_lines, start=1):
        if line.strip() == '':
            continue
        for size in map(int, line.split()):
            assert fall_day[size] <= day_idx, f'Snack {size} placed on day {day_idx} but fell on day {fall_day[size]}'

def test_placement_order_monotonic(run, x):
    lines_input = x.strip().split('\n')
    n = int(lines_input[0])
    fall = list(map(int, lines_input[1].split()))
    fall_day = {size: day+1 for day, size in enumerate(fall)}
    output = run(x)
    out_lines = output.rstrip('\n').split('\n')
    placed_day = {}
    for day_idx, line in enumerate(out_lines, start=1):
        if line.strip() == '':
            continue
        for size in map(int, line.split()):
            placed_day[size] = day_idx
    for s in range(n, 1, -1):
        if s in placed_day and s-1 in placed_day:
            assert placed_day[s] <= placed_day[s-1], f'Placement order violated: {s} placed later than {s-1}'

def test_per_day_fall_constraint(run, x):
    lines_input = x.strip().split('\n')
    n = int(lines_input[0])
    fall = list(map(int, lines_input[1].split()))
    fall_day = {size: day+1 for day, size in enumerate(fall)}
    output = run(x)
    out_lines = output.rstrip('\n').split('\n')
    for day_idx, line in enumerate(out_lines, start=1):
        if line.strip() == '':
            continue
        for size in map(int, line.split()):
            assert fall_day[size] <= day_idx, f'Snack {size} placed on day {day_idx} but fell later'

def test_valid_format(run, x):
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    for line in lines:
        stripped = line.rstrip(' ')
        if stripped == '':
            continue
        parts = stripped.split()
        for part in parts:
            if not part.isdigit():
                raise AssertionError(f'Non‑integer token: {part}')
        # check no extra non‑whitespace characters
        if stripped.replace(' ', '') != ''.join(parts):
            raise AssertionError(f'Extra characters in line: {line}')
        # each token must be integer in range 1..n
        n = int(x.strip().split('\n')[0])
        for part in parts:
            val = int(part)
            assert 1 <= val <= n, f'Value {val} out of range 1..{n}'

def test_cumulative_placement_bound(run, x):
    n = int(x.strip().split('\n')[0])
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    cumulative = 0
    for i, line in enumerate(lines, start=1):
        if line.strip() != '':
            cumulative += len(line.split())
        assert cumulative <= i, f'By day {i}, placed {cumulative} snacks, but only {i} have fallen'

def test_small_exact_simulation(run, x):
    lines_input = x.strip().split('\n')
    n = int(lines_input[0])
    if n > 15:
        return
    fall = list(map(int, lines_input[1].split()))
    # simulate
    available = set()
    expected_lines = []
    next_needed = n
    for day in range(1, n+1):
        size = fall[day-1]
        available.add(size)
        line_parts = []
        while next_needed in available:
            line_parts.append(str(next_needed))
            available.remove(next_needed)
            next_needed -= 1
        expected_lines.append(' '.join(line_parts) if line_parts else '')
    output = run(x)
    out_lines = output.rstrip('\n').split('\n')
    assert out_lines == expected_lines, f'Simulation mismatch:\nexpected {expected_lines}\ngot {out_lines}'

