tests_src:
def test_bruteforce(run, x):
    import sys
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    if n > 10:
        return
    MOD = 10**9 + 7
    from itertools import product
    total = 0
    for mask in product([False, True], repeat=n):
        g = [[] for _ in range(n)]
        for i in range(n):
            u = i
            v = a[i] - 1
            if mask[i]:
                u, v = v, u
            g[u].append(v)
        # Detect directed cycle
        visited = [0] * n  # 0 unvisited, 1 in stack, 2 done
        def dfs(node):
            visited[node] = 1
            for nei in g[node]:
                if visited[nei] == 1:
                    return True
                if visited[nei] == 0:
                    if dfs(nei):
                        return True
            visited[node] = 2
            return False
        cycle = False
        for i in range(n):
            if visited[i] == 0:
                if dfs(i):
                    cycle = True
                    break
        if not cycle:
            total += 1
    ans = int(run(x).strip())
    assert ans == total, f'Brute‑force says {total}, got {ans}'

def test_output_format(run, x):
    out = run(x).rstrip('\n')
    # Must be a single line of decimal digits, no leading zeros except for '0' itself
    lines = out.split('\n')
    assert len(lines) == 1, 'Output must be exactly one line'
    num = lines[0]
    assert num.isdigit(), 'Output must contain only digits'
    if num != '0':
        assert num[0] != '0', 'No leading zeros allowed'

def test_mod_range(run, x):
    out = run(x).strip()
    ans = int(out)
    assert 0 <= ans <= 10**9 + 6, 'Answer must be in modulo range'

def test_upper_bound(run, x):
    n = int(x.strip().split('\n')[0])
    ans = int(run(x).strip())
    assert ans <= 2 ** n, f'Answer {ans} cannot exceed 2^{n}'

def test_lower_bound(run, x):
    ans = int(run(x).strip())
    assert ans >= 0, 'Answer cannot be negative'

def test_example1(run, x):
    if x == '3\n2 3 1\n':
        out = run(x)
        assert out.rstrip('\n') == '6', 'Example 1 mismatch'

def test_example2(run, x):
    if x == '4\n2 1 1 1\n':
        out = run(x)
        assert out.rstrip('\n') == '8', 'Example 2 mismatch'

def test_example3(run, x):
    if x == '5\n2 4 2 5 3\n':
        out = run(x)
        assert out.rstrip('\n') == '28', 'Example 3 mismatch'

def test_no_extra_output(run, x):
    out = run(x)
    lines = out.split('\n')
    # Allow a trailing newline
    if out.endswith('\n'):
        lines = out.rstrip('\n').split('\n')
    assert len(lines) == 1, 'Output must be exactly one line'

def test_single_cycle(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))
    # Check if a is a permutation forming a single directed cycle
    if sorted(a) == list(range(1, n + 1)):
        visited = [False] * n
        cur = 0
        while not visited[cur]:
            visited[cur] = True
            cur = a[cur] - 1
        if all(visited):
            ans = int(run(x).strip())
            expected = (2 ** n) - 2
            assert ans == expected, f'Single cycle of length n should yield {expected}, got {ans}'

