      "source": "def test_bad_segment_impossible(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    n, m = map(int, lines[0].split())
    x_cost, k, y_cost = map(int, lines[1].split())
    a = list(map(int, lines[2].split()))
    b = list(map(int, lines[3].split())) if lines[3].strip() else []
    # Check if b is a subsequence of a
    # Compute matched indices
    idx = []
    i = 0
    for v in b:
        while i < n and a[i] != v:
            i += 1
        if i == n:
            return  # not a subsequence, handled by other test
        idx.append(i)
        i += 1
    # Now idx has positions in a that are kept
    # Add sentinels before first and after last
    kept_positions = [-1] + idx + [n]
    impossible = False
    for seg_idx in range(len(kept_positions) - 1):
        l = kept_positions[seg_idx] + 1
        r = kept_positions[seg_idx + 1] - 1
        L = r - l + 1
        if L <= 0:
            continue
        if L < k:
            # Need to check max in segment > both bordering kept warriors
            left_val = a[kept_positions[seg_idx]] if seg_idx >= 0 and kept_positions[seg_idx] != -1 else -1
            right_val = a[kept_positions[seg_idx + 1]] if seg_idx + 1 < len(idx) + 1 and kept_positions[seg_idx + 1] != n else -1
            seg_max = max(a[l:r+1]) if l <= r else -1
            if (left_val == -1 or seg_max > left_val) and (right_val == -1 or seg_max > right_val):
                impossible = True
                break
    if impossible:
        assert run(x).strip() == '-1', "Must output -1 when a segment is impossible to clear""
    },
