def test_format(run, x):
    out = run(x)
    lines = out.strip().splitlines()
    assert len(lines) == 1, "output must be exactly one line"
    s = lines[0].strip()
    # Must parse as integer
    try:
        ans = int(s)
    except ValueError:
        assert False, "output must be a single integer"
    # No extra characters after stripping
    assert str(ans) == s, "no extra leading zeros or spaces"

def test_range(run, x):
    out = run(x)
    ans = int(out.strip())
    # Compute n from the first line of input
    first_line = x.split('\n')[0].strip()
    k1, k2, k3 = map(int, first_line.split())
    n = k1 + k2 + k3
    assert 0 <= ans <= n, f"answer must be between 0 and {n}"

def test_upper_bound(run, x):
    out = run(x)
    ans = int(out.strip())
    first_line = x.split('\n')[0].strip()
    k1, k2, k3 = map(int, first_line.split())
    # Moving all problems to one contestant gives a valid distribution
    # The cost is the number of problems not already with that contestant
    upper = min(k2 + k3, k1 + k3, k1 + k2)
    assert ans <= upper, f"answer must be at most {upper} (all problems to one contestant)"

def test_lower_bound(run, x):
    out = run(x)
    ans = int(out.strip())
    assert ans >= 0, "answer cannot be negative"

def test_all_first(run, x):
    first_line = x.split('\n')[0].strip()
    k1, k2, k3 = map(int, first_line.split())
    if k2 == 0 and k3 == 0:
        out = run(x)
        ans = int(out.strip())
        assert ans == 0, "when all problems are with first contestant, answer must be 0"

def test_all_second(run, x):
    first_line = x.split('\n')[0].strip()
    k1, k2, k3 = map(int, first_line.split())
    if k1 == 0 and k3 == 0:
        out = run(x)
        ans = int(out.strip())
        assert ans == 0, "when all problems are with second contestant, answer must be 0"

def test_all_third(run, x):
    first_line = x.split('\n')[0].strip()
    k1, k2, k3 = map(int, first_line.split())
    if k1 == 0 and k2 == 0:
        out = run(x)
        ans = int(out.strip())
        assert ans == 0, "when all problems are with third contestant, answer must be 0"

def test_brute_small(run, x):
    # Parse input
    lines = x.strip().split('\n')
    k1, k2, k3 = map(int, lines[0].split())
    n = k1 + k2 + k3
    if n > 15:
        return  # Skip large inputs
    # Collect all problems with their initial contestant labels
    problems = []
    # first contestant label 0
    if k1 > 0:
        for v in lines[1].split():
            problems.append((int(v), 0))
    # second contestant label 1
    if k2 > 0:
        for v in lines[2].split():
            problems.append((int(v), 1))
    # third contestant label 2
    if k3 > 0:
        for v in lines[3].split():
            problems.append((int(v), 2))
    # Sort by problem number
    problems.sort(key=lambda p: p[0])
    A = [label for _, label in problems]
    # Brute-force over all splits a (prefix size) and b (middle size)
    best = n
    for a in range(n + 1):
        for b in range(a, n + 1):
            # expected label: 0 for i < a, 1 for a <= i < b, 2 for i >= b
            cost = 0
            for i, label in enumerate(A):
                if i < a:
                    if label != 0:
                        cost += 1
                elif i < b:
                    if label != 1:
                        cost += 1
                else:
                    if label != 2:
                        cost += 1
            if cost < best:
                best = cost
    out = run(x)
    ans = int(out.strip())
    assert ans == best, f"brute-force minimum is {best}, got {ans}"

def test_LNDS(run, x):
    # Parse input
    lines = x.strip().split('\n')
    k1, k2, k3 = map(int, lines[0].split())
    n = k1 + k2 + k3
    if n > 200000:  # safety, but given inputs are small
        return
    problems = []
    if k1 > 0:
        for v in lines[1].split():
            problems.append((int(v), 0))
    if k2 > 0:
        for v in lines[2].split():
            problems.append((int(v), 1))
    if k3 > 0:
        for v in lines[3].split():
            problems.append((int(v), 2))
    problems.sort(key=lambda p: p[0])
    A = [label for _, label in problems]
    # Compute longest non-decreasing subsequence (0,1,2 are ordered)
    # O(n) DP: keep the smallest tail for each length
    import bisect
    tails = []
    for label in A:
        pos = bisect.bisect_right(tails, label)
        if pos == len(tails):
            tails.append(label)
        else:
            tails[pos] = label
    L = len(tails)
    expected = n - L
    out = run(x)
    ans = int(out.strip())
    assert ans == expected, f"expected n - LNDS = {expected}, got {ans}"

def test_cut_dp(run, x):
    # Parse input
    lines = x.strip().split('\n')
    k1, k2, k3 = map(int, lines[0].split())
    n = k1 + k2 + k3
    if n > 1000:
        return  # Keep it fast
    problems = []
    if k1 > 0:
        for v in lines[1].split():
            problems.append((int(v), 0))
    if k2 > 0:
        for v in lines[2].split():
            problems.append((int(v), 1))
    if k3 > 0:
        for v in lines[3].split():
            problems.append((int(v), 2))
    problems.sort(key=lambda p: p[0])
    A = [label for _, label in problems]
    # Build prefix sums for counts of 0,1,2
    pref0 = [0] * (n + 1)
    pref1 = [0] * (n + 1)
    pref2 = [0] * (n + 1)
    for i in range(1, n + 1):
        pref0[i] = pref0[i-1] + (1 if A[i-1] == 0 else 0)
        pref1[i] = pref1[i-1] + (1 if A[i-1] == 1 else 0)
        pref2[i] = pref2[i-1] + (1 if A[i-1] == 2 else 0)
    best = n
    for a in range(n + 1):
        for b in range(a, n + 1):
            # cost = (problems not 0 in [0,a)) + (problems not 1 in [a,b)) + (problems not 2 in [b,n))
            cost = (a - pref0[a]) + \
                   ((b - a) - (pref1[b] - pref1[a])) + \
                   ((n - b) - (pref2[n] - pref2[b]))
            if cost < best:
                best = cost
    out = run(x)
    ans = int(out.strip())
    assert ans == best, f"cut DP minimum is {best}, got {ans}"

