    {
      "name": "test_small_brute_force",
      "intent": "If the input has at most 6 companies and at most 10 employees total, exhaustively enumerate all possible sequences of pairwise merges, compute the total increase for each sequence, and take the minimum. The output must equal that minimum. For larger inputs, skip the test."
    },
    {
      "name": "test_zero_if_all_max_equal",
      "intent": "If all companies have the same maximum salary, then no increases are needed to satisfy the merging condition. Therefore the output must be exactly 0."
    },
    {
      "name": "test_nonzero_if_max_differ",
