    lines = x.strip('\n').split('\n')
    first = lines[0].split()
    if len(first) == 1:
        # first line is t
        if len(lines) < 2:
            return
        n, x_spec = map(int, lines[1].split())
        edges = lines[2:2+n-1] if len(lines) >= 2+n-1 else []
    else:
        n, x_spec = map(int, first)
        edges = lines[1:1+n-1]
    # compute degree of x_spec
    degree = 0
    for e in edges:
        if e.strip() == '':
            continue
        u, v = map(int, e.split())
        if u == x_spec or v == x_spec:
            degree += 1
    if degree <= 1:
        out = run(x)
        assert out == 'Ayush\n', 'If x is a leaf (degree 0 or 1), Ayush wins'

def test_star_center(run, x):
    lines = x.strip('\n').split('\n')
    first = lines[0].split()
    if len(first) == 1:
        if len(lines) < 2:
            return
        n, x_spec = map(int, lines[1].split())
        edges = lines[2:2+n-1] if len(lines) >= 2+n-1 else []
    else:
        n, x_spec = map(int, first)
        edges = lines[1:1+n-1]
    # compute degrees
    deg = {i:0 for i in range(1, n+1)}
    for e in edges:
        if e.strip() == '':
            continue
        u, v = map(int, e.split())
        deg[u] += 1
        deg[v] += 1
    # check if tree is a star with center x_spec
    # exactly one node has degree >1 and it is x_spec, all others degree 1
    cnt_gt1 = sum(1 for d in deg.values() if d > 1)
    if cnt_gt1 == 1 and deg[x_spec] > 1:
        # all other nodes have degree 1
        if all(d == 1 for node, d in deg.items() if node != x_spec):
            expected = 'Ayush\n' if deg[x_spec] % 2 == 1 else 'Ashish\n'
            out = run(x)
            assert out == expected, f'Star with center degree {deg[x_spec]} expects {expected.strip()}'

def test_simulation(run, x):
    # parse input
    lines = x.strip('\n').split('\n')
    first = lines[0].split()
    if len(first) == 1:
        if len(lines) < 2:
            return
        n, x_spec = map(int, lines[1].split())
        edges = lines[2:2+n-1] if len(lines) >= 2+n-1 else []
    else:
        n, x_spec = map(int, first)
        edges = lines[1:1+n-1]
    # only simulate if n <= 10 (as per plan)
    if n > 10:
        return
    # build adjacency list
    from collections import defaultdict
    adj = defaultdict(list)
    for e in edges:
        if e.strip() == '':
            continue
        u, v = map(int, e.split())
        adj[u].append(v)
        adj[v].append(u)
    # minimax simulation
    def game_state(nodes_set, edges_set, turn_ayush):
        # nodes_set is frozenset of remaining nodes
        # edges_set is frozenset of remaining edges (as tuples u<v)
        # returns True if Ayush wins from this state
        if x_spec not in nodes_set:
            # x already removed, previous player won
            return not turn_ayush  # if it's Ayush's turn, previous was Ashish who won, so Ayush loses
        leaves = [node for node in nodes_set if len([e for e in edges_set if node in e]) <= 1]
        if not leaves:
            # no leaves left but x still present -> impossible in tree, but handle
            return False
        for leaf in leaves:
            new_nodes = nodes_set - {leaf}
            # find edge incident to leaf
            incident = None
            for e in edges_set:
                if leaf in e:
                    incident = e
                    break
            if incident is None:
                new_edges = edges_set  # leaf had degree 0 (only possible if n==1)
            else:
                new_edges = edges_set - {incident}
            if not game_state(new_nodes, new_edges, not turn_ayush):
                return True
        return False
    nodes = frozenset(range(1, n+1))
    edges_set = frozenset(tuple(sorted((u, v))) for e in edges if e.strip() != '' for u, v in [map(int, e.split())])
    ayush_wins = game_state(nodes, edges_set, True)
    expected = 'Ayush\n' if ayush_wins else 'Ashish\n'
    out = run(x)
    assert out == expected, f'Simulation expects {expected.strip()}'

def test_output_length(run, x):
    out = run(x)
    assert len(out) in (6, 7), 'Output length must be 6 (Ayush\\n) or 7 (Ashish\\n)'
    assert out.endswith('\n'), 'Output must end with newline'

def test_no_extra(run, x):
    out = run(x)
    stripped = out.rstrip('\n')
    assert stripped in ('Ayush', 'Ashish'), 'Output without newline must be exactly Ayush or Ashish'
    # check no extra whitespace
    assert out == stripped + '\n', 'No extra characters besides newline'

