        a_counts[a] = a_counts.get(a, 0) + 1
        b_counts[b] = b_counts.get(b, 0) + 1
        pair_counts[(a, b)] = pair_counts.get((a, b), 0) + 1
    # total = n! mod MOD
    fact = 1
    for i in range(2, n+1):
        fact = (fact * i) % MOD
    total = fact
    # fA = product of factorials of a_counts
    fA = 1
    for cnt in a_counts.values():
        fc = 1
        for i in range(2, cnt+1):
            fc = (fc * i) % MOD
        fA = (fA * fc) % MOD
    # fB similarly
    fB = 1
    for cnt in b_counts.values():
        fc = 1
        for i in range(2, cnt+1):
            fc = (fc * i) % MOD
        fB = (fB * fc) % MOD
    # fAB: if the sequence of b is non-decreasing when pairs sorted by (a,b)
    sorted_pairs = sorted(pairs)
    b_seq = [p[1] for p in sorted_pairs]
    def is_sorted_non_decreasing(arr):
        return all(arr[i] <= arr[i+1] for i in range(len(arr)-1))
    if is_sorted_non_decreasing(b_seq):
        fAB = 1
        for cnt in pair_counts.values():
            fc = 1
            for i in range(2, cnt+1):
                fc = (fc * i) % MOD
            fAB = (fAB * fc) % MOD
    else:
        fAB = 0
    # inclusion-exclusion
    expected = (total - fA - fB + fAB) % MOD
    if expected < 0:
        expected += MOD
    output = run(x).strip()
    try:
        val = int(output)
    except ValueError:
        assert False, f"Output not integer: '{output}'"
    assert val == expected, f"Inclusion‑exclusion expects {expected}, got {val}"


def test_symmetry(run, x):
    lines = x.strip().splitlines()
