    fB = 1
    for cnt in b_counts.values():
        fc = 1
        for i in range(2, cnt+1):
            fc = (fc * i) % MOD
        fB = (fB * fc) % MOD
    sorted_pairs = sorted(pairs)
    b_seq = [p[1] for p in sorted_pairs]
    def is_sorted_non_decreasing(arr):
        return all(arr[i] <= arr[i+1] for i in range(len(arr)-1))
    if is_sorted_non_decreasing(b_seq):
        fAB = 1
        for cnt in pair_counts.values():
