def test_no_extra_whitespace(run, x):
    output = run(x)
    stripped = output.strip()
    # Must consist only of digits
    assert stripped.isdigit() or (stripped == '' and output == ''), f"Output contains non-digit characters: '{output}'"
    # No leading zeros unless it is '0'
    if stripped != '0' and len(stripped) > 1:
        assert stripped[0] != '0', f"Output has leading zero: '{output}'"
    # The integer parsed must equal the stripped string's integer
    # (already checked in test_valid_integer, but we ensure no extra whitespace changes value)
    if output != stripped:
        # If there is surrounding whitespace, the integer value must still match
        try:
            val_output = int(output.strip())
            val_stripped = int(stripped)
            assert val_output == val_stripped, f"Whitespace changes value: '{output}'"
        except ValueError:
            pass  # handled above


def test_n2_binary(run, x):
    lines = x.strip().splitlines()
