        try:
            val = int(output)
        except ValueError:
            assert False, f"Output not integer: '{output}'"
        # For n=2, the answer can only be 0 or 1 (either both permutations are bad or one is good)
        assert val in (0, 1), f"For n=2 answer must be 0 or 1, got {val}"

