def test_exact_match(run, x):
    n = int(x.strip())
    if not (n % 2 == 1 and 3 <= n <= 101):
        return  # only test valid inputs from spec
    center = (n - 1) // 2
    expected_lines = []
    for i in range(n):
        row = []
        for j in range(n):
            if abs(i - center) + abs(j - center) <= center:
                row.append('D')
            else:
                row.append('*')
        expected_lines.append(''.join(row))
    expected = '\n'.join(expected_lines) + '\n'
    assert run(x) == expected

def test_line_count(run, x):
    n = int(x.strip())
    if not (n % 2 == 1 and 3 <= n <= 101):
        return
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    assert len(lines) == n

def test_line_length(run, x):
    n = int(x.strip())
    if not (n % 2 == 1 and 3 <= n <= 101):
        return
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    for line in lines:
        assert len(line) == n

def test_valid_chars(run, x):
    n = int(x.strip())
    if not (n % 2 == 1 and 3 <= n <= 101):
        return
    output = run(x)
    for ch in output:
        assert ch in '*D\n'

def test_rows_palindromes(run, x):
    n = int(x.strip())
    if not (n % 2 == 1 and 3 <= n <= 101):
        return
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    for line in lines:
        assert line == line[::-1]

def test_vertical_symmetry(run, x):
    n = int(x.strip())
    if not (n % 2 == 1 and 3 <= n <= 101):
        return
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    for i in range(n):
        assert lines[i] == lines[n - 1 - i]

def test_row_d_counts(run, x):
    n = int(x.strip())
    if not (n % 2 == 1 and 3 <= n <= 101):
        return
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    center = (n - 1) // 2
    for i, line in enumerate(lines):
        d = abs(i - center)
        expected_count = n - 2 * d
        actual_count = line.count('D')
        assert actual_count == expected_count

def test_total_d_count(run, x):
    n = int(x.strip())
    if not (n % 2 == 1 and 3 <= n <= 101):
        return
    output = run(x)
    total_d = output.count('D')
    expected = (n * n + 1) // 2
    assert total_d == expected

def test_diamond_boundary(run, x):
    n = int(x.strip())
    if not (n % 2 == 1 and 3 <= n <= 101):
        return
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    center = (n - 1) // 2
    for i, line in enumerate(lines):
        d = abs(i - center)
        expected_prefix = '*' * d
        expected_middle = 'D' * (n - 2 * d)
        expected_suffix = '*' * d
        expected_row = expected_prefix + expected_middle + expected_suffix
        assert line == expected_row

def test_middle_row_all_d(run, x):
    n = int(x.strip())
    if not (n % 2 == 1 and 3 <= n <= 101):
        return
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    middle_idx = (n - 1) // 2
    middle_line = lines[middle_idx]
    assert middle_line == 'D' * n

