def test_format(run, x):
    output = run(x)
    lines = output.strip('\n').split('\n')
    assert len(lines) == 1, 'Output must be exactly one line.'
    line = lines[0]
    assert line in ('Ayush', 'Ashish'), 'Output must be exactly "Ayush" or "Ashish".'

def test_n1(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0]) if len(lines) > 0 else 0
    if n == 1:
        output = run(x).strip()
        assert output == 'Ayush', 'For n=1, Ayush must win.'

def test_n2(run, x):
    lines = x.strip().split('\n')
    if len(lines) >= 1:
        parts = lines[0].split()
        if len(parts) >= 1:
            n = int(parts[0])
            if n == 2:
                output = run(x).strip()
                assert output == 'Ayush', 'For n=2, Ayush must win.'

def test_leaf(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    first = lines[0].split()
    if len(first) < 2:
        return
    n, x_node = map(int, first[:2])
    deg = {i: 0 for i in range(1, n+1)}
    for line in lines[1:1+(n-1)]:
        u, v = map(int, line.split())
        deg[u] += 1
        deg[v] += 1
    if deg[x_node] == 1:
        output = run(x).strip()
        assert output == 'Ayush', 'When special node is a leaf, Ayush must win.'

def test_leaf0(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    first = lines[0].split()
    if len(first) < 2:
        return
    n, x_node = map(int, first[:2])
    deg = {i: 0 for i in range(1, n+1)}
    for line in lines[1:1+(n-1)]:
        u, v = map(int, line.split())
        deg[u] += 1
        deg[v] += 1
    if deg[x_node] == 0:
        output = run(x).strip()
        assert output == 'Ayush', 'When special node has degree 0, Ayush must win.'

def test_example1(run, x):
    if x == '1\n3 1\n2 1\n3 1\n':
        output = run(x).strip()
        assert output == 'Ashish', 'Example 1 must output Ashish.'

def test_example2(run, x):
    if x == '1\n3 2\n1 2\n1 3\n':
        output = run(x).strip()
        assert output == 'Ayush', 'Example 2 must output Ayush.'

def test_ashish_degree(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    first = lines[0].split()
    if len(first) < 2:
        return
    n, x_node = map(int, first[:2])
    deg = {i: 0 for i in range(1, n+1)}
    for line in lines[1:1+(n-1)]:
        u, v = map(int, line.split())
        deg[u] += 1
        deg[v] += 1
    output = run(x).strip()
    if output == 'Ashish':
        assert deg[x_node] > 1, 'Ashish can only win if special node degree > 1.'

def test_star_odd(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    first = lines[0].split()
    if len(first) < 2:
        return
    n, x_node = map(int, first[:2])
    deg = {i: 0 for i in range(1, n+1)}
    edges = []
    for line in lines[1:1+(n-1)]:
        u, v = map(int, line.split())
        edges.append((u, v))
        deg[u] += 1
        deg[v] += 1
    # Check if it's a star centered at x
    is_star = all((u == x_node or v == x_node) for u, v in edges) and deg[x_node] == n-1
    if is_star and n >= 3 and n % 2 == 1:
        output = run(x).strip()
        assert output == 'Ashish', 'For star with center x and odd n≥3, Ashish must win (optimal play).'

def test_small_correct(run, x):
