    if t != 1:
        return
    # Parse single test case
    n, x_node = map(int, lines[0].split()[1:3])
    if n > 13:
        return  # skip large cases
    edges = []
    for line in lines[1:1+(n-1)]:
        u, v = map(int, line.split())
        edges.append((u-1, v-1))  # zero-index
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    # Memoization for game state: (frozenset(remaining_nodes), turn)
    from functools import lru_cache
    @lru_cache(None)
    def win(nodes_set, turn_ayush):
        nodes = list(nodes_set)
        # Base: if x not in set, then the game already ended? Actually game ends when x removed.
        # We treat terminal as previous move removed x, so current player has already lost if x not present.
        if (x_node-1) not in nodes_set:
            return not turn_ayush  # previous player removed x, so current player lost?
        # Check if any leaf exists
        leaves = [v for v in nodes if sum(1 for u in adj[v] if u in nodes_set) <= 1]
        if not leaves:
            # no moves -> current player loses (cannot remove x)
            return False
        # Try each leaf removal
        for leaf in leaves:
            new_set = nodes_set - {leaf}
            if not win(new_set, not turn_ayush):
                return True
        return False
    initial = frozenset(range(n))
