                break
            i_str, L_str, R_str, ans_str = lines[line_idx].split()
            i = int(i_str); L = int(L_str); R = int(R_str); ans = int(ans_str)
            shift = h - i
            ancestor = cand >> shift
            if (ancestor >= L and ancestor <= R) != (ans == 1):
                ok = False
                break
        if ok:
            others_exist = True
            break
