    except ValueError:
        assert False, f'Output "{out}" is not a valid integer'

def test_range(run, x):
    out = run(x).strip()
    d = int(out)
    lines = x.strip().split('\n')
    n, _ = map(int, lines[0].split())
    assert 0 <= d <= n - 1, f'Diameter {d} outside [0, n-1] for n={n}'

def test_examples(run, x):
    if x == '4 3\n1 2\n1 3\n1 4\n':
