    if n == 1:
        out = run(x).strip()
        assert out == '0', f'For n=1 diameter must be 0, got {out}'

def test_two_nodes(run, x):
    lines = x.strip().split('\n')
    n, _ = map(int, lines[0].split())
    if n == 2:
        out = run(x).strip()
        assert out == '1', f'For n=2 diameter must be 1, got {out}'

def test_path(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if m != n - 1:
        return
    deg = {}
    for i in range(1, n + 1):
        deg[i] = 0
    for edge in lines[1:]:
        if not edge:
            continue
        a, b = map(int, edge.split())
        deg[a] += 1
        deg[b] += 1
    leaves = [v for v in deg if deg[v] == 1]
    if len(leaves) == 2 and all(deg[v] <= 2 for v in deg):
        out = run(x).strip()
        d = int(out)
        assert d == n - 1, f'Path of {n} nodes must have diameter {n-1}, got {d}'

def test_star(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n < 3:
        return
    deg = {}
    for i in range(1, n + 1):
        deg[i] = 0
    for edge in lines[1:]:
        if not edge:
            continue
        a, b = map(int, edge.split())
        deg[a] += 1
        deg[b] += 1
    if any(deg[v] == n - 1 for v in deg) and all(deg[v] == 1 for v in deg if deg[v] != n - 1):
        out = run(x).strip()
        d = int(out)
        assert d == 2, f'Star with {n} nodes must have diameter 2, got {d}'

def test_eccentricity_lower_bound(run, x):
    from collections import deque
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 100000 or m > 100000:
        return  # safety, though inputs are within bounds
    adj = [[] for _ in range(n)]
