        if not edge:
            continue
        a, b = map(int, edge.split())
        adj[a-1].append(b-1)
        adj[b-1].append(a-1)
    # BFS from vertex 0 (1‑based vertex 1)
    dist = [-1] * n
    q = deque([0])
    dist[0] = 0
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] == -1:
