{
  "rationale": "We propose ten tests based on necessary conditions that any correct solution must satisfy. They include output format checks, bounds derived from direct edges and incident colors, special cases (single color, small inputs), symmetry, connectivity in the whole graph, and complete colors. These tests are designed to catch backdoors that cause violations of these necessary conditions. The small brute-force test provides an exact check for small inputs. The bounds tests are robust and follow directly from the problem statement. We would drop the distinct colors bound first if needed, as it is the weakest upper bound.",
  "plan": [
    {
      "name": "test_output_structure",
      "intent": "Verify that the output has exactly q lines, each line contains a single integer, and each integer is between 0 and m (inclusive)."
    },
    {
      "name": "test_isolated_vertices",
      "intent": "For each query (u,v), if either vertex has degree 0 (no incident edges), then the answer must be 0."
    },
    {
      "name": "test_direct_edge_lower_bound",
      "intent": "For each query (u,v), the answer must be at least the number of colors for which there exists an edge directly connecting u and v."
    },
    {
      "name": "test_incident_colors_upper_bound",
      "intent": "For each query (u,v), the answer must be at most the number of colors that appear on at least one edge incident to u and at least one edge incident to v."
    },
    {
      "name": "test_small_brute_force",
      "intent": "If n <= 10, m <= 10, and q <= 10, compute the correct answer by brute-force: for each color, check connectivity via BFS/DFS. Compare with the output."
    },
    {
      "name": "test_single_color",
      "intent": "If m == 1, there is only one color. Compute whether u and v are connected in the graph (all edges are of that color) and assert the answer is 1 if connected, 0 otherwise."
    },
    {
      "name": "test_distinct_colors_bound",
      "intent": "For each query, the answer cannot exceed the total number of distinct colors that appear on at least one edge in the entire graph."
    },
    {
      "name": "test_symmetry",
      "intent": "For any pair of queries that are reverses of each other (i.e., (u,v) and (v,u)), their answers must be equal."
    },
    {
      "name": "test_disconnected_whole_graph",
      "intent": "Compute the connected components of the whole graph (ignoring colors). For each query, if u and v are in different components, the answer must be 0."
    },
    {
      "name": "test_complete_colors",
      "intent": "For each color that has edges between every pair of vertices (i.e., forms a complete graph on all n vertices), that color must be counted for every query. Thus, each answer must be at least the number of such colors."
