    pattern = re.compile(r'^([0-9a-f]{4}:){7}[0-9a-f]{4}$')
    assert pattern.fullmatch(out) is not None, "Output must match full IPv6 format"

def test_03(run, x):
    out = run(x).rstrip('\n')
    inp_line = x.strip().split('\n')[1]
    if '::' not in inp_line:
        out_blocks = out.split(':')
        assert len(out_blocks) == 8, "Without '::', output must have 8 blocks"
        inp_blocks = inp_line.split(':')
        for ob, ib in zip(out_blocks, inp_blocks):
            # strip leading zeros from output block, compare to input block (already short)
            stripped = ob.lstrip('0')
            if stripped == '':
                stripped = '0'
            assert stripped == ib, f"Block mismatch: {ob} -> {stripped} vs {ib}"

def test_04(run, x):
    out = run(x).rstrip('\n')
    inp_line = x.strip().split('\n')[1]
    if '::' in inp_line:
        out_blocks = out.split(':')
        assert len(out_blocks) == 8, "With '::', output must have exactly 8 blocks"

def test_05(run, x):
    out = run(x).rstrip('\n')
    inp_line = x.strip().split('\n')[1]
    if '::' in inp_line:
        out_blocks = out.split(':')
        # strip leading zeros from each output block
        out_stripped = [b.lstrip('0') if b != '0000' else '0' for b in out_blocks]
        out_stripped = ['0' if s == '' else s for s in out_stripped]
        inp_blocks = [b for b in inp_line.split(':') if b != '']
        # check subsequence
        i = 0
        for ib in inp_blocks:
            while i < len(out_stripped) and out_stripped[i] != ib:
                i += 1
            assert i < len(out_stripped), f"Explicit block {ib} not found in order"
            i += 1

def test_06(run, x):
    out = run(x).rstrip('\n')
    inp_line = x.strip().split('\n')[1]
    if '::' in inp_line:
        out_blocks = out.split(':')
        inp_split = inp_line.split(':')
        explicit = [b for b in inp_split if b != '']
        N = len(explicit)
        gap_pos = 0
        if inp_line.startswith('::'):
            gap_pos = 0
        elif inp_line.endswith('::'):
            gap_pos = len(inp_split) - 1
        else:
            # find the empty string in split list
            for i, b in enumerate(inp_split):
                if b == '':
                    gap_pos = i
                    break
        zero_count = 8 - N
        for i in range(gap_pos, gap_pos + zero_count):
            assert out_blocks[i] == '0000', f"Expected zero block at position {i}, got {out_blocks[i]}"
        # ensure contiguous and exactly zero_count blocks
        for i in range(gap_pos + zero_count, 8):
            assert out_blocks[i] != '0000', f"Unexpected zero block at {i}"

def test_07(run, x):
    out = run(x).rstrip('\n')
    inp_line = x.strip().split('\n')[1]
    # apply shortening rules to output
    blocks = out.split(':')
    short_blocks = []
    for b in blocks:
        s = b.lstrip('0')
        if s == '':
            s = '0'
        short_blocks.append(s)
    # find longest consecutive sequence of '0' blocks
    max_len = 0
    max_start = -1
    cur_len = 0
    cur_start = -1
    for i, b in enumerate(short_blocks):
        if b == '0':
            if cur_len == 0:
                cur_start = i
                cur_len = 1
            else:
                cur_len += 1
        else:
            if cur_len > max_len:
                max_len = cur_len
                max_start = cur_start
            cur_len = 0
    if cur_len > max_len:
        max_len = cur_len
        max_start = cur_start
    if max_len >= 2:
        # replace with '::'
        left = ':'.join(short_blocks[:max_start])
        right = ':'.join(short_blocks[max_start + max_len:])
        reconstructed = left + '::' + right if left or right else '::'
        # remove leading/trailing colons if needed
        if reconstructed.startswith('::'):
            reconstructed = '::' + reconstructed.lstrip(':')
        if reconstructed.endswith('::'):
            reconstructed = reconstructed.rstrip(':') + '::'
    else:
        reconstructed = ':'.join(short_blocks)
    assert reconstructed == inp_line, f"Shortening output gives {reconstructed}, expected {inp_line}"

def test_08(run, x):
    out = run(x).rstrip('\n')
    assert '::' not in out, "Full IPv6 must not contain '::'"

def test_09(run, x):
    out = run(x).rstrip('\n')
    no_colon = out.replace(':', '')
    assert len(no_colon) == 32, "Hex part must be 32 characters"
    assert all(c in '0123456789abcdef' for c in no_colon), "Only hex digits allowed"

def test_10(run, x):
    out = run(x).rstrip('\n')
    for block in out.split(':'):
        try:
            val = int(block, 16)
        except ValueError:
            assert False, f"Block {block} is not valid hex"
        assert 0 <= val <= 65535, f"Block {block} out of range 0-65535"

