        out = run(x).strip()
        assert out == 'NO', f'For n=1, output must be NO, got {out}'

def test_m1(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if m == 1:
        out = run(x).strip()
        if n == 1:
            assert out == 'NO', f'For n=1,m=1, output must be NO, got {out}'
        else:
            assert out == 'YES', f'For n>1,m=1, output must be YES, got {out}'

def test_all_zero_row(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
