def test_format(run, x):
    out = run(x).strip()
    assert out == 'Yes' or out == 'No', 'Output must be exactly Yes or No after stripping whitespace.'

def test_a_divides_c(run, x):
    a, b, c = map(int, x.strip().split())
    if c % a == 0:
        assert run(x).strip() == 'Yes', 'If c is divisible by a, answer must be Yes.'

def test_b_divides_c(run, x):
    a, b, c = map(int, x.strip().split())
    if c % b == 0:
        assert run(x).strip() == 'Yes', 'If c is divisible by b, answer must be Yes.'

def test_small_c_no(run, x):
    a, b, c = map(int, x.strip().split())
    if c < a and c < b and c % a != 0 and c % b != 0:
        assert run(x).strip() == 'No', 'If c < a and c < b and not divisible by a or b, answer must be No.'

def test_coprime_large(run, x):
    import math
    a, b, c = map(int, x.strip().split())
    if math.gcd(a, b) == 1 and c > a * b - a - b:
        assert run(x).strip() == 'Yes', 'If a and b coprime and c > a*b - a - b, answer must be Yes.'

def test_yes_implies_multiple_of_gcd(run, x):
    import math
    a, b, c = map(int, x.strip().split())
    out = run(x).strip()
    if out == 'Yes':
        assert c % math.gcd(a, b) == 0, 'If answer is Yes, c must be divisible by gcd(a,b).'

def test_not_multiple_of_gcd_implies_no(run, x):
    import math
    a, b, c = map(int, x.strip().split())
    if c % math.gcd(a, b) != 0:
        assert run(x).strip() == 'No', 'If c not divisible by gcd(a,b), answer must be No.'

def test_c_equals_a_or_b(run, x):
    a, b, c = map(int, x.strip().split())
    if c == a or c == b:
        assert run(x).strip() == 'Yes', 'If c equals a or b, answer must be Yes.'

def test_a_equal_b_iff(run, x):
    a, b, c = map(int, x.strip().split())
    if a == b:
        out = run(x).strip()
        if c % a == 0:
            assert out == 'Yes', 'If a == b and c divisible by a, answer must be Yes.'
        else:
            assert out == 'No', 'If a == b and c not divisible by a, answer must be No.'

def test_examples(run, x):
    if x == '4 6 15\n':
        assert run(x) == 'No\n', 'Example 1 mismatch.'
    elif x == '3 2 7\n':
        assert run(x) == 'Yes\n', 'Example 2 mismatch.'
    elif x == '6 11 6\n':
        assert run(x) == 'Yes\n', 'Example 3 mismatch.'

