tests_src:
def test_brute_force(run, x):
    a, b, c = map(int, x.strip().split())
    if c > 1000:
        return  # too large to brute-force safely
    found = False
    for x in range(c // a + 1):
        if (c - a * x) % b == 0:
            y = (c - a * x) // b
            if y >= 0:
                found = True
                break
    expected = "Yes\n" if found else "No\n"
    assert run(x) == expected

def test_output_format(run, x):
    out = run(x)
    assert out in ("Yes\n", "No\n")

def test_divisible_by_a_or_b(run, x):
    a, b, c = map(int, x.strip().split())
    if c % a == 0 or c % b == 0:
        assert run(x) == "Yes\n"

def test_a_or_b_eq_one(run, x):
    a, b, c = map(int, x.strip().split())
    if a == 1 or b == 1:
        assert run(x) == "Yes\n"

def test_both_greater_than_c(run, x):
    a, b, c = map(int, x.strip().split())
    if a > c and b > c:
        assert run(x) == "No\n"

def test_gcd_does_not_divide(run, x):
    import math
    a, b, c = map(int, x.strip().split())
    g = math.gcd(a, b)
    if c % g != 0:
        assert run(x) == "No\n"

def test_yes_implies_gcd_divides(run, x):
    import math
    a, b, c = map(int, x.strip().split())
    out = run(x)
    if out == "Yes\n":
        assert c % math.gcd(a, b) == 0

def test_even_even_odd(run, x):
    a, b, c = map(int, x.strip().split())
    if a % 2 == 0 and b % 2 == 0 and c % 2 == 1:
        assert run(x) == "No\n"

def test_examples(run, x):
    if x == "4 6 15\n":
        assert run(x) == "No\n"
    elif x == "3 2 7\n":
        assert run(x) == "Yes\n"
    elif x == "6 11 6\n":
        assert run(x) == "Yes\n"

def test_c_less_than_min(run, x):
    a, b, c = map(int, x.strip().split())
    if c < a and c < b:
        assert run(x) == "No\n"

