def test_n1(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 1:
        a = int(lines[1].strip())
        output = run(x)
        if a == 0:
            assert output == 'cslnb\n', f'For n=1, a=0 must output cslnb\\n, got {repr(output)}'
        else:
            assert output == 'sjfnb\n', f'For n=1, a!=0 must output sjfnb\\n, got {repr(output)}'

def test_example_2_2_2(run, x):
    if x == '2\n2 2\n':
        output = run(x)
        assert output == 'sjfnb\n', f'For input "2\\n2 2\\n", output must be sjfnb\\n, got {repr(output)}'

def test_example_1_0(run, x):
    lines = x.strip().split('\n')
    if len(lines) == 2:
        n = int(lines[0])
        if n == 2:
            a = list(map(int, lines[1].split()))
            if set(a) == {0, 1}:
                output = run(x)
                assert output == 'cslnb\n', f'For two piles with sizes 0 and 1, output must be cslnb\\n, got {repr(output)}'

def test_example_2_3_1(run, x):
    if x == '3\n2 3 1\n':
        output = run(x)
        assert output == 'sjfnb\n', f'For input "3\\n2 3 1\\n", output must be sjfnb\\n, got {repr(output)}'

def test_triple_duplicate(run, x):
    lines = x.strip().split('\n')
    if len(lines) == 2:
        a = list(map(int, lines[1].split()))
        from collections import Counter
        cnt = Counter(a)
        if any(v >= 3 for v in cnt.values()):
            output = run(x)
            assert output == 'cslnb\n', f'If any value appears >=3 times, output must be cslnb\\n, got {repr(output)}'

def test_two_zeros(run, x):
    lines = x.strip().split('\n')
    if len(lines) == 2:
        a = list(map(int, lines[1].split()))
        if a.count(0) >= 2:
            output = run(x)
            assert output == 'cslnb\n', f'If at least two piles are 0, output must be cslnb\\n, got {repr(output)}'

