    lines = x.strip().split('\n')
    if len(lines) == 2:
        a = list(map(int, lines[1].split()))
        from collections import Counter
        cnt = Counter(a)
        duplicate_counts = sum(1 for v in cnt.values() if v >= 2)
        if duplicate_counts >= 2:
