                if d * d != m:
                    tot += f(d)
            d += 1
        return tot
    def F(kval, m):
        if kval == 1:
            return f(g(m))
        if kval % 2 == 0:
            return g(F(kval-1, m))
        else:
            return f(F(kval-1, m))
    expected = F(k-1, n)
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == expected

def test_n_lt_mod(run, x):
    MOD = 1000000007
    s = x.strip().split()
    n = int(s[0])
    if n >= MOD:
        return
    out = run(x).strip()
    assert out.isdigit()
    val = int(out)
    assert 1 <= val <= n

def test_k2_small(run, x):
    import math
    s = x.strip().split()
    n = int(s[0])
    k = int(s[1])
    if k != 2 or n > 10**6:
        return
    # compute φ(n)
