def test_small_bruteforce(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    if H > 4 or W > 4:
        return
    grid = lines[1:]
    from itertools import permutations
    n = len(grid)
    m = len(grid[0]) if grid else 0
    target = None
    for row_perm in permutations(range(H)):
        for col_perm in permutations(range(W)):
            ok = True
            for i in range(H):
                for j in range(W):
                    a = grid[row_perm[i]][col_perm[j]]
                    ri = H - 1 - i
                    rj = W - 1 - j
                    b = grid[row_perm[ri]][col_perm[rj]]
                    if a != b:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                target = 'YES\n'
                break
        if target:
            break
    if target is None:
        target = 'NO\n'
    assert run(x) == target, f'For H={H},W={W} brute‑force says {target.strip()}'

