import math
def phi(m):
    result = m
    p = 2
    while p * p <= m:
        if m % p == 0:
            while m % p == 0:
                m //= p
            result -= result // p
        p += 1 if p == 2 else 2
    if m > 1:
        result -= result // m
    return result
def f_spec(m):
    return 1 if m == 1 else phi(m)
def g_spec(m):
    total = 0
    d = 1
    while d * d <= m:
        if m % d == 0:
            total += f_spec(m // d)
            if d != m // d:
                total += f_spec(d)
        d += 1
    return total
def F_spec(n, k):
    if k == 1:
        return f_spec(g_spec(n))
    prev = F_spec(n, k - 1)
    if k % 2 == 0:
        return g_spec(prev)
    else:
        return f_spec(prev)
def test_small_brute(run, x):
    n_str, k_str = x.strip().split()
    n = int(n_str); k = int(k_str)
    if n <= 100000 and (k + 1) // 2 <= 10:  # t = ceil(k/2) ≤ 10
        expected = F_spec(n, k) % 1000000007
        out = int(run(x).strip())
        assert out == expected, f'For small input expected {expected}, got {out}'

