    },
    {
      "name": "test_small_bruteforce",
      "source": "def test_small_bruteforce(run, x):
    # Only run exhaustive minimax if n <= 8.
    lines = x.strip('\n').split('\n')
    if len(lines) != 2:
        return
    n_str, a_str = lines[0], lines[1]
    if not n_str.isdigit():
        return
    n = int(n_str)
    if n > 8:
        return
    nums = list(map(int, a_str.split()))
    if len(nums) != n:
        return
    # Brute-force game outcome
    from functools import lru_cache
    @lru_cache(None)
    def win_state(mask):
        if mask == 0:
            return False  # player to move loses (no cards)
        cards = [nums[i] for i in range(n) if (mask >> i) & 1]
        for i in range(n):
            if (mask >> i) & 1:
