def test_format(run, x):
    output = run(x)
    assert output in ('Conan\n', 'Agasa\n'), f'Output must be exactly Conan\\n or Agasa\\n, got {repr(output)}'

def test_n1(run, x):
    # Only check if input is exactly n=1
    lines = x.strip('\n').split('\n')
    if len(lines) != 2:
        return
    n_str, a_str = lines[0], lines[1]
    if not (n_str.isdigit() and a_str.strip().replace(' ', '').isdigit()):
        return
    n = int(n_str)
    if n == 1:
        output = run(x)
        assert output == 'Conan\n', f'For n=1, output must be Conan\\n, got {repr(output)}'

def test_all_equal(run, x):
    # Check if all numbers are identical
    lines = x.strip('\n').split('\n')
    if len(lines) != 2:
        return
    n_str, a_str = lines[0], lines[1]
    if not n_str.isdigit():
        return
    n = int(n_str)
    nums = list(map(int, a_str.split()))
    if len(nums) != n:
        return
    if len(set(nums)) == 1:  # all equal
        expected = 'Conan\n' if n % 2 == 1 else 'Agasa\n'
        output = run(x)
        assert output == expected, f'For all equal numbers, parity mismatch: expected {expected!r}, got {output!r}'

def test_unique_max(run, x):
    # If maximum appears exactly once, Conan should win.
    lines = x.strip('\n').split('\n')
    if len(lines) != 2:
        return
    n_str, a_str = lines[0], lines[1]
    if not n_str.isdigit():
        return
    n = int(n_str)
    nums = list(map(int, a_str.split()))
    if len(nums) != n:
        return
    max_val = max(nums)
    if nums.count(max_val) == 1:
        output = run(x)
        assert output == 'Conan\n', f'When maximum appears once, output must be Conan\\n, got {output!r}'

def test_small_bruteforce(run, x):
    # Only run exhaustive minimax if n <= 8.
    lines = x.strip('\n').split('\n')
    if len(lines) != 2:
        return
    n_str, a_str = lines[0], lines[1]
    if not n_str.isdigit():
        return
    n = int(n_str)
    if n > 8:
        return
    nums = list(map(int, a_str.split()))
    if len(nums) != n:
        return
    # Brute-force game outcome
    from functools import lru_cache
    @lru_cache(None)
    def win_state(mask):
        if mask == 0:
            return False  # player to move loses (no cards)
        cards = [nums[i] for i in range(n) if (mask >> i) & 1]
        for i in range(n):
            if (mask >> i) & 1:
                new_mask = mask
                chosen = nums[i]
                # remove all j with a_j < chosen
                for j in range(n):
                    if nums[j] < chosen:
                        new_mask &= ~(1 << j)
                # remove the chosen card itself
                new_mask &= ~(1 << i)
                if not win_state(new_mask):
                    return True
        return False
    initial_mask = (1 << n) - 1
    expected = 'Conan\n' if win_state(initial_mask) else 'Agasa\n'
    output = run(x)
    assert output == expected, f'Brute-force mismatch: expected {expected!r}, got {output!r}'

def test_output_length(run, x):
    output = run(x)
    assert len(output) == 6, f'Output length must be 6 (5 letters + newline), got {len(output)}: {repr(output)}'

def test_no_leading_trailing_spaces(run, x):
    output = run(x)
    stripped = output.rstrip('\n')
    assert stripped == output.rstrip(), f'Output has extra whitespace before/after: {repr(output)}'

def test_example1(run, x):
    if x == '3\n4 5 7\n':
        output = run(x)
        assert output == 'Conan\n', f'For example 1, output must be Conan\\n, got {repr(output)}'

def test_example2(run, x):
    if x == '2\n1 1\n':
        output = run(x)
        assert output == 'Agasa\n', f'For example 2, output must be Agasa\\n, got {repr(output)}'

def test_case_sensitive(run, x):
    output = run(x)
    assert output in ('Conan\n', 'Agasa\n'), f'Output must be exactly Conan\\n or Agasa\\n (case‑sensitive), got {repr(output)}'

