def test_format(run, x):
    out = run(x)
    lines = out.strip().split('\n')
    assert len(lines) == 1, 'Output must be a single line'
    parts = lines[0].split()
    n = int(x.strip().split('\n')[0])
    assert len(parts) == n, f'Expected {n} integers, got {len(parts)}'
    for p in parts:
        val = int(p)
        assert 1 <= val <= 10**9, f'Value {val} out of range [1,1e9]'

def test_diagonal_zeros(run, x):
    # Input already has zeros on diagonal per problem statement; we just verify.
    lines = x.strip().split('\n')
    n = int(lines[0])
    for i in range(1, n+1):
        row = list(map(int, lines[i].split()))
        assert row[i-1] == 0, f'Diagonal element M[{i-1}][{i-1}] is not zero'

def test_input_symmetry(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    M = [list(map(int, lines[i+1].split())) for i in range(n)]
    for i in range(n):
        for j in range(n):
            assert M[i][j] == M[j][i], f'Matrix not symmetric at ({i},{j})'

def test_divisibility_row(run, x):
    out = run(x)
    a = list(map(int, out.strip().split()))
    lines = x.strip().split('\n')
    n = int(lines[0])
    M = [list(map(int, lines[i+1].split())) for i in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                assert M[i][j] % a[i] == 0, f'M[{i}][{j}] = {M[i][j]} not divisible by a[{i}] = {a[i]}'

def test_divisibility_column(run, x):
    out = run(x)
    a = list(map(int, out.strip().split()))
