    M = [list(map(int, lines[i+1].split())) for i in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                assert M[j][i] % a[i] == 0, f'M[{j}][{i}] = {M[j][i]} not divisible by a[{i}] = {a[i]}'

