    {
      "name": "test_small_bruteforce",
      "source": "def test_small_bruteforce(run, x):
    import itertools
    lines = x.strip().split('\n')
    if len(lines) < 4:
        return
    n = int(lines[2].split()[0])
    if n > 4:
        return
    x1, y1 = map(int, lines[0].split())
    x2, y2 = map(int, lines[1].split())
    coeffs = []
    for i in range(n):
        a, b, c = map(int, lines[3 + i].split())
        coeffs.append((a, b, c))
    # All sign patterns (each line gives +1 or -1, zero not allowed because points not on lines)
    patterns = set()
    for signs in itertools.product([-1, 1], repeat=n):
        patterns.add(signs)
    # Map point to its pattern
    def get_pattern(px, py):
        return tuple(1 if a * px + b * py + c > 0 else -1 for a, b, c in coeffs)
    start = get_pattern(x1, y1)
    target = get_pattern(x2, y2)
    # Build adjacency: two patterns are adjacent if they differ in exactly one sign and that flip corresponds to crossing a line with a nonzero-length border?
    # Actually, for infinite lines, two regions share a nonzero border iff they differ in exactly one sign (the line separating them).
    # This is a standard fact: regions are cells of the arrangement, adjacency = Hamming distance 1.
    adj = {p: [] for p in patterns}
    for p in patterns:
        for i in range(n):
            q = list(p)
            q[i] = -q[i]
            q = tuple(q)
            if q in patterns:
                adj[p].append(q)
    # BFS
    from collections import deque
    if start == target:
        expected = 0
    else:
        dist = {start: 0}
        q = deque([start])
        while q:
            cur = q.popleft()
            for nb in adj[cur]:
                if nb not in dist:
                    dist[nb] = dist[cur] + 1
                    if nb == target:
                        q.clear()
                        break
                    q.append(nb)
        expected = dist.get(target, -1)
        if expected == -1:
            # Should not happen because arrangement is connected, but skip if somehow disconnected.
            return
    out = run(x)
    assert int(out.strip()) == expected, f'For n={n} small brute‑force, expected {expected}.'"
    },
