    g = [0]*(max_a+1)
    for s in range(1, max_a+1):
        moves = set()
        moves.add(g[s-1])
        if s % 2 == 0:
            half = s//2
            if k % 2 == 1:
                # k piles of Grundy(half)
                moves.add(g[half] if k % 2 == 1 else 0)
            else:
                # k even: xor of k copies of g[half] is 0 because k even
                moves.add(0)
        g[s] = mex(moves)
    xor = 0
    for a in piles:
        xor ^= g[a]
    expected = 'Kevin\n' if xor != 0 else 'Nicky\n'
    assert run(x) == expected, f'Brute force on small: expected {expected.strip()}, got {run(x).strip()}'

