def test_format(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    assert lines
    k_line = lines[0]
    try:
        k = int(k_line)
    except ValueError:
        assert False, "First line must be an integer"
    assert k >= 0
    if k == 0:
        assert len(lines) == 1, "When k=0, there should be no further lines"
    else:
        assert len(lines) == k + 1, f"Expected {k+1} lines, got {len(lines)}"
        for i in range(1, k+1):
            assert lines[i], f"Suffix line {i} must be non-empty"
            assert lines[i].isalpha() and lines[i].islower(), f"Suffix line {i} must be lowercase letters"

def test_suffix_length(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    if len(lines) <= 1:
        return
    k = int(lines[0])
    for i in range(1, k+1):
        s = lines[i]
        assert 2 <= len(s) <= 3, f"Suffix length must be 2 or 3, got '{s}' of length {len(s)}"
        assert all('a' <= c <= 'z' for c in s), f"Suffix must contain only lowercase English letters: '{s}'"

def test_sorted_distinct(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    if len(lines) <= 1:
        return
    k = int(lines[0])
    suffixes = lines[1:]
    assert suffixes == sorted(suffixes), "Suffixes must be in lexicographical order"
    assert len(suffixes) == len(set(suffixes)), "Suffixes must be distinct"

def test_k_consistent(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    if not lines:
        assert False, "Output is empty"
    k = int(lines[0])
    if k == 0:
        assert len(lines) == 1
    else:
        assert len(lines) == k + 1

def test_suffix_starts_after_root(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    if len(lines) <= 1:
        return
    k = int(lines[0])
    s = x.strip()
    for i in range(1, k+1):
        suffix = lines[i]
        # Check that suffix appears as a contiguous substring starting at position >= 5
        found = any(s[j:j+len(suffix)] == suffix for j in range(5, len(s)))
        assert found, f"Suffix '{suffix}' does not appear in input after position 4"

def test_last_two_for_long(run, x):
    s = x.strip()
    if len(s) < 7:
        return
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    if len(lines) <= 1:
        assert False, f"For length {len(s)} >= 7, last two characters must be a suffix"
    k = int(lines[0])
    suffixes = lines[1:]
    last_two = s[-2:]
    assert last_two in suffixes, f"Last two characters '{last_two}' must be in suffixes"

def test_last_three_for_longer(run, x):
    s = x.strip()
    if len(s) < 8:
        return
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    if len(lines) <= 1:
        assert False, f"For length {len(s)} >= 8, last three characters must be a suffix"
    k = int(lines[0])
    suffixes = lines[1:]
    last_three = s[-3:]
    assert last_three in suffixes, f"Last three characters '{last_three}' must be in suffixes"

def test_upper_bound(run, x):
    s = x.strip()
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    if len(lines) <= 1:
        return
    k = int(lines[0])
    possible = set()
    for i in range(5, len(s)):
        if i + 2 <= len(s):
            possible.add(s[i:i+2])
        if i + 3 <= len(s):
            possible.add(s[i:i+3])
    assert k <= len(possible), f"Number of suffixes {k} exceeds possible distinct substrings after position 4"

def test_brute_force_small(run, x):
    s = x.strip()
    if len(s) > 10:
        return
    # Enumerate all decompositions
    n = len(s)
    suffixes_possible = set()
    # Root length must be > 4
    for root_end in range(5, n+1):
        # remaining string length
        rem = n - root_end
        # Use recursion to fill the remaining part with length 2 or 3 suffixes,
        # with no two consecutive equal.
        def dfs(pos, last_suffix):
            if pos == n:
                return True
            # try length 2
            if pos + 2 <= n:
                suff2 = s[pos:pos+2]
                if suff2 != last_suffix:
                    if dfs(pos+2, suff2):
                        suffixes_possible.add(suff2)
            # try length 3
            if pos + 3 <= n:
                suff3 = s[pos:pos+3]
                if suff3 != last_suffix:
                    if dfs(pos+3, suff3):
                        suffixes_possible.add(suff3)
            return False  # not needed, we only collect suffixes
        # start after root_end with no previous suffix
        dfs(root_end, '')
    expected = sorted(suffixes_possible)
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    if not expected:
        assert lines == ['0'] or lines == [], f"For small input, expected 0 suffixes, got {out}"
    else:
        k = int(lines[0])
        got = lines[1:]
        assert got == expected, f"For small input, expected {expected}, got {got}"


def test_no_empty_suffix(run, x):
    out = run(x).rstrip('\n')
    lines = out.split('\n')
    if len(lines) <= 1:
        return
    k = int(lines[0])
    for i in range(1, k+1):
        assert lines[i] != '', f"Suffix line {i} is empty"

