    expected = 'YES' if possible else 'NO'
    assert out == expected, f"brute force says {expected} for n,m≤8, got {out}"

def test_examples(run, x):
    # exact strings from statement (including newline at end? We'll strip trailing newline for comparison)
    examples = [
        ("3 3\n1 0 1\n2 1 3\n2 1 2\n2 2 3", "NO"),
        ("3 3\n1 0 1\n3 1 2 3\n1 2\n2 1 3", "YES"),
        ("3 3\n1 0 1\n3 1 2 3\n2 1 2\n1 3", "NO"),
    ]
    inp_stripped = x.rstrip('\n')
    for ex_in, ex_out in examples:
        if inp_stripped == ex_in:
            out = run(x).strip()
            assert out == ex_out, f"Example input expects {ex_out}, got {out}"

def test_switch_count_parity(run, x):
    out = run(x).strip()
    if out == 'YES':
        lines = x.strip().split('\n')
        n_m = list(map(int, lines[0].split()))
        n, m = n_m
        r = list(map(int, lines[1].split()))
        # parity condition: sum (1 - r_i) mod 2 must be 0.
        # (Derived from linear algebra over GF(2) – necessary but not sufficient.)
        s = sum(1 - v for v in r) % 2
        assert s == 0, f"When output is YES, sum(1‑r_i) mod 2 must be 0, got {s}"

