tests_src:
def test_example_11(run, x):
    if x.strip() == '11':
        out = run(x)
        assert out.strip() == '2', f'For input 11 expected 2, got {out.strip()}'


def test_example_14(run, x):
    if x.strip() == '14':
        out = run(x)
        assert out.strip() == '0', f'For input 14 expected 0, got {out.strip()}'


def test_example_61441(run, x):
    if x.strip() == '61441':
        out = run(x)
        assert out.strip() == '2', f'For input 61441 expected 2, got {out.strip()}'


def test_example_571576(run, x):
    if x.strip() == '571576':
        out = run(x)
        assert out.strip() == '10', f'For input 571576 expected 10, got {out.strip()}'


def test_example_2128506(run, x):
    if x.strip() == '2128506':
        out = run(x)
        assert out.strip() == '3', f'For input 2128506 expected 3, got {out.strip()}'


def test_zero(run, x):
    if x.strip() == '0':
        out = run(x)
        assert out.strip() == '1', f'For input 0 expected 1 (hex digit 0 has one hole), got {out.strip()}'


def test_non_negative(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 0, f'Output must be non‑negative, got {val}'


def test_upper_bound(run, x):
    n = int(x.strip())
    if n == 0:
        digits = 1
    else:
        # floor(log16(n)) + 1 without floats
        digits = 0
        temp = n
        while temp > 0:
            temp //= 16
            digits += 1
    max_holes = 2 * digits
    out = run(x)
    val = int(out.strip())
    assert val <= max_holes, f'Output {val} exceeds maximum possible holes {max_holes} for {n}'


def test_single_digit_range(run, x):
    n = int(x.strip())
    if 0 <= n <= 15:
        out = run(x)
        val = int(out.strip())
        assert val in (0, 1, 2), f'Single hex digit must give 0,1, or 2 holes, got {val}'


def test_output_format(run, x):
    import re
    out = run(x)
    assert re.fullmatch(r'^-?\d+\n$', out), f'Output must be an integer possibly with minus, then newline, got {repr(out)}'

