tests_src:
def test_example_11(run, x):
    if x.strip() == '11':
        assert run(x).strip() == '2'

def test_example_14(run, x):
    if x.strip() == '14':
        assert run(x).strip() == '0'

def test_input_0(run, x):
    if x.strip() == '0':
        # Hexadecimal digit '0' has one hole
        assert run(x).strip() == '1'

def test_input_31(run, x):
    if x.strip() == '31':
        # Hexadecimal '1F': '1' (0 holes), 'F' (0 holes) total 0
        assert run(x).strip() == '0'

def test_input_8(run, x):
    if x.strip() == '8':
        # Hexadecimal digit '8' has two holes
        assert run(x).strip() == '2'

def test_input_4(run, x):
    if x.strip() == '4':
        # Hexadecimal digit '4' has one hole
        assert run(x).strip() == '1'

def test_input_15(run, x):
    if x.strip() == '15':
        # Hexadecimal 'F' (0 holes)
        assert run(x).strip() == '0'

def test_input_16(run, x):
    if x.strip() == '16':
        # Hexadecimal '10': '1' (0), '0' (1) total 1
        assert run(x).strip() == '1'

def test_input_255(run, x):
    if x.strip() == '255':
        # Hexadecimal 'FF': both 'F' have 0 holes
        assert run(x).strip() == '0'

def test_input_4095(run, x):
    if x.strip() == '4095':
        # Hexadecimal 'FFF': all 'F' have 0 holes
        assert run(x).strip() == '0'

