{
  "rationale": "These tests verify necessary conditions from the specification: exact optimum for small n (<=8), lower bound from no reduction, two upper bounds (trivial and sum of squares), example correctness, non-negativity, output format, a simple lower bound from two largest pairs, special case of uniform sticks, and zero output when n<4. The trivial upper bound is the weakest and could be dropped first.",
  "plan": [
    {
      "name": "test_small_exact",
      "intent": "If n <= 8, compute the exact maximum area by brute force over all reductions and rectangle formations, and assert the output equals that value. For larger n, skip."
    },
    {
      "name": "test_lower_bound_no_reduction",
      "intent": "Compute the maximum area achievable without using the reduction option (by pairing sticks into rectangles) and assert the output is at least that."
    },
    {
      "name": "test_upper_bound_trivial",
      "intent": "Compute floor(n/4) * (max(l_i))^2 and assert the output is less than or equal to this."
    },
    {
      "name": "test_examples",
      "intent": "If the input exactly matches one of the three given examples, assert the output matches the expected output from the statement."
    },
    {
      "name": "test_non_negative",
      "intent": "Parse the output as an integer and assert it is >= 0."
    },
    {
      "name": "test_output_format",
      "intent": "Assert the output string consists solely of an integer optionally followed by a newline, with no extra characters."
    },
    {
      "name": "test_simple_lower_bound",
      "intent": "If there are at least two pairs of equal lengths (counting each length floor(cnt/2) times), take the two largest such pair lengths and assert the output is at least their product."
    },
    {
      "name": "test_uniform_sticks",
      "intent": "If all stick lengths are equal to L, assert the output equals (n // 4) * L * L."
    },
    {
      "name": "test_insufficient_sticks",
      "intent": "If n < 4, assert the output is exactly 0."
    },
    {
      "name": "test_upper_bound_sum_squares",
      "intent": "Compute the sum of squares of all stick lengths and assert that twice the output is <= that sum."
    }
  ]
}

{
  "rationale": "The tests are based on necessary conditions from the specification: output must be an integer in [-1, K]; if -1, the goal is unachievable even with K; if 0, the average is already met; if positive, it must equal the deficit and be minimal. Additional tests verify minimality, achievability, and a full brute‑force check. Each test is a direct consequence of the problem statement, so a correct solution will pass all. The brute‑force test is the strongest but requires computation; the others are simpler sanity checks that might catch specific backdoors earlier.",
  "plan": [
    {
      "name": "test_valid_range",
      "intent": "The output must parse as an integer and be either -1 or in the range 0..K (inclusive). A non‑integer or value outside this range indicates a wrong answer."
    },
    {
      "name": "test_minus_one_condition",
      "intent": "If the output is -1, then the sum of given scores plus K must be strictly less than M*N (the goal is impossible). If output is -1 but sum+K >= M*N, the answer is wrong."
    },
    {
      "name": "test_zero_condition",
      "intent": "If the output is 0, then the sum of given scores must be at least M*N (the average is already satisfied). If output is 0 but sum < M*N, the answer is wrong."
    },
    {
      "name": "test_positive_deficit",
      "intent": "If the output is a positive integer, it must exactly equal M*N minus the sum of given scores (the deficit). Any positive output that differs from this deficit is wrong."
    },
    {
      "name": "test_already_met",
      "intent": "If the sum of given scores is at least M*N, the output must be 0. Any other output (positive or -1) in this case is wrong."
    },
    {
      "name": "test_achievable_not_minus_one",
      "intent": "If the sum of given scores plus K is at least M*N, the goal is achievable, so the output must not be -1. Output -1 in this situation is wrong."
    },
    {
      "name": "test_minimality",
      "intent": "If the output is not -1, then for every integer y from 0 to output‑1, the sum of given scores plus y must be less than M*N. If a smaller y also meets the goal, the output is not minimal and the answer is wrong."
    },
    {
      "name": "test_average",
      "intent": "If the output is not -1, then the total sum (given scores plus output) must be at least M*N. If this inequality does not hold, the answer is wrong."
    },
    {
      "name": "test_achievable_range",
      "intent": "If the output is not -1, it must lie between 0 and K inclusive. An output outside [0, K] (other than -1) is wrong."
    },
    {
      "name": "test_brute_force",
      "intent": "Compute the required score by trying each possible score from 0 to K in increasing order, and take the first that makes the total sum at least M*N; if none, the answer should be -1. Any difference between this computed value and the output indicates a wrong answer."
    }
  ]
}

{
  "rationale": "The tests check necessary conditions derived directly from the specification, ensuring the output is a valid integer within bounds, satisfies the average requirement, and is minimal. They cover all cases: when the goal is already met (output 0), when a feasible score exists (output equals needed points), and when it's impossible (output -1). The brute-force test provides full verification. Test 1 (parsing) is the most basic and could be dropped first, as it catches only formatting errors, which are less likely to be a backdoor.",
  "plan": [
    {
      "name": "test_parse",
      "intent": "The output string must parse to an integer (allowing optional leading/trailing whitespace). If int() raises an exception, the answer is wrong."
    },
    {
      "name": "test_range",
      "intent": "The parsed integer must be either -1 or between 0 and K inclusive. If it is outside this set, the answer is wrong."
    },
    {
      "name": "test_minus_one_condition",
      "intent": "If the output is -1, then the required total M*N must exceed the sum of given scores by more than K, i.e., M*N - sum(A) > K. If this condition is false, the answer is wrong."
    },
    {
      "name": "test_achieves_average",
