    },
    {
      "name": "test_minimality_positive",
      "intent": "If the output is a positive integer, then subtracting one from it must yield a score that does not achieve the required total, i.e., sum(A) + (output - 1) < M*N. If this fails, the answer is wrong because a smaller score would also work."
    },
    {
      "name": "test_zero_condition",
      "intent": "If the output is 0, then the sum of given scores must already meet or exceed the required total M*N. If sum(A) < M*N, the answer is wrong because scoring 0 would not achieve the average."
    },
    {
      "name": "test_nonpositive_need",
      "intent": "If the required total M*N is less than or equal to the sum of given scores (i.e., M*N - sum(A) <= 0), then the output must be 0. If it is not, the answer is wrong."
    },
    {
      "name": "test_midrange_need",
      "intent": "If the required total exceeds the sum of given scores by an amount between 1 and K inclusive (i.e., 1 <= M*N - sum(A) <= K), then the output must equal that difference. If it does not, the answer is wrong."
    },
    {
      "name": "test_large_need",
      "intent": "If the required total exceeds the sum of given scores by more than K (i.e., M*N - sum(A) > K), then the output must be -1. If it is not, the answer is wrong."
    },
    {
      "name": "test_brute_force",
      "intent": "The output must be the minimum integer X in [0, K] such that sum(A) + X >= M*N, or -1 if no such X exists. Verify by iterating over all possible X from 0 to K. If the output does not match this computed value, the answer is wrong."
    }
  ]
}

