def test_format(run, x):
    output = run(x)
    lines = output.strip().split('\n')
    assert len(lines) == 1, 'output must be a single line'
    value = lines[0].strip()
    try:
        int(value)
    except ValueError:
        raise AssertionError('output must be a single integer')
    # No extra characters after the integer on its line
    assert output.strip() == value, 'no extra whitespace or text after the integer'


def test_non_negative(run, x):
    output = run(x)
    ans = int(output.strip())
    assert ans >= 0, 'answer cannot be negative'


def test_upper_bound_n(run, x):
    output = run(x)
    ans = int(output.strip())
    # parse n from input
    first_line = x.split('\n')[0].strip()
    n = int(first_line.split()[0])
    assert ans <= n-1, f'answer cannot exceed {n-1}'


def test_empty_graph(run, x):
    # parse n, m from input
    first_line = x.split('\n')[0].strip()
    n, m = map(int, first_line.split()[:2])
    if m == 0:
        output = run(x)
        ans = int(output.strip())
        expected = n-1 if n > 1 else 0
        assert ans == expected, f'for m=0, answer must be {expected}'


def test_single_city(run, x):
    first_line = x.split('\n')[0].strip()
    n = int(first_line.split()[0])
    if n == 1:
        output = run(x)
        ans = int(output.strip())
        assert ans == 0, 'for n=1 answer must be 0'


def test_all_reachable(run, x):
    # parse n, m, s and edges
    lines = x.strip().split('\n')
    n, m, s = map(int, lines[0].split())
    adj = [[] for _ in range(n+1)]
    for line in lines[1:1+m]:
        if not line.strip():
            continue
        u, v = map(int, line.split())
        adj[u].append(v)
    from collections import deque
    visited = [False]*(n+1)
    q = deque([s])
    visited[s] = True
    while q:
        u = q.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                q.append(v)
    reachable_count = sum(visited[1:])
    if reachable_count == n:
        output = run(x)
        ans = int(output.strip())
        assert ans == 0, 'when all cities reachable, answer must be 0'


def test_unreachable_upper_bound(run, x):
    lines = x.strip().split('\n')
    n, m, s = map(int, lines[0].split())
    adj = [[] for _ in range(n+1)]
    for line in lines[1:1+m]:
        if not line.strip():
            continue
        u, v = map(int, line.split())
        adj[u].append(v)
    from collections import deque
    visited = [False]*(n+1)
    q = deque([s])
    visited[s] = True
    while q:
        u = q.popleft()
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                q.append(v)
    unreachable = n - sum(visited[1:])
    output = run(x)
    ans = int(output.strip())
    assert ans <= unreachable, f'answer cannot exceed unreachable city count {unreachable}'


def test_outdegree_zero(run, x):
    lines = x.strip().split('\n')
    n, m, s = map(int, lines[0].split())
    adj = [[] for _ in range(n+1)]
    for line in lines[1:1+m]:
        if not line.strip():
