    def dfs2(u, c):
        comp[u] = c
        for v in rev_adj[u]:
            if comp[v] == 0:
                dfs2(v, c)
    cid = 0
    for u in reversed(order):
        if comp[u] == 0:
            cid += 1
            dfs2(u, cid)
    # Condensation graph
    indeg = [0]*(cid+1)
    for u in range(1, n+1):
        for v in adj[u]:
            if comp[u] != comp[v]:
                indeg[comp[v]] += 1
    # Reachable SCCs from s
    reachable_scc = set()
    stack = [comp[s]]
