    comp = [0]*(n+1)
    def dfs2(u, c):
        comp[u] = c
        for v in rev_adj[u]:
            if comp[v] == 0:
                dfs2(v, c)
    cid = 0
    for u in reversed(order):
        if comp[u] == 0:
            cid += 1
            dfs2(u, cid)
    # Condensation graph indegrees
    indeg = [0]*(cid+1)
    for u in range(1, n+1):
        for v in adj[u]:
            if comp[u] != comp[v]:
                indeg[comp[v]] += 1
    # Reachable SCCs from s
    reachable_scc = set()
    stack = [comp[s]]
    reachable_scc.add(comp[s])
    while stack:
        cur = stack.pop()
        for u in range(1, n+1):
            if comp[u] == cur:
                for v in adj[u]:
                    nxt = comp[v]
                    if nxt not in reachable_scc:
                        reachable_scc.add(nxt)
                        stack.append(nxt)
    # Count SCCs not reachable with indegree zero
    need = 0
    for c in range(1, cid+1):
        if c not in reachable_scc and indeg[c] == 0:
            need += 1
    output = run(x)
    ans = int(output.strip())
    assert ans >= need, f'answer must be at least {need}'

