tests_src:
def test_exact_match(run, x):
    S = x.rstrip('\n')
    # Only compute expected when input is small enough to stay fast
    if len(S) <= 100:  # spec limit, safe to compute
        expected = 'x' * len(S) + '\n'
        assert run(x) == expected

def test_length_match(run, x):
    S = x.rstrip('\n')
    out = run(x)
    assert len(out) == len(S) + 1  # characters plus newline

def test_ends_with_newline(run, x):
    out = run(x)
    assert out.endswith('\n')

def test_only_x_and_newline(run, x):
    out = run(x)
    for ch in out:
        assert ch in 'x\n'

def test_line_is_all_x(run, x):
    out = run(x)
    lines = out.split('\n')
    # Output should be exactly one line plus trailing newline -> lines length 2
    assert len(lines) == 2 and lines[1] == ''
    assert all(ch == 'x' for ch in lines[0])

def test_x_count(run, x):
    S = x.rstrip('\n')
    out = run(x)
    assert out.count('x') == len(S)

def test_no_lowercase(run, x):
    out = run(x)
    for ch in out:
        if ch != 'x' and ch != '\n':
            assert not ('a' <= ch <= 'z')

def test_stripped_length(run, x):
    S = x.rstrip('\n')
    out = run(x)
    out_line = out.rstrip('\n')
    assert len(out_line) == len(S)

def test_nonempty(run, x):
    out = run(x)
    assert out != ''

def test_no_original_chars(run, x):
    S = x.rstrip('\n')
    out = run(x)
    out_line = out.rstrip('\n')
    for c in S:
        if c != 'x':
            assert c not in out_line

