def test_all_equal(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    try:
        n = int(lines[0])
        vals = list(map(int, lines[1].split()))
        if len(vals) == n and all(v == vals[0] for v in vals) and n >= 3:
            out = run(x)
            assert out == 'Yes\n', f'All equal sides must output Yes\\n, got {repr(out)}'
    except ValueError:
        pass

def test_max_equals_sum_others(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    try:
        n = int(lines[0])
        vals = list(map(int, lines[1].split()))
        if len(vals) != n:
            return
        total = sum(vals)
        mx = max(vals)
        if 2 * mx == total:
