def test_triangle_inequality(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    try:
        n = int(lines[0])
        if n != 3:
            return
        vals = list(map(int, lines[1].split()))
        if len(vals) != 3:
            return
        a, b, c = sorted(vals)
        if a + b > c:
            out = run(x)
            assert out == 'Yes\n', f'For triangle with a+b>c, output must be Yes\\n, got {repr(out)}'
        else:
            out = run(x)
            assert out == 'No\n', f'For triangle with a+b≤c, output must be No\\n, got {repr(out)}'
    except ValueError:
        pass

def test_no_extra_whitespace(run, x):
    out = run(x)
    assert out in {'Yes\n', 'No\n'}, f'Output must be exactly Yes\\n or No\\n, got {repr(out)}'

def test_full_verification(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    try:
        n = int(lines[0])
        vals = list(map(int, lines[1].split()))
        if len(vals) != n:
            return
        total = sum(vals)
        mx = max(vals)
        expected = 'Yes\n' if mx < total - mx else 'No\n'
        out = run(x)
        assert out == expected, f'Expected {repr(expected)} from theorem, got {repr(out)}'
    except ValueError:
        pass

