tests_src:
def test_format(run, x):
    out = run(x)
    assert out in ('Yes\n', 'No\n'), "Output must be exactly 'Yes\\n' or 'No\\n'"


def test_yes_implies_D_le_TS(run, x):
    out = run(x)
    if out == 'Yes\n':
        D, T, S = map(int, x.split())
        assert D <= T * S, "If output is Yes, D must be ≤ T*S"


def test_no_implies_D_gt_TS(run, x):
    out = run(x)
    if out == 'No\n':
        D, T, S = map(int, x.split())
        assert D > T * S, "If output is No, D must be > T*S"


def test_D_le_TS_implies_yes(run, x):
    D, T, S = map(int, x.split())
    if D <= T * S:
        out = run(x)
        assert out == 'Yes\n', "If D ≤ T*S, output must be Yes"


def test_D_gt_TS_implies_no(run, x):
    D, T, S = map(int, x.split())
    if D > T * S:
        out = run(x)
        assert out == 'No\n', "If D > T*S, output must be No"


def test_divisible_case(run, x):
    D, T, S = map(int, x.split())
    if D % S == 0:
        out = run(x)
        expected = 'Yes\n' if D // S <= T else 'No\n'
        assert out == expected, f"For D divisible by S, expected {expected.strip()}"


def test_ceil_condition(run, x):
    D, T, S = map(int, x.split())
    travel_time_ceil = (D + S - 1) // S  # ceil(D/S)
    out = run(x)
    if out == 'Yes\n':
        assert travel_time_ceil <= T, "If Yes, ceil(D/S) must be ≤ T"
    elif out == 'No\n':
        assert travel_time_ceil > T, "If No, ceil(D/S) must be > T"
    else:
        assert False, "Output must be Yes or No"


def test_no_extra_whitespace(run, x):
    out = run(x)
    stripped = out.rstrip('\n')
    assert stripped in ('Yes', 'No'), "Stripped output must be exactly Yes or No"
    assert out == stripped + '\n', "Output must end with a newline and have no extra whitespace"


def test_boundary_exact(run, x):
    D, T, S = map(int, x.split())
    if D == T * S:
        out = run(x)
        assert out == 'Yes\n', "When D exactly equals T*S, output must be Yes"


def test_boundary_one_more(run, x):
    D, T, S = map(int, x.split())
    if D == T * S + 1:
        out = run(x)
        assert out == 'No\n', "When D = T*S + 1, output must be No"

