def test_exhaustive(run, x):
    import itertools
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = [list(line.strip()) for line in lines[1:]]
    # Exhaustive enumeration is feasible only for small grids
    total_cells = H * W
    if total_cells > 16:  # 2^(H+W) grows fast, but enumeration of subsets is still 2^(H+W). For H=6,W=6, 2^12=4096, which is fine. We guard on total choices.
        max_subsets = 2 ** (H + W)
        if max_subsets > 1000000:  # If too many subsets, skip exhaustive check to keep test fast.
            return
    all_rows = range(H)
    all_cols = range(W)
    count = 0
    for rmask in range(1 << H):
