def test_bruteforce(run, x):
    # parse input
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    # Constraints guarantee H,W ≤ 6, so 2**(H+W) ≤ 4096, brute-force is fine
    grid = lines[1:1+H]
    # enumerate all subsets
    total = 0
    for rmask in range(1 << H):
        for cmask in range(1 << W):
            black = 0
            for i in range(H):
                if not (rmask >> i) & 1:
                    continue  # row not chosen
                row = grid[i]
                for j in range(W):
                    if not (cmask >> j) & 1:
                        continue  # column not chosen
                    if row[j] == '#':
                        black += 1
            if black == K:
                total += 1
    # compare with program output
    out = run(x).strip()
    assert out.isdigit() and int(out) == total


def test_bounds(run, x):
    lines = x.strip().split('\n')
    H, W, _ = map(int, lines[0].split())
    total_choices = 2 ** (H + W)
    out = run(x).strip()
    val = int(out)
    assert 0 <= val <= total_choices


def test_k_gt_black(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = lines[1:1+H]
    B = sum(row.count('#') for row in grid)
    if K > B:
        out = run(x).strip()
        assert out == '0'


def test_k_eq_black(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = lines[1:1+H]
    B = sum(row.count('#') for row in grid)
    if K == B:
        # count rows with no black
        all_white_rows = sum(1 for row in grid if row.count('#') == 0)
        # count columns with no black
        all_white_cols = 0
        for j in range(W):
            if all(grid[i][j] == '.' for i in range(H)):
                all_white_cols += 1
        expected = 2 ** all_white_rows * 2 ** all_white_cols
        out = run(x).strip()
        assert out.isdigit() and int(out) == expected


def test_no_black(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = lines[1:1+H]
    B = sum(row.count('#') for row in grid)
    if B == 0:
        out = run(x).strip()
        if K == 0:
            assert int(out) == 2 ** (H + W)
        else:
            assert out == '0'


def test_all_black(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = lines[1:1+H]
    if all(c == '#' for row in grid for c in row):
        from math import comb
        total = 0
        for r in range(H+1):
            for c in range(W+1):
                if r * c == K:
                    total += comb(H, r) * comb(W, c)
        out = run(x).strip()
        assert out.isdigit() and int(out) == total


def test_k_zero_at_least_one(run, x):
    lines = x.strip().split('\n')
    _, _, K = map(int, lines[0].split())
    if K == 0:
        out = run(x).strip()
        val = int(out)
        assert val >= 1  # choosing all rows and all columns always gives 0 black squares


def test_one_black(run, x):
    lines = x.strip().split('\n')
    H, W, K = map(int, lines[0].split())
    grid = lines[1:1+H]
    B = sum(row.count('#') for row in grid)
    if B == 1:
        # locate the black cell
        for i in range(H):
            for j in range(W):
                if grid[i][j] == '#':
                    r, c = i, j
                    break
        if K == 1:
            expected = 2 ** (H - 1) * 2 ** (W - 1)
        elif K == 0:
            expected = 2 ** (H + W) - 2 ** (H - 1) * 2 ** (W - 1)
        else:
            expected = 0
        out = run(x).strip()
        assert out.isdigit() and int(out) == expected


def test_valid_integer(run, x):
    out = run(x).strip()
    # must be digits, no leading zeros unless it's '0'
    assert out.isdigit()
    if out != '0':
        assert out[0] != '0'


def test_format(run, x):
    out = run(x).strip()
    # ensure it's exactly the string representation of the integer
    assert out == str(int(out))

