def test_brute_force(run, x):
    # Only compute brute-force for lengths ≤10 (the constraint).
    output = run(x)
    S = x.strip()
    if 4 <= len(S) <= 10:
        conditions_hold = (
            S[0] == 'A' and
            1 <= S[2:-1].count('C') <= 1 and
            all(c.islower() for c in S[1:] if c != 'C') and
            S[2:-1].count('C') == 1
        )
        expected = 'AC\n' if conditions_hold else 'WA\n'
        assert output == expected

def test_output_format(run, x):
    output = run(x)
    assert output in ('AC\n', 'WA\n')

def test_first_letter(run, x):
    output = run(x)
    if output == 'AC\n':
        S = x.strip()
        assert len(S) >= 1 and S[0] == 'A'

def test_one_C_in_range(run, x):
    output = run(x)
    if output == 'AC\n':
        S = x.strip()
        # positions 2 to len(S)-2 inclusive (0-indexed)
        substr = S[2:-1]
        assert substr.count('C') == 1

def test_two_uppers(run, x):
    output = run(x)
    if output == 'AC\n':
        S = x.strip()
        upper_count = sum(1 for c in S if c.isupper())
        assert upper_count == 2

def test_uppercase_positions(run, x):
    output = run(x)
    if output == 'AC\n':
        S = x.strip()
        upper_indices = [i for i, c in enumerate(S) if c.isupper()]
        assert len(upper_indices) == 2
        assert upper_indices[0] == 0
        assert S[upper_indices[0]] == 'A'
        c_idx = upper_indices[1]
        assert 2 <= c_idx <= len(S)-2
        assert S[c_idx] == 'C'

def test_at_least_one_lower(run, x):
    output = run(x)
    if output == 'AC\n':
        S = x.strip()
        assert any(c.islower() for c in S)

def test_length_requirement(run, x):
    output = run(x)
    if output == 'AC\n':
        S = x.strip()
        assert 4 <= len(S)

def test_C_not_second(run, x):
    output = run(x)
    if output == 'AC\n':
        S = x.strip()
        assert len(S) >= 2 and S[1] != 'C'

def test_C_not_last(run, x):
    output = run(x)
    if output == 'AC\n':
        S = x.strip()
        assert S[-1] != 'C'

