def test_full_check(run, x):
    # Compute whether S satisfies all conditions
    S = x.strip()
    cond1 = (len(S) >= 4 and S[0] == 'A')
    if not cond1:
        expected = 'WA\n'
    else:
        sub = S[2:-1]  # third char to second last inclusive
        c_count = sum(1 for ch in sub if ch == 'C')
        cond2 = (c_count == 1)
        if not cond2:
            expected = 'WA\n'
        else:
            # locate that C
            c_pos = next(i for i, ch in enumerate(sub) if ch == 'C')
            # check all others lowercase
            others = S[1:2] + sub[:c_pos] + sub[c_pos+1:] + S[-1:] if len(S) > 2 else ''
            cond3 = all(ch.islower() for ch in others)
            expected = 'AC\n' if cond3 else 'WA\n'
    assert run(x) == expected

def test_output_format(run, x):
    out = run(x)
    assert out in ('AC\n', 'WA\n')

def test_ac_first_a(run, x):
    out = run(x)
    if out == 'AC\n':
        S = x.strip()
        assert len(S) >= 1 and S[0] == 'A'

def test_ac_one_c_in_range(run, x):
    out = run(x)
    if out == 'AC\n':
        S = x.strip()
        sub = S[2:-1]  # third char to second last inclusive
        c_count = sum(1 for ch in sub if ch == 'C')
        assert c_count == 1

def test_ac_exactly_two_uppercase(run, x):
    out = run(x)
    if out == 'AC\n':
        S = x.strip()
        upper = sum(1 for ch in S if ch.isupper())
        assert upper == 2

def test_ac_others_lowercase(run, x):
    out = run(x)
    if out == 'AC\n':
        S = x.strip()
        # locate the C in range
        sub = S[2:-1]
        c_pos = next(i for i, ch in enumerate(sub) if ch == 'C')
        # positions: first char (index 0) and the C at index (2 + c_pos) in S
        skip = {0, 2 + c_pos}
        for i, ch in enumerate(S):
            if i not in skip:
                assert ch.islower()

def test_wa_implies_not_all_conditions(run, x):
    out = run(x)
    if out == 'WA\n':
        S = x.strip()
        cond1 = (len(S) >= 4 and S[0] == 'A')
        if not cond1:
            return  # already not all conditions
        sub = S[2:-1]
        c_count = sum(1 for ch in sub if ch == 'C')
        cond2 = (c_count == 1)
        if not cond2:
            return
