def test_output_format(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n'), f'Output must be exactly YES\\n or NO\\n, got {repr(out)}'

def test_sorted_input(run, x):
    # Parse cautiously; only assert if input is a valid sorted permutation.
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    try:
        N = int(lines[0].strip())
        vals = list(map(int, lines[1].split()))
    except:
        return
    if len(vals) != N:
        return
    if sorted(vals) != list(range(1, N+1)):
        return  # Not a valid permutation
    if all(vals[i] == i+1 for i in range(N)):
        out = run(x)
        assert out == 'YES\n', f'Sorted permutation must output YES\\n, got {repr(out)}'

def test_two_mismatches(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    try:
        N = int(lines[0].strip())
        vals = list(map(int, lines[1].split()))
    except:
        return
    if len(vals) != N:
        return
    if sorted(vals) != list(range(1, N+1)):
        return
    mismatches = sum(1 for i in range(N) if vals[i] != i+1)
    if mismatches == 2:
        out = run(x)
        assert out == 'YES\n', f'Exactly two mismatches must output YES\\n, got {repr(out)}'

def test_more_than_two_mismatches(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    try:
        N = int(lines[0].strip())
        vals = list(map(int, lines[1].split()))
    except:
        return
    if len(vals) != N:
        return
    if sorted(vals) != list(range(1, N+1)):
        return
    mismatches = sum(1 for i in range(N) if vals[i] != i+1)
    if mismatches > 2:
        out = run(x)
        assert out == 'NO\n', f'More than two mismatches must output NO\\n, got {repr(out)}'

def test_bruteforce(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    try:
        N = int(lines[0].strip())
        vals = list(map(int, lines[1].split()))
    except:
        return
    if len(vals) != N:
        return
    if sorted(vals) != list(range(1, N+1)):
        return
    # Only brute force for small N (N<=10) to keep test fast.
    if N > 10:
        return
    target = list(range(1, N+1))
    possible = False
    # Check no swap
    if vals == target:
        possible = True
    # Check all swaps
    for i in range(N):
        for j in range(i+1, N):
            v = vals.copy()
            v[i], v[j] = v[j], v[i]
            if v == target:
                possible = True
    expected = 'YES\n' if possible else 'NO\n'
    out = run(x)
    assert out == expected, f'Brute force says {expected.strip()} for this permutation, got {repr(out)}'

