{
  "rationale": "The tests verify output format, range, and logical consequences of the problem: if the interval length is at least 2019 or contains a multiple of 2019, the answer must be 0. For small intervals we compute the exact answer by brute‑force. Additional checks ensure consistency: consecutive inputs, achievability, and the sample. The weakest test is test_upper_bound_consecutive_small, which could be dropped first because it only provides an upper bound already implied by the brute‑force test.",
  "plan": [
    {
      "name": "test_format",
      "intent": "The output must be a single integer followed by a newline. Parse the output as an integer; if it fails, the answer is malformed."
    },
    {
      "name": "test_range",
      "intent": "The integer must be between 0 and 2018 inclusive, because it is a remainder modulo 2019. An outside value is impossible."
    },
    {
      "name": "test_large_interval",
      "intent": "If R - L >= 2019, then the interval contains a multiple of 2019, so the minimum possible value is 0. Assert that the parsed output equals 0."
    },
    {
      "name": "test_contains_multiple",
      "intent": "If there exists any integer k such that 2019*k is between L and R inclusive, then choosing that multiple and any other number gives product 0 mod 2019. Therefore the output must be 0."
    },
    {
      "name": "test_small_interval_bruteforce",
      "intent": "If R - L < 2019, the number of pairs is at most a few million. Compute the minimum of (i*j) mod 2019 over all L <= i < j <= R by brute‑force and compare with the output. This directly verifies correctness for all small intervals."
    },
    {
      "name": "test_consecutive",
      "intent": "If R == L + 1, the only pair is (L, R). Hence the output must equal (L * R) mod 2019. Check this equality."
    },
    {
      "name": "test_nonzero_no_multiple",
      "intent": "If the output is not 0, then there cannot be a multiple of 2019 in the interval, because that would force the answer to be 0. Verify that ceil(L/2019)*2019 > R."
    },
    {
      "name": "test_upper_bound_consecutive_small",
      "intent": "For intervals with R - L <= 1000, compute the minimum of (i*(i+1)) mod 2019 over i = L .. R-1. The true minimum over all pairs cannot exceed this value, so assert that the output is less than or equal to this computed minimum."
    },
    {
      "name": "test_achievable_small",
      "intent": "For intervals with R - L <= 5000, verify that the output is achievable: there exists at least one pair (i, j) with L <= i < j <= R such that (i*j) mod 2019 equals the output. This ensures the answer is not invented."
    },
    {
      "name": "test_sample",
      "intent": "If the input string is exactly '2020 2040\\n', the output must be '2\\n', as given in the problem statement. This checks the provided example."
    }
  ]
}

