def test_format(run, x):
    out = run(x)
    assert out.endswith('\n'), 'output must end with newline'
    num_str = out.rstrip('\n')
    assert num_str.isdigit() or (num_str[0] == '-' and num_str[1:].isdigit()), 'output must be an integer'
    # we parse later for other tests, no need to store here

def test_range(run, x):
    out = run(x)
    num = int(out.strip())
    assert 0 <= num <= 2018, 'remainder modulo 2019 must be in [0,2018]'

def test_large_interval(run, x):
    L, R = map(int, x.strip().split())
    if R - L >= 2019:
        out = run(x)
        ans = int(out.strip())
        assert ans == 0, f'interval length >=2019 => answer must be 0, got {ans}'

def test_contains_multiple(run, x):
    L, R = map(int, x.strip().split())
    # smallest multiple of 2019 >= L
    first_mult = ((L + 2018) // 2019) * 2019
    if first_mult <= R:
        out = run(x)
        ans = int(out.strip())
        assert ans == 0, f'interval contains a multiple of 2019 => answer must be 0, got {ans}'

def test_small_interval_bruteforce(run, x):
    L, R = map(int, x.strip().split())
    if R - L < 2019:
        out = run(x)
        ans = int(out.strip())
        # brute‑force the minimum
        best = 2019
        for i in range(L, R):
            for j in range(i + 1, R + 1):
                val = (i * j) % 2019
                if val < best:
                    best = val
        assert ans == best, f'brute‑force gives {best}, got {ans}'

def test_consecutive(run, x):
    L, R = map(int, x.strip().split())
    if R == L + 1:
        out = run(x)
        ans = int(out.strip())
        expected = (L * R) % 2019
        assert ans == expected, f'only pair is ({L},{R}) => answer must be {expected}, got {ans}'

def test_nonzero_no_multiple(run, x):
    L, R = map(int, x.strip().split())
    out = run(x)
    ans = int(out.strip())
    if ans != 0:
        # then there must be no multiple of 2019 in [L,R]
        first_mult = ((L + 2018) // 2019) * 2019
        assert first_mult > R, f'output is {ans} but interval contains a multiple of 2019'

def test_upper_bound_consecutive_small(run, x):
    L, R = map(int, x.strip().split())
    if R - L <= 1000:
        out = run(x)
        ans = int(out.strip())
        # compute min of consecutive products
        bound = 2019
        for i in range(L, R):
            val = (i * (i + 1)) % 2019
            if val < bound:
                bound = val
        assert ans <= bound, f'answer {ans} cannot exceed min of consecutive products {bound}'

def test_achievable_small(run, x):
    L, R = map(int, x.strip().split())
    if R - L <= 5000:
        out = run(x)
        ans = int(out.strip())
        # enumerate all pairs to see if ans appears
        found = False
        for i in range(L, R):
            for j in range(i + 1, R + 1):
                if (i * j) % 2019 == ans:
                    found = True
                    break
            if found:
                break
        assert found, f'answer {ans} is not achievable by any pair in the interval'

def test_sample(run, x):
    if x == '2020 2040\n':
        out = run(x)
        assert out == '2\n', f'sample input must output 2, got {out!r}'

