def test_format(run, x):
    out = run(x)
    assert out in ('YES\n', 'NO\n'), f'Output must be exactly YES\\n or NO\\n, got {repr(out)}'

def test_sorted(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    p = list(map(int, lines[1].split()))
    if all(p[i] == i+1 for i in range(N)):
        out = run(x)
        assert out == 'YES\n', f'Sorted permutation must output YES, got {repr(out)}'

def test_two_misplaced(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    p = list(map(int, lines[1].split()))
    misplaced = [i for i in range(N) if p[i] != i+1]
    if len(misplaced) == 2:
        # spec says we can swap the two misplaced positions to sort
        # but we must verify by brute-force that at least one swap works
        # because the test plan says output must be YES.
        # Use brute-force over all swaps (including no swap) to check.
        sorted_list = list(range(1, N+1))
        ok = False
        for i in range(N):
            for j in range(i+1, N):
                q = p.copy()
                q[i], q[j] = q[j], q[i]
                if q == sorted_list:
                    ok = True
                    break
            if ok:
                break
        if p == sorted_list:
            ok = True
        if ok:
            out = run(x)
            assert out == 'YES\n', f'Two misplaced indices must output YES, got {repr(out)}'

def test_many_misplaced(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N > 10:  # too many to brute-force cheaply; skip heavy check
        return
    p = list(map(int, lines[1].split()))
    misplaced = [i for i in range(N) if p[i] != i+1]
    if len(misplaced) > 2:
        # Brute-force check: can any single swap sort it?
        sorted_list = list(range(1, N+1))
        possible = False
        for i in range(N):
            for j in range(i+1, N):
                q = p.copy()
                q[i], q[j] = q[j], q[i]
                if q == sorted_list:
                    possible = True
                    break
            if possible:
                break
        if p == sorted_list:
            possible = True
        if not possible:
            out = run(x)
            assert out == 'NO\n', f'More than two misplaced and no swap sorts -> must output NO, got {repr(out)}'

def test_cycle_condition(run, x):
    # The spec does not mention cycles, so we cannot assert anything about cycles.
    # Weakening: just check output is valid.
    out = run(x)
    assert out in ('YES\n', 'NO\n'), f'Invalid output'

def test_brute_force(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    p = list(map(int, lines[1].split()))
    sorted_list = list(range(1, N+1))
    possible = False
    for i in range(N):
        for j in range(i+1, N):
            q = p.copy()
            q[i], q[j] = q[j], q[i]
            if q == sorted_list:
                possible = True
                break
        if possible:
            break
    if p == sorted_list:
        possible = True
    out = run(x)
    if possible:
        assert out == 'YES\n', f'Brute-force says YES, got {repr(out)}'
    else:
        assert out == 'NO\n', f'Brute-force says NO, got {repr(out)}'

def test_n2(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N == 2:
        # For N=2, any permutation is sortable by at most one swap.
        out = run(x)
        assert out == 'YES\n', f'N=2 must output YES, got {repr(out)}'

def test_n3(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N == 3:
        p = list(map(int, lines[1].split()))
        sorted_list = list(range(1, N+1))
        possible = False
        for i in range(N):
            for j in range(i+1, N):
                q = p.copy()
                q[i], q[j] = q[j], q[i]
                if q == sorted_list:
                    possible = True
                    break
            if possible:
                break
        if p == sorted_list:
            possible = True
        out = run(x)
        if possible:
            assert out == 'YES\n', f'N=3 brute-force says YES, got {repr(out)}'
        else:
            assert out == 'NO\n', f'N=3 brute-force says NO, got {repr(out)}'

def test_no_swap_if_no(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    p = list(map(int, lines[1].split()))
    sorted_list = list(range(1, N+1))
    out = run(x)
    if out == 'NO\n':
        possible = False
        for i in range(N):
            for j in range(i+1, N):
                q = p.copy()
                q[i], q[j] = q[j], q[i]
                if q == sorted_list:
                    possible = True
                    break
            if possible:
                break
        if p == sorted_list:
            possible = True
        assert not possible, f'Output is NO but a swap sorts the permutation'

def test_yes_if_swap(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    p = list(map(int, lines[1].split()))
    sorted_list = list(range(1, N+1))
    out = run(x)
    if out == 'YES\n':
        if p == sorted_list:
            return
        possible = False
        for i in range(N):
            for j in range(i+1, N):
                q = p.copy()
                q[i], q[j] = q[j], q[i]
                if q == sorted_list:
                    possible = True
                    break
            if possible:
                break
        assert possible, f'Output is YES but no swap sorts the permutation'

