def test_valid_integer(run, x):
    output = run(x)
    try:
        h = int(output.strip())
        assert h >= 0
    except:
        assert False, "Output must be a non‑negative integer"


def test_multiple_of_5(run, x):
    output = run(x)
    h = int(output.strip())
    assert h % 5 == 0, "Happiness points must be a multiple of 5"


def test_500yen_coins_count(run, x):
    X = int(x.strip())
    output = run(x)
    h = int(output.strip())
    if X >= 500:
        assert h // 1000 == X // 500, "Number of 500‑yen coins must be floor(X/500)"
    else:
        # When X < 500, no 500‑yen coins can be used, so happiness from 500‑yen coins must be 0
        assert h // 1000 == 0, "No 500‑yen coins possible when X < 500"


def test_5yen_coins_feasible(run, x):
    X = int(x.strip())
    output = run(x)
    h = int(output.strip())
    coins500 = h // 1000
    coins5 = (h % 1000) // 5
    max_coins5 = (X - 500 * coins500) // 5 if X >= 500 * coins500 else 0
    assert coins5 <= max_coins5, "Too many 5‑yen coins for the remaining money"


def test_leftover_money(run, x):
    X = int(x.strip())
    output = run(x)
    h = int(output.strip())
    coins500 = h // 1000
    coins5 = (h % 1000) // 5
    leftover = X - 500 * coins500 - 5 * coins5
    assert leftover == X % 5, f"Leftover money must equal X mod 5, got {leftover}"


def test_multiple_of_500(run, x):
    X = int(x.strip())
    if X % 500 == 0:
        output = run(x)
        h = int(output.strip())
        expected = 1000 * (X // 500)
        assert h == expected, f"For X divisible by 500, happiness must be {expected}"


def test_small_less_than_5(run, x):
    X = int(x.strip())
    if X < 5:
        output = run(x)
        h = int(output.strip())
        assert h == 0, "For X < 5, happiness must be 0"


def test_brute_force_small(run, x):
    X = int(x.strip())
    if X <= 2000:
        output = run(x)
        h = int(output.strip())
        best = 0
        for c500 in range(X // 500 + 1):
            for c5 in range((X - 500 * c500) // 5 + 1):
                happiness = 1000 * c500 + 5 * c5
                if happiness > best:
                    best = happiness
        assert h == best, f"For X={X}, optimal happiness is {best}"


def test_example_zero(run, x):
    if x == "0\n":
        output = run(x)
        assert output.strip() == "0", "For input '0', output must be exactly '0'"


def test_upper_bound_2x(run, x):
    X = int(x.strip())
    output = run(x)
    h = int(output.strip())
    assert h <= 2 * X, f"Happiness cannot exceed 2*X (={2*X})"

