def test_correctness(run, x):
    out = run(x)
    # Compute if any two consecutive digits are equal
    has_pair = any(x[i] == x[i+1] for i in range(3))
    expected = 'Bad\n' if has_pair else 'Good\n'
    assert out == expected, f'expected {expected!r}, got {out!r}'

def test_output_format(run, x):
    out = run(x)
    assert out in ('Bad\n', 'Good\n'), f'output must be exactly "Bad\\n" or "Good\\n", got {out!r}'

def test_bad_implies_pair(run, x):
    out = run(x)
    if out == 'Bad\n':
        has_pair = any(x[i] == x[i+1] for i in range(3))
        assert has_pair, f'output is Bad but no consecutive equal digits found in {x}'

def test_good_implies_no_pair(run, x):
    out = run(x)
    if out == 'Good\n':
        all_different = all(x[i] != x[i+1] for i in range(3))
        assert all_different, f'output is Good but there is a consecutive equal pair in {x}'

def test_stripped_output(run, x):
