def test_n1(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    if n == 1:
        out = run(x)
        val = int(out.strip())
        assert val == 0, f"n=1 must output 0, got {val}"

def test_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False, "Output must be a valid integer"

def test_nonnegative(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 0, f"Cost cannot be negative, got {val}"

def test_upper_bound_star(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    out = run(x)
    val = int(out.strip())
    if n == 0:
        return
    min_a = min(a)
    upper = sum(a) + (n - 2) * min_a
    assert val <= upper, f"Cost {val} exceeds star bound {upper}"

def test_lower_bound_min_edge(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    out = run(x)
    val = int(out.strip())
    if n <= 1:
        return
    min_regular = float('inf')
    for i in range(n):
        for j in range(i+1, n):
            cost = a[i] + a[j]
            if cost < min_regular:
                min_regular = cost
    min_special = float('inf')
    for k in range(2, 2 + m):
        if k >= len(lines):
            break
        w = int(lines[k].split()[2])
        if w < min_special:
            min_special = w
    min_edge = min(min_regular, min_special)
    lower = (n - 1) * min_edge
    assert val >= lower, f"Cost {val} below lower bound {lower}"

def test_m0_exact(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if m != 0:
        return
    a = list(map(int, lines[1].split()))
    out = run(x)
    val = int(out.strip())
    min_a = min(a)
    expected = sum(a) + (n - 2) * min_a
    assert val == expected, f"m=0: expected {expected}, got {val}"

def test_small_brute(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n > 8:
        return
    a = list(map(int, lines[1].split()))
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            edges.append((a[i] + a[j], i, j))
    for k in range(2, 2 + m):
        if k >= len(lines):
            break
        x_i, y_i, w = map(int, lines[k].split())
        edges.append((w, x_i-1, y_i-1))
    # Kruskal
    parent = list(range(n))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    def union(u, v):
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[rv] = ru
            return True
        return False
    edges.sort()
    total = 0
    used = 0
    for cost, u, v in edges:
        if union(u, v):
            total += cost
            used += 1
            if used == n - 1:
                break
    out = run(x)
    val = int(out.strip())
    assert val == total, f"Brute force expects {total}, got {val}"

def test_lower_bound_sum_incident(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    out = run(x)
    val = int(out.strip())
    if n <= 1:
        return
    cheap = [float('inf')] * n
    # regular edges
    for i in range(n):
        for j in range(n):
            if i != j:
                cost = a[i] + a[j]
                if cost < cheap[i]:
                    cheap[i] = cost
    # special offers
    for k in range(2, 2 + m):
        if k >= len(lines):
            break
        x_i, y_i, w = map(int, lines[k].split())
        i, j = x_i-1, y_i-1
        if w < cheap[i]:
            cheap[i] = w
        if w < cheap[j]:
            cheap[j] = w
    total_cheap = sum(cheap)
    lower = (total_cheap + 1) // 2  # ceil
    assert val >= lower, f"Cost {val} below half sum of cheapest incident {lower}"

def test_n2(run, x):
    lines = x.strip().split('\n')
    n, m = map(int, lines[0].split())
    if n != 2:
        return
    a = list(map(int, lines[1].split()))
    regular = a[0] + a[1]
    best = regular
    for k in range(2, 2 + m):
        if k >= len(lines):
            break
        x_i, y_i, w = map(int, lines[k].split())
        if (x_i == 1 and y_i == 2) or (x_i == 2 and y_i == 1):
            if w < best:
                best = w
    out = run(x)
    val = int(out.strip())
    assert val == best, f"n=2: expected {best}, got {val}"

def test_format(run, x):
    out = run(x)
    stripped = out.strip()
    try:
        int(stripped)
    except ValueError:
        assert False, "Output must be an integer"
    assert out == stripped + '\n', "Output must be exactly integer followed by newline"

