def test_parse(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit(), 'Output must be digits after stripping whitespace'
    m = int(s)  # must parse

def test_range(run, x):
    out = run(x)
    m = int(out.strip())
    assert 2 <= m <= 1000000, 'm must satisfy 2 ≤ m ≤ 1000000'

def test_known(run, x):
    s = int(x.strip())
    out = run(x).strip()
    if s == 1:
        assert out == '4', 'For s=1, answer must be 4'
    elif s == 2:
        assert out == '4', 'For s=2, answer must be 4'
    elif s == 8:
        assert out == '5', 'For s=8, answer must be 5'

def test_sequence_values(run, x):
    s = int(x.strip())
    out = run(x).strip()
    m = int(out)
    seq = []
    cur = s
    for i in range(m):
        seq.append(cur)
        if cur % 2 == 0:
            cur = cur // 2
        else:
            cur = 3 * cur + 1
    # last term a_m
    seq.append(cur)
    # check all terms ≤ 1000000 and integer
    for val in seq:
        assert isinstance(val, int)
        assert 1 <= val <= 1000000, 'Sequence value out of promised bound'

def test_repeat(run, x):
    s = int(x.strip())
    out = run(x).strip()
    m = int(out)
    seq = []
    cur = s
    for i in range(m):
        seq.append(cur)
        if cur % 2 == 0:
            cur = cur // 2
        else:
            cur = 3 * cur + 1
    a_m = cur
    assert a_m in seq, f'a_{m} must appear earlier in sequence'

def test_no_earlier_repeat(run, x):
    s = int(x.strip())
    out = run(x).strip()
    m = int(out)
    seq = []
    cur = s
    for i in range(m - 1):  # only up to a_{m-1}
        if cur in seq:
            assert False, f'Repeat found before index {m}'
        seq.append(cur)
        if cur % 2 == 0:
            cur = cur // 2
        else:
            cur = 3 * cur + 1
    # after loop, cur is a_m, not checked for earlier repeat here
    # just ensure no repeat in seq
    assert len(seq) == len(set(seq)), f'Terms a_1..a_{{m-1}} must be distinct'

def test_recurrence(run, x):
    s = int(x.strip())
    out = run(x).strip()
    m = int(out)
    seq = [s]
    cur = s
    for i in range(2, m + 1):
        if cur % 2 == 0:
            cur = cur // 2
        else:
            cur = 3 * cur + 1
        seq.append(cur)
    # verify recurrence for i >= 2
    for i in range(1, m):
        prev = seq[i-1]
        cur = seq[i]
        if prev % 2 == 0:
            expected = prev // 2
        else:
            expected = 3 * prev + 1
        assert cur == expected, f'Recurrence failed at i={i+1}'

def test_distinct_count(run, x):
    s = int(x.strip())
    out = run(x).strip()
    m = int(out)
    seq = []
    cur = s
    for i in range(m - 1):
        seq.append(cur)
        if cur % 2 == 0:
            cur = cur // 2
        else:
            cur = 3 * cur + 1
    assert len(set(seq)) == m - 1, f'First m-1 terms must be distinct'

def test_correct_answer(run, x):
    s = int(x.strip())
    # only check for small s to stay within time; s ≤ 20 is safe
    if s > 20:
        return
    seen = {}
    cur = s
    idx = 1
    while cur not in seen:
        seen[cur] = idx
        if cur % 2 == 0:
            cur = cur // 2
        else:
            cur = 3 * cur + 1
        idx += 1
    m0 = idx
    out = run(x).strip()
    m = int(out)
    assert m == m0, f'Output m={m} does not match computed m0={m0}'

def test_output_newline(run, x):
    out = run(x)
    assert out.endswith('\n'), 'Output must end with newline'

