tests_src:
def test_small_brute(run, x):
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n = n_m[0]
    if n > 6:
        return  # too big for brute force
    a = list(map(int, lines[1].split()))
    offers = {}
    for line in lines[2:]:
        if not line.strip():
            continue
        x, y, w = map(int, line.split())
        x -= 1
        y -= 1
        if (x, y) in offers:
            offers[(x, y)] = min(offers[(x, y)], w)
        else:
            offers[(x, y)] = w
        if (y, x) in offers:
            offers[(y, x)] = min(offers[(y, x)], w)
        else:
            offers[(y, x)] = w
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            cost = a[i] + a[j]
            if (i, j) in offers:
                cost = min(cost, offers[(i, j)])
            edges.append((cost, i, j))
    edges.sort()
    parent = list(range(n))
    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u
    mst_cost = 0
    components = n
    for cost, u, v in edges:
        ru = find(u)
        rv = find(v)
        if ru != rv:
            parent[rv] = ru
            mst_cost += cost
            components -= 1
            if components == 1:
                break
    output = run(x)
    assert int(output.strip()) == mst_cost

def test_no_offers(run, x):
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n, m = n_m
    if m != 0:
        return
    a = list(map(int, lines[1].split()))
    if n == 1:
        expected = 0
    else:
        min_a = min(a)
        expected = (n - 2) * min_a + sum(a)
    output = run(x)
    assert int(output.strip()) == expected

def test_output_format(run, x):
    out = run(x)
    s = out.strip()
    assert s.isdigit() or (s[0]=='-' and s[1:].isdigit()), "not an integer"
    val = int(s)
    assert 0 <= val <= 10**18, "out of range"
    assert out == str(val) + '\n' or out == str(val), "extra whitespace"

def test_upper_bound(run, x):
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n = n_m[0]
    a = list(map(int, lines[1].split()))
    if n == 1:
        upper = 0
    else:
        min_a = min(a)
        upper = (n - 2) * min_a + sum(a)
    output = run(x)
    val = int(output.strip())
    assert val <= upper

def test_n2(run, x):
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n, m = n_m
    if n != 2:
        return
    a = list(map(int, lines[1].split()))
    best = a[0] + a[1]
    for line in lines[2:]:
        if not line.strip():
            continue
        x, y, w = map(int, line.split())
        if (x==1 and y==2) or (x==2 and y==1):
            if w < best:
                best = w
    output = run(x)
    assert int(output.strip()) == best

def test_n1(run, x):
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n = n_m[0]
    if n != 1:
        return
    output = run(x)
    assert output.strip() == '0'

def test_examples(run, x):
    examples = [
        ("3 2\n1 3 3\n2 3 5\n2 1 1\n", "5\n"),
        ("4 0\n1 3 3 7\n", "16\n"),
        ("5 4\n1 2 3 4 5\n1 2 8\n1 3 10\n1 4 7\n1 5 15\n", "18\n")
    ]
    for inp, exp in examples:
        if x == inp:
            out = run(x)
            assert out == exp
            return

def test_all_equal_no_offers(run, x):
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n, m = n_m
    if m != 0:
        return
    a = list(map(int, lines[1].split()))
    if len(set(a)) != 1:
        return
    val = a[0]
    expected = 2 * val * (n - 1)
    output = run(x)
    assert int(output.strip()) == expected

def test_lower_bound(run, x):
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n, m = n_m
    a = list(map(int, lines[1].split()))
    min_edge_cost = 10**18
    # normal edges
    for i in range(n):
        for j in range(i+1, n):
            cost = a[i] + a[j]
            if cost < min_edge_cost:
                min_edge_cost = cost
    # offers
    for line in lines[2:]:
        if not line.strip():
            continue
        x, y, w = map(int, line.split())
        if w < min_edge_cost:
            min_edge_cost = w
    # MST must have n-1 edges, each at least min_edge_cost
    lower = (n - 1) * min_edge_cost if n >= 2 else 0
    output = run(x)
    val = int(output.strip())
    assert val >= lower

def test_bounds_sandwich(run, x):
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n, m = n_m
    a = list(map(int, lines[1].split()))
    # lower bound as in test_lower_bound
    min_edge_cost = 10**18
    for i in range(n):
        for j in range(i+1, n):
            cost = a[i] + a[j]
            if cost < min_edge_cost:
                min_edge_cost = cost
    for line in lines[2:]:
        if not line.strip():
            continue
        x, y, w = map(int, line.split())
        if w < min_edge_cost:
            min_edge_cost = w
    lower = (n - 1) * min_edge_cost if n >= 2 else 0
    # upper bound as in test_upper_bound
    if n == 1:
        upper = 0
    else:
        min_a = min(a)
        upper = (n - 2) * min_a + sum(a)
    output = run(x)
    val = int(output.strip())
    assert lower <= val <= upper

