def test_correct_by_simulation(run, x):
    # Simulate sequence until a repeat, compute m, compare to output.
    s = int(x.strip())
    seen = {}
    seq = []
    cur = s
    i = 1
    # spec guarantees m ≤ 1000000, so we stop after that many terms.
    max_steps = 1000000
    while i <= max_steps:
        if cur in seen:
            m = i
            break
        seen[cur] = i
        seq.append(cur)
        if cur % 2 == 0:
            cur //= 2
        else:
            cur = 3 * cur + 1
        i += 1
    else:
        # should not happen per spec, but if it does we cannot compute m.
        return
    out = run(x)
    try:
        out_m = int(out.strip())
    except:
        assert False, 'output not an integer'
    assert out_m == m, f'simulation gives m={m}, output is {out_m}'


def test_has_repeat_at_m(run, x):
    out = run(x)
    try:
        m = int(out.strip())
    except:
        assert False, 'output not an integer'
    s = int(x.strip())
    # Simulate up to m-th term.
    seq = []
    cur = s
    for i in range(1, m+1):
        seq.append(cur)
        if cur % 2 == 0:
            cur //= 2
        else:
            cur = 3 * cur + 1
    # Check a_m equals some earlier a_n, n<m.
    a_m = seq[-1]
    found = False
    for n in range(m-1):
        if seq[n] == a_m:
            found = True
            break
    assert found, f'no earlier term equals a_{m}={a_m}'


def test_no_repeat_before_m(run, x):
    out = run(x)
    try:
        m = int(out.strip())
    except:
        assert False, 'output not an integer'
    if m <= 1:
        # m must be at least 2 by spec (since m>n≥1).
        assert False, f'm too small: {m}'
    s = int(x.strip())
    # Simulate up to m-1 terms.
    seen = set()
    cur = s
    for i in range(1, m):
        if cur in seen:
            assert False, f'early repeat at i={i}, term={cur}'
        seen.add(cur)
        if cur % 2 == 0:
            cur //= 2
        else:
            cur = 3 * cur + 1
    # Last term before m is not stored, but we only need distinctness up to m-1.


def test_bounds(run, x):
    out = run(x)
    try:
        m = int(out.strip())
    except:
        assert False, 'output not an integer'
    # m must be at least 2 because m>n≥1, but example 1 gives m=4.
    # spec says m ≤ 1000000.
    assert 2 <= m <= 1000000, f'm={m} outside [2,1000000]'


def test_example_1(run, x):
    if x == '1\n':
        out = run(x)
        assert out == '4\n', f'input 1 must output 4, got {out!r}'


def test_example_2(run, x):
    if x == '2\n':
        out = run(x)
        assert out == '4\n', f'input 2 must output 4, got {out!r}'


def test_example_8(run, x):
    if x == '8\n':
        out = run(x)
        assert out == '5\n', f'input 8 must output 5, got {out!r}'


