    out = run(x)
    lines = out.rstrip('\n').split('\n')
    assert len(lines) == 1, 'more than one line'
    line = lines[0]
    assert line.strip() == line, 'extra whitespace'
    try:
        m = int(line)
    except:
        assert False, 'output not an integer'
    # no extra characters
    assert str(m) == line, 'integer representation mismatch'


def test_sequence_values_bound(run, x):
    out = run(x)
    try:
        m = int(out.strip())
    except:
        assert False, 'output not an integer'
    s = int(x.strip())
    cur = s
    # simulate up to m, check each term ≤ 1e6 and positive.
    for i in range(1, m+1):
        assert 1 <= cur <= 1000000, f'term {i}={cur} out of bounds'
        if cur % 2 == 0:
            cur //= 2
        else:
            cur = 3 * cur + 1


