  "plan": [
    {
      "name": "test_valid_integer",
      "intent": "The output must be a single integer. Parse the output as an integer and assert it is nonnegative. If parsing fails or the integer is negative, the answer is wrong."
    },
    {
      "name": "test_upper_bound_components",
      "intent": "Compute the number of connected components in the graph (via BFS/DFS). Since each cycle is a connected component, the output must not exceed this count. Assert output ≤ number of connected components."
    },
    {
      "name": "test_upper_bound_edges",
      "intent": "Each cycle component contains at least three edges, and edges are distinct across cycles. Therefore output ≤ m // 3. Compute m from the input and assert this inequality."
    },
    {
      "name": "test_upper_bound_vertices",
      "intent": "Each cycle component contains at least three vertices. Therefore output ≤ n // 3. Compute n from the input and assert this inequality."
    },
    {
      "name": "test_small_n_no_cycles",
      "intent": "If n < 3, no cycle can exist because a cycle requires at least three vertices. In this case, the output must be 0. Check if n < 3 and assert output == 0."
    },
    {
      "name": "test_no_edges",
      "intent": "If m == 0, there are no edges, so there can be no cycles. The output must be 0. Check if m == 0 and assert output == 0."
    },
    {
      "name": "test_single_cycle",
      "intent": "If the graph is connected (number of connected components is 1), every vertex has degree exactly 2, and n ≥ 3, then the entire graph is a cycle. In this case, the output must be 1. Check these conditions and assert output == 1 when all hold."
    },
    {
      "name": "test_degree2_components_bound",
      "intent": "Let S be the set of vertices with degree exactly 2. Consider the subgraph induced by S (edges with both endpoints in S). Compute its connected components. Every cycle component is entirely within S and forms a connected component in this induced subgraph, so output ≤ number of components in induced subgraph of S. Assert this inequality."
    },
    {
      "name": "test_degree2_vertices_bound",
      "intent": "Let T be the number of vertices with degree exactly 2. Each cycle component contains at least three such vertices, so output ≤ T // 3. Compute T and assert this bound."
    },
    {
      "name": "test_exact_reference",
      "intent": "For small graphs (n ≤ 20), compute the correct answer directly: find all connected components; for each component, if every vertex in it has degree exactly 2 and the component size ≥ 3, count it as a cycle. Compare this count to the output. If they differ, the answer is wrong. (Since all given inputs have n ≤ 15, this test applies to all of them.)"
