def test_exact_line_count(run, x):
    t = int(x.strip().split()[0])
    out = run(x)
    lines = out.strip('\n').split('\n')
    assert len(lines) == t, f'Expected {t} lines, got {len(lines)}'

def test_output_integers(run, x):
    out = run(x)
    for line in out.strip('\n').split('\n'):
        line = line.strip()
        try:
            int(line)
        except ValueError:
            assert False, f'Line {repr(line)} is not an integer'

def test_range(run, x):
    t = int(x.strip().split()[0])
    out = run(x)
    lines = out.strip('\n').split('\n')
    for i in range(t):
        a, b = map(int, x.strip().split()[1+2*i:3+2*i])
        k = int(lines[i].strip())
        assert 0 <= k < b, f'k={k} not in [0, {b}-1]'

def test_divisibility(run, x):
    t = int(x.strip().split()[0])
    out = run(x)
    lines = out.strip('\n').split('\n')
    for i in range(t):
        a, b = map(int, x.strip().split()[1+2*i:3+2*i])
        k = int(lines[i].strip())
        assert (a + k) % b == 0, f'(a+k) % b = ({a}+{k}) % {b} != 0'

def test_zero_when_divisible(run, x):
    t = int(x.strip().split()[0])
    out = run(x)
    lines = out.strip('\n').split('\n')
    for i in range(t):
        a, b = map(int, x.strip().split()[1+2*i:3+2*i])
        k = int(lines[i].strip())
        if a % b == 0:
            assert k == 0, f'a={a} divisible by b={b}, but k={k} != 0'

def test_nonzero_when_not_divisible(run, x):
    t = int(x.strip().split()[0])
    out = run(x)
    lines = out.strip('\n').split('\n')
    for i in range(t):
        a, b = map(int, x.strip().split()[1+2*i:3+2*i])
        k = int(lines[i].strip())
        if a % b != 0:
            assert k != 0, f'a={a} not divisible by b={b}, but k=0'

def test_small_bruteforce(run, x):
    t = int(x.strip().split()[0])
    out = run(x)
    lines = out.strip('\n').split('\n')
    for i in range(t):
        a, b = map(int, x.strip().split()[1+2*i:3+2*i])
        if a <= 1000 and b <= 1000:
            k_correct = (b - a % b) % b
            k = int(lines[i].strip())
            assert k == k_correct, f'Small case: expected {k_correct}, got {k}'

def test_minimality_small_k(run, x):
    t = int(x.strip().split()[0])
    out = run(x)
    lines = out.strip('\n').split('\n')
    for i in range(t):
        a, b = map(int, x.strip().split()[1+2*i:3+2*i])
        k = int(lines[i].strip())
        if k <= 1000:
            for j in range(k):
                if (a + j) % b == 0:
                    assert False, f'j={j} < k={k} also makes a divisible'

def test_nonnegative(run, x):
    out = run(x)
    for line in out.strip('\n').split('\n'):
        k = int(line.strip())
        assert k >= 0, f'k={k} is negative'

def test_no_extra_whitespace(run, x):
    t = int(x.strip().split()[0])
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    # No empty lines
    for line in lines:
        assert line.strip() != '', 'Found empty line'
    # Exactly t lines
    assert len(lines) == t, f'Expected {t} lines, got {len(lines)}'

