def test_output_range_and_format(run, x):
    output = run(x)
    try:
        val = int(output.strip())
    except ValueError:
        assert False, "output not an integer"
    assert 0 <= val <= 3, f"output {val} outside [0,3]"


def test_no_R_gives_zero(run, x):
    s = x.strip()
    if 'R' not in s:
        assert run(x) == '0\n', "all S should output 0"


def test_RRR_gives_three(run, x):
    s = x.strip()
    if s == 'RRR':
        assert run(x) == '3\n', "RRR should output 3"


def test_RR_not_RRR_gives_two(run, x):
    s = x.strip()
    if 'RR' in s and s != 'RRR':
        assert run(x) == '2\n', "contains RR but not RRR should output 2"


def test_R_no_RR_gives_one(run, x):
    s = x.strip()
    if 'R' in s and 'RR' not in s:
        assert run(x) == '1\n', "has R but no RR should output 1"


def test_zero_implies_no_R(run, x):
    output = run(x)
    val = int(output.strip())
    s = x.strip()
    if val == 0:
        assert 'R' not in s, f"output 0 but input contains R"


def test_three_implies_RRR(run, x):
    output = run(x)
    val = int(output.strip())
    s = x.strip()
    if val == 3:
        assert s == 'RRR', f"output 3 but input is not RRR"


def test_two_implies_RR_not_RRR(run, x):
    output = run(x)
    val = int(output.strip())
    s = x.strip()
    if val == 2:
        assert 'RR' in s and s != 'RRR', f"output 2 but input does not contain RR or is RRR"


def test_one_implies_R_no_RR(run, x):
    output = run(x)
    val = int(output.strip())
    s = x.strip()
    if val == 1:
        assert 'R' in s and 'RR' not in s, f"output 1 but input lacks R or contains RR"


def test_direct_computation(run, x):
    s = x.strip()
    max_consecutive = 0
    current = 0
    for ch in s:
        if ch == 'R':
            current += 1
            max_consecutive = max(max_consecutive, current)
        else:
            current = 0
    output = run(x)
    val = int(output.strip())
    assert val == max_consecutive, f"output {val} does not match computed max {max_consecutive}"

