def test_exact(run, x):
    import itertools
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    if n > 10:
        return  # skip large enumeration
    books = []
    for i in range(1, n+1):
        t, a, b = map(int, lines[i].split())
        books.append((t, a, b))
    best = None
    for mask in range(1 << n):
        total = 0
        alice = 0
        bob = 0
        for i in range(n):
            if mask >> i & 1:
                total += books[i][0]
                alice += books[i][1]
                bob += books[i][2]
        if alice >= k and bob >= k:
            if best is None or total < best:
                best = total
    output = run(x).strip()
    if best is None:
        assert output == '-1'
    else:
        assert int(output) == best


def test_format(run, x):
    out = run(x)
    assert out.endswith('\n'), "output must end with newline"
    s = out.strip()
    if s == '-1':
        return
    # must be a positive integer
    assert s.isdigit(), "output must be digits only"
    assert int(s) > 0, "output must be positive if not -1"


def test_necessary_counts(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    alice_cnt = 0
    bob_cnt = 0
    for i in range(1, n+1):
        t, a, b = map(int, lines[i].split())
        if a == 1:
            alice_cnt += 1
        if b == 1:
            bob_cnt += 1
    if alice_cnt < k or bob_cnt < k:
        out = run(x).strip()
        assert out == '-1', f"impossible because counts: Alice {alice_cnt}, Bob {bob_cnt}, k={k}"


def test_lower_bound(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    alice_times = []
    bob_times = []
    for i in range(1, n+1):
        t, a, b = map(int, lines[i].split())
        if a == 1:
            alice_times.append(t)
        if b == 1:
            bob_times.append(t)
    out = run(x).strip()
    if out == '-1':
        return
    T = int(out)
    if len(alice_times) >= k:
        alice_times.sort()
        lower_alice = sum(alice_times[:k])
        assert T >= lower_alice, f"T={T} < sum of smallest k Alice times {lower_alice}"
    if len(bob_times) >= k:
        bob_times.sort()
        lower_bob = sum(bob_times[:k])
        assert T >= lower_bob, f"T={T} < sum of smallest k Bob times {lower_bob}"


def test_upper_bound(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    alice_books = []
    bob_books = []
    for i in range(1, n+1):
        t, a, b = map(int, lines[i].split())
        if a == 1:
            alice_books.append((t, i-1))
        if b == 1:
            bob_books.append((t, i-1))
    if len(alice_books) < k or len(bob_books) < k:
        return  # already checked by test_necessary_counts
    alice_books.sort(key=lambda x: x[0])
    bob_books.sort(key=lambda x: x[0])
    chosen = set()
    total = 0
    for j in range(k):
        chosen.add(alice_books[j][1])
        total += alice_books[j][0]
    for j in range(k):
        idx = bob_books[j][1]
        if idx not in chosen:
            total += bob_books[j][0]
    out = run(x).strip()
    if out == '-1':
        return
    T = int(out)
    assert T <= total, f"T={T} exceeds trivial union bound {total}"


def test_negative_one_impossible(run, x):
    import itertools
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    if n > 10:
        return
    books = []
    for i in range(1, n+1):
        t, a, b = map(int, lines[i].split())
        books.append((t, a, b))
    out = run(x).strip()
    if out == '-1':
        # verify no subset works
        possible = False
        for mask in range(1 << n):
            total = 0
            alice = 0
            bob = 0
            for i in range(n):
                if mask >> i & 1:
                    total += books[i][0]
                    alice += books[i][1]
                    bob += books[i][2]
            if alice >= k and bob >= k:
                possible = True
                break
        assert not possible, "output is -1 but a feasible subset exists"


def test_all_both(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    all_both = True
    times = []
    for i in range(1, n+1):
        t, a, b = map(int, lines[i].split())
        if not (a == 1 and b == 1):
            all_both = False
            break
        times.append(t)
    if not all_both:
        return
    times.sort()
    expected = sum(times[:k])
    out = run(x).strip()
    assert out != '-1', "must be possible when every book liked by both"
    assert int(out) == expected, f"expected sum of smallest k t_i: {expected}"


def test_no_both(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    alice_only = []
    bob_only = []
    for i in range(1, n+1):
        t, a, b = map(int, lines[i].split())
        if a == 1 and b == 1:
            return  # there is a both book, skip
        if a == 1:
            alice_only.append(t)
        if b == 1:
            bob_only.append(t)
    out = run(x).strip()
    if len(alice_only) < k or len(bob_only) < k:
        assert out == '-1', f"impossible: Alice {len(alice_only)} Bob {len(bob_only)} k={k}"
    else:
        alice_only.sort()
        bob_only.sort()
        expected = sum(alice_only[:k]) + sum(bob_only[:k])
        assert out != '-1', "should be possible"
        assert int(out) == expected, f"expected sum of separate smallest k: {expected}"


def test_total_sum_bound(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    total_sum = 0
    for i in range(1, n+1):
        t, a, b = map(int, lines[i].split())
        total_sum += t
    out = run(x).strip()
    if out == '-1':
        return
    T = int(out)
    assert 1 <= T <= total_sum, f"T={T} not in [1, total_sum={total_sum}]"


def test_k1_special(run, x):
    lines = x.strip().split('\n')
    n, k = map(int, lines[0].split())
    if k != 1:
        return
    both_t = []
    alice_t = []
    bob_t = []
    for i in range(1, n+1):
        t, a, b = map(int, lines[i].split())
        if a == 1 and b == 1:
            both_t.append(t)
        if a == 1 and b == 0:
            alice_t.append(t)
        if a == 0 and b == 1:
            bob_t.append(t)
    out = run(x).strip()
    if not both_t and (not alice_t or not bob_t):
        assert out == '-1', f"impossible for k=1: both={both_t}, alice={alice_t}, bob={bob_t}"
        return
    candidates = []
    if both_t:
        candidates.append(min(both_t))
    if alice_t and bob_t:
        candidates.append(min(alice_t) + min(bob_t))
    expected = min(candidates)
    assert out != '-1', "should be possible"
    assert int(out) == expected, f"for k=1 expected minimum of {candidates}: {expected}"

