      "name": "test_geometric_progression_integer_next",
      "intent": "If the sequence is a valid geometric progression (a≠0, b≠0, a≠b, b*b == a*c, c*c == b*d) and d*d is divisible by c, the output must equal d*d // c."
    },
    {
      "name": "test_geometric_progression_noninteger_next",
      "intent": "If the sequence is a valid geometric progression (as defined above) and d*d is not divisible by c, the output must be 42."
    },
    {
      "name": "test_neither_progression",
      "intent": "If the sequence is not arithmetic (differences not all equal) and not geometric (as defined above), the output must be 42."
    },
    {
      "name": "test_all_equal",
      "intent": "If all four numbers are equal, the output must equal that number."
    },
    {
      "name": "test_zero_sequence",
      "intent": "If all four numbers are zero, the output must be 0."
    },
    {
      "name": "test_arithmetic_direction",
      "intent": "If the sequence is arithmetic with common difference diff = b-a, then if diff > 0 the output must be greater than d, and if diff < 0 the output must be less than d."
    },
    {
      "name": "test_geometric_direction",
      "intent": "If the sequence is a valid geometric progression with a > 0 and ratio q = b/a, then if q > 1 the output must be greater than d, and if 0 < q < 1 the output must be less than d."
    },
    {
      "name": "test_42_implies_no_valid_next",
      "intent": "If the output is 42, then the sequence must not be arithmetic, and if it is a valid geometric progression, then d*d must not be divisible by c."
    }
  ]
}

