def test_output_format(run, x):
    out = run(x)
    assert out.endswith('\n'), "output must end with newline"
    s = out.strip()
    if s == '0':
        return
    if s.startswith('-'):
        s = s[1:]
    assert s.isdigit() and (len(s) == 1 or s[0] != '0'), "output must be integer without leading zeros"

def test_arithmetic_progression(run, x):
    a, b, c, d = map(int, x.strip().split())
    if b - a == c - b == d - c:
        expected = 2 * d - c
        out = run(x).strip()
        assert out == str(expected), f"Arithmetic progression should give {expected}"

def test_geometric_progression_integer_next(run, x):
    a, b, c, d = map(int, x.strip().split())
    if a != 0 and b != 0 and a != b and b * b == a * c and c * c == b * d:
        if d * d % c == 0:
            expected = d * d // c
            out = run(x).strip()
            assert out == str(expected), f"Geometric progression with integer next term should give {expected}"

def test_geometric_progression_noninteger_next(run, x):
    a, b, c, d = map(int, x.strip().split())
    if a != 0 and b != 0 and a != b and b * b == a * c and c * c == b * d:
        if d * d % c != 0:
            out = run(x).strip()
            assert out == '42', "Geometric progression with non-integer next term must output 42"

def test_neither_progression(run, x):
    a, b, c, d = map(int, x.strip().split())
    arithmetic = (b - a == c - b == d - c)
    geometric = (a != 0 and b != 0 and a != b and b * b == a * c and c * c == b * d)
    if not arithmetic and not geometric:
        out = run(x).strip()
        assert out == '42', "Neither arithmetic nor geometric must output 42"

def test_all_equal(run, x):
    a, b, c, d = map(int, x.strip().split())
    if a == b == c == d:
        out = run(x).strip()
        assert out == str(a), f"All equal sequence should output {a}"

def test_zero_sequence(run, x):
    a, b, c, d = map(int, x.strip().split())
    if a == b == c == d == 0:
        out = run(x).strip()
        assert out == '0', "All zeros must output 0"

def test_arithmetic_direction(run, x):
    a, b, c, d = map(int, x.strip().split())
    if b - a == c - b == d - c:
        diff = b - a
        ans = int(run(x).strip())
        if diff > 0:
            assert ans > d, "Positive arithmetic diff must give next term > last"
        elif diff < 0:
            assert ans < d, "Negative arithmetic diff must give next term < last"

def test_geometric_direction(run, x):
    a, b, c, d = map(int, x.strip().split())
    if a > 0 and b > 0 and a != b and b * b == a * c and c * c == b * d:
        q = b // a  # integer division, but direction only needs sign and >1/<1
        # Actually compute exact ratio as float for direction
        if b % a == 0 and (b // a) > 1:
            ans = int(run(x).strip())
            assert ans > d, "Geometric ratio >1 must give next term > last"
        elif b % a == 0 and 0 < (b // a) < 1:
            # This case cannot happen with integer a,b unless a > b and b divides a
            # We'll use float check
            if b / a > 1:
                ans = int(run(x).strip())
                assert ans > d
            elif 0 < b / a < 1:
                ans = int(run(x).strip())
                assert ans < d

def test_42_implies_no_valid_next(run, x):
    out = run(x).strip()
    if out == '42':
        a, b, c, d = map(int, x.strip().split())
        arithmetic = (b - a == c - b == d - c)
        geometric = (a != 0 and b != 0 and a != b and b * b == a * c and c * c == b * d)
        # If arithmetic, output should not be 42
        assert not arithmetic, "Output 42 but sequence is arithmetic"
        if geometric:
            assert d * d % c != 0, "Output 42 but geometric next term is integer"

