{
  "rationale": "The tests check necessary conditions derived from the specification. Tests 1-2 verify output format. Tests 3,6,7 ensure -1 corresponds to no possible collision. Tests 4-5 verify that a positive output is a feasible collision time and is minimal. Tests 8-10 provide bounds that must hold. All tests are fast for the given inputs (n ≤ 10). If a test must be dropped, test_upper_bound_overall is the weakest because the bound is loose and less likely to catch subtle errors.",
  "plan": [
    {
      "name": "test_output_is_integer",
      "intent": "The output must be a string that parses as an integer. If parsing fails, the answer is wrong."
    },
    {
      "name": "test_output_positive_or_minus_one",
      "intent": "The parsed integer must be either -1 or a positive integer. A zero or negative integer other than -1 is invalid."
    },
    {
      "name": "test_minus_one_implies_no_collision",
      "intent": "If the output is -1, then there must be no pair of particles moving towards each other (i.e., no i < j with direction[i] = 'R' and direction[j] = 'L'). If such a pair exists, the answer cannot be -1."
    },
    {
      "name": "test_positive_implies_feasible_collision",
      "intent": "If the output is not -1, there must exist at least one pair (i, j) with direction[i] = 'R' and direction[j] = 'L' such that (x[j] - x[i]) // 2 equals the output. Otherwise, the claimed collision time is impossible."
    },
    {
      "name": "test_positive_implies_minimal",
      "intent": "If the output is not -1, then for every pair (i, j) with direction[i] = 'R' and direction[j] = 'L', the collision time (x[j] - x[i]) // 2 must be at least the output. If any pair gives a smaller time, the output is not the first collision."
    },
    {
      "name": "test_adjacent_rl_implies_not_minus_one",
      "intent": "If there is an index i such that direction[i] = 'R' and direction[i+1] = 'L', then a collision is possible and the output must not be -1."
    },
    {
      "name": "test_all_same_direction_implies_minus_one",
      "intent": "If all directions are 'L' or all are 'R', then no collision can occur and the output must be -1."
    },
    {
      "name": "test_upper_bound_adjacent",
      "intent": "If there exists an adjacent R-L pair, then the output (if not -1) must be less than or equal to the minimum collision time among all adjacent R-L pairs. Since the first collision cannot be later than the earliest adjacent collision, a larger output is wrong."
    },
    {
      "name": "test_lower_bound_one",
      "intent": "If the output is not -1, it must be at least 1. Collisions cannot occur at time 0 because particles start at distinct positions."
    },
    {
      "name": "test_upper_bound_overall",
      "intent": "If the output is not -1, it must be at most (max coordinate - min coordinate) // 2. The farthest apart particles moving towards each other would collide at that time, so the first collision cannot be later."
    }
  ]
}

