tests_src:
def test_output_is_integer(run, x):
    output = run(x).strip()
    try:
        int(output)
    except ValueError:
        assert False, "Output must be an integer"


def test_output_positive_or_minus_one(run, x):
    output = run(x).strip()
    val = int(output)
    assert val == -1 or val > 0, "Output must be -1 or positive"


def test_minus_one_implies_no_collision(run, x):
    output = run(x).strip()
    if output.strip() != '-1':
        return
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 0:
        return
    dirs = lines[1].strip()
    coords = list(map(int, lines[2].split()))
    # If any R before L, collision is possible (though not guaranteed)
    # Specification: if such a pair exists, -1 is impossible
    for i in range(n):
        for j in range(i+1, n):
            if dirs[i] == 'R' and dirs[j] == 'L':
                assert False, "Found R-L pair, output cannot be -1"


def test_positive_implies_feasible_collision(run, x):
    output = run(x).strip()
    if output.strip() == '-1':
        return
    t = int(output)
    lines = x.strip().split('\n')
    n = int(lines[0])
    dirs = lines[1].strip()
    coords = list(map(int, lines[2].split()))
    feasible = False
    for i in range(n):
        for j in range(i+1, n):
            if dirs[i] == 'R' and dirs[j] == 'L':
                if (coords[j] - coords[i]) % 2 == 0 and (coords[j] - coords[i]) // 2 == t:
                    feasible = True
    assert feasible, f"No R-L pair collides at time {t}"


def test_positive_implies_minimal(run, x):
    output = run(x).strip()
    if output.strip() == '-1':
        return
    t = int(output)
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 1000:  # avoid O(n^2) on huge inputs
        return
    dirs = lines[1].strip()
    coords = list(map(int, lines[2].split()))
    for i in range(n):
        for j in range(i+1, n):
            if dirs[i] == 'R' and dirs[j] == 'L':
                if (coords[j] - coords[i]) % 2 == 0:
                    coll = (coords[j] - coords[i]) // 2
                    if coll < t:
                        assert False, f"Found earlier collision time {coll} < {t}"


def test_adjacent_rl_implies_not_minus_one(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n < 2:
        return
    dirs = lines[1].strip()
    for i in range(n-1):
        if dirs[i] == 'R' and dirs[i+1] == 'L':
            output = run(x).strip()
            assert output.strip() != '-1', "Adjacent R-L exists, output cannot be -1"
            return


def test_all_same_direction_implies_minus_one(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    dirs = lines[1].strip()
    if all(c == 'L' for c in dirs) or all(c == 'R' for c in dirs):
        output = run(x).strip()
        assert output.strip() == '-1', "All same direction, output must be -1"


def test_upper_bound_adjacent(run, x):
    output = run(x).strip()
    if output.strip() == '-1':
        return
    t = int(output)
    lines = x.strip().split('\n')
    n = int(lines[0])
    dirs = lines[1].strip()
    coords = list(map(int, lines[2].split()))
    min_adjacent = None
    for i in range(n-1):
        if dirs[i] == 'R' and dirs[i+1] == 'L':
            coll = (coords[i+1] - coords[i]) // 2
            if min_adjacent is None or coll < min_adjacent:
                min_adjacent = coll
    if min_adjacent is not None:
        assert t <= min_adjacent, f"Output {t} exceeds earliest adjacent collision time {min_adjacent}"


def test_lower_bound_one(run, x):
    output = run(x).strip()
    if output.strip() == '-1':
        return
    t = int(output)
    assert t >= 1, "Positive collision time must be at least 1"


def test_upper_bound_overall(run, x):
    output = run(x).strip()
    if output.strip() == '-1':
        return
    t = int(output)
    lines = x.strip().split('\n')
    n = int(lines[0])
    coords = list(map(int, lines[2].split()))
    max_possible = (coords[-1] - coords[0]) // 2
    assert t <= max_possible, f"Output {t} exceeds overall bound {max_possible}"

