    if diff == c - b == d - c:
        expected = d + diff
        out = int(run(x).strip())
        assert out == expected, f"Arithmetic progression expects {expected}, got {out}"

def test_geometric_integer_next(run, x):
    a, b, c, d = map(int, x.strip().split())
    if a == 0:
        return  # geometric requires a != 0, handled by other tests
    if b == 0:
        return  # ratio zero not allowed
