            expected = d * b // a
            out = int(run(x).strip())
            assert out == expected, f"Geometric progression expects {expected}, got {out}"

def test_neither_progression(run, x):
    a, b, c, d = map(int, x.strip().split())
    diff = b - a
    is_arith = diff == c - b == d - c
    is_geom = (a != 0 and b != 0 and b != a and 
               a * c == b * b and b * d == c * c)
    if not is_arith and not is_geom:
        out = int(run(x).strip())
        assert out == 42, f"Sequence is neither arithmetic nor geometric, must output 42, got {out}"

def test_zero_handling(run, x):
    a, b, c, d = map(int, x.strip().split())
    if a == b == c == d == 0:
