    if a == 0 and not (b - a == c - b == d - c):
        # sequence not arithmetic, and geometric impossible because a=0
        out = int(run(x).strip())
        assert out == 42, f"Sequence with zero first term and not arithmetic must output 42, got {out}"

def test_non_42_extends(run, x):
    out = int(run(x).strip())
