def test_output_format(run, x):
    out = run(x).rstrip('\n')
    if out == 'IMPOSSIBLE':
        return
    assert len(out) == int(x.split()[2]), 'output length must equal k'
    assert all(c in 'LRUD' for c in out), 'output must contain only L,R,U,D'

def test_simulation(run, x):
    out = run(x).rstrip('\n')
    if out == 'IMPOSSIBLE':
        return
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    grid = [list(line.strip()) for line in lines[1:1+n]]
    start = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X':
                start = (i, j)
                break
        if start:
            break
    dirs = {'L': (0, -1), 'R': (0, 1), 'U': (-1, 0), 'D': (1, 0)}
    r, c = start
    for step, ch in enumerate(out):
        dr, dc = dirs[ch]
        nr, nc = r + dr, c + dc
        assert 0 <= nr < n and 0 <= nc < m, 'move out of bounds'
        assert grid[nr][nc] != '*', 'move into obstacle'
        r, c = nr, nc
    assert (r, c) == start, 'did not return to start'

def test_odd_k(run, x):
    k = int(x.split()[2])
    if k % 2 == 1:
        out = run(x).rstrip('\n')
        assert out == 'IMPOSSIBLE', 'odd k must be IMPOSSIBLE'

def test_brute_force(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n * m > 25 or k > 30:
        return  # too big for brute force
    grid = [list(line.strip()) for line in lines[1:1+n]]
    start = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X':
                start = (i, j)
                break
        if start:
            break
    dirs = [('D', 1, 0), ('L', 0, -1), ('R', 0, 1), ('U', -1, 0)]
    best = None
    from functools import lru_cache
    @lru_cache(None)
    def dfs(r, c, steps):
        if steps == 0:
            return [()] if (r, c) == start else []
        res = []
        for sym, dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] != '*':
                for rest in dfs(nr, nc, steps-1):
                    res.append((sym,) + rest)
        return res
    all_cycles = dfs(start[0], start[1], k)
    if not all_cycles:
        correct = 'IMPOSSIBLE'
    else:
        best = min(all_cycles, key=lambda t: ''.join(t))
        correct = ''.join(best)
    out = run(x).rstrip('\n')
    assert out == correct

def test_start_isolated(run, x):
