    n, m, k = map(int, lines[0].split())
    if n * m > 100 or k > 200:
        return  # DP too large
    grid = [list(line.strip()) for line in lines[1:1+n]]
    start = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X':
                start = (i, j)
                break
        if start:
            break
    si, sj = start
    # DP over parity: any cycle of length exactly k?
    from functools import lru_cache
    @lru_cache(None)
    def can(r, c, steps):
        if steps == 0:
