    else:
        assert out == 'IMPOSSIBLE', 'no cycle exists but output is a string'

def test_first_move(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n * m > 100 or k > 200:
        return  # skip large
