    start = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X':
                start = (i, j)
                break
        if start:
            break
    si, sj = start
    order = [('D',1,0), ('L',0,-1), ('R',0,1), ('U',-1,0)]
    possible_first = []
    from functools import lru_cache
    @lru_cache(None)
    def can_return(r, c, steps):
