def test_lexicographic_heuristic(run, x):
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    if n * m > 100 or k > 200:
        return  # skip large
    grid = [list(line.strip()) for line in lines[1:1+n]]
    start = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X':
                start = (i, j)
                break
        if start:
            break
    si, sj = start
    from functools import lru_cache
    @lru_cache(None)
    def any_cycle(r, c, steps):
        if steps == 0:
            return [()] if (r, c) == (si, sj) else []
        for dr, dc in [(1,0), (-1,0), (0,1), (0,-1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] != '*':
                for rest in any_cycle(nr, nc, steps-1):
                    return [(dr, dc)] + rest  # return first found
        return []
    cyc = any_cycle(si, sj, k)
    if not cyc:
        return  # impossible, nothing to compare
    dir_to_ch = {(1,0):'D', (-1,0):'U', (0,1):'R', (0,-1):'L'}
    found = ''.join(dir_to_ch[d] for d in cyc)
    out = run(x).rstrip('\n')
    if out == 'IMPOSSIBLE':
        return
    assert out <= found, 'output is lexicographically larger than a known cycle'

def test_reachability(run, x):
    out = run(x).rstrip('\n')
    if out == 'IMPOSSIBLE':
        return
    lines = x.strip().split('\n')
    n, m, _ = map(int, lines[0].split())
    grid = [list(line.strip()) for line in lines[1:1+n]]
    start = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X':
                start = (i, j)
                break
        if start:
            break
    from collections import deque
    dist = [[-1]*m for _ in range(n)]
    dq = deque([start])
    dist[start[0]][start[1]] = 0
    while dq:
        r, c = dq.popleft()
        for dr, dc in [(1,0), (-1,0), (0,1), (0,-1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] != '*' and dist[nr][nc] == -1:
                dist[nr][nc] = dist[r][c] + 1
                dq.append((nr, nc))
    dirs = {'L': (0, -1), 'R': (0, 1), 'U': (-1, 0), 'D': (1, 0)}
    r, c = start
    for ch in out:
        dr, dc = dirs[ch]
        nr, nc = r + dr, c + dc
        assert dist[nr][nc] != -1, 'move to unreachable cell'
        r, c = nr, nc

def test_no_impossible_variant(run, x):
    out = run(x).rstrip('\n')
    if out != 'IMPOSSIBLE' and out.startswith('IMPOSSIBLE'):
        assert False, 'output must be exactly IMPOSSIBLE or a cycle string'

