def test_format(run, x):
    out = run(x)
    if out == "IMPOSSIBLE":
        return
    # must be exactly length k, only chars DLRU, no extra whitespace
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    out = out.rstrip('\n')
    assert len(out) == k, f"Output length {len(out)} != k={k}"
    assert all(c in "DLRU" for c in out), f"Invalid character in output"
    # ensure no extra newline beyond what run returned (already stripped)
    # but we allow trailing newline as usual; run(x) includes it.
    # We only stripped trailing newline for length check.
    # No extra whitespace: we already checked characters.
    return

def test_direction_balance(run, x):
    out = run(x)
    if out == "IMPOSSIBLE":
        return
    out = out.rstrip('\n')
    d = out.count('D')
    u = out.count('U')
    l = out.count('L')
    r = out.count('R')
    assert d == u, f"D={d} != U={u}"
    assert l == r, f"L={l} != R={r}"

def test_simulation(run, x):
    out = run(x)
    if out == "IMPOSSIBLE":
        return
    out = out.rstrip('\n')
    lines = x.strip().split('\n')
    n, m, k = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:]]
    # find start
    sr = sc = -1
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'X':
                sr, sc = i, j
                break
        if sr != -1:
            break
    r, c = sr, sc
    for ch in out:
        dr = {'D':1, 'U':-1, 'L':0, 'R':0}[ch]
        dc = {'D':0, 'U':0, 'L':-1, 'R':1}[ch]
        r += dr
        c += dc
        assert 0 <= r < n and 0 <= c < m, f"Move {ch} goes out of bounds at ({r},{c})"
        assert grid[r][c] != '*', f"Move {ch} hits obstacle at ({r},{c})"
    assert (r, c) == (sr, sc), f"End position ({r},{c}) not start ({sr},{sc})"

