def test_valid_integer(run, x):
    out = run(x)
    try:
        int(out.strip())
    except ValueError:
        assert False, "Output must be a valid integer"

def test_non_negative(run, x):
    out = run(x)
    val = int(out.strip())
    assert val >= 0, "Output must be non‑negative"

def test_upper_bound_13len(run, x):
    out = run(x)
    s = x.strip()
    val = int(out.strip())
    # maximal distance between any two letters is 13 (e.g., 'a' to 'n' or 'z' to 'm')
    assert val <= 13 * len(s), f"Output {val} exceeds 13 * length"

def test_all_same(run, x):
    s = x.strip()
    if len(set(s)) == 1:
        out = run(x).strip()
        assert out == '0', f"All same characters, expected '0', got {out}"

def test_length_2(run, x):
    s = x.strip()
    if len(s) == 2:
        def dist(a, b):
            d = abs(ord(a) - ord(b))
            return min(d, 26 - d)
        expected = dist('a', s[0]) + dist(s[0], s[1])
        out = int(run(x).strip())
        assert out == expected, f"For length 2, expected {expected}, got {out}"

def test_length_3(run, x):
    s = x.strip()
    if len(s) == 3:
        def dist(a, b):
            d = abs(ord(a) - ord(b))
            return min(d, 26 - d)
        expected = dist('a', s[0]) + dist(s[0], s[1]) + dist(s[1], s[2])
        out = int(run(x).strip())
        assert out == expected, f"For length 3, expected {expected}, got {out}"

def test_general(run, x):
    s = x.strip()
    # compute minimal rotations as defined in the note
    def dist(a, b):
        d = abs(ord(a) - ord(b))
        return min(d, 26 - d)
    pos = 'a'
    total = 0
    for ch in s:
        total += dist(pos, ch)
        pos = ch
    out = int(run(x).strip())
    assert out == total, f"Expected {total}, got {out}"

def test_no_extra_whitespace(run, x):
    out = run(x)
    stripped = out.strip()
    # after stripping newline, must consist only of digits
    assert stripped.isdigit(), "Output must contain only digits (and newline)"
    # ensure no extra spaces or lines
    lines = out.splitlines()
    assert len(lines) == 1, "Output must be a single line"
    assert lines[0] == stripped, "No leading/trailing spaces allowed"

def test_output_not_empty(run, x):
    out = run(x)
    assert out != '', "Output must not be empty"

def test_upper_bound_direct(run, x):
    s = x.strip()
    out = int(run(x).strip())
    # direct letter index differences (a=0,...,z=25)
    def idx(ch): return ord(ch) - ord('a')
    total = idx(s[0])  # distance from 'a' to first
    for i in range(1, len(s)):
        total += abs(idx(s[i]) - idx(s[i-1]))
    assert out <= total, f"Output {out} exceeds direct‑difference bound {total}"

