def test_correctness(run, x):
    # brute-force BFS/DP simulation for m up to 100
    lines = x.strip().splitlines()
    n_m = list(map(int, lines[0].split()))
    if len(n_m) != 2:
        return  # malformed input, but spec guarantees valid
    n, m = n_m
    teleports = []
    for i in range(1, n+1):
        a_b = list(map(int, lines[i].split()))
        if len(a_b) != 2:
            return
        a, b = a_b
        teleports.append((a, b))
    # BFS on points 0..m
    reachable = [False] * (m+1)
    reachable[0] = True
    changed = True
    while changed:
        changed = False
        for a, b in teleports:
            for p in range(m+1):
                if reachable[p] and a == p:
                    for q in range(a, b+1):
                        if q <= m and not reachable[q]:
                            reachable[q] = True
                            changed = True
    expected = 'YES' if reachable[m] else 'NO'
    output = run(x).strip()
    assert output.upper() == expected.upper()

def test_output_format(run, x):
    output = run(x)
    stripped = output.strip()
    assert stripped.upper() in ('YES', 'NO'), 'Output must be YES or NO'

def test_no_teleport_at_zero(run, x):
    lines = x.strip().splitlines()
    n_m = list(map(int, lines[0].split()))
    n = n_m[0]
    has_zero = False
    for i in range(1, n+1):
        a_b = list(map(int, lines[i].split()))
        if a_b[0] == 0:
            has_zero = True
            break
    if not has_zero:
        output = run(x).strip().upper()
        assert output == 'NO', 'No teleport at 0 must yield NO'

def test_direct_jump(run, x):
    lines = x.strip().splitlines()
    n_m = list(map(int, lines[0].split()))
    n, m = n_m
    has_direct = False
