def test_brute_small(run, x):
    s = x.strip()
    if len(s) > 5:
        return  # brute-force only for small hints as per plan
    n = len(s)
    count = 0
    # enumerate all digit strings length n, first digit non-zero
    for num in range(10**(n-1), 10**n):
        cand = str(num)
        ok = True
        mapping = {}
        used_digits = set()
        for i,ch in enumerate(s):
            if ch == '?':
                continue
            if '0' <= ch <= '9':
                if cand[i] != ch:
                    ok = False
                    break
                # digit fixed, check letters that map to this position
                for letter in mapping:
                    if mapping[letter] == ch and any(s[j]==letter for j in range(n) if s[j]==letter and cand[j]!=ch):
                        ok = False
                        break
                if not ok:
                    break
            else:  # letter A-J
                if ch in mapping:
                    if mapping[ch] != cand[i]:
                        ok = False
                        break
                else:
                    if cand[i] in used_digits:
                        ok = False
                        break
                    mapping[ch] = cand[i]
                    used_digits.add(cand[i])
        if ok:
            count += 1
    out = run(x).strip()
    assert out.isdigit()
    assert int(out) == count

def test_output_format(run, x):
    out = run(x).strip()
    assert len(out) > 0, "output is empty"
    assert out.isdigit(), "output contains non-digit characters"
    # leading zeros only allowed if output is exactly "0"
    if out != "0":
        assert out[0] != '0', "output has leading zeros"

def test_upper_bound(run, x):
    s = x.strip()
    n = len(s)
    upper = 9 * (10 ** (n-1))
    out = run(x).strip()
    assert out.isdigit()
    val = int(out)
    assert val <= upper, f"output {val} exceeds maximum possible {upper}"

def test_non_negative(run, x):
    out = run(x).strip()
    assert out.isdigit()
    val = int(out)
    assert val >= 0, "output is negative"

def test_letter_two_digits(run, x):
    s = x.strip()
    # check if a letter appears with different fixed digits in hint
    letter_digit = {}
    contradiction = False
    for i,ch in enumerate(s):
        if 'A' <= ch <= 'J':
            # look for fixed digits at same positions of this letter
            for j,c2 in enumerate(s):
                if c2 == ch and '0' <= s[j] <= '9':
                    digit = s[j]
                    if ch in letter_digit and letter_digit[ch] != digit:
                        contradiction = True
                        break
                    letter_digit[ch] = digit
            if contradiction:
                break
    out = run(x).strip()
    if contradiction:
        assert out == "0", f"contradiction for letter with two digits, expected 0 got {out}"

def test_two_letters_same_digit(run, x):
    s = x.strip()
    # collect fixed digits for each letter
    letter_digit = {}
    for i,ch in enumerate(s):
        if 'A' <= ch <= 'J':
            for j,c2 in enumerate(s):
                if c2 == ch and '0' <= s[j] <= '9':
                    digit = s[j]
                    letter_digit[ch] = digit
    # check if two different letters are forced to same digit
    seen = {}
    contradiction = False
    for letter,digit in letter_digit.items():
        if digit in seen and seen[digit] != letter:
            contradiction = True
            break
        seen[digit] = letter
    out = run(x).strip()
    if contradiction:
        assert out == "0", f"two letters forced to same digit, expected 0 got {out}"

def test_first_letter_zero(run, x):
    s = x.strip()
    if s[0] in "ABCDEFGHIJ":
        # check if that letter is forced to digit '0' anywhere
        letter = s[0]
        forced_zero = False
        for i,ch in enumerate(s):
            if ch == letter and '0' <= s[i] <= '9' and s[i] == '0':
                forced_zero = True
                break
        out = run(x).strip()
        if forced_zero:
            assert out == "0", f"first letter forced to zero, expected 0 got {out}"

def test_too_many_letters(run, x):
    s = x.strip()
    distinct_letters = {ch for ch in s if 'A' <= ch <= 'J'}
    out = run(x).strip()
    if len(distinct_letters) > 10:
        assert out == "0", f"too many distinct letters ({len(distinct_letters)}), expected 0 got {out}"

def test_examples(run, x):
    s = x.strip()
    out = run(x).strip()
    if s == "?":
        assert out == "9", f"hint '?' expected 9 got {out}"
    elif s == "AJ":
        assert out == "81", f"hint 'AJ' expected 81 got {out}"
    elif s == "1?AA":
        assert out == "100", f"hint '1?AA' expected 100 got {out}"

def test_all_digits(run, x):
    s = x.strip()
    if all('0' <= ch <= '9' for ch in s):
        # first character is not '0' guaranteed by input
        out = run(x).strip()
        assert out == "1", f"all-digit hint expected 1 got {out}"

