def test_brute_force_small(run, x):
    s = x.strip()
    if len(s) > 6:
        return
    from itertools import product
    def matches(code):
        if code[0] == '0':
            return False
        mapping = {}
        for ch, dig in zip(s, code):
            if ch == '?':
                continue
            if '0' <= ch <= '9':
                if dig != ch:
                    return False
                continue
            # ch is A-J
            if ch in mapping:
                if mapping[ch] != dig:
                    return False
            else:
                if dig in mapping.values():
                    return False
                mapping[ch] = dig
        return True
    cnt = 0
    for digits in product('0123456789', repeat=len(s)):
        if matches(digits):
            cnt += 1
    out = run(x).strip()
    assert out.isdigit() and int(out) == cnt

def test_output_positive_integer(run, x):
    out = run(x).strip()
    assert out.isdigit() and int(out) >= 1

def test_all_digits(run, x):
    s = x.strip()
    if all('0' <= ch <= '9' for ch in s):
        out = run(x).strip()
        assert out == '1'

def test_all_question(run, x):
    s = x.strip()
    if all(ch == '?' for ch in s):
        out = run(x).strip()
        expected = 9 * (10 ** (len(s) - 1))
        assert out == str(expected)

def test_all_letters_distinct(run, x):
    s = x.strip()
    letters = [ch for ch in s if 'A' <= ch <= 'J']
    if len(letters) == len(s) and len(set(letters)) == len(letters):
        d = len(letters)
        if d > 10:
            return
        from math import perm
        # first letter cannot be 0
        total = 9 * perm(9, d - 1) if d > 0 else 1
        out = run(x).strip()
        assert out == str(total)

def test_upper_bound(run, x):
    s = x.strip()
    out = run(x).strip()
    bound = 9 * (10 ** (len(s) - 1))
    assert int(out) <= bound

def test_output_numeric(run, x):
    out = run(x).strip()
    assert out.isdigit()

def test_divisible_by_question_product(run, x):
    s = x.strip()
    q = s.count('?')
    if q == 0:
        return
    factor = 10 ** q
    if s[0] == '?':
        factor = factor // 10 * 9
    out = run(x).strip()
    assert int(out) % factor == 0

def test_divisible_by_letter_product(run, x):
    s = x.strip()
    letters = [ch for ch in s if 'A' <= ch <= 'J']
    d = len(set(letters))
    if d == 0:
        return
    from math import perm
    if '0' <= s[0] <= '9':
        factor = perm(10, d)
    else:
        # first character is letter or '?'
        # but if first char is letter, that letter cannot be 0
        # factor for letters: first letter 9 choices, remaining d-1 letters choose from 9 remaining digits
        if s[0] in letters:
            factor = 9 * perm(9, d - 1) if d > 1 else 9
        else:
            # first char is '?' (not a letter), letters unrestricted except distinct
            factor = perm(10, d)
    out = run(x).strip()
    assert int(out) % factor == 0

def test_first_char_implies_div9(run, x):
    s = x.strip()
    if s[0] == '?' or ('A' <= s[0] <= 'J'):
        out = run(x).strip()
        assert int(out) % 9 == 0

