def test_brute_force(run, x):
    n = int(x.strip())
    if 1 <= n <= 1000:
        seq = ''
        i = 1
        while len(seq) < n:
            seq += str(i)
            i += 1
        expected = seq[n-1]
        output = run(x).strip()
        assert output == expected, f'For n={n}, expected {repr(expected)}, got {repr(output)}'

