def test_small_brute(run, x):
    x1, y1, x2, y2 = map(int, x.strip().split())
    total_points = (x2 - x1 + 1) * (y2 - y1 + 1)
    if total_points <= 10000:
        count = 0
        for xc in range(x1, x2 + 1):
            for yc in range(y1, y2 + 1):
                if xc % 2 == yc % 2:
                    count += 1
        assert int(run(x).strip()) == count

def test_non_negative_integer(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0

def test_upper_bound_total(run, x):
    x1, y1, x2, y2 = map(int, x.strip().split())
    total_points = (x2 - x1 + 1) * (y2 - y1 + 1)
    assert int(run(x).strip()) <= total_points

def test_lower_bound_existence(run, x):
    x1, y1, x2, y2 = map(int, x.strip().split())
    # For each parity (0,1), if there exists y in [y1,y2] with that parity, then all x with same parity contribute at least one cell.
    y_parities = {y % 2 for y in range(y1, y2 + 1)}
    min_possible = 0
    for p in (0, 1):
        if p in y_parities:
            # count x in [x1,x2] with parity p
            x_count = (x2 - x1 + 2 - (x1 % 2 != p)) // 2
            min_possible += x_count
    assert int(run(x).strip()) >= min_possible

def test_upper_bound_per_x(run, x):
    x1, y1, x2, y2 = map(int, x.strip().split())
    height = y2 - y1 + 1
    max_per_x = (height + 1) // 2  # ceil(height/2)
    x_count = x2 - x1 + 1
    assert int(run(x).strip()) <= x_count * max_per_x

def test_degenerate_point(run, x):
    x1, y1, x2, y2 = map(int, x.strip().split())
    if x1 == x2 and y1 == y2:
        expected = 1 if (x1 % 2) == (y1 % 2) else 0
        assert int(run(x).strip()) == expected

def test_horizontal_line(run, x):
    x1, y1, x2, y2 = map(int, x.strip().split())
    if y1 == y2:
        parity = y1 % 2
        count = (x2 - x1 + 2 - (x1 % 2 != parity)) // 2
        assert int(run(x).strip()) == count

def test_vertical_line(run, x):
    x1, y1, x2, y2 = map(int, x.strip().split())
    if x1 == x2:
        parity = x1 % 2
        count = (y2 - y1 + 2 - (y1 % 2 != parity)) // 2
        assert int(run(x).strip()) == count

def test_example(run, x):
    if x.strip() == '1 1 5 5':
        assert run(x).strip() == '13'

def test_parity_consistency(run, x):
    x1, y1, x2, y2 = map(int, x.strip().split())
    # Two possible counts assuming cells are exactly where x%2 == y%2
    # Formula: count = number of (x,y) in rectangle with x%2 == y%2.
    # Compute both possibilities based on whether we start counting from x1,y1 parity match.
    # Actually compute directly but only using parity logic.
    # For each x in [x1,x2], the matching y are those with same parity as x.
    total = 0
    for xc in range(x1, x2 + 1):
        parity = xc % 2
        # count y in [y1,y2] with y%2 == parity
        if (y1 % 2) == parity:
            first = y1
        else:
            first = y1 + 1
        if first > y2:
            cnt = 0
        else:
            cnt = (y2 - first) // 2 + 1
        total += cnt
    assert int(run(x).strip()) == total

