tests_src:
def test_format(run, x):
    out = run(x)
    tokens = out.split()
    if len(tokens) == 0:
        raise AssertionError('empty output')
    if tokens[0] == '-1':
        assert len(tokens) == 1, 'with -1 there must be exactly one token'
    else:
        for tok in tokens:
            int(tok)  # must be convertible


def test_sorted(run, x):
    out = run(x)
    if out.strip() == '-1':
        return
    nums = list(map(int, out.split()))
    for i in range(len(nums)-1):
        assert nums[i] < nums[i+1], 'not strictly increasing'


def test_mod(run, x):
    y, k, n = map(int, x.split())
    out = run(x)
    if out.strip() == '-1':
        return
    for val in map(int, out.split()):
        assert (val + y) % k == 0, f'x={val} does not satisfy (x+y)%k==0'


def test_bounds(run, x):
    y, k, n = map(int, x.split())
    out = run(x)
    if out.strip() == '-1':
        return
    for val in map(int, out.split()):
        assert 1 <= val <= n - y, f'x={val} outside [1, n-y]'


def test_step(run, x):
    y, k, n = map(int, x.split())
    out = run(x)
    if out.strip() == '-1':
        return
    nums = list(map(int, out.split()))
    if len(nums) >= 2:
        step = nums[1] - nums[0]
        assert step % k == 0, 'consecutive difference not multiple of k'
        for i in range(2, len(nums)):
            assert nums[i] - nums[i-1] == step, 'step not constant'
    if len(nums) > 0:
        assert (nums[0] + y) % k == 0  # already in test_mod, but safe


def test_existence(run, x):
    y, k, n = map(int, x.split())
    out = run(x).strip()
    # find smallest x_min >= 1 such that (x_min + y) % k == 0
    r = (-y) % k
    x_min = r if r != 0 else k
    if x_min + y > n:
        assert out == '-1', 'should be -1 when no valid x'
    else:
        assert out != '-1', 'should not be -1 when valid x exists'


def test_first_last(run, x):
    y, k, n = map(int, x.split())
    out = run(x).strip()
    if out == '-1':
        return
    nums = list(map(int, out.split()))
    r = (-y) % k
    x_min = r if r != 0 else k
    x_max = (n // k) * k - y
    assert x_max >= x_min, 'inconsistent range'
    assert nums[0] == x_min, f'first element should be {x_min}'
    assert nums[-1] == x_max, f'last element should be {x_max}'


def test_count(run, x):
    y, k, n = map(int, x.split())
    out = run(x).strip()
    if out == '-1':
        # compute expected count
        import math
        low_m = math.ceil((y+1) / k)
        high_m = n // k
        cnt = max(0, high_m - low_m + 1)
        assert cnt == 0, 'output -1 but count >0'
    else:
        nums = list(map(int, out.split()))
        import math
        low_m = math.ceil((y+1) / k)
        high_m = n // k
        cnt = max(0, high_m - low_m + 1)
        assert len(nums) == cnt, f'expected {cnt} numbers, got {len(nums)}'


def test_no_duplicates(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    nums = list(map(int, out.split()))
    seen = set()
    for v in nums:
        assert v not in seen, f'duplicate value {v}'
        seen.add(v)


def test_consistency(run, x):
    y, k, n = map(int, x.split())
    out = run(x).strip()
    # brute‑force all valid x, but only if n/k <= 1e5 (given in spec)
    # since n/k <= 1e5, iterating m is safe.
    import math
    low_m = math.ceil((y+1) / k)
    high_m = n // k
    expected = []
    for m in range(low_m, high_m + 1):
        x_val = m * k - y
        if x_val >= 1:
            expected.append(x_val)
    if not expected:
        assert out == '-1', f'expected -1, got {out}'
    else:
        got = list(map(int, out.split()))
        assert got == expected, f'expected {expected}, got {got}'

