def test_small_n_brute_force(run, x):
    import sys
    lines = x.strip().splitlines()
    if not lines:
        return
    first = lines[0].strip().split()
    if not first:
        return
    n = int(first[0])
    if n > 5:
        return  # skip
    from itertools import permutations
    heights = [i for i in range(1, n+1) for _ in range(2)]
    seqs = set()
    for perm in permutations(heights):
        # mausoleum condition: non-decreasing then non-increasing
        inc = True
        dec_start = -1
        for i in range(1, 2*n):
            if inc:
                if perm[i] < perm[i-1]:
                    inc = False
                    dec_start = i
            else:
                if perm[i] > perm[i-1]:
                    break
        else:
            seqs.add(perm)
    # now apply constraints
    k = int(first[1]) if len(first) > 1 else 0
    constraints = []
    for line in lines[1:1+k]:
        parts = line.strip().split()
        if len(parts) < 3:
            continue
        x_i, sign, y_i = int(parts[0]), parts[1], int(parts[2])
        constraints.append((x_i, sign, y_i))
    def satisfies(seq):
        for x_i, sign, y_i in constraints:
            a = seq[x_i-1]
            b = seq[y_i-1]
            if sign == '=':
                if a != b:
                    return False
            elif sign == '<':
                if a >= b:
                    return False
            elif sign == '>':
                if a <= b:
                    return False
            elif sign == '<=':
                if a > b:
                    return False
            elif sign == '>=':
                if a < b:
                    return False
        return True
    valid = [seq for seq in seqs if satisfies(seq)]
    expected = len(valid)
    out = run(x).strip()
    if not out:
        assert False
    ans = int(out)
    assert ans == expected, f"For small n={n}, expected {expected} but got {ans}"


