def test_output_format(run, x):
    out = run(x)
    # must be exactly one non‑negative integer followed by newline, no extra whitespace
    assert out.endswith('\n'), "output must end with newline"
    stripped = out.strip()
    assert stripped == out.rstrip('\n'), "extra whitespace besides trailing newline"
    assert stripped.isdigit() or (stripped == '0'), "output must be a non‑negative integer"
    # no leading zeros unless the number is exactly "0"
    if stripped != '0':
        assert stripped[0] != '0', "no leading zeros allowed"


def test_upper_bound(run, x):
    import math
    lines = x.strip().splitlines()
    if not lines:
        return
    first = lines[0].strip().split()
    if not first:
        return
    n = int(first[0])
    total = math.factorial(2*n) // (2**n)
    out = run(x).strip()
    if not out:
        assert False
    ans = int(out)
    assert 0 <= ans <= total, f"Answer {ans} out of bounds [0, {total}]"


def test_equality_component_size(run, x):
    lines = x.strip().splitlines()
