    # build equality graph
    from collections import defaultdict
    adj = defaultdict(list)
    for line in lines[1:1+k]:
        parts = line.strip().split()
        if len(parts) < 3:
            continue
        x_i, sign, y_i = int(parts[0]), parts[1], int(parts[2])
        if sign == '=':
            adj[x_i].append(y_i)
            adj[y_i].append(x_i)
    visited = set()
    for v in range(1, 2*n+1):
        if v in visited:
            continue
        stack = [v]
        comp = []
        while stack:
            node = stack.pop()
            if node in visited:
                continue
            visited.add(node)
            comp.append(node)
            for nb in adj[node]:
                if nb not in visited:
                    stack.append(nb)
        if len(comp) > 2:
            # impossible: each height appears exactly twice
            out = run(x).strip()
            if not out:
                assert False
            ans = int(out)
            assert ans == 0, f"Equality component size >2, answer must be 0, got {ans}"


def test_strict_inequality_cycle(run, x):
    lines = x.strip().splitlines()
    if not lines:
        return
    first = lines[0].strip().split()
    if not first:
        return
    n = int(first[0])
    k = int(first[1]) if len(first) > 1 else 0
    # 1. build equality components
    from collections import defaultdict
    eq_adj = defaultdict(list)
    for line in lines[1:1+k]:
        parts = line.strip().split()
        if len(parts) < 3:
            continue
        x_i, sign, y_i = int(parts[0]), parts[1], int(parts[2])
        if sign == '=':
            eq_adj[x_i].append(y_i)
            eq_adj[y_i].append(x_i)
    comp_id = {}
    comps = []
    for v in range(1, 2*n+1):
        if v in comp_id:
            continue
        stack = [v]
        comp = []
        while stack:
            node = stack.pop()
            if node in comp_id:
                continue
            comp_id[node] = len(comps)
            comp.append(node)
            for nb in eq_adj[node]:
                if nb not in comp_id:
                    stack.append(nb)
        comps.append(comp)
    # 2. build directed graph of strict inequalities on components
    strict_edges = defaultdict(set)
    for line in lines[1:1+k]:
        parts = line.strip().split()
        if len(parts) < 3:
            continue
        x_i, sign, y_i = int(parts[0]), parts[1], int(parts[2])
        if sign in ('<', '>'):
            cx = comp_id[x_i]
            cy = comp_id[y_i]
            if cx == cy:
                # self‑contradiction, handled by another test
                continue
            if sign == '<':
                strict_edges[cx].add(cy)
            else:  # '>'
                strict_edges[cy].add(cx)
    # 3. detect cycle
    UNVISITED, VISITING, DONE = 0, 1, 2
    state = {v: UNVISITED for v in range(len(comps))}
    def dfs(u):
        state[u] = VISITING
        for v in strict_edges[u]:
            if state[v] == VISITING:
                return True  # cycle
            if state[v] == UNVISITED:
                if dfs(v):
                    return True
        state[u] = DONE
        return False
    has_cycle = False
    for v in range(len(comps)):
        if state[v] == UNVISITED:
            if dfs(v):
                has_cycle = True
                break
    if has_cycle:
        out = run(x).strip()
        if not out:
            assert False
        ans = int(out)
        assert ans == 0, f"Strict inequality cycle, answer must be 0, got {ans}"


