def test_small_n_bruteforce(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 10:
        return  # skip for large inputs
    c = []
    d = []
    total = 0
    for i in range(1, n+1):
        ci, di = lines[i].split()
        ci = int(ci)
        di = int(di)
        c.append(ci)
        d.append(di)
        total += ci
    pref = 0
    L = -10**18
    R = 10**18
    for i in range(n):
        if d[i] == 1:
            L = max(L, 1900 - pref)
        else:
            R = min(R, 1899 - pref)
        pref += c[i]
    out = run(x).strip()
    if L > R:
        assert out == 'Impossible', 'small n: should be Impossible'
    elif R == 10**18:
        assert out == 'Infinity', 'small n: should be Infinity'
    else:
        expected = R + total
        assert out == str(expected), f'small n: expected {expected}, got {out}'

def test_examples(run, x):
    examples = {
        "3\n-7 1\n5 2\n8 2\n": "1907",
        "2\n57 1\n22 2\n": "Impossible",
        "1\n-5 1\n": "Infinity",
        "4\n27 2\n13 1\n-50 1\n8 2\n": "1897"
    }
    if x in examples:
        expected = examples[x]
        out = run(x).strip()
        assert out == expected, f'example mismatch: expected {expected}, got {out}'

def test_impossible_consistent(run, x):
    out = run(x).strip()
    if out != 'Impossible':
        return
    lines = x.strip().split('\n')
    n = int(lines[0])
    c = []
    d = []
    pref = 0
    L = -10**18
    R = 10**18
    for i in range(1, n+1):
        ci, di = lines[i].split()
        ci = int(ci)
        di = int(di)
        if di == 1:
            L = max(L, 1900 - pref)
        else:
            R = min(R, 1899 - pref)
        pref += ci
    # L > R is necessary for impossibility
    if L <= R:
        assert False, 'output Impossible but L <= R'

def test_infinity_consistent(run, x):
    out = run(x).strip()
    if out != 'Infinity':
        return
    lines = x.strip().split('\n')
    n = int(lines[0])
    for i in range(1, n+1):
        _, d = lines[i].split()
        if d == '2':
            assert False, 'output Infinity but found div2 contest'

