def test_output_format(run, x):
    out = run(x)
    # Must be a string that can be parsed as a non‑negative integer.
    stripped = out.strip()
    assert stripped.isdigit() or (stripped[0] == '-' and stripped[1:].isdigit()), 'Output must be an integer'
    val = int(stripped)
    assert val >= 0, 'Output must be non‑negative'

def test_upper_bound(run, x):
    import math
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    total_permutations = math.factorial(2*n) // (2**n)
    out = run(x).strip()
    val = int(out)
    assert val <= total_permutations, f'Answer {val} exceeds total permutations {total_permutations}'

def test_n1_special(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0].split()[0])
    if n != 1:
        return  # This test only applies to n=1
    k = int(lines[0].split()[1])
    has_strict = False
    for i in range(1, k+1):
        parts = lines[i].split()
        sign = parts[1]
        if sign == '<' or sign == '>':
            has_strict = True
            break
    out = run(x).strip()
    val = int(out)
    if has_strict:
        assert val == 0, f'n=1 with strict inequality must give 0, got {val}'
    else:
        assert val == 1, f'n=1 with no strict inequality must give 1, got {val}'

def test_bruteforce_small(run, x):
    import itertools, math
    lines = x.strip().split('\n')
    nk = lines[0].split()
    n = int(nk[0])
    if n > 5:
        return  # too large for brute force
    k = int(nk[1])
    # Parse constraints
    constraints = []
    for i in range(1, k+1):
        parts = lines[i].split()
        x_i = int(parts[0])
        sign = parts[1]
        y_i = int(parts[2])
        constraints.append((x_i, sign, y_i))
    # Heights list: two of each 1..n
    heights = [h for h in range(1, n+1) for _ in range(2)]
    # All distinct permutations of this multiset
    seen = set()
    count = 0
    for perm in itertools.permutations(heights):
        if perm in seen:
            continue
        seen.add(perm)
        # Unimodal condition
        inc = True
        peak = False
        ok = True
        for i in range(1, 2*n):
            if not peak:
                if perm[i] < perm[i-1]:
                    peak = True
            else:
                if perm[i] > perm[i-1]:
                    ok = False
                    break
        if not ok:
            continue
        # Additional constraints
        satisfies = True
        for x_i, sign, y_i in constraints:
            a = perm[x_i-1]
            b = perm[y_i-1]
            if sign == '=':
                if a != b:
                    satisfies = False
                    break
            elif sign == '<':
                if a >= b:
                    satisfies = False
                    break
            elif sign == '>':
                if a <= b:
                    satisfies = False
                    break
            elif sign == '<=':
                if a > b:
                    satisfies = False
                    break
            elif sign == '>=':
                if a < b:
                    satisfies = False
                    break
        if satisfies:
            count += 1
    out = run(x).strip()
    val = int(out)
    assert val == count, f'Brute force says {count}, got {val}'

