        else:
            expected = best
        out = run(x)
        ans = int(out.strip())
        assert ans == expected, f'small exact DP expects {expected}'

def test_greedy_upper_bound(run, x):
    lines = x.strip().split('\n')
    n, d = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    balance = 0
    deposits = 0
    possible = True
    for v in a:
        if v == 0 and balance < 0:
            # deposit enough to make balance >= 0, but not exceed d
            need = -balance
            max_deposit = d - balance
            deposit = min(need, max_deposit)
            balance += deposit
            deposits += 1
        balance += v
        if balance > d:
            possible = False
            break
    out = run(x)
    ans = int(out.strip())
    if possible:
        assert ans <= deposits, f'greedy gives upper bound {deposits}'

def test_examples_from_statement(run, x):
    examples = [
        ("5 10\n-1 5 0 -5 3\n", "0\n"),
        ("3 4\n-10 0 20\n", "-1\n"),
        ("5 10\n-5 0 10 -11 0\n", "2\n")
    ]
    for inp, exp in examples:
        if x == inp:
            out = run(x)
            assert out == exp, f'example mismatch: expected {repr(exp)} got {repr(out)}'

def test_no_check_days(run, x):
    lines = x.strip().split('\n')
    n, d = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    if 0 not in a:
        prefix = 0
        max_prefix = 0
        for v in a:
            prefix += v
            if prefix > max_prefix:
                max_prefix = prefix
        out = run(x)
        ans = int(out.strip())
        if max_prefix > d:
            assert ans == -1, 'no zeros, max prefix > d must output -1'
        else:
            assert ans == 0, 'no zeros and max prefix ≤ d must output 0'

def test_answer_zero_iff_conditions(run, x):
    lines = x.strip().split('\n')
    n, d = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    prefix = 0
    max_prefix = 0
    check_ok = True
    for v in a:
        prefix += v
        if prefix > max_prefix:
            max_prefix = prefix
        if v == 0 and prefix < 0:
            check_ok = False
    out = run(x)
    ans = int(out.strip())
    zero_conditions = (max_prefix <= d) and check_ok
    if ans == 0:
        assert zero_conditions, 'answer 0 requires max_prefix ≤ d and all check days non‑negative'
    else:
        if zero_conditions:
            # answer could be 0 but not necessarily if deposits needed to keep balance ≤ d? Actually if conditions hold, no deposit needed: answer 0 is possible.
            # So any other answer is wrong.
            assert False, 'conditions for answer 0 hold, but answer is not 0'

def test_answer_leq_zeros(run, x):
    lines = x.strip().split('\n')
    a = list(map(int, lines[1].split()))
    zero_count = sum(1 for v in a if v == 0)
    out = run(x)
    ans = int(out.strip())
    if ans != -1:
        assert ans <= zero_count, f'answer {ans} exceeds number of zeros {zero_count}'

