def test_output_format(run, x):
    out = run(x).strip()
    if out == 'Infinity' or out == 'Impossible':
        return
    # must be an integer, no leading zeros unless it's '0'
    assert out.isdigit() or (out[0] == '-' and out[1:].isdigit()), 'not a valid integer'
    if out != '0':
        assert out[0] != '0', 'unnecessary leading zero'
        if out[0] == '-' and len(out) > 2:
            assert out[1] != '0', 'unnecessary leading zero after minus'

def test_div1_infinity_equivalence(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    all_div1 = True
    for i in range(1, n+1):
        _, d = lines[i].split()
        if d != '1':
            all_div1 = False
            break
    out = run(x).strip()
    if all_div1:
        assert out == 'Infinity', 'all division 1 must yield Infinity'
    if out == 'Infinity':
        assert all_div1, 'Infinity output requires all contests division 1'

def test_all_div2_possible(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    all_div2 = True
    for i in range(1, n+1):
        _, d = lines[i].split()
        if d != '2':
            all_div2 = False
            break
    if all_div2:
        out = run(x).strip()
        assert out not in ['Infinity', 'Impossible'], 'all division 2 must yield an integer'

def test_impossible_requires_both_divisions(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    has_div1 = False
    has_div2 = False
    for i in range(1, n+1):
        _, d = lines[i].split()
        if d == '1':
            has_div1 = True
        else:
            has_div2 = True
    out = run(x).strip()
    if out == 'Impossible':
        assert has_div1 and has_div2, 'Impossible output requires both divisions'

def test_integer_requires_div2(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    all_div1 = True
    for i in range(1, n+1):
        _, d = lines[i].split()
        if d != '1':
            all_div1 = False
            break
    out = run(x).strip()
    if out not in ['Infinity', 'Impossible']:
        # integer output
        assert not all_div1, 'integer output cannot happen with all division 1'

def test_full_simulation(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 30:  # too big for brute force, skip
        return
    c = []
    d = []
    for i in range(1, n+1):
        ci, di = lines[i].split()
        c.append(int(ci))
        d.append(int(di))
    # simulation
    lo = -10**18  # practical lower bound
    hi = 10**18   # practical upper bound
    prefix = 0
    for i in range(n):
        if d[i] == 1:
            lo = max(lo, 1900 - prefix)
        else:
            hi = min(hi, 1899 - prefix)
        prefix += c[i]
        if lo > hi:
            expected = 'Impossible'
            break
    else:
        if hi == 10**18:
            expected = 'Infinity'
        else:
            expected = str(prefix + hi)
    out = run(x).strip()
    assert out == expected, f'full simulation mismatch: got {out}, expected {expected}'

def test_integer_consistency_and_maximality(run, x):
    out = run(x).strip()
    if out in ['Infinity', 'Impossible']:
        return
    lines = x.strip().split('\n')
    n = int(lines[0])
    c = []
    d = []
    total = 0
    for i in range(1, n+1):
        ci, di = lines[i].split()
        ci = int(ci)
        c.append(ci)
        d.append(int(di))
        total += ci
    x0 = int(out) - total  # initial rating
    # check x0 satisfies all constraints
    prefix = 0
    for i in range(n):
        rating_before = x0 + prefix
        if d[i] == 1:
            if rating_before < 1900:
                return  # violation: x0 fails, but we only assert when both conditions fail
        else:
            if rating_before > 1899:
                return  # violation
        prefix += c[i]
    # now check x0+1 violates at least one constraint
    prefix = 0
    ok = True
    for i in range(n):
        rating_before = (x0+1) + prefix
        if d[i] == 1:
            if rating_before < 1900:
                ok = False
                break
        else:
            if rating_before > 1899:
                ok = False
                break
        prefix += c[i]
    assert not ok, 'x0+1 still satisfies all constraints, so answer not maximal'

def test_impossible_interval_empty(run, x):
    out = run(x).strip()
    if out != 'Impossible':
        return
    lines = x.strip().split('\n')
    n = int(lines[0])
    c = []
    d = []
    for i in range(1, n+1):
        ci, di = lines[i].split()
        c.append(int(ci))
        d.append(int(di))
    lo = -10**18
    hi = 10**18
    prefix = 0
    for i in range(n):
        if d[i] == 1:
            lo = max(lo, 1900 - prefix)
        else:
            hi = min(hi, 1899 - prefix)
        prefix += c[i]
    assert lo > hi, 'Impossible output but interval not empty'

def test_infinity_all_div1(run, x):
    out = run(x).strip()
    if out != 'Infinity':
        return
    lines = x.strip().split('\n')
    n = int(lines[0])
    for i in range(1, n+1):
        _, d = lines[i].split()
        assert d == '1', 'Infinity output but found division 2'

def test_formula_with_div2(run, x):
    out = run(x).strip()
    if out in ['Infinity', 'Impossible']:
        return
    lines = x.strip().split('\n')
    n = int(lines[0])
    c = []
    d = []
    total = 0
    has_div2 = False
    for i in range(1, n+1):
        ci, di = lines[i].split()
        ci = int(ci)
        c.append(ci)
        d.append(int(di))
        total += ci
        if di == '2':
