        assert out.strip() == '0', 'must output 0 when divisibility fails'"
    },
    {
      "name": "test_nonneg_ab",
      "source": "def test_nonneg_ab(run, x):
    X, Y = map(int, x.strip().split())
    out = run(x)
    out_val = int(out.strip())
    if out_val != 0:
