def test_format(run, x):
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    if len(lines) == 1:
        assert lines[0] == 'Infinite', "If one line, must be 'Infinite'"
    elif len(lines) == 2:
        assert lines[0] == 'Finite', "First line must be 'Finite'"
        try:
            int(lines[1])
        except ValueError:
            assert False, "Second line must be an integer"
    else:
        assert False, "Output must be 1 or 2 lines"


def test_int_range(run, x):
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    if len(lines) == 2:
        val = int(lines[1])
        assert -2**31 <= val <= 2**31 - 1, "Integer must fit 32-bit signed"


def test_example1(run, x):
    if x == "3\n2 1 3\n":
        assert run(x) == "Finite\n7\n", "Example 1 mismatch"


def test_example2(run, x):
    if x == "3\n1 2 3\n":
        assert run(x) == "Infinite\n", "Example 2 mismatch"


def test_2_3_infinite(run, x):
    # parse sequence
    lines = x.strip().split('\n')
    n = int(lines[0])
    seq = list(map(int, lines[1].split()))
    has_23 = any(seq[i] == 2 and seq[i+1] == 3 for i in range(n-1))
    if has_23:
        output = run(x)
        lines_out = output.rstrip('\n').split('\n')
        assert lines_out[0] == 'Infinite', "Sequence contains 2,3 -> must be Infinite"


def test_lower_bound(run, x):
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    if len(lines) == 2:
        val = int(lines[1])
        assert val >= 1, "Finite points must be at least 1"


def test_upper_bound(run, x):
    output = run(x)
    lines = output.rstrip('\n').split('\n')
    if len(lines) == 2:
        val = int(lines[1])
        # parse n from input
        n = int(x.strip().split('\n')[0])
        assert val <= 4 * (n - 1), f"Finite points cannot exceed 4*(n-1) = {4*(n-1)}"


def test_no_extra_whitespace(run, x):
    output = run(x)
    lines = output.split('\n')
    for line in lines:
        if line != '' and line != line.strip():
            assert False, "Line has leading/trailing whitespace"
    # also no spaces/tabs inside lines except newline
    for ch in output:
        if ch not in '\n' and ch.isspace():
            assert False, "Output contains whitespace other than newline"


def test_n2_exact(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n == 2:
        seq = list(map(int, lines[1].split()))
        a, b = seq
        expected = {
            (1,2): "Finite\n3\n",
            (1,3): "Finite\n4\n",
            (2,1): "Finite\n3\n",
            (2,3): "Infinite\n",
            (3,1): "Finite\n4\n",
            (3,2): "Finite\n3\n",
        }
        assert run(x) == expected[(a,b)], f"n=2 pair ({a},{b}) mismatch"


def test_valid_characters(run, x):
    output = run(x)
    allowed = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789\n")
    for ch in output:
        if ch not in allowed:
            assert False, f"Invalid character '{ch}' in output"

