            cadj = {node: [] for node in comp}
            for u, v in comp_edges:
                cadj[u].append(v)
                cadj[v].append(u)
            # DP: dp[u] = number of connected subsets of subtree rooted at u that include u
            # root arbitrarily at comp[0]
            root = comp[0]
            parent = {}
            order = []
            stack = [(root, -1)]
            while stack:
                u, p = stack.pop()
                parent[u] = p
                order.append(u)
                for v in cadj[u]:
                    if v != p:
                        stack.append((v, u))
            dp = {}
            for u in reversed(order):
                ways = 1
                for v in cadj[u]:
                    if v == parent[u]:
                        continue
                    ways = ways * (dp[v] + 1) % 1000000007
                dp[u] = ways
            # total subsets that are connected in this component = sum of dp over all roots? Actually dp[u] counts subsets that include u and are connected in its subtree. But we need subsets that are connected in the whole component. For a tree, the total number of non-empty connected induced subgraphs = sum over all nodes u of dp[u] where dp is computed with u as root? The standard formula: root at any node, compute dp[u] as product(1+dp[child]), then total = sum dp[u]. That gives the correct total for the whole tree.
            # We already computed dp with root as comp[0]; but dp computed with one root may not give sum over all subsets? Actually for a tree, if you root at r, define f(u) = number of connected subsets of subtree of u that include u. Then total connected subsets of whole tree = sum_u f(u) where f is computed with that root. Because each connected subset S has a unique node in S that is closest to the root (the root of S), and it will be counted exactly once in the sum.
            # So we can just sum dp values from our DP.
            total_comp = sum(dp.values()) % 1000000007
            total = (total + total_comp) % 1000000007
    expected = total % 1000000007
    ans = int(run(x).strip())
    assert ans == expected

def test_d_large(run, x):
    data = x.strip().split()
    if len(data) < 2:
        return
    d = int(data[0])
    n = int(data[1])
    a = list(map(int, data[2:2+n]))
    if max(a) - min(a) > d:
        return
    edges = []
    idx = 2+n
    for i in range(n-1):
        u = int(data[idx+2*i]) - 1
        v = int(data[idx+2*i+1]) - 1
        edges.append((u, v))
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    # DP: root at 0
    parent = [-1]*n
    order = []
    stack = [0]
    parent[0] = -2
    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if parent[v] == -1:
                parent[v] = u
                stack.append(v)
    dp = [0]*n
    for u in reversed(order):
        prod = 1
        for v in adj[u]:
            if v == parent[u]:
                continue
            prod = prod * (dp[v] + 1) % 1000000007
        dp[u] = prod
    total = sum(dp) % 1000000007
    ans = int(run(x).strip())
    assert ans == total

def test_n2(run, x):
    data = x.strip().split()
    if len(data) < 2:
        return
    n = int(data[1])
    if n != 2:
        return
    d = int(data[0])
    a = list(map(int, data[2:4]))
    ans = int(run(x).strip())
    if abs(a[0] - a[1]) <= d:
        assert ans == 3
    else:
        assert ans == 2

def test_n1(run, x):
    data = x.strip().split()
