def test_correctness(run, x):
    # Compute volume directly from input for n <= 200 (safe)
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return  # malformed input, ignore
    n_str = lines[0].strip()
    if not n_str.isdigit():
        return
    n = int(n_str)
    if n > 200:
        return  # skip large inputs to keep test fast
    text = lines[1].strip()
    words = text.split()
    if not words:
        return
    max_caps = 0
    for w in words:
        caps = sum(1 for ch in w if 'A' <= ch <= 'Z')
        if caps > max_caps:
            max_caps = caps
    out = run(x).strip()
    assert out.isdigit(), f'Output must be integer, got {out}'
    assert int(out) == max_caps, f'Expected {max_caps}, got {out}'

def test_output_format(run, x):
    out = run(x).strip()
    # must parse as non-negative integer
    assert out.isdigit() or (out.startswith('-') and out[1:].isdigit()), f'Output not integer: {out}'
    val = int(out)
    assert val >= 0, f'Output negative: {val}'

def test_upper_bound_total_capitals(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    text = lines[1].strip()
    total_caps = sum(1 for ch in text if 'A' <= ch <= 'Z')
    out = run(x).strip()
    if not out.isdigit():
        return  # caught by format test
    val = int(out)
    assert val <= total_caps, f'Output {val} exceeds total capitals {total_caps}'

def test_lower_bound_any_capital(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    text = lines[1].strip()
    has_capital = any('A' <= ch <= 'Z' for ch in text)
    if has_capital:
        out = run(x).strip()
        if not out.isdigit():
            return
        val = int(out)
        assert val >= 1, f'Capital present but output is 0'

def test_all_caps_lower_bound(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    words = lines[1].strip().split()
    for w in words:
        if all('A' <= ch <= 'Z' for ch in w):
            out = run(x).strip()
            if not out.isdigit():
                return
            val = int(out)
            assert val >= len(w), f'All-caps word length {len(w)} but output {val}'

def test_upper_bound_word_length(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    words = lines[1].strip().split()
    if not words:
        return
    max_len = max(len(w) for w in words)
    out = run(x).strip()
    if not out.isdigit():
        return
    val = int(out)
    assert val <= max_len, f'Output {val} exceeds max word length {max_len}'

def test_bound_n(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 1:
        return
    n_str = lines[0].strip()
    if not n_str.isdigit():
        return
    n = int(n_str)
    out = run(x).strip()
    if not out.isdigit():
        return
    val = int(out)
    assert val <= n, f'Output {val} exceeds n={n}'

def test_no_capitals_implies_zero(run, x):
    lines = x.strip().split('\n')
    if len(lines) < 2:
        return
    text = lines[1].strip()
    words = text.split()
    if not words:
        return
    has_capital = any('A' <= ch <= 'Z' for ch in text)
    if not has_capital:
        out = run(x).strip()
        if not out.isdigit():
            return
        val = int(out)
        assert val == 0, f'No capitals but output is {val}'

def test_answer_equals_some_word_volume(run, x):
    lines = x.strip().split('\n')
