def test_valid_integer(run, x):
    out = run(x).strip()
    val = int(out)
    MOD = 10**9 + 7
    assert 0 <= val < MOD, f'output {val} not in range [0, {MOD})'

def test_no_leading_zeros(run, x):
    out = run(x).strip()
    if out != '0':
        assert out[0] != '0', f'leading zero in non-zero output {out}'

def test_unreachable_zero(run, x):
    X, Y = map(int, x.split())
    out = run(x).strip()
    if (2*Y - X) % 3 != 0 or (2*X - Y) % 3 != 0:
        assert out == '0', f'output {out} should be 0 for unreachable ({X},{Y})'
    else:
        a = (2*Y - X)//3
        b = (2*X - Y)//3
        if a < 0 or b < 0:
            assert out == '0', f'output {out} should be 0 for unreachable ({X},{Y})'

def test_single_path(run, x):
    X, Y = map(int, x.split())
    out = run(x).strip()
    if X == 0 and Y == 0:
        assert out == '1', f'origin must have 1 way, got {out}'
        return
    if (2*Y - X) % 3 == 0 and (2*X - Y) % 3 == 0:
        a = (2*Y - X)//3
        b = (2*X - Y)//3
        if a >= 0 and b >= 0 and min(a,b) == 0:
            assert out == '1', f'output {out} should be 1 for exactly one path ({X},{Y})'

def test_dp_small(run, x):
    X, Y = map(int, x.split())
    if X > 1000 or Y > 1000:
        return
    MOD = 10**9 + 7
    dp = [[0]*(Y+1) for _ in range(X+1)]
    dp[0][0] = 1
    for i in range(X+1):
        for j in range(Y+1):
            if i-1 >= 0 and j-2 >= 0:
                dp[i][j] = (dp[i][j] + dp[i-1][j-2]) % MOD
            if i-2 >= 0 and j-1 >= 0:
                dp[i][j] = (dp[i][j] + dp[i-2][j-1]) % MOD
    expected = dp[X][Y]
    out = int(run(x).strip())
    assert out == expected, f'DP mismatch: got {out}, expected {expected}'

def test_nonzero_implies_reachable(run, x):
    out = run(x).strip()
    if out == '0':
        return
    X, Y = map(int, x.split())
    assert (2*Y - X) % 3 == 0 and (2*X - Y) % 3 == 0, f'nonzero {out} but (X,Y) not reachable mod condition'
    a = (2*Y - X)//3
    b = (2*X - Y)//3
    assert a >= 0 and b >= 0, f'nonzero {out} but a={a} or b={b} negative'

def test_output_format(run, x):
    out = run(x).strip()
    import re
    assert re.fullmatch(r'[0-9]+', out), f'output {repr(out)} contains non-digit characters'

def test_sample(run, x):
    if x.strip() == '3 3':
        out = run(x).strip()
        assert out == '2', f'sample input 3 3 should output 2, got {out}'

def test_small_bruteforce(run, x):
    X, Y = map(int, x.split())
    if X + Y > 20:
        return
    MOD = 10**9 + 7
    from itertools import product
    # each move is (+1,+2) or (+2,+1)
    # maximum moves <= X+Y
    total = 0
    for m in range((X+Y)//3, (X+Y)+1):
        for seq in product([(1,2),(2,1)], repeat=m):
            i, j = 0, 0
            for di,dj in seq:
                i += di
                j += dj
                if i > X or j > Y:
                    break
            if i == X and j == Y:
                total += 1
    expected = total % MOD
    out = int(run(x).strip())
    assert out == expected, f'bruteforce mismatch: got {out}, expected {expected}'

def test_sum_divisible_by_3_if_nonzero(run, x):
    out = run(x).strip()
    if out == '0':
        return
    X, Y = map(int, x.split())
    assert (X + Y) % 3 == 0, f'nonzero {out} but (X+Y) mod 3 != 0'

