def test_format(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    assert len(lines) == 2, f"Expected 2 lines, got {len(lines)}"
    # first line integer
    try:
        k = int(lines[0].strip())
    except ValueError:
        raise AssertionError("First line not an integer")
    # second line may be empty or space-separated integers
    second = lines[1].strip()
    if second == '':
        # empty line allowed
        pass
    else:
        # must be space-separated integers
        parts = second.split()
        for p in parts:
            try:
                int(p)
            except ValueError:
                raise AssertionError(f"Second line contains non-integer: {p}")

def test_count(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if len(lines) != 2:
        return  # test_format will catch this
    first = lines[0].strip()
    second = lines[1].strip()
    try:
        k = int(first)
    except ValueError:
        raise AssertionError("First line not an integer")
    if k == 0:
        assert second == '', f"When k=0 second line must be empty, got '{second}'"
    else:
        parts = second.split()
        assert len(parts) == k, f"Expected {k} integers, got {len(parts)}"

def test_positivity(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if len(lines) != 2:
        return
    second = lines[1].strip()
    if second == '':
        return
    for part in second.split():
        val = int(part)
        assert val >= 1, f"Output integer {val} is not positive"

def test_increasing(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    if len(lines) != 2:
        return
    second = lines[1].strip()
    if second == '':
        return
    vals = list(map(int, second.split()))
    for i in range(1, len(vals)):
        assert vals[i] > vals[i-1], f"List not strictly increasing: {vals}"

