    assert len(lines) == 2, f'Expected 2 lines, got {len(lines)}'
    for line in lines:
        if line == '-':
            continue
        assert line.startswith('"') and line.endswith('"'), f'Line not dash and not quoted: {line}'
        content = line[1:-1]
        # No internal quotes
        assert '"' not in content, f'Internal quote in line: {line}'


def test_a_words_are_numbers(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    a_line = lines[0]
    if a_line == '-':
        return
    content = a_line[1:-1]
    if content == '':
        # Empty string between quotes means zero words
        return
    words = content.split(',')
    for w in words:
        assert w != '', 'Empty word in a'  # Empty word cannot be a valid integer
        # Must be nonnegative integer without leading zeroes
        # '0' is allowed, other numbers must not start with '0'
        assert w.isdigit(), f'Non-digit in a-word: {w}'
        if w != '0':
            assert w[0] != '0', f'Leading zero in a-word: {w}'


def test_b_words_are_not_numbers(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    b_line = lines[1]
    if b_line == '-':
        return
    content = b_line[1:-1]
    if content == '':
        # Empty string means zero words, none can be numbers
        return
    words = content.split(',')
    for w in words:
        if w == '':
            continue  # empty word is not a valid integer (spec says word can be empty, but empty is not a number)
        # Check if it looks like a valid integer
        if w.isdigit() and (w == '0' or w[0] != '0'):
            # This is a valid integer number, but should not appear in b
            assert False, f'Valid number in b-word: {w}'


def test_words_no_separators(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    for line in lines:
        if line == '-':
            continue
        content = line[1:-1]
