            continue
        words = content.split(',')
        for w in words:
            assert ',' not in w, f'Comma inside word: {w}'
            assert ';' not in w, f'Semicolon inside word: {w}'


def test_total_word_count(run, x):
    out = run(x)
    lines = out.rstrip('\n').split('\n')
    input_words = []
    # Count words in input: split on ',' and ';' but keep empties.
    # Since we cannot use re.split, we iterate.
    word = ''
    for ch in x.strip('\n'):
        if ch == ',' or ch == ';':
            input_words.append(word)
            word = ''
        else:
            word += ch
    input_words.append(word)  # last word
    total_input = len(input_words)
