    X = max(0, (N-1)*50 - S)
    if C[1] == 0:
        if X > 0:
            T_ex = INF  # impossible, but bound would be infinite; skip check
            return
        else:
            T_ex = 0
    else:
        exchanges = (X + C[1] - 1)//C[1]
        T_ex = exchanges * D[1]
    out = run(x).strip().split()
    for i in range(2, N+1):
        got = int(out[i-2])
        bound = dist[i] + T_ex
        if got > bound:
            assert False, f'City {i}: output {got} > upper bound {bound}'


def test_upper_bound_min_silver_path(run, x):
    data = list(map(int, x.strip().split()))
    it = iter(data)
    N = next(it); M = next(it); S = next(it)
    edges = []
    for _ in range(M):
        u = next(it); v = next(it); a = next(it); b = next(it)
        edges.append((u, v, a, b))
    C = [0]*(N+1); D = [0]*(N+1)
    for i in range(1, N+1):
        C[i] = next(it); D[i] = next(it)
    # Dijkstra on silver cost A_i
    from heapq import heappush, heappop
    INF = 10**30
    dist_cost = [INF]*(N+1)
    dist_time = [INF]*(N+1)
    dist_cost[1] = 0
    dist_time[1] = 0
    pq = [(0, 0, 1)]  # (cost, time, city)  but we only need cost
    while pq:
        cost, time, u = heappop(pq)
        if dist_cost[u] != cost:
            continue
        for uu, vv, aa, bb in edges:
            if uu == u:
                nc = cost + aa
                nt = time + bb
                if nc < dist_cost[vv]:
                    dist_cost[vv] = nc
                    dist_time[vv] = nt
                    heappush(pq, (nc, nt, vv))
                elif nc == dist_cost[vv] and nt < dist_time[vv]:
                    dist_time[vv] = nt
            if vv == u:
                nc = cost + aa
                nt = time + bb
                if nc < dist_cost[uu]:
                    dist_cost[uu] = nc
                    dist_time[uu] = nt
                    heappush(pq, (nc, nt, uu))
                elif nc == dist_cost[uu] and nt < dist_time[uu]:
                    dist_time[uu] = nt
    out = run(x).strip().split()
    for i in range(2, N+1):
        got = int(out[i-2])
        cost = dist_cost[i]
        time_path = dist_time[i]
        if cost <= S:
            bound = time_path
        else:
            if C[1] == 0:
                # cannot get more silver, bound infinite; skip
                continue
            need = cost - S
            exchanges = (need + C[1] - 1)//C[1]
            bound = time_path + exchanges * D[1]
        if got > bound:
            assert False, f'City {i}: output {got} > bound {bound}'


def test_upper_bound_direct_edge(run, x):
