    out = run(x).strip().split()
    out_idx = 0
    for i in range(2, N+1):
        got = int(out[out_idx]); out_idx += 1
        # find direct edge from 1 to i
        bound = None
        for u,v,a,b in edges:
            if u==1 and v==i or v==1 and u==i:
                if a <= S:
                    bound = b
                else:
