def test_upper_bound_trivial(run, x):
    data = list(map(int, x.strip().split()))
    it = iter(data)
    N = next(it); M = next(it); S = next(it)
    edges = []
    sum_B = 0
    for _ in range(M):
        u = next(it); v = next(it); a = next(it); b = next(it)
        sum_B += b
    C = [0]*(N+1); D = [0]*(N+1)
    for i in range(1, N+1):
        C[i] = next(it); D[i] = next(it)
    X = (N-1)*50
    if C[1]==0:
        if X==0:
            T_ex = 0
        else:
            # impossible, skip bound
            return
    else:
        exchanges = (X + C[1] - 1)//C[1]
        T_ex = exchanges * D[1]
    bound = sum_B + T_ex
    out = run(x).strip().split()
    for line in out:
        got = int(line)
        if got > bound:
            assert False, f'Output {got} > trivial bound {bound}'


def test_overflow(run, x):
