def test_rich_case(run, x):
    data = list(map(int, x.strip().split()))
    it = iter(data)
    N = next(it); M = next(it); S = next(it)
    if S < (N-1)*50:
        return
    edges = []
    for _ in range(M):
        u = next(it); v = next(it); a = next(it); b = next(it)
        edges.append((u, v, a, b))
    # skip C,D lines
    for _ in range(N):
        next(it); next(it)
    # shortest travel time ignoring silver
    from heapq import heappush, heappop
    INF = 10**30
    dist = [INF]*(N+1)
    dist[1] = 0
    pq = [(0, 1)]
    while pq:
        t, u = heappop(pq)
        if dist[u] != t:
            continue
        for uu, vv, aa, bb in edges:
            if uu == u:
                nt = t + bb
                if nt < dist[vv]:
                    dist[vv] = nt
                    heappush(pq, (nt, vv))
            if vv == u:
                nt = t + bb
                if nt < dist[uu]:
                    dist[uu] = nt
                    heappush(pq, (nt, uu))
    out = run(x).strip().split()
    for i in range(2, N+1):
        got = int(out[i-2])
        expected = dist[i]
        if got != expected:
            assert False, f'City {i}: output {got} != shortest time {expected}'
